def check_system_deps():
    missing = []
    for cmd, pkg in REQUIRED_CMDS.items():
        if subprocess.run(['which', cmd], capture_output=True).returncode != 0:
            missing.append(pkg)
    if missing:
        print("=" * 60)
        print("  ⚠️  MISSING: sudo apt install -y " + ' '.join(set(missing)))
        print("=" * 60 + "\n")
        return False
    return True

