@app.after_request
def add_header(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    if request.endpoint != 'status_widget':
        response.headers['X-Frame-Options'] = 'SAMEORIGIN'
    response.headers['Referrer-Policy'] = 'strict-origin-when-cross-origin'
    if request.is_secure or request.headers.get('X-Forwarded-Proto') == 'https':
        response.headers['Strict-Transport-Security'] = 'max-age=31536000'
    response.headers['Content-Security-Policy'] = "default-src 'self' https: data: blob:; script-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net https://cdnjs.cloudflare.com https://translate.google.com https://translate.googleapis.com https://www.gstatic.com; style-src 'self' 'unsafe-inline' https:; font-src 'self' https: data:; img-src 'self' data: https:; connect-src 'self' https://translate.googleapis.com https://translate-pa.googleapis.com"
    # Static assets (css/js/icons) never change content without a redeploy —
    # let the browser cache them instead of re-fetching on every page load.
    # This is the single biggest "the panel feels slow" fix for anyone on a
    # cheap/high-latency VPS: every dashboard/VM-list page pulls in several
    # MB of the same JS/CSS that used to be re-downloaded every single time.
    if request.path.startswith('/static/'):
        response.headers['Cache-Control'] = 'public, max-age=604800, immutable'
    else:
        _maybe_gzip(response)
    return response

_COMPRESSIBLE_MIMES = ('text/html', 'application/json', 'text/css', 'application/javascript',
                       'text/javascript', 'image/svg+xml', 'text/plain', 'text/xml', 'application/xml')

def _maybe_gzip(response):
    # Dashboard/status/terminal polling all return small-ish HTML/JSON pages
    # repeatedly — compressing them cuts real bytes-over-the-wire on a slow
    # link, which is most of what "the panel feels slow" actually is for
    # anyone not on a fat local connection. Static assets are handled by
    # their own Cache-Control branch above (best fix there is not sending
    # them again at all) and binary downloads never hit this branch since
    # their mimetype isn't in the allow-list below.
    try:
        if response.direct_passthrough or response.status_code < 200 or response.status_code >= 300:
            return
        if 'Content-Encoding' in response.headers:
            return
        mimetype = (response.mimetype or '').lower()
        if not any(mimetype.startswith(m) for m in _COMPRESSIBLE_MIMES):
            return
        accept_enc = request.headers.get('Accept-Encoding', '')
        if 'gzip' not in accept_enc.lower():
            return
        data = response.get_data()
        if len(data) < 500:  # not worth the CPU for tiny bodies
            return
        response.set_data(gzip.compress(data, compresslevel=6))
        response.headers['Content-Encoding'] = 'gzip'
        response.headers['Content-Length'] = str(len(response.get_data()))
        vary = response.headers.get('Vary', '')
        if 'Accept-Encoding' not in vary:
            response.headers['Vary'] = (vary + ', Accept-Encoding').strip(', ')
    except Exception:
        pass  # never let compression break a real response

