terminal_sessions = {}
TERMINAL_SESSION_IDLE_LIMIT = 15 * 60  # seconds — orphaned sessions (e.g. browser closed
                                        # without a clean disconnect) get reaped after this

def _reap_stale_terminal_sessions():
    """Close and drop any SSH shell session that hasn't been read from or
    written to in a while. Without this, a session whose browser tab was
    just closed (no clean /disconnect call) keeps its paramiko SSHClient +
    channel open on the host forever, leaking a socket + thread per orphan."""
    now = time.time()
    stale = [sid for sid, s in terminal_sessions.items()
             if now - s.get('last_active', s.get('created', now)) > TERMINAL_SESSION_IDLE_LIMIT]
    for sid in stale:
        sess = terminal_sessions.pop(sid, None)
        if not sess:
            continue
        try:
            sess['channel'].close()
        except Exception:
            pass
        try:
            sess['ssh'].close()
        except Exception:
            pass

serial_sessions = {}
SERIAL_SESSION_IDLE_LIMIT = 15 * 60

def _reap_stale_serial_sessions():
    """Same idea as _reap_stale_terminal_sessions but for raw serial-console
    sockets — without this, a closed browser tab leaks a TCP connection to
    QEMU's telnet serial chardev forever."""
    now = time.time()
    stale = [sid for sid, s in serial_sessions.items()
             if now - s.get('last_active', s.get('created', now)) > SERIAL_SESSION_IDLE_LIMIT]
    for sid in stale:
        sess = serial_sessions.pop(sid, None)
        if not sess:
            continue
        try:
            sess['sock'].close()
        except Exception:
            pass

def strip_telnet_iac(data: bytes) -> bytes:
    """QEMU's `-serial telnet:...` chardev speaks minimal Telnet option
    negotiation (IAC WILL/WONT/DO/DONT) mixed into the raw serial byte
    stream. Strip those 2-3 byte command sequences so what's left is just
    the guest's actual serial output — otherwise stray \\xff bytes and
    negotiation noise show up as garbage in the console."""
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        b = data[i]
        if b == 0xFF:  # IAC
            if i + 1 >= n:
                break
            cmd = data[i + 1]
            if cmd == 0xFF:  # escaped literal 0xFF
                out.append(0xFF)
                i += 2
            elif cmd in (251, 252, 253, 254):  # WILL/WONT/DO/DONT — has an option byte
                i += 3
            else:
                i += 2
        else:
            out.append(b)
            i += 1
    return bytes(out)

# ─────────────────────────── Security helpers ───────────────────────────

_UUID_RE = re.compile(
    r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', re.I
)

def is_valid_uuid(val):
    return bool(val and isinstance(val, str) and _UUID_RE.match(val.strip()))

def safe_vm_id(vid):
    """Return vid if valid UUID else None (blocks path traversal)."""
    if not is_valid_uuid(vid):
        return None
    return vid.strip().lower()

def safe_int(val, default=0, min_v=None, max_v=None):
    try:
        n = int(val)
    except (TypeError, ValueError):
        return default
    if min_v is not None and n < min_v:
        return default
    if max_v is not None and n > max_v:
        return default
    return n

def sanitize_name(name, max_len=64):
    name = (name or '').strip()
    name = re.sub(r'[^\w\s.\-]', '', name)[:max_len]
    return name.strip() or 'vm'

def constant_time_eq(a, b):
    try:
        return secrets.compare_digest(str(a or ''), str(b or ''))
    except Exception:
        return False

# Simple in-memory rate limiter {key: [timestamps]}
_rate_buckets = {}

def _client_ip():
    """Real client IP for rate limiting / audit. X-Forwarded-For is only believed when the request
    arrived from a local/private address (i.e. through our own reverse proxy); then the LAST entry —
    the one the proxy appended — is used, because earlier entries can be forged by the client."""
    ra = request.remote_addr or 'unknown'
    try:
        a = ipaddress.ip_address(ra)
        from_proxy = a.is_loopback or a.is_private
    except ValueError:
        from_proxy = False
    if from_proxy or os.environ.get('PHVM_TRUST_PROXY') == '1':
        xff = (request.headers.get('X-Forwarded-For') or '').split(',')[-1].strip()
        if xff:
            return xff
    return ra

def rate_limit(key, limit=10, window=60):
    """Return True if allowed, False if rate exceeded."""
    now = time.time()
    bucket = _rate_buckets.get(key, [])
    bucket = [t for t in bucket if now - t < window]
    if len(bucket) >= limit:
        _rate_buckets[key] = bucket
        return False
    bucket.append(now)
    _rate_buckets[key] = bucket
    return True

def csrf_token():
    if '_csrf' not in session:
        session['_csrf'] = secrets.token_hex(16)
    return session['_csrf']

def verify_csrf():
    token = request.form.get('_csrf') or (request.headers.get('X-CSRF-Token') or '')
    if request.is_json and request.json:
        token = token or (request.json.get('_csrf') or '')
    expected = session.get('_csrf', '')
    if not expected or not constant_time_eq(token, expected):
        return False
    return True

# Destructive actions that are still plain GET links. SameSite=Lax cookies are sent on
# cross-site top-level GET navigations, so a malicious page could link a logged-in user
# straight into /vm/<id>/delete. Browsers label such requests Sec-Fetch-Site: cross-site
# (page scripts can't forge that header), and old browsers fall back to a Referer check.
_DESTRUCTIVE_GET_ENDPOINTS = {
    'delete_vm_route', 'reinstall_vm_route', 'snapshot_restore', 'snapshot_delete', 'backup_delete', 'backup_restore',
}

@app.before_request
def _keep_signed_in():
    # Without this the cookie is a browser-session cookie and dies when the tab/browser is closed.
    if session.get('user_id') or session.get('_pending_2fa_user_id'):
        session.permanent = bool(session.get('_remember', True))

@app.before_request
def _block_cross_site_destructive_get():
    if request.endpoint not in _DESTRUCTIVE_GET_ENDPOINTS or request.method != 'GET':
        return None
    site = (request.headers.get('Sec-Fetch-Site') or '').lower()
    if site:
        ok = site in ('same-origin', 'none')
    else:
        ref = request.headers.get('Referer') or ''
        ok = (not ref) or (urllib.parse.urlparse(ref).netloc == request.host)
    if not ok:
        return ("Blocked: this action must be started from inside the panel.", 403)
    return None

