def get_public_ip():
    """Public IPv4 of this server. IPv4 is forced: dual-stack VPSes otherwise answer with an IPv6 address,
    which most players/routers cannot use."""
    for url in ('https://api.ipify.org', 'https://ipv4.icanhazip.com', 'https://ifconfig.me/ip', 'https://checkip.amazonaws.com'):
        try:
            out = subprocess.check_output(['curl', '-4', '-s', '--max-time', '5', url], timeout=7).decode().strip()
            if ipaddress.ip_address(out).version == 4:
                return out
        except Exception:
            continue
    return '127.0.0.1'

