def host_cpu_name():
    """Marketing name of the host CPU (e.g. 'AMD EPYC 7502 32-Core Processor')."""
    try:
        for line in open('/proc/cpuinfo'):
            if line.lower().startswith('model name'):
                return re.sub(r'\s+', ' ', line.split(':', 1)[1]).strip()
    except Exception:
        pass
    return ''


def kvm_available():
    """Return True if /dev/kvm exists and is usable."""
    try:
        if not os.path.exists('/dev/kvm'):
            return False
        # readable + writable
        return os.access('/dev/kvm', os.R_OK | os.W_OK)
    except Exception:
        return False

HAVE_KVM = kvm_available()

def detect_host_cpu_name():
    """Read the real CPU model string from this host, e.g. 'AMD EPYC 7302P
    16-Core Processor' or 'AMD Ryzen 9 5950X' — baked into every VM's
    neofetch/fastfetch config so 'CPU' shows the real hardware regardless
    of KVM passthrough support."""
    try:
        with open('/proc/cpuinfo') as f:
            for line in f:
                if line.lower().startswith('model name'):
                    return line.split(':', 1)[1].strip()
    except Exception:
        pass
    return 'Unknown CPU'

HOST_CPU_NAME = detect_host_cpu_name()

def generate_vm_password(length=12):
    """Generate a secure random password for VM root/sudo users."""
    alphabet = string.ascii_letters + string.digits
    # ensure mix
    pw = [
        secrets.choice(string.ascii_lowercase),
        secrets.choice(string.ascii_uppercase),
        secrets.choice(string.digits),
    ]
    pw += [secrets.choice(alphabet) for _ in range(max(0, length - 3))]
    random.SystemRandom().shuffle(pw)
    return ''.join(pw)

def allocate_private_ip():
    """Allocate a unique private IP from 10.10.0.0/16 for NAT VMs."""
    used = set()
    rows = db_execute("SELECT private_ip FROM vm_instances WHERE private_ip IS NOT NULL", fetch=True) or []
    for r in rows:
        if r['private_ip']:
            used.add(r['private_ip'])
    for _ in range(5000):
        a = random.randint(0, 255)
        b = random.randint(2, 254)  # skip .0 .1 .255-ish
        ip = f"10.10.{a}.{b}"
        if ip not in used:
            return ip
    return f"10.10.{random.randint(0,255)}.{random.randint(2,254)}"

PHVM_BRIDGE = 'phvmbr0'
PHVM_BRIDGE_SUBNET = '10.99.0.0/24'
PHVM_BRIDGE_GW = '10.99.0.1'
NETPLAN_DEDICATED_FILE = '/etc/netplan/90-phvm-dedicated-ips.yaml'


def detect_primary_interface():
    """Return the host's main outbound network interface name, e.g. 'eth0'."""
    try:
        r = subprocess.run(['ip', 'route', 'show', 'default'], capture_output=True, text=True, timeout=5)
        m = re.search(r'dev\s+(\S+)', r.stdout or '')
        if m:
            return m.group(1)
    except Exception:
        pass
    return 'eth0'


def ensure_phvm_bridge():
    """Create the private bridge that dedicated-IP VMs attach to, if it
    doesn't already exist. Fully isolated from the real LAN — traffic only
    reaches it via explicit DNAT rules per dedicated IP, so this never
    requires any cooperation from the datacenter beyond routing the IP to
    this host at all."""
    try:
        r = subprocess.run(['ip', 'link', 'show', PHVM_BRIDGE], capture_output=True, text=True)
        if r.returncode != 0:
            subprocess.run(['ip', 'link', 'add', PHVM_BRIDGE, 'type', 'bridge'], check=False)
            subprocess.run(['ip', 'addr', 'add', f'{PHVM_BRIDGE_GW}/24', 'dev', PHVM_BRIDGE], check=False)
            subprocess.run(['ip', 'link', 'set', PHVM_BRIDGE, 'up'], check=False)
        else:
            subprocess.run(['ip', 'link', 'set', PHVM_BRIDGE, 'up'], check=False)
        # IP forwarding + outbound NAT so VMs on the bridge can reach the internet
        subprocess.run(['sysctl', '-w', 'net.ipv4.ip_forward=1'], capture_output=True)
        iface = detect_primary_interface()
        r2 = subprocess.run(['iptables', '-t', 'nat', '-C', 'POSTROUTING', '-s', PHVM_BRIDGE_SUBNET,
                             '-o', iface, '-j', 'MASQUERADE'], capture_output=True)
        if r2.returncode != 0:
            subprocess.run(['iptables', '-t', 'nat', '-A', 'POSTROUTING', '-s', PHVM_BRIDGE_SUBNET,
                           '-o', iface, '-j', 'MASQUERADE'], capture_output=True)
        return True
    except Exception as e:
        print(f'[PHvm] ensure_phvm_bridge failed: {e}')
        return False


def allocate_bridge_ip():
    """Pick a free 10.99.0.x address for the next dedicated-IP VM."""
    used = set()
    for r in (db_execute("SELECT bridge_ip FROM public_ips WHERE bridge_ip IS NOT NULL", fetch=True) or []):
        used.add(r['bridge_ip'])
    for i in range(10, 250):
        cand = f'10.99.0.{i}'
        if cand not in used:
            return cand
    return None


def sync_dedicated_ips_netplan():
    """Regenerate the dedicated netplan file listing every leased IP as a
    secondary address on the host's primary interface, then apply it. Kept
    in our own file so we never touch the provider's original netplan config."""
    if not shutil.which('netplan'):
        return False, 'netplan not found on this host (not an Ubuntu/netplan system?)'
    iface = detect_primary_interface()
    ips = db_execute("SELECT ip_address FROM public_ips", fetch=True) or []
    addr_list = '\n'.join(f'        - {r["ip_address"]}/32' for r in ips)
    yaml_content = f"""network:
  version: 2
  ethernets:
    {iface}:
      addresses:
{addr_list if addr_list else '        []'}
"""
    try:
        Path(NETPLAN_DEDICATED_FILE).write_text(yaml_content)
        os.chmod(NETPLAN_DEDICATED_FILE, 0o600)
        r = subprocess.run(['netplan', 'apply'], capture_output=True, text=True, timeout=30)
        if r.returncode != 0:
            return False, (r.stderr or r.stdout or 'netplan apply failed')[:500]
        return True, None
    except Exception as e:
        return False, str(e)


def bind_dedicated_ip(public_ip, bridge_ip):
    """DNAT+SNAT so `public_ip` behaves like it belongs entirely to the VM
    living at `bridge_ip` on the private bridge — every port, not just SSH."""
    try:
        subprocess.run(['iptables', '-t', 'nat', '-A', 'PREROUTING', '-d', public_ip,
                        '-j', 'DNAT', '--to-destination', bridge_ip], capture_output=True)
        subprocess.run(['iptables', '-t', 'nat', '-A', 'POSTROUTING', '-s', bridge_ip,
                        '-j', 'SNAT', '--to-source', public_ip], capture_output=True)
        subprocess.run(['iptables', '-A', 'FORWARD', '-d', bridge_ip, '-j', 'ACCEPT'], capture_output=True)
        subprocess.run(['iptables', '-A', 'FORWARD', '-s', bridge_ip, '-j', 'ACCEPT'], capture_output=True)
        return True
    except Exception as e:
        print(f'[PHvm] bind_dedicated_ip failed: {e}')
        return False


def unbind_dedicated_ip(public_ip, bridge_ip):
    try:
        subprocess.run(['iptables', '-t', 'nat', '-D', 'PREROUTING', '-d', public_ip,
                        '-j', 'DNAT', '--to-destination', bridge_ip], capture_output=True)
        subprocess.run(['iptables', '-t', 'nat', '-D', 'POSTROUTING', '-s', bridge_ip,
                        '-j', 'SNAT', '--to-source', public_ip], capture_output=True)
        subprocess.run(['iptables', '-D', 'FORWARD', '-d', bridge_ip, '-j', 'ACCEPT'], capture_output=True)
        subprocess.run(['iptables', '-D', 'FORWARD', '-s', bridge_ip, '-j', 'ACCEPT'], capture_output=True)
    except Exception:
        pass


def setup_vm_tap(vid):
    """Create+attach a TAP interface for a dedicated-IP VM. Returns the tap name."""
    tap_name = f'tap-{vid[:8]}'
    try:
        r = subprocess.run(['ip', 'link', 'show', tap_name], capture_output=True)
        if r.returncode != 0:
            subprocess.run(['ip', 'tuntap', 'add', tap_name, 'mode', 'tap'], check=False)
        subprocess.run(['ip', 'link', 'set', tap_name, 'master', PHVM_BRIDGE], check=False)
        subprocess.run(['ip', 'link', 'set', tap_name, 'up'], check=False)
        return tap_name
    except Exception as e:
        print(f'[PHvm] setup_vm_tap failed: {e}')
        return tap_name


def teardown_vm_tap(vid):
    tap_name = f'tap-{vid[:8]}'
    try:
        subprocess.run(['ip', 'link', 'set', tap_name, 'down'], capture_output=True)
        subprocess.run(['ip', 'link', 'delete', tap_name], capture_output=True)
    except Exception:
        pass


def get_vm_bridge_ip(vid):
    """Returns the private bridge IP if this VM has a dedicated public IP
    bound to it, else None (falls back to normal NAT networking)."""
    row = db_execute("SELECT bridge_ip FROM public_ips WHERE assigned_vm_id=? AND bridge_ip IS NOT NULL",
                     (vid,), fetchone=True)
    return row['bridge_ip'] if row else None


def _port_is_free(p):
    """True if nothing on this host is listening on TCP port p (catches ports held by Docker,
    QEMU, SSH or any other program that the panel database doesn't know about)."""
    for host in ('0.0.0.0', '127.0.0.1'):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            sock.bind((host, int(p)))
        except OSError:
            return False
        finally:
            sock.close()
    return True


def allocate_host_port(preferred=None):
    """Allocate a free host TCP port (SSH, Minecraft, VNC, extra forwards).

    A port counts as taken if the panel DB already hands it to a VM / server / forward, or if
    something on the host is already listening on it. With `preferred` (e.g. 25565 for Minecraft)
    the next free port after it is tried (25566, 25567, ...) before falling back to a random one."""
    used = set()
    for col in ('ssh_port', 'vnc_port', 'vnc_console_port', 'serial_port'):
        try:
            for r in (db_execute(f"SELECT {col} FROM vm_instances WHERE {col} IS NOT NULL", fetch=True) or []):
                used.add(int(r[col]))
        except Exception:
            pass
    for r in (db_execute("SELECT host_port FROM port_forwards", fetch=True) or []):
        used.add(int(r['host_port']))
    if preferred and 1024 <= int(preferred) <= 65535:
        for cand in range(int(preferred), min(int(preferred) + 300, 65535)):
            if cand not in used and _port_is_free(cand):
                return cand
    base = int(gsv('base_ssh_port', 10000))
    for _ in range(5000):
        p = random.randint(base, min(base + 20000, 65000))
        if p not in used and _port_is_free(p):
            return p
    return random.randint(20000, 60000)

def allocate_vnc_port():
    """Allocate a free host port for a QEMU -vnc display (real VNC, not SSH)."""
    return allocate_host_port()

def ensure_local_node():
    """Ensure the panel host Local Node exists; recreate if deleted."""
    local = db_execute("SELECT * FROM nodes WHERE is_local=1", fetchone=True)
    if local:
        try:
            cpu = psutil.cpu_count() or 1
            ram = int(psutil.virtual_memory().total / (1024 * 1024))
            disk = int(psutil.disk_usage('/').total / (1024 ** 3))
            db_execute(
                "UPDATE nodes SET hostname=?, status='online', cpu_cores=?, ram_mb=?, disk_gb=?, "
                "has_kvm=?, last_seen=CURRENT_TIMESTAMP WHERE is_local=1",
                (socket.gethostname(), cpu, ram, disk, 1 if HAVE_KVM else 0)
            )
        except Exception:
            pass
        return local['id'] if isinstance(local, dict) or hasattr(local, 'keys') else local[0]
    try:
        cpu = psutil.cpu_count() or 1
        ram = int(psutil.virtual_memory().total / (1024 * 1024))
        disk = int(psutil.disk_usage('/').total / (1024 ** 3))
    except Exception:
        cpu, ram, disk = 1, 0, 0
    # avoid name collision
    name = 'Local Node'
    exists = db_execute("SELECT id FROM nodes WHERE name=?", (name,), fetchone=True)
    if exists:
        db_execute("UPDATE nodes SET is_local=1, status='online', hostname=?, has_kvm=?, "
                   "cpu_cores=?, ram_mb=?, disk_gb=?, last_seen=CURRENT_TIMESTAMP WHERE id=?",
                   (socket.gethostname(), 1 if HAVE_KVM else 0, cpu, ram, disk, exists['id']))
        return exists['id']
    db_execute(
        "INSERT INTO nodes (name, hostname, is_local, status, cpu_cores, ram_mb, disk_gb, has_kvm, notes) "
        "VALUES (?,?,1,'online',?,?,?,?,?)",
        (name, socket.gethostname(), cpu, ram, disk, 1 if HAVE_KVM else 0, 'Panel host')
    )
    row = db_execute("SELECT id FROM nodes WHERE is_local=1", fetchone=True)
    return row['id'] if row else None




