# ─────────────────────────── Database ───────────────────────────

_db_local = threading.local()

def get_db_connection():
    conn = getattr(_db_local, 'conn', None)
    if conn is not None:
        return conn
    conn = sqlite3.connect(DATABASE, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA busy_timeout=5000")
    conn.execute("PRAGMA foreign_keys=ON")
    _db_local.conn = conn
    return conn

@contextmanager
def get_db():
    conn = get_db_connection()
    try:
        yield conn
    finally:
        pass  # connection is cached per-thread; do not close here

_WRITE_STMT_RE = re.compile(r'^\s*(insert|update|delete|replace|create|drop|alter)\b', re.IGNORECASE)

def db_execute(query, params=None, fetch=False, fetchone=False, rowcount=False, lastrowid=False):
    for attempt in range(5):
        conn = get_db_connection()
        try:
            cursor = conn.execute(query, params) if params else conn.execute(query)
            if rowcount:
                result = cursor.rowcount
            elif lastrowid:
                result = cursor.lastrowid
            else:
                result = cursor.fetchall() if fetch else (cursor.fetchone() if fetchone else None)
            # Skipping commit() on plain SELECTs matters: this function is
            # called constantly (every page load does several), and in
            # WAL mode a commit still has to sync a transaction even when
            # nothing was written. Only writes need one.
            if _WRITE_STMT_RE.match(query):
                conn.commit()
            return result
        except sqlite3.OperationalError as e:
            if 'locked' in str(e) and attempt < 4:
                time.sleep(0.3 * (attempt + 1))
                continue
            raise
        except sqlite3.Error:
            # Connection may be in a bad state (e.g. broken transaction) — drop it
            # so the next call transparently reconnects instead of staying wedged.
            try:
                conn.close()
            except Exception:
                pass
            _db_local.conn = None
            raise

