def _build_bot_provision_script_base(runtime, ram_mb):
    """Bash script (run once at first boot) that turns a plain Ubuntu VM
    into a ready-to-use Node.js or Python bot-hosting box."""
    if runtime == 'python':
        return """#!/bin/bash
set -e
apt-get update -y
apt-get install -y python3 python3-pip python3-venv screen
mkdir -p /root/bot
cd /root/bot
python3 -m venv venv
cat > /root/bot/README.txt << 'EOF'
PHvm Bot Hosting — Python
==========================
Your virtualenv is ready at /root/bot/venv

Upload your bot's files into /root/bot, then:
  cd /root/bot
  source venv/bin/activate
  pip install -r requirements.txt   # if you have one
  screen -S bot
  python3 your_bot.py
  # Ctrl+A then D to detach — it keeps running after you disconnect.
  # Reattach any time with: screen -r bot
EOF
echo "Python bot-hosting environment ready" > /root/phvm-provision-done
"""
    # default: node
    return f"""#!/bin/bash
set -e
curl -fsSL https://deb.nodesource.com/setup_20.x | bash -
apt-get install -y nodejs screen
npm install -g pm2
mkdir -p /root/bot
cat > /root/bot/README.txt << 'EOF'
PHvm Bot Hosting — Node.js {{{{VERSION}}}}
==========================
Node.js + npm + pm2 (process manager) are installed.

Upload your bot's files into /root/bot, then:
  cd /root/bot
  npm install
  pm2 start index.js --name bot
  pm2 save
  pm2 startup            # keeps it running across reboots

Useful pm2 commands: pm2 logs bot | pm2 restart bot | pm2 stop bot
EOF
echo "Node.js bot-hosting environment ready" > /root/phvm-provision-done
""".replace('{{VERSION}}', '20.x')


def _svc_unit_block(name, workdir, exec_start, desc, restart='on-failure'):
    """Bash that installs <name>.service plus a <name>.socket FIFO. The FIFO is
    wired to the service's stdin, which is what lets the panel send console
    commands (Pterodactyl-style) to a process systemd is supervising."""
    return (
        "cat > /etc/systemd/system/%(n)s.socket << 'EOF'\n"
        "[Unit]\nDescription=Console input for %(d)s\n"
        "[Socket]\nListenFIFO=/run/%(n)s.stdin\nSocketMode=0600\nRemoveOnStop=true\nFlushPending=true\n"
        "EOF\n"
        "cat > /etc/systemd/system/%(n)s.service << 'EOF'\n"
        "[Unit]\nDescription=%(d)s\nAfter=network.target\nRequires=%(n)s.socket\n"
        "[Service]\nWorkingDirectory=%(w)s\nSockets=%(n)s.socket\nStandardInput=socket\n"
        "StandardOutput=journal\nStandardError=journal\nExecStart=%(e)s\n"
        "Restart=%(r)s\nRestartSec=5\nTimeoutStopSec=60\nUser=root\n"
        "[Install]\nWantedBy=multi-user.target\n"
        "EOF\n"
        "systemctl daemon-reload\n"
    ) % {'n': name, 'd': desc, 'w': workdir, 'e': exec_start, 'r': restart}


def _bot_start_script_cmd(command):
    """Bash that (re)writes /root/bot/.phvm-start.sh with the given startup command."""
    body = ("#!/bin/bash\ncd /root/bot\n[ -f venv/bin/activate ] && . venv/bin/activate\n"
            "[ -f .env ] && { set -a; . ./.env; set +a; }\n"
            "export PATH=$PATH:/usr/local/bin\nexec " + command + "\n")
    b64 = base64.b64encode(body.encode('utf-8')).decode('ascii')
    return f"mkdir -p /root/bot && echo {b64} | base64 -d > /root/bot/.phvm-start.sh && chmod +x /root/bot/.phvm-start.sh\n"


def _bot_default_startup(runtime):
    return 'python3 main.py' if runtime == 'python' else 'node index.js'


def _bot_service_block(runtime):
    return (_bot_start_script_cmd(_bot_default_startup(runtime))
            + _svc_unit_block('phvm-bot', '/root/bot', '/bin/bash /root/bot/.phvm-start.sh',
                              'PHvm Bot (%s)' % runtime, restart='always'))


_JAVA_PICK_BASH = r"""
# Minecraft 26.1+ needs Java 25; older versions run on Java 21.
JAVA_MAJOR=21
case "${VER%%.*}" in 2[6-9]|[3-9][0-9]) JAVA_MAJOR=25 ;; esac
if [ "$JAVA_MAJOR" = "25" ]; then apt-get install -y openjdk-25-jre-headless; fi
echo "$JAVA_MAJOR" > /root/mcserver/.phvm-java
"""

def _mc_java_major(ver):
    """Java major version a Minecraft version needs (26.x and newer -> 25, else 21)."""
    try:
        return 25 if int(str(ver).split('.')[0]) >= 26 else 21
    except (ValueError, IndexError):
        return 21

def _mc_start_sh_block(heap_mb):
    """Bash that writes /root/mcserver/start.sh — picks the Java in .phvm-java (default 21)."""
    body = ("#!/bin/bash\ncd /root/mcserver\nJM=$(cat .phvm-java 2>/dev/null || echo 21)\n"
            "J=/usr/lib/jvm/java-$JM-openjdk-amd64/bin/java\n[ -x \"$J\" ] || J=$(command -v java)\n"
            "exec \"$J\" -Xms%dM -Xmx%dM -jar server.jar nogui\n") % (heap_mb, heap_mb)
    return ("mkdir -p /root/mcserver && echo " + base64.b64encode(body.encode()).decode()
            + " | base64 -d > /root/mcserver/start.sh && chmod +x /root/mcserver/start.sh\n")


def _svc_install_script(kind, ram_mb, software='paper', runtime='node'):
    """Idempotent script used to add the console FIFO to servers that were
    provisioned before it existed (and as a repair action)."""
    if kind == 'minecraft':
        heap = max(512, int(ram_mb or 1024) - 512)
        return _mc_start_sh_block(heap) + _svc_unit_block('minecraft', '/root/mcserver',
                               '/bin/bash /root/mcserver/start.sh', 'Minecraft Server (%s)' % software)
    return _bot_service_block(runtime)


def _build_bot_provision_script(runtime, ram_mb):
    """Runtime install (base) + a ready-to-start phvm-bot service with console FIFO."""
    base = _build_bot_provision_script_base(runtime, ram_mb).rstrip('\n')
    head, sep, last = base.rpartition('\necho ')
    return head + '\n' + _bot_service_block(runtime) + sep + last + '\n'


def _build_minecraft_provision_script(software, mc_version, ram_mb, use_playit=False, use_minekube=False):
    """Bash script that installs Java, downloads the chosen server jar
    (resolved at boot time via each project's real API — never a hardcoded
    build number that would go stale), and sets it up as a systemd service
    that starts on boot. Optionally also sets up a playit.gg tunnel, so the
    server is reachable over a playit address with no port-forwarding or
    public IP needed on the VM's side at all — playit's agent only makes
    outbound connections."""
    software = (software or 'paper').lower()
    mc_version = (mc_version or 'latest').strip() or 'latest'
    heap_mb = max(512, int(ram_mb) - 512)  # leave the OS ~512MB headroom

    playit_block = ""
    playit_readme = ""
    if use_playit:
        playit_block = """
# playit.gg tunnel agent — gives this server a public playit address without
# needing any port forwarding or a public IP on this VM. The agent only
# makes outbound connections to playit's relay network.
curl -SsL https://playit-cloud.github.io/playit-agent/install.sh | bash || true
systemctl enable playit 2>/dev/null || true
systemctl restart playit 2>/dev/null || true
"""
        playit_readme = """

Playit.gg tunnel
-----------------
A playit.gg agent is installed and running as the "playit" service. On first
start it has no identity yet, so it prints a one-time claim link:

  journalctl -u playit -f

Open that link in a browser, sign in / create a free playit.gg account, and
claim the agent. Then in the playit.gg dashboard, add a Minecraft tunnel
pointing at 127.0.0.1:25565 on this agent — playit gives you a public
address/port to share with friends, and traffic reaches this VM through the
tunnel with nothing to configure on the VM itself.
"""

    # Minekube Connect is a server PLUGIN (not a system agent), so it only
    # works on plugin-capable software — Paper/Purpur, not vanilla.
    minekube_block = ""
    minekube_readme = ""
    if use_minekube and software in ('paper', 'purpur'):
        minekube_block = """
# Minekube Connect plugin — free public address for this server with no
# port forwarding, and no separate agent/account claim step like playit:
# it just works as soon as the server starts with the plugin installed.
mkdir -p /root/mcserver/plugins
curl -fsSL "https://github.com/minekube/connect-java/releases/latest/download/connect-spigot.jar" \\
  -o /root/mcserver/plugins/connect-spigot.jar || true
# Required since MC 1.19+: this only loosens secure-profile enforcement for
# chat signing, it doesn't affect online-mode / anything security-relevant
# beyond that. See https://connect.minekube.com for details.
if [ -f /root/mcserver/server.properties ]; then
  sed -i 's/^enforce-secure-profile=.*/enforce-secure-profile=false/' /root/mcserver/server.properties
  grep -q '^enforce-secure-profile=' /root/mcserver/server.properties || echo "enforce-secure-profile=false" >> /root/mcserver/server.properties
else
  echo "enforce-secure-profile=false" > /root/mcserver/server.properties
fi
"""
        minekube_readme = """

Minekube Connect
-----------------
The Connect plugin (connect-spigot.jar) is installed in /root/mcserver/plugins
— no port forwarding and no separate account/claim step needed. Check the
server console (journalctl -u minecraft -f) after it starts for the public
address it's been assigned, or see https://connect.minekube.com.
"""

    if software == 'purpur':
        download_logic = f"""
VER="{mc_version}"
if [ "$VER" = "latest" ]; then
  VER=$(curl -fsSL https://api.purpurmc.org/v2/purpur | python3 -c "import sys,json; d=json.load(sys.stdin); print(d['versions'][-1])")
fi
curl -fsSL "https://api.purpurmc.org/v2/purpur/${{VER}}/latest/download" -o /root/mcserver/server.jar
"""
    elif software == 'vanilla':
        download_logic = f"""
VER="{mc_version}"
MANIFEST=$(curl -fsSL https://launchermeta.mojang.com/mc/game/version_manifest_v2.json)
if [ "$VER" = "latest" ]; then
  VER=$(echo "$MANIFEST" | python3 -c "import sys,json; print(json.load(sys.stdin)['latest']['release'])")
fi
VERSION_URL=$(echo "$MANIFEST" | python3 -c "
import sys, json
d = json.load(sys.stdin)
v = '$VER'
for e in d['versions']:
    if e['id'] == v:
        print(e['url']); break
")
SERVER_URL=$(curl -fsSL "$VERSION_URL" | python3 -c "import sys,json; print(json.load(sys.stdin)['downloads']['server']['url'])")
curl -fsSL "$SERVER_URL" -o /root/mcserver/server.jar
"""
    else:  # paper (default) — PaperMC's old api.papermc.io/v2 was sunset (HTTP 410); use Fill v3
        download_logic = f"""
VER="{mc_version}"
cat > /tmp/phvm-paper-url.py << 'PYEOF'
import sys, json, urllib.request
base = 'https://fill.papermc.io/v3/projects/paper'
want = sys.argv[1]
def get(u):
    req = urllib.request.Request(u)
    req.add_header('User-Agent', 'PHvm-Panel/1.0')
    return json.load(urllib.request.urlopen(req, timeout=30))
if want == 'latest':
    versions = [v for group in get(base)['versions'].values() for v in group]
else:
    versions = [want]
for v in versions:
    builds = get(base + '/versions/' + v + '/builds')
    stable = [b for b in builds if b.get('channel') == 'STABLE']
    pick = stable or (builds if want != 'latest' else [])
    if pick:
        open('/tmp/phvm-mcver', 'w').write(v)
        print(pick[0]['downloads']['server:default']['url'])
        break
else:
    sys.exit('No downloadable Paper build found for ' + want)
PYEOF
JAR_URL=$(python3 /tmp/phvm-paper-url.py "$VER")
VER=$(cat /tmp/phvm-mcver)
curl -fsSL -A "PHvm-Panel/1.0" "$JAR_URL" -o /root/mcserver/server.jar
"""

    unit_block = _mc_start_sh_block(heap_mb) + _svc_unit_block('minecraft', '/root/mcserver',
                                 '/bin/bash /root/mcserver/start.sh', f'Minecraft Server ({software})')
    java_block = _JAVA_PICK_BASH
    return f"""#!/bin/bash
set -e
apt-get update -y
apt-get install -y openjdk-21-jre-headless screen python3
mkdir -p /root/mcserver
cd /root/mcserver
{download_logic}
{java_block}
echo "eula=true" > /root/mcserver/eula.txt
{unit_block}
{minekube_block}
systemctl daemon-reload
systemctl enable minecraft
systemctl start minecraft
{playit_block}
cat > /root/mcserver/README.txt << EOF
PHvm Minecraft Hosting — {software} {mc_version}
=================================
Server is starting now (first boot generates the world — give it a minute).
Port 25565 is forwarded — connect with this VM's SSH host and the Minecraft
port shown on its Manage page.

  systemctl status minecraft   # check it's running
  journalctl -u minecraft -f   # live server console/logs
  systemctl restart minecraft  # after editing server.properties etc.

Server files (server.properties, world/, plugins/ for Paper/Purpur) are in
/root/mcserver.
{playit_readme}{minekube_readme}
EOF
echo "Minecraft ({software} {mc_version}) provisioned" > /root/phvm-provision-done
"""


def complete_vm_setup(vid, ost, ram, cpu, stor, sp, vp, network_mode='private', public_ip=None, private_ip=None,
                      provision_kind=None, provision_option=None):
    vrow0 = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
    node = get_vm_node(vrow0) if vrow0 else None
    if node_is_remote(node):
        complete_vm_setup_remote(vid, node, ost, ram, cpu, stor, sp, vp)
        return
    if OS_TEMPLATES.get(ost, {}).get('iso') or (vrow0 and row_get(vrow0, 'is_iso')):
        complete_vm_setup_iso(vid, ost, ram, cpu, stor, sp, vp, vrow0)
        return
    try:
        vrow = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
        root_pw = (vrow['ssh_password'] if vrow and vrow['ssh_password'] else None) or generate_vm_password()
        if vrow and not vrow['ssh_password']:
            db_execute("UPDATE vm_instances SET ssh_password=? WHERE vm_id=?", (root_pw, vid))
        tmpl = get_os_templates().get(ost, get_os_templates().get('ubuntu-22.04', {}))
        hostname = f'phvm-{vid[:8]}'
        # Port forwards for this VM
        fws = db_execute("SELECT host_port, guest_port, protocol FROM port_forwards WHERE vm_id=?", (vid,), fetch=True) or []
        extra = [dict(r) for r in fws]
        vm.up(vid, 5, 'Preparing workspace…')
        vm.download_image(vid, ost)
        vm.up(vid, 60, 'Resizing disk…')
        vm.resize_disk(vid, stor)
        bridge_ip = get_vm_bridge_ip(vid)
        _kind_label = {'bot': 'Bot hosting', 'minecraft': 'Minecraft server', 'sandbox': 'Docker sandbox'}.get(provision_kind)
        vm.up(vid, 70, f'Preparing {_kind_label} installer…' if _kind_label else 'Building cloud-init seed…')
        extra_packages, extra_script = None, None
        if provision_kind == 'bot':
            extra_packages = ['python3'] if provision_option == 'python' else ['curl']
            extra_script = _build_bot_provision_script(provision_option, ram)
        elif provision_kind == 'sandbox':
            extra_packages = ['curl', 'ca-certificates']
            extra_script = _SANDBOX_SH
        elif provision_kind == 'minecraft':
            opt = provision_option or {}
            extra_script = _build_minecraft_provision_script(opt.get('software'), opt.get('version'), ram,
                                                              use_playit=bool(opt.get('playit')),
                                                              use_minekube=bool(opt.get('minekube')))
        vm.create_cloud_init(vid, ost, hostname, root_pw, cpu, bridge_ip=bridge_ip,
                             extra_packages=extra_packages, extra_script=extra_script)
        vm.up(vid, 85, 'Starting QEMU…')
        nested = False
        if vrow:
            try:
                nested = bool(vrow['nested_kvm'])
            except Exception:
                nested = False
        pid = vm.start_vm(vid, ost, ram, cpu, stor, sp, vp, network_mode, public_ip, private_ip, extra, nested, bridge_ip=bridge_ip)
        if pid and bridge_ip:
            dip_row = db_execute("SELECT ip_address FROM public_ips WHERE assigned_vm_id=?", (vid,), fetchone=True)
            if dip_row:
                bind_dedicated_ip(dip_row['ip_address'], bridge_ip)
                db_execute("UPDATE public_ips SET bound=1 WHERE assigned_vm_id=?", (vid,))
        if pid:
            db_execute("UPDATE vm_instances SET status='running', pid=?, creation_progress=100, "
                       "ssh_user=?, ssh_password=?, creation_step=?, creation_progress=100 WHERE vm_id=?",
                       (pid, 'root', root_pw,
                        (f'Ready — {_kind_label} is installing inside the VM (a few minutes)' if _kind_label else 'Ready — VM is running'), vid))
            v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
            if v:
                add_notification(v['user_id'], 'VM Ready!',
                                 f'VM "{v["name"]}" is running. SSH port: {sp}', 'success')
        else:
            time.sleep(3)
            pid = vm.start_vm(vid, ost, ram, cpu, stor, sp, vp, network_mode, public_ip, private_ip, extra, nested)
            if pid:
                db_execute("UPDATE vm_instances SET status='running', pid=?, creation_progress=100, "
                           "ssh_password=? WHERE vm_id=?",
                           (pid, root_pw, vid))
            else:
                db_execute("UPDATE vm_instances SET status='stopped', creation_progress=100, "
                           "creation_step=? WHERE vm_id=?", ('Failed to start', vid))
        if pid:
            time.sleep(15)
            try:
                vm.ssh_exec(sp, 'growpart /dev/vda 1 || growpart /dev/sda 1 || true; '
                            'resize2fs /dev/vda1 || resize2fs /dev/sda1 || true',
                            password=root_pw)
            except Exception:
                pass
    except Exception as e:
        db_execute("UPDATE vm_instances SET status='error', creation_step=? WHERE vm_id=?",
                   (str(e)[:200], vid))


# ─────────────────────────── Auth routes ───────────────────────────

@app.route('/license', methods=['GET', 'POST'])
def license_page():
    if is_licensed():
        return redirect(url_for('index'))
    if request.method == 'POST':
        ip = _client_ip()
        if not rate_limit(f'license:{ip}', limit=10, window=120):
            flash('Too many attempts. Try again later.', 'danger')
            return render_template('license.html', install_id=_license_install_id()), 429
        key = request.form.get('license_key', '').strip()[:128]
        if activate_license(key):
            try:
                audit(session.get('user_id'), 'license_activate', 'License activated')
            except Exception:
                pass
            flash('License activated successfully!', 'success')
            return redirect(url_for('index'))
        flash('Invalid license key for this install. Check and try again.', 'danger')
    return render_template('license.html', install_id=_license_install_id())

