_login_fails = {}


def _login_locked(username):
    now = time.time()
    lst = [t for t in _login_fails.get((username or '').lower(), []) if now - t < 900]
    _login_fails[(username or '').lower()] = lst
    return len(lst) >= 6


def _login_failed(username, user):
    k = (username or '').lower()
    if not k:
        return
    lst = _login_fails.setdefault(k, [])
    lst.append(time.time())
    if len(lst) == 6 and user:   # alert once when the lock kicks in
        notify_user(user['id'], 'Failed login attempts',
                    f"There were 6 wrong passwords for your account from {_client_ip()}. It is locked for 15 minutes. If that was not you, change your password.", 'danger')
        if user['role'] != 'admin':
            _notify_all_admins('Login lock', f"User {user['username']} was locked after 6 wrong passwords (IP {_client_ip()}).", 'warning')


@app.route('/forgot', methods=['GET', 'POST'])
def forgot_password():
    msg = None
    if request.method == 'POST':
        if not rate_limit('forgot:' + _client_ip(), limit=5, window=600):
            msg = 'Too many requests. Try again later.'
        elif not _turnstile_ok():
            msg = 'Please complete the human check.'
        else:
            q = (request.form.get('login') or '').strip()[:120]
            u = db_execute("SELECT id, username, email FROM users WHERE (username=? OR email=?) AND is_active=1", (q, q), fetchone=True) if q else None
            if u and row_get(u, 'email') and '@' in u['email']:
                tok = secrets.token_urlsafe(32)
                db_execute("DELETE FROM password_resets WHERE user_id=?", (u['id'],))
                db_execute("INSERT INTO password_resets (token_hash, user_id, expires) VALUES (?,?,?)",
                           (hashlib.sha256(tok.encode()).hexdigest(), u['id'], int(time.time()) + 3600))
                link = request.host_url.rstrip('/') + '/reset/' + tok
                threading.Thread(target=send_email, args=(u['email'], 'Reset your password',
                                 f"Hi {u['username']},\n\nOpen this link to choose a new password (valid for 1 hour):\n{link}\n\nIf you did not ask for this, ignore this email."), daemon=True).start()
            msg = 'If that account has an email address, a reset link is on its way. Check your inbox (and spam).'
    return render_template('auth_simple.html', mode='forgot', msg=msg)


@app.route('/reset/<token>', methods=['GET', 'POST'])
def reset_password(token):
    h = hashlib.sha256(token.encode()).hexdigest()
    row = db_execute("SELECT * FROM password_resets WHERE token_hash=? AND expires>?", (h, int(time.time())), fetchone=True)
    if not row:
        return render_template('auth_simple.html', mode='bad', msg='This reset link is invalid or has expired.'), 400
    err = None
    if request.method == 'POST':
        p1, p2 = request.form.get('password', ''), request.form.get('password2', '')
        if len(p1) < 8:
            err = 'Use at least 8 characters.'
        elif p1 != p2:
            err = 'The two passwords do not match.'
        else:
            db_execute("UPDATE users SET password=?, must_change_password=0 WHERE id=?", (generate_password_hash(p1), row['user_id']))
            db_execute("DELETE FROM password_resets WHERE user_id=?", (row['user_id'],))
            audit(row['user_id'], 'password_reset', _client_ip())
            notify_user(row['user_id'], 'Password changed', 'Your password was just changed using a reset link. If this was not you, contact the admin immediately.', 'warning')
            flash('Password changed. You can sign in now.', 'success')
            return redirect(url_for('login'))
    return render_template('auth_simple.html', mode='reset', msg=err)


@app.route('/login', methods=['GET', 'POST'])
def login():
    if session.get('user_id'):
        return redirect(url_for('index'))
    if request.method == 'POST':
        ip = _client_ip()
        if not rate_limit(f'login:{ip}', limit=8, window=60):
            flash('Too many login attempts. Wait a minute.', 'danger')
            return render_template('login.html'), 429
        if not _turnstile_ok():
            flash('Please complete the human check.', 'danger')
            return render_template('login.html'), 400
        u = request.form.get('username', '').strip()[:64]
        p = request.form.get('password', '')
        if _login_locked(u):
            flash('Too many failed attempts for this account. Try again in 15 minutes, or use "Forgot password".', 'danger')
            return render_template('login.html'), 429
        user = db_execute("SELECT * FROM users WHERE username=? AND is_active=1", (u,), fetchone=True)
        if user and check_password_hash(user['password'], p):
            _login_fails.pop(u.lower(), None)
            session['_remember'] = bool(request.form.get('remember'))   # unticked = sign out when the browser closes
            if row_get(user, 'totp_enabled'):
                session['_pending_2fa_user_id'] = user['id']
                return redirect(url_for('login_2fa'))
            session['user_id'] = user['id']
            session['username'] = user['username']
            session['role'] = user['role']
            session['avatar_url'] = row_get(user, 'avatar_url')
            db_execute("UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?", (user['id'],))
            audit(user['id'], 'login', f'Login from {request.remote_addr}')
            _login_alert(user['id'], _client_ip())
            _device_check(user['id'], _client_ip())
            flash(f'Welcome, {user["username"]}!', 'success')
            if user['role'] == 'admin' and check_password_hash(user['password'], 'phvm123'):
                flash('⚠️ This admin account still uses the default password "phvm123". Change it now (Profile → password) — anyone can log in with it.', 'danger')
            return redirect(url_for('index'))
        _login_failed(u, user)
        flash('Invalid username or password.', 'danger')
    return render_template('login.html', discord_oauth_enabled=(gsv('discord_oauth_enabled', 'false') or 'false').lower() in ('1', 'true', 'yes'))

@app.route('/login/discord')
def login_discord():
    if session.get('user_id'):
        return redirect(url_for('index'))
    client_id = (gsv('discord_oauth_client_id', '') or '').strip()
    if not client_id or (gsv('discord_oauth_enabled', 'false') or 'false').lower() not in ('1', 'true', 'yes'):
        flash('Discord login is not configured.', 'danger')
        return redirect(url_for('login'))
    state = secrets.token_urlsafe(24)
    session['_discord_oauth_state'] = state
    redirect_uri = url_for('login_discord_callback', _external=True)
    params = urllib.parse.urlencode({
        'client_id': client_id,
        'redirect_uri': redirect_uri,
        'response_type': 'code',
        'scope': 'identify',
        'state': state,
    })
    return redirect(f'https://discord.com/api/oauth2/authorize?{params}')

@app.route('/login/discord/callback')
def login_discord_callback():
    if session.get('user_id'):
        return redirect(url_for('index'))
    error = request.args.get('error')
    if error:
        flash('Discord login was cancelled or failed.', 'danger')
        return redirect(url_for('login'))
    code = request.args.get('code', '')
    state = request.args.get('state', '')
    if not code or not state or state != session.pop('_discord_oauth_state', None):
        flash('Discord login failed (invalid state). Please try again.', 'danger')
        return redirect(url_for('login'))

    client_id = (gsv('discord_oauth_client_id', '') or '').strip()
    client_secret = (gsv('discord_oauth_client_secret', '') or '').strip()
    if not client_id or not client_secret:
        flash('Discord login is not configured.', 'danger')
        return redirect(url_for('login'))

    redirect_uri = url_for('login_discord_callback', _external=True)
    ip = _client_ip()
    if not rate_limit(f'discord_oauth:{ip}', limit=10, window=120):
        flash('Too many attempts. Try again later.', 'danger')
        return redirect(url_for('login'))

    try:
        token_data = urllib.parse.urlencode({
            'client_id': client_id,
            'client_secret': client_secret,
            'grant_type': 'authorization_code',
            'code': code,
            'redirect_uri': redirect_uri,
        }).encode('utf-8')
        req = urllib.request.Request(
            'https://discord.com/api/oauth2/token', data=token_data,
            headers={'Content-Type': 'application/x-www-form-urlencoded', 'User-Agent': 'PHvm-Panel-OAuth'}
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            token_json = json.loads(resp.read().decode('utf-8'))
        access_token = token_json.get('access_token')
        if not access_token:
            raise ValueError('No access token returned')

        req2 = urllib.request.Request(
            'https://discord.com/api/users/@me',
            headers={'Authorization': f'Bearer {access_token}', 'User-Agent': 'PHvm-Panel-OAuth'}
        )
        with urllib.request.urlopen(req2, timeout=10) as resp2:
            discord_user = json.loads(resp2.read().decode('utf-8'))
        discord_id = str(discord_user.get('id', ''))
    except Exception as e:
        flash(f'Discord login failed: {e}', 'danger')
        return redirect(url_for('login'))

    if not discord_id:
        flash('Could not verify your Discord account.', 'danger')
        return redirect(url_for('login'))

    user = db_execute("SELECT * FROM users WHERE discord_id=? AND is_active=1", (discord_id,), fetchone=True)
    if not user:
        flash("No PHvm account is linked to this Discord account yet. Run phvm!register in Discord first, then try again.", 'danger')
        return redirect(url_for('login'))

    session['user_id'] = user['id']
    session['username'] = user['username']
    session['role'] = user['role']
    session['avatar_url'] = row_get(user, 'avatar_url')
    db_execute("UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?", (user['id'],))
    audit(user['id'], 'login_discord', f'Discord OAuth login from {request.remote_addr}')
    flash(f'Welcome, {user["username"]}!', 'success')
    return redirect(url_for('index'))

