@app.route('/register', methods=['GET', 'POST'])
def register():
    if session.get('user_id'):
        return redirect(url_for('index'))
    if request.args.get('ref'):
        session['_ref'] = request.args.get('ref')[:16]
    if request.method == 'POST':
        ip = _client_ip()
        if not rate_limit(f'register:{ip}', limit=5, window=300):
            flash('Too many registrations from this IP.', 'danger')
            return render_template('register.html'), 429
        if not _turnstile_ok():
            flash('Please complete the human check.', 'danger')
            return render_template('register.html'), 400
        u = request.form.get('username', '').strip()
        e = request.form.get('email', '').strip()
        p = request.form.get('password', '')
        p2 = request.form.get('password2', '')
        if not u or not e or not p:
            flash('All fields are required.', 'warning')
            return render_template('register.html')
        if len(u) < 3:
            flash('Username must be at least 3 characters.', 'warning')
            return render_template('register.html')
        if len(p) < 8:
            flash('Password must be at least 8 characters.', 'warning')
            return render_template('register.html')
        if p != p2:
            flash('Passwords do not match.', 'danger')
            return render_template('register.html')
        try:
            db_execute(
                "INSERT INTO users (username, email, password, role) VALUES (?,?,?,?)",
                (u, e, generate_password_hash(p, method='scrypt'), 'user')
            )
            audit(None, 'register', f'New user {u}')
            try:
                _rc = (request.form.get('ref') or request.args.get('ref') or session.get('_ref') or '').strip().upper()[:16]
                _ref = db_execute("SELECT id FROM users WHERE referral_code=?", (_rc,), fetchone=True) if _rc else None
                if _ref:
                    db_execute("UPDATE users SET referred_by=? WHERE username=? AND id<>?", (_ref['id'], u, _ref['id']))
            except Exception:
                pass

            new_user = db_execute("SELECT * FROM users WHERE username=?", (u,), fetchone=True)

            # Auto-login immediately after registering, straight into the dashboard.
            if new_user:
                session['user_id'] = new_user['id']
                session['username'] = new_user['username']
                session['role'] = new_user['role']
                flash('Account created! Welcome to PHvm.', 'success')
                return redirect(url_for('dashboard'))

            flash('Account created! You can sign in now.', 'success')
            return redirect(url_for('login'))
        except Exception:
            flash('Username or email already exists.', 'danger')
            return render_template('register.html')
    return render_template('register.html')

