@app.route('/dashboard')
@login_required
def dashboard():
    # Shows every VM in the panel (system-wide overview), not just the caller's own.
    _is_adm = session.get('role') == 'admin'     # privacy: only admins see every user's servers
    all_vms = db_execute(
        "SELECT vi.*, u.username AS owner_username FROM vm_instances vi "
        "LEFT JOIN users u ON u.id = vi.user_id " + ("" if _is_adm else "WHERE vi.user_id=? ") + "ORDER BY vi.created_at DESC",
        (() if _is_adm else (session['user_id'],)), fetch=True
    ) or []
    notifs = db_execute("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 10",
                        (session['user_id'],), fetch=True) or []
    vl = []
    for v in all_vms:
        d = dict(v)
        r, _ = vm.vm_status(v['vm_id'])
        d['real_status'] = 'running' if r else ('creating' if v['status'] == 'creating' else 'stopped')
        vl.append(d)
    running_count = sum(1 for x in vl if x.get('real_status') == 'running')
    return render_template('dashboard.html', vms=vl, notifications=notifs, running_count=running_count,
                           panel_wide_view=_is_adm)

