@app.route('/vm/create', methods=['GET', 'POST'])
@admin_required
def create_vm():
    if request.method == 'POST':
        name = sanitize_name(request.form.get('name', ''), 64)
        ost = request.form.get('os_template', 'ubuntu-22.04')
        try:
            ram = safe_int(request.form.get('ram_mb', 2048), 2048, 256, 262144)
            cpu = safe_int(request.form.get('cpu_cores', 2), 2, 1, 128)
            stor = safe_int(request.form.get('storage_gb', 20), 20, 5, 10000)
            uid = safe_int(request.form.get('user_id', session['user_id']), session['user_id'], 1, None)
        except Exception:
            flash('Invalid resource values.', 'danger')
            return redirect(url_for('create_vm'))
        uref = db_execute("SELECT id FROM users WHERE id=? AND is_active=1", (uid,), fetchone=True)
        if not uref:
            flash('Selected user is invalid.', 'danger')
            return redirect(url_for('create_vm'))

        is_iso_check = bool(OS_TEMPLATES.get(ost, {}).get('iso'))
        node_id_check = request.form.get('node_id', '').strip()
        will_be_local = is_iso_check or not node_id_check or (
            db_execute("SELECT is_local FROM nodes WHERE id=?", (node_id_check,), fetchone=True) or {'is_local': 1}
        )['is_local']
        ram_overcommit_warning = None
        disk_overcommit_warning = None
        if will_be_local:
            try:
                avail_mb = psutil.virtual_memory().available / (1024 * 1024)
                if ram > avail_mb:
                    # Don't block — QEMU (without -mem-prealloc, which we don't
                    # use) allows this the same way Proxmox does: the VM only
                    # actually uses RAM as it's touched, plus ballooning. Just
                    # warn so it's not a total surprise if the VM gets sluggish
                    # or the host starts swapping under real load.
                    ram_overcommit_warning = (
                        f'Heads up: {ram}MB requested but only ~{int(avail_mb)}MB is free right now. '
                        f'The VM will still be created (overcommitted, like Proxmox allows) — it\'ll run fine as '
                        f'long as it doesn\'t actually use all of it at once. If it becomes sluggish or won\'t '
                        f'start, free up RAM or lower this VM\'s allocation.'
                    )
            except Exception:
                pass
            try:
                # Disk images are thin-provisioned qcow2 — storage_gb is a cap,
                # not space reserved up front, so (like RAM above) we warn
                # instead of blocking. But unlike RAM overcommit, running an
                # actual VM's filesystem out of real disk mid-write risks
                # corruption on THAT VM and starves every other VM on this
                # host at the same time — worth a clearer, harder-to-miss
                # warning than the RAM one.
                free_gb = shutil.disk_usage(str(VM_DIR)).free / (1024 ** 3)
                if stor > free_gb:
                    disk_overcommit_warning = (
                        f'Heads up: {stor}GB requested but only ~{int(free_gb)}GB is actually free on this host '
                        f'right now. The disk image is thin-provisioned (only grows as the VM writes data), so '
                        f'the VM will still be created — but if it (or other VMs sharing this disk) ever actually '
                        f'writes past ~{int(free_gb)}GB combined, writes will start failing and can corrupt data. '
                        f'Free up disk space or lower this VM\'s storage allocation.'
                    )
            except Exception:
                pass

        network_mode = request.form.get('network_mode', 'private')
        public_ip_id = request.form.get('public_ip_id', '').strip()
        node_id = request.form.get('node_id', '').strip()
        # Always generate a unique password
        root_pw = generate_vm_password(12)

        if not name:
            flash('VM name required.', 'warning')
            return redirect(url_for('create_vm'))
        if ost not in OS_TEMPLATES:
            flash('Invalid OS template.', 'danger')
            return redirect(url_for('create_vm'))

        is_iso = bool(OS_TEMPLATES.get(ost, {}).get('iso'))

        vid = str(uuid.uuid4())
        # SSH host port always auto-assigned (never asked)
        sp = allocate_host_port()
        # Serial console port (QEMU telnet) — separate from SSH
        vp = allocate_host_port()
        vnc_console_port = allocate_vnc_port() if is_iso else None

        if is_iso:
            # ISO installers (Proxmox etc.) boot into a manual, graphical setup
            # over VNC — that only works on this panel's own node for now.
            nid = ensure_local_node()
            if node_id and int(node_id) != nid:
                flash('ISO-installer templates run on the Local Node only (VNC console isn\'t available on remote nodes yet).', 'warning')
        else:
            nid = int(node_id) if node_id else ensure_local_node()
            if not nid:
                nid = ensure_local_node()

        assigned_ip = None
        private_ip = None
        if network_mode == 'public' and public_ip_id:
            pip = db_execute("SELECT * FROM public_ips WHERE id=? AND is_available=1",
                             (int(public_ip_id),), fetchone=True)
            if pip:
                assigned_ip = pip['ip_address']
                bip = allocate_bridge_ip()
                if bip and ensure_phvm_bridge():
                    db_execute("UPDATE public_ips SET is_available=0, assigned_vm_id=?, bridge_ip=? WHERE id=?",
                               (vid, bip, pip['id']))
                else:
                    db_execute("UPDATE public_ips SET is_available=0, assigned_vm_id=? WHERE id=?",
                               (vid, pip['id']))
                    flash('IP assigned, but the private bridge could not be set up — it may not route traffic yet. Check the host has "ip"/"iptables" available.', 'warning')
            else:
                flash('Selected public IP is no longer available. Using private NAT mode.', 'warning')
                network_mode = 'private'

        if network_mode == 'private':
            private_ip = allocate_private_ip()
        else:
            # Public/dedicated IP: real traffic arrives via the bridge+DNAT
            # binding (see bind_dedicated_ip), not a NAT host port — SSH is
            # just port 22 on the dedicated IP itself, like a real VPS.
            sp = 22
            private_ip = None

        ssh_host = assigned_ip or PUBLIC_IP

        # Guest ports only for private/NAT VMs — host ports auto-assigned.
        max_nat = int(gsv('max_nat_ports_per_vm', 5) or 5)
        guest_ports_raw = request.form.get('guest_ports', '').strip() if network_mode == 'private' else ''
        extra_list = []
        if guest_ports_raw:
            seen_gp = set()
            for part in guest_ports_raw.replace(' ', '').split(','):
                if len(extra_list) >= max_nat:
                    flash(f'Max {max_nat} NAT ports per VM — extra ports ignored.', 'warning')
                    break
                try:
                    gp = int(part.split(':')[-1])  # allow accidental host:guest form, take guest
                    if gp < 1 or gp > 65535 or gp in seen_gp or gp == 22:
                        continue
                    seen_gp.add(gp)
                    hp = allocate_host_port()
                    extra_list.append({'host_port': hp, 'guest_port': gp, 'protocol': 'tcp'})
                except ValueError:
                    pass

        nested_kvm = 1 if request.form.get('nested_kvm') == 'on' else 0
        if nested_kvm and not HAVE_KVM:
            flash('Nested KVM requested but host has no KVM — using TCG.', 'warning')
            nested_kvm = 0

        db_execute(
            "INSERT INTO vm_instances "
            "(vm_id, user_id, name, os_template, ram_mb, cpu_cores, storage_gb, "
            "ssh_port, ssh_host, ssh_user, ssh_password, network_mode, public_ip, "
            "private_ip, node_id, vnc_port, serial_port, status, creation_step, creation_progress, accel_mode, nested_kvm, "
            "is_iso, vnc_console_port) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (vid, uid, name, ost, ram, cpu, stor, sp, ssh_host, 'root', root_pw,
             network_mode, assigned_ip, private_ip, nid, vp, vp, 'creating', 'Queued — starting install…', 1,
             'kvm' if HAVE_KVM else 'tcg', nested_kvm,
             1 if is_iso else 0, vnc_console_port)
        )
        for fw in extra_list:
            try:
                db_execute(
                    "INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                    (vid, fw['host_port'], fw['guest_port'], 'tcp', f"{fw['host_port']}->{fw['guest_port']}")
                )
            except Exception:
                pass

        add_notification(uid, 'VM Creating...', f'VM "{name}" – SSH port: {sp}', 'info')
        audit(session['user_id'], 'create_vm', f'Created VM {name} ({vid[:8]}) on node {nid}')
        threading.Thread(target=complete_vm_setup,
                         args=(vid, ost, ram, cpu, stor, sp, vp, network_mode, assigned_ip, private_ip),
                         daemon=True).start()
        if ram_overcommit_warning:
            flash(ram_overcommit_warning, 'warning')
        if disk_overcommit_warning:
            flash(disk_overcommit_warning, 'danger')
        flash(f'VM "{name}" is being created!', 'success')
        return redirect(url_for('vm_installing', vm_id=vid))

    users = db_execute("SELECT id, username FROM users WHERE is_active=1 ORDER BY username", fetch=True) or []
    public_ips = db_execute("SELECT * FROM public_ips WHERE is_available=1 ORDER BY ip_address", fetch=True) or []
    nodes = db_execute("SELECT * FROM nodes ORDER BY is_local DESC, name", fetch=True) or []
    try:
        host_avail_ram_mb = int(psutil.virtual_memory().available / (1024 * 1024))
        host_free_disk_gb = int(shutil.disk_usage(str(VM_DIR)).free / (1024 ** 3))
    except Exception:
        host_avail_ram_mb = None
        host_free_disk_gb = None
    return render_template('create_vm.html',
                           os_templates=OS_TEMPLATES,
                           users=users,
                           public_ips=public_ips,
                           nodes=nodes,
                           have_kvm=HAVE_KVM,
                           host_avail_ram_mb=host_avail_ram_mb,
                           host_free_disk_gb=host_free_disk_gb)


@app.route('/vm/<vm_id>/progress')
@login_required
@vm_owner_or_admin
def vm_progress(vm_id):
    v = db_execute("SELECT vm_id, name, status, creation_progress, creation_step, created_at FROM vm_instances WHERE vm_id=?",
                   (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False}), 404
    running, pid = vm.vm_status(vm_id)
    prog = int(v['creation_progress'] or 0)
    step = v['creation_step'] or 'Pending'
    status = v['status'] or 'creating'
    if running and status == 'creating':
        status = 'running'
        prog = max(prog, 100)
    return jsonify({
        'success': True,
        'vm_id': v['vm_id'],
        'name': v['name'],
        'status': status,
        'progress': prog,
        'step': step,
        'running': running,
        'done': status in ('running', 'stopped', 'error') and prog >= 100,
        'error': status == 'error',
    })

@app.route('/vm/<vm_id>/installing')
@login_required
@vm_owner_or_admin
def vm_installing(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        flash('VM not found.', 'danger')
        return redirect(url_for('dashboard'))
    # If already ready, go to manage
    if v['status'] in ('running', 'stopped') and int(v['creation_progress'] or 0) >= 100:
        return redirect(url_for('manage_vm', vm_id=vm_id))
    kind = row_get(v, 'provision_kind')
    if kind == 'web' and _app_key(v):
        return render_template('installing_web.html', vm=v, kind='web', steps=[{'min': m, 'label': l} for m, l in [(0, 'Queued'), (20, 'Preparing'), (45, 'Downloading the app'), (75, 'Setting up your login'), (90, 'Starting'), (100, 'Ready')]])
    if kind == 'web':
        steps = [(0, 'Queued'), (10, 'Preparing site files'), (25, 'Downloading WordPress'),
                 (50, 'Downloading the database'), (70, 'Creating the site'), (85, 'Starting WordPress'), (100, 'Ready')]
        return render_template('installing_web.html', vm=v, kind='web',
                               steps=[{'min': m, 'label': l} for m, l in steps])
    if kind in _SERVER_KINDS:
        # Minecraft / Bot servers get their own setup page (no QEMU / cloud-init wording)
        if row_get(v, 'runtime') == 'docker':
            steps = [(0, 'Queued'), (10, 'Preparing server files'), (25, 'Downloading server image'),
                     (70, 'Creating the container'), (90, 'Starting the server' if kind == 'minecraft' else 'Finalizing'),
                     (100, 'Ready')]
        else:
            steps = [(0, 'Queued'), (5, 'Preparing workspace'), (60, 'Allocating storage'),
                     (70, 'Preparing Minecraft installer' if kind == 'minecraft' else 'Preparing bot hosting'),
                     (85, 'Booting the machine'), (100, 'Ready')]
        _rt = row_get(v, 'provision_opt') or ''
        return render_template('installing_minecraft.html' if kind == 'minecraft' else 'installing_bot.html',
                               vm=v, kind=kind, runtime=(_rt if _rt in ('node', 'python') else 'node'),
                               steps=[{'min': m, 'label': l} for m, l in steps])
    return render_template('installing.html', vm=v)

@app.route('/vm/<vm_id>/manage')
@login_required
@vm_owner_or_admin
def manage_vm(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if v and v['status'] == 'creating' and int(v['creation_progress'] or 0) < 100:
        return redirect(url_for('vm_installing', vm_id=vm_id))
    if v and row_get(v, 'provision_kind') == 'web':
        return redirect(url_for('web_panel', vm_id=vm_id))
    if v and row_get(v, 'provision_kind') in _SERVER_KINDS and (not request.args.get('advanced') or row_get(v, 'runtime') == 'docker'):
        return redirect(url_for('server_panel', vm_id=vm_id))
    node = None
    if v and v['node_id']:
        node = db_execute("SELECT * FROM nodes WHERE id=?", (v['node_id'],), fetchone=True)
    if node_is_remote(node):
        r, pid = node_client.status(node, vm_id)
        m = node_client.metrics(node, vm_id) if r else None
    else:
        r, pid = vm.vm_status(vm_id)
        m = vm.vm_metrics(pid) if r else None
    if m:
        sample_usage(vm_id, m)
    if v:
        check_vm_expiry_alerts(v)
    tmpl = get_os_templates().get(v['os_template'], {})
    fws = db_execute("SELECT * FROM port_forwards WHERE vm_id=? ORDER BY host_port", (vm_id,), fetch=True) or []
    snapshots = db_execute("SELECT * FROM vm_snapshots WHERE vm_id=? ORDER BY created_at DESC", (vm_id,), fetch=True) or []
    backups = db_execute("SELECT * FROM vm_backups WHERE vm_id=? ORDER BY created_at DESC", (vm_id,), fetch=True) or []
    usage_history = db_execute("SELECT * FROM usage_history WHERE vm_id=? ORDER BY id ASC", (vm_id,), fetch=True) or []
    return render_template('manage_vm.html', vm=v, is_running=r, metrics=m,
                           default_user=tmpl.get('default_user', 'ubuntu'),
                           port_forwards=fws, node=node, snapshots=snapshots,
                           backups=backups, bk_sched=db_execute("SELECT * FROM vm_backup_sched WHERE vm_id=?", (vm_id,), fetchone=True), usage_history=usage_history,
                           max_nat_ports=int(gsv('max_nat_ports_per_vm', 5) or 5))

# ═══════════════ Docker runtime (Pterodactyl-style Minecraft / Bot servers) ═══════════════
# Minecraft and Bot plans run as Docker containers instead of QEMU VMs: they start in
# seconds and use far less RAM. Each server gets a data directory on the host
# (DOCKER_SERVERS_DIR/<vm_id>) that is bind-mounted at /data in the container AND
# visible to the panel at the same path, so the file manager, plugins, backups and
# settings are plain local file operations. Console/power use the docker CLI.
# If Docker isn't reachable the panel silently falls back to the old VM flow.

DOCKER_SERVERS_DIR = Path(os.environ.get('PHVM_SERVERS_DIR', '/srv/phvm-servers'))
DK_BACKUP_DIR = DOCKER_SERVERS_DIR / '_backups'
_DK_IMAGES = {'node': 'node:20-bookworm', 'python': 'python:3.12-bookworm'}
_DK_MC_TYPES = {'paper': 'PAPER', 'purpur': 'PURPUR', 'vanilla': 'VANILLA', 'fabric': 'FABRIC', 'forge': 'FORGE',
                'neoforge': 'NEOFORGE', 'quilt': 'QUILT', 'modrinth': 'MODRINTH'}
_DK_MODDED = ('fabric', 'forge', 'neoforge', 'quilt', 'modrinth')
_dk_cache = {}
_dk_avail = {'t': 0.0, 'v': False}
_DK_TASKS = {}
_DK_ANSI = re.compile(r'\x1b\[[0-9;?]*[A-Za-z]')


def _docker(*args, timeout=60, stdin=None):
    try:
        r = subprocess.run(['docker'] + [str(a) for a in args], capture_output=True, text=True,
                           timeout=timeout, input=stdin)
        return r.returncode, r.stdout or '', r.stderr or ''
    except FileNotFoundError:
        return 127, '', 'docker CLI is not installed'
    except subprocess.TimeoutExpired:
        return 124, '', 'docker command timed out'


def docker_available():
    now = time.time()
    if now - _dk_avail['t'] < 30:
        return _dk_avail['v']
    rc, _, _ = _docker('info', '--format', '{{.ServerVersion}}', timeout=8)
    ok = rc == 0
    if ok:
        try:
            DK_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        except Exception:
            ok = False
    _dk_avail.update(t=now, v=ok)
    return ok


def _docker_enabled():
    return str(gsv('use_docker_servers', '1')) != '0' and docker_available()


def _is_docker_vm(vid):
    if not vid:
        return False
    now = time.time()
    hit = _dk_cache.get(vid)
    if hit and now - hit[0] < 10:
        return hit[1]
    try:
        # one query primes every server's runtime (was one SELECT per server on every list page)
        rows = db_execute("SELECT vm_id, runtime FROM vm_instances", fetch=True) or []
        for x in rows:
            _dk_cache[row_get(x, 'vm_id')] = (now, row_get(x, 'runtime') == 'docker')
    except Exception:
        pass
    hit = _dk_cache.get(vid)
    if hit and hit[0] == now:
        return hit[1]
    _dk_cache[vid] = (now, False)
    return False


def _cname(vid):
    return 'phvm-' + str(vid)


def _dk_dir(vid):
    return DOCKER_SERVERS_DIR / str(vid)


_dk_snap = {'t': 0, 'names': set()}
_dk_snap_lock = threading.Lock()


def dk_status_fast(vid):
    """List-page status: ONE `docker ps` (shared by every server, cached 2 s) instead of one `docker inspect` per
    server. Falls back to the exact per-container check if the batch call fails."""
    now = time.time()
    if now - _dk_snap['t'] > 2:
        with _dk_snap_lock:
            if time.time() - _dk_snap['t'] > 2:
                rc, out, _ = _docker('ps', '--format', '{{.Names}}', timeout=10)
                if rc != 0:
                    return dk_status(vid)
                _dk_snap['names'] = set(out.split())
                _dk_snap['t'] = time.time()
    return (True, 1) if _cname(vid) in _dk_snap['names'] else (False, None)


def dk_status(vid):
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}|{{.State.Pid}}', _cname(vid), timeout=10)
    if rc != 0:
        return False, None
    run, _, pid = out.strip().partition('|')
    if run != 'true':
        return False, None
    return True, (int(pid) if pid.isdigit() and int(pid) > 0 else 1)


def _dk_mc_unthrottle(vid):
    """Docker shows every player as the same address, so Bukkit's per-IP "Connection throttled! Please wait before
    reconnecting" (default 4 s) and the vanilla rate-limit kick players who join close together. Turn both off."""
    d = _dk_dir(vid)
    try:
        b = d / 'bukkit.yml'
        if b.exists():
            txt = b.read_text(encoding='utf-8', errors='replace')
            if re.search(r'^\s*connection-throttle:', txt, re.M):
                new = re.sub(r'^(\s*connection-throttle:).*$', r'\1 -1', txt, flags=re.M)
            elif re.search(r'^settings:\s*$', txt, re.M):
                new = re.sub(r'^settings:\s*$', 'settings:\n  connection-throttle: -1', txt, count=1, flags=re.M)
            else:
                new = txt.rstrip('\n') + '\nsettings:\n  connection-throttle: -1\n'
            if new != txt:
                b.write_text(new, encoding='utf-8')
        else:
            b.write_text('settings:\n  connection-throttle: -1\n', encoding='utf-8')
        _dk_chown(str(b), 1000, 1000)
        if (d / 'server.properties').exists():
            props = _dk_props_read(vid)
            if props.get('rate-limit', '0') != '0':
                _dk_props_write(vid, {'rate-limit': '0'})
    except Exception as e:
        print(f'[mc] unthrottle failed for {vid}: {e}', flush=True)


def dk_start(vid):
    vm._st.pop(vid, None)
    try:
        _kind = (_dk_row(vid) or {})
        if row_get(_kind, 'provision_kind') == 'minecraft':
            _dk_mc_unthrottle(vid)
    except Exception:
        pass
    if _web_is(vid):
        _docker('start', _cname(vid) + '-db', timeout=60)
    rc, _, err = _docker('start', _cname(vid), timeout=60)
    if rc != 0:
        vm._real.last_start_error = err.strip()[:300]
        return None
    return dk_status(vid)[1] or 1


def dk_stop(vid):
    vm._st.pop(vid, None)
    rc, _, _ = _docker('stop', '-t', '45', _cname(vid), timeout=90)
    if _web_is(vid):
        _docker('stop', '-t', '30', _cname(vid) + '-db', timeout=60)
    return rc == 0


# ---- local "SFTP" so the existing file manager works unchanged on server data dirs ----
class _OwnedFile:
    def __init__(self, f, path, uid, gid):
        self._f, self._path, self._uid, self._gid = f, path, uid, gid

    def __getattr__(self, n):
        return getattr(self._f, n)

    def __enter__(self):
        return self

    def __exit__(self, *a):
        self.close()

    def close(self):
        self._f.close()
        _dk_chown(self._path, self._uid, self._gid)


def _dk_chown(path, uid, gid):
    if uid is None:
        return
    try:
        os.chown(path, uid, gid if gid is not None else uid)
    except Exception:
        pass


class _LocalSFTP:
    def __init__(self, root, uid=None):
        self.root = os.path.realpath(str(root))
        self.uid = uid
        os.makedirs(self.root, exist_ok=True)

    def _p(self, path):
        rel = posixpath.normpath('/' + str(path or '/').lstrip('/')).lstrip('/')
        full = os.path.realpath(os.path.join(self.root, rel))
        if full != self.root and not full.startswith(self.root + os.sep):
            raise PermissionError('Outside the server directory')
        return full

    def listdir_attr(self, path):
        out = []
        with os.scandir(self._p(path)) as it:
            for e in it:
                st = e.stat(follow_symlinks=False)
                out.append(types.SimpleNamespace(filename=e.name, st_mode=st.st_mode, st_size=st.st_size, st_mtime=st.st_mtime))
        return out

    def stat(self, path):
        return os.stat(self._p(path))

    def lstat(self, path):
        full = self._p(os.path.dirname(str(path).rstrip('/')) or '/')
        return os.lstat(os.path.join(full, os.path.basename(str(path).rstrip('/')))) if os.path.basename(str(path).rstrip('/')) else os.lstat(full)

    def mkdir(self, path, mode=0o755):
        p = self._p(path)
        os.mkdir(p, mode)
        _dk_chown(p, self.uid, self.uid)

    def remove(self, path):
        os.remove(os.path.join(self._p(os.path.dirname(str(path).rstrip('/')) or '/'), os.path.basename(str(path).rstrip('/'))))

    def rmdir(self, path):
        os.rmdir(self._p(path))

    def posix_rename(self, src, dst):
        os.replace(self._p(src), self._p(dst))

    rename = posix_rename

    def chmod(self, path, mode):
        os.chmod(self._p(path), mode)

    def open(self, path, mode='r', *a, **k):
        p = self._p(path)
        binary = 'b' in mode
        f = open(p, mode, **({} if binary else {'encoding': 'utf-8'}))
        return _OwnedFile(f, p, self.uid, self.uid) if any(c in mode for c in 'wa') else f

    def putfo(self, fl, remotepath, *a, **k):
        p = self._p(remotepath)
        with open(p, 'wb') as out:
            shutil.copyfileobj(fl, out)
        _dk_chown(p, self.uid, self.uid)

    def getfo(self, remotepath, fl, *a, **k):
        with open(self._p(remotepath), 'rb') as src:
            shutil.copyfileobj(src, fl)

    def close(self):
        pass


def _dk_uid(v):
    kind = row_get(v, 'provision_kind')
    if kind == 'web':
        try:
            if (json.loads(row_get(v, 'provision_opt') or '{}') or {}).get('engine') == 'ols':
                return 65534                                                # OpenLiteSpeed runs PHP as nobody
        except Exception:
            pass
    if kind == 'web':
        _k = _app_key(v)
        if _k:
            return int(_APPS[_k].get('uid') or 0)
    return 1000 if kind == 'minecraft' else 33 if kind == 'web' else 0     # 33 = www-data (WordPress)


def _dk_chown_tree(path, uid):
    try:
        for root, dirs, files in os.walk(path):
            _dk_chown(root, uid, uid)
            for n in files:
                _dk_chown(os.path.join(root, n), uid, uid)
    except Exception:
        pass


# ---- background tasks (backup, version change, git deploy …) ----
def _dk_task(vid, label, fn):
    """Run fn(log) in a thread; the server page shows `label` as a busy banner and the log in the console."""
    t = _DK_TASKS.get(vid)
    if t and not t['done']:
        return False, 'Another task is still running — wait for it to finish.'
    state = {'label': label, 'log': [], 'done': False}
    _DK_TASKS[vid] = state

    def runner():
        try:
            fn(lambda m: state['log'].append(str(m)))
        except Exception as e:
            state['log'].append(f'FAILED: {e}')
        finally:
            state['done'] = True
    threading.Thread(target=runner, daemon=True).start()
    return True, label + ' started.'


def _dk_busy(vid):
    t = _DK_TASKS.get(vid)
    return t['label'] if t and not t['done'] else ''


# ---- container creation ----
def _dk_mc_image_tag(version, software=None):
    v = (version or 'latest').strip().lower()
    if v == 'latest':
        return 'java21' if software in _DK_MODDED else 'java25'   # mod loaders rarely support 26.x yet
    try:
        return 'java25' if int(v.split('.')[0]) >= 26 else 'java21'
    except ValueError:
        return 'java21'


def _dk_mc_create_args(vid, ram_mb, cores, host_port, opt):
    software = (opt.get('software') or 'paper').lower()
    software = software if software in _DK_MC_TYPES else 'paper'
    version = (opt.get('version') or 'latest').strip() or 'latest'
    if version.lower() != 'latest' and not _RE_VER.match(version):
        version = 'latest'
    heap = max(512, int(ram_mb) - 600)
    image = 'itzg/minecraft-server:' + _dk_mc_image_tag(version, software)
    args = ['create', '--name', _cname(vid), '--restart', 'unless-stopped', '--label', 'phvm=1',
            '--memory', f'{int(ram_mb)}m', '--memory-swap', f'{int(ram_mb)}m', '--cpus', str(max(1, int(cores))),
            '--log-opt', 'max-size=10m', '--log-opt', 'max-file=3',
            '-p', f'{host_port}:25565', '-v', f'{_dk_dir(vid)}:/data',
            '-e', 'EULA=TRUE', '-e', f'TYPE={_DK_MC_TYPES[software]}',
            '-e', 'VERSION=' + ('LATEST' if version.lower() == 'latest' else version),
            '-e', f'MEMORY={heap}M', '-e', f'INIT_MEMORY={min(heap, 512)}M', '-e', 'JVM_XX_OPTS=-XX:-AlwaysPreTouch', '-e', 'USE_AIKAR_FLAGS=true', '-e', 'ENABLE_RCON=true', '-e', 'TZ=UTC']
    if software == 'modrinth' and _RE_SLUG.match(str(opt.get('modpack') or '')):
        args += ['-e', 'MODRINTH_MODPACK=' + opt['modpack']]
    cracked = bool(opt['cracked']) if 'cracked' in opt else (gsv('mc_cracked_default', 'true') or 'true').lower() in ('1', 'true', 'yes')
    if cracked:     # offline mode: non-premium ("cracked") launchers can join; secure-profile would kick them on 1.19+
        args += ['-e', 'ONLINE_MODE=FALSE', '-e', 'ENFORCE_SECURE_PROFILE=false']
    elif opt.get('minekube'):
        args += ['-e', 'ENFORCE_SECURE_PROFILE=false']   # Minekube Connect needs this
    if opt.get('bedrock') and str(opt.get('bedrock_port') or '').isdigit():
        args += ['-p', f"{int(opt['bedrock_port'])}:19132/udp"]
    args.append(image)
    return image, args


def _dk_bot_script_text(command):
    return ("#!/bin/bash\ncd /data\n[ -f venv/bin/activate ] && . venv/bin/activate\n"
            "[ -f .env ] && { set -a; . ./.env; set +a; }\ntouch .console_in\n"
            "exec " + command + " < <(tail -F -n0 .console_in 2>/dev/null)\n")


def _dk_write_bot_script(vid, command):
    p = _dk_dir(vid) / '.phvm-start.sh'
    p.write_text(_dk_bot_script_text(command))
    p.chmod(0o755)


def _dk_bot_create_args(vid, ram_mb, cores, runtime):
    image = _DK_IMAGES.get(runtime, _DK_IMAGES['node'])
    return image, ['create', '--name', _cname(vid), '--restart', 'unless-stopped', '--init', '--label', 'phvm=1',
                   '--memory', f'{int(ram_mb)}m', '--memory-swap', f'{int(ram_mb)}m', '--cpus', str(max(1, int(cores))),
                   '--log-opt', 'max-size=10m', '--log-opt', 'max-file=3',
                   '-v', f'{_dk_dir(vid)}:/data', '-w', '/data', '-e', 'HOME=/data', image, 'bash', '/data/.phvm-start.sh']


def complete_docker_setup(vid, kind, opt):
    """Thread: prepare data dir, pull image, create (and for Minecraft start) the container."""
    try:
        v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
        d = _dk_dir(vid)
        d.mkdir(parents=True, exist_ok=True)
        uid = 1000 if kind == 'minecraft' else 0
        _dk_chown(str(d), uid, uid)
        vm.up(vid, 10, 'Preparing server files…')
        if kind == 'minecraft':
            opt = opt if isinstance(opt, dict) else {}
            fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (vid,), fetchone=True)
            image, args = _dk_mc_create_args(vid, v['ram_mb'], v['cpu_cores'], fw['host_port'] if fw else 25565, opt)
        else:
            runtime = opt if opt in ('node', 'python') else 'node'
            _dk_write_bot_script(vid, _bot_default_startup(runtime))
            image, args = _dk_bot_create_args(vid, v['ram_mb'], v['cpu_cores'], runtime)
        vm.up(vid, 25, f'Downloading {image} (the first server can take a few minutes)…')
        rc, out, err = _docker('pull', image, timeout=1800)
        if rc != 0:
            raise RuntimeError('image download failed: ' + (err or out).strip()[-200:])
        vm.up(vid, 70, 'Creating the container…')
        _docker('rm', '-f', _cname(vid), timeout=30)
        rc, out, err = _docker(*args, timeout=120)
        if rc != 0:
            raise RuntimeError('container create failed: ' + (err or out).strip()[-300:])
        if kind == 'minecraft':
            if (opt or {}).get('minekube') and ((opt or {}).get('software') or 'paper') in ('paper', 'purpur'):
                vm.up(vid, 80, 'Installing Minekube Connect…')
                try:
                    _dk_install_minekube(vid)
                except Exception as e:
                    print(f'[docker] minekube install failed for {vid}: {e}', flush=True)
            vm.up(vid, 90, 'Starting the server…')
            _dk_mc_unthrottle(vid)
            rc, out, err = _docker('start', _cname(vid), timeout=60)
            if rc != 0:
                raise RuntimeError('container start failed: ' + (err or out).strip()[-300:])
            step, status = 'Ready — the server is starting (first start downloads Minecraft)', 'running'
        else:
            step, status = 'Ready — upload your bot, set the startup command and press Start', 'stopped'
        db_execute("UPDATE vm_instances SET status=?, creation_progress=100, creation_step=? WHERE vm_id=?", (status, step, vid))
    except Exception as e:
        print(f"[docker] setup failed for {vid}: {e}", flush=True)
        db_execute("UPDATE vm_instances SET status='error', creation_step=? WHERE vm_id=?", (f'Docker setup failed: {e}'[:300], vid))


def _dk_cleanup(vid):
    """Remove container + data + backups of a Docker server (no-op for normal VMs)."""
    if not _is_docker_vm(vid):
        return
    if _web_is(vid):
        _web_cleanup(vid)
    _docker('rm', '-f', _cname(vid), timeout=60)
    _docker('rm', '-f', _cname(vid) + '-playit', timeout=30)
    for p in (_dk_dir(vid), DK_BACKUP_DIR / str(vid)):
        try:
            if str(p.resolve()).startswith(str(DOCKER_SERVERS_DIR.resolve())) and p.exists():
                shutil.rmtree(p, ignore_errors=True)
        except Exception:
            pass
    _dk_cache.pop(vid, None)
    _DK_TASKS.pop(vid, None)


def dk_dispatch(fn):
    """Route decorator: Docker servers go to DK_HANDLERS[<function name>] instead of the VM/SSH implementation."""
    @wraps(fn)
    def wrapper(vm_id, *a, **kw):
        if _is_docker_vm(vm_id):
            h = DK_HANDLERS.get(fn.__name__)
            if h:
                return h(vm_id, *a, **kw)
            return jsonify({'success': False, 'message': 'Not available for Docker servers.'})
        return fn(vm_id, *a, **kw)
    return wrapper


DK_HANDLERS = {}


# ═══════════════ Server panel (Pterodactyl-style Minecraft / Bot hosting) ═══════════════
# The VM is the "machine"; the game/bot server is a systemd service inside it
# (minecraft / phvm-bot) with its stdin wired to a FIFO so we can send console
# commands. Everything below talks to it over the VM's local SSH port.

_SERVER_KINDS = ('minecraft', 'bot')
_SERVER_SVC = {'minecraft': ('minecraft', '/root/mcserver'), 'bot': ('phvm-bot', '/root/bot')}

def _server_ctx(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    kind = row_get(v, 'provision_kind') if v else None
    if not v or kind not in _SERVER_KINDS:
        return None, None, 'This VM is not a Minecraft/Bot server.'
    if node_is_remote(get_vm_node(v)):
        return v, kind, 'Server panel is not available for VMs on remote nodes yet — use the Advanced VM page.'
    return v, kind, None

def _server_sh(v, cmd, timeout=25):
    return vm.ssh_exec(v['ssh_port'], cmd, password=v['ssh_password'] or '', host='127.0.0.1', timeout=timeout)

def _mc_direct_address(v):
    """Best address players can use right now: dedicated IP if the VM has one, else
    the admin-set Server IP (or the detected public IP) plus the forwarded port."""
    fws = db_execute("SELECT host_port, guest_port FROM port_forwards WHERE vm_id=?", (v['vm_id'],), fetch=True) or []
    mc_port = next((f['host_port'] for f in fws if f['guest_port'] == 25565), None)
    dedicated = row_get(v, 'public_ip')
    if dedicated:
        host, port = dedicated, 25565
    else:
        host = (gsv('server_ip', '') or '').strip() or row_get(v, 'ssh_host') or PUBLIC_IP
        port = mc_port
    if not host or not port or host == '127.0.0.1':
        return None
    return f"{host}:{int(port)}"

@app.route('/vm/<vm_id>/server')
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_panel(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if not v or kind not in _SERVER_KINDS:
        return redirect(url_for('manage_vm', vm_id=vm_id, advanced=1))
    running, _ = vm.vm_status(vm_id)
    return render_template('server.html', vm=v, kind=kind, is_running=running, svc_error=err,
                           files_path=_SERVER_SVC[kind][1], mc_address=(_mc_direct_address(v) if kind == 'minecraft' else None),
                           startup_cmd=row_get(v, 'startup_cmd') or '')

@app.route('/vm/<vm_id>/server/state')
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_state(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return jsonify({'success': False, 'message': err})
    running, _ = vm.vm_status(vm_id)
    if not running:
        return jsonify({'success': True, 'machine': False, 'installed': False, 'state': 'offline', 'console': False, 'logs': ''})
    svc = _SERVER_SVC[kind][0]
    out = _server_sh(v, (
        f'echo "@@done:$(test -f /root/phvm-provision-done && echo 1 || echo 0)"; '
        f'echo "@@active:$(systemctl is-active {svc} 2>/dev/null)"; '
        f'echo "@@console:$(test -p /run/{svc}.stdin && echo 1 || echo 0)"; '
        f'echo "@@busy:$(cat /root/.phvm-busy 2>/dev/null)"; '
        + ('echo "@@playit:$(systemctl is-active playit 2>/dev/null)"; '
           'echo "@@minekube:$(test -f /root/mcserver/plugins/connect-spigot.jar && echo 1 || echo 0)"; '
           'echo "@@playit_addr:$(journalctl -u playit -n 200 --no-pager -o cat 2>/dev/null | grep -Eo \'[A-Za-z0-9.-]+\\.(joinmc\\.link|ply\\.gg)(:[0-9]+)?\' | tail -1)"; '
           'echo "@@playit_claim:$(journalctl -u playit -n 200 --no-pager -o cat 2>/dev/null | grep -Eo \'https://playit\\.gg/claim/[A-Za-z0-9]+\' | tail -1)"; '
           'echo "@@mk_addr:$(journalctl -u minecraft -n 400 --no-pager -o cat 2>/dev/null | grep -Eo \'[A-Za-z0-9-]+\\.play\\.minekube\\.net\' | tail -1)"; '
           if kind == 'minecraft' else '') +
        f'echo "@@logs"; '
        f'if test -f /root/.phvm-busy; then echo "== $(cat /root/.phvm-busy) =="; tail -n 40 /root/phvm-task.log 2>/dev/null; echo "== server log =="; fi; '
        f'if test -f /root/phvm-provision-done; then journalctl -u {svc} -n 250 --no-pager -o cat 2>/dev/null; '
        f'else tail -n 60 /root/phvm-provision.log 2>/dev/null || echo "Waiting for the installer to start…"; fi'
    ))
    if '@@done:' not in out:
        return jsonify({'success': True, 'machine': True, 'installed': False, 'state': 'booting', 'console': False,
                        'logs': 'The machine is still booting — this can take a minute…'})
    head, _, logs = out.partition('@@logs\n')
    info = dict(l[2:].split(':', 1) for l in head.splitlines() if l.startswith('@@') and ':' in l)
    address, note = None, None
    if kind == 'minecraft':
        mk, pl = info.get('mk_addr', '').strip(), info.get('playit_addr', '').strip()
        if mk:
            address, note = mk, 'Minekube address'
        elif pl:
            address, note = pl, 'playit.gg address'
        elif (info.get('playit') or '').strip() == 'active' and info.get('playit_claim', '').strip():
            note = 'Claim your playit agent: ' + info['playit_claim'].strip()
        else:
            address = _mc_direct_address(v)
            note = 'Direct address' if address else 'Waiting for an address…'
    return jsonify({'success': True, 'machine': True, 'installed': info.get('done') == '1',
                    'state': (info.get('active') or 'inactive').strip(), 'console': info.get('console') == '1',
                    'logs': logs[-20000:], 'address': address, 'address_note': note,
                    'java_issue': ('requires running the server with Java' in logs or 'UnsupportedClassVersionError' in logs),
                    'busy': (info.get('busy') or '').strip()})

@app.route('/vm/<vm_id>/server/power', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_power(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return jsonify({'success': False, 'message': err})
    action = (request.get_json(silent=True) or {}).get('action', '')
    svc = _SERVER_SVC[kind][0]
    cmds = {
        'start': f'systemctl enable --now {svc}' if kind == 'bot' else f'systemctl start {svc}',
        'stop': f'systemctl stop {svc}',
        'restart': f'systemctl restart {svc}',
        'kill': f'systemctl kill -s SIGKILL {svc}',
    }
    if action not in cmds:
        return jsonify({'success': False, 'message': 'Unknown action.'})
    out = _server_sh(v, cmds[action], timeout=90)
    audit(session['user_id'], f'server_{action}', f'{vm_id} ({svc})')
    bad = out and any(w in out.lower() for w in ('failed', 'not found', 'connection', 'denied'))
    return jsonify({'success': not bad, 'message': (out or '').strip()[:300] or 'OK'})

@app.route('/vm/<vm_id>/server/command', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_command(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return jsonify({'success': False, 'message': err})
    cmd = ((request.get_json(silent=True) or {}).get('command') or '').strip()
    if not cmd or len(cmd) > 300 or '\n' in cmd or '\r' in cmd:
        return jsonify({'success': False, 'message': 'Enter a single-line command (max 300 chars).'})
    svc = _SERVER_SVC[kind][0]
    out = _server_sh(v, f'test -p /run/{svc}.stdin && printf "%s\\n" {shlex.quote(cmd)} > /run/{svc}.stdin && echo SENT || echo NOFIFO')
    if 'SENT' in out:
        return jsonify({'success': True})
    return jsonify({'success': False, 'message': 'Console input is not enabled on this server yet — use "Enable console".'})

@app.route('/vm/<vm_id>/server/enable-console', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_enable_console(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return jsonify({'success': False, 'message': err})
    svc = _SERVER_SVC[kind][0]
    was = _server_sh(v, f'systemctl is-active {svc} 2>/dev/null').strip()
    runtime = 'python' if 'python' in (_server_sh(v, 'test -d /root/bot/venv && echo python || echo node')) else 'node'
    script = _svc_install_script(kind, v['ram_mb'], runtime=runtime)
    if kind == 'bot' and row_get(v, 'startup_cmd'):
        script = _bot_start_script_cmd(v['startup_cmd']) + _svc_unit_block(
            'phvm-bot', '/root/bot', '/bin/bash /root/bot/.phvm-start.sh', f'PHvm Bot ({runtime})', restart='always')
    b64 = base64.b64encode((script + (f'systemctl restart {svc}\n' if was == 'active' else '')).encode()).decode()
    out = _server_sh(v, f'echo {b64} | base64 -d | bash', timeout=90)
    audit(session['user_id'], 'server_enable_console', vm_id)
    return jsonify({'success': True, 'message': (out or 'Console enabled.').strip()[:300]})

@app.route('/vm/<vm_id>/server/retry-install', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_retry_install(vm_id):
    """Re-run the (current) installer inside the VM — for installs that failed, e.g. a download error."""
    v, kind, err = _server_ctx(vm_id)
    if err:
        return jsonify({'success': False, 'message': err})
    if 'ok' in _server_sh(v, 'test -f /root/phvm-provision-done && echo ok || echo no'):
        return jsonify({'success': False, 'message': 'Already installed.'})
    try:
        opt = json.loads(row_get(v, 'provision_opt') or 'null')
    except Exception:
        opt = None
    if kind == 'minecraft':
        opt = opt if isinstance(opt, dict) else {}
        script = _build_minecraft_provision_script(opt.get('software') or 'paper', opt.get('version') or 'latest', v['ram_mb'],
                                                   use_playit=bool(opt.get('playit')), use_minekube=bool(opt.get('minekube')))
    else:
        runtime = opt if opt in ('node', 'python') else 'node'
        script = _build_bot_provision_script(runtime, v['ram_mb'])
    b64 = base64.b64encode(script.encode()).decode()
    out = _server_sh(v, f'echo {b64} | base64 -d > /root/phvm-provision.sh && '
                        f'(nohup bash /root/phvm-provision.sh > /root/phvm-provision.log 2>&1 &) ; echo STARTED')
    audit(session['user_id'], 'server_retry_install', vm_id)
    if 'STARTED' not in out:
        return jsonify({'success': False, 'message': 'Could not reach the machine — is it running?'})
    return jsonify({'success': True, 'message': 'Installer restarted. Watch the console for progress.'})

# ───────────── Minecraft extras: plugins, versions, icon, properties/MOTD, backups ─────────────
_MC_DIR = '/root/mcserver'
_HTTP_UA = 'PHvm-Panel/1.0 (Minecraft hosting panel)'
_http_cache = {}
_MC_DENY_PROPS = {'server-port', 'server-ip', 'query.port', 'rcon.port', 'rcon.password', 'enable-rcon',
                  'enable-query', 'enable-jmx-monitoring', 'management-server-enabled', 'management-server-port',
                  'management-server-secret'}
_RE_JAR = re.compile(r'^[A-Za-z0-9._()+\- ]{1,120}\.jar(\.disabled)?$')
_RE_SLUG = re.compile(r'^[A-Za-z0-9_\-]{1,64}$')
_RE_VER = re.compile(r'^[0-9A-Za-z.\-]{1,32}$')
_RE_BACKUP = re.compile(r'^[A-Za-z0-9._\-]{1,100}\.tgz$')

_PAPER_URL_PY = """import sys, json, urllib.request
base = 'https://fill.papermc.io/v3/projects/paper'
want = sys.argv[1]
def get(u):
    req = urllib.request.Request(u)
    req.add_header('User-Agent', 'PHvm-Panel/1.0')
    return json.load(urllib.request.urlopen(req, timeout=30))
builds = get(base + '/versions/' + want + '/builds')
stable = [b for b in builds if b.get('channel') == 'STABLE']
pick = stable or builds
if not pick:
    sys.exit('No Paper build found for ' + want)
print(pick[0]['downloads']['server:default']['url'])
"""

def _http_json(url, ttl=0, timeout=15):
    now = time.time()
    hit = _http_cache.get(url)
    if hit and now - hit[0] < ttl:
        return hit[1]
    req = urllib.request.Request(url, headers={'User-Agent': _HTTP_UA})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        data = json.loads(r.read().decode('utf-8'))
    if ttl:
        _http_cache[url] = (now, data)
    return data

def _mc_ctx(vm_id, need_machine=True):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return None, jsonify({'success': False, 'message': err})
    if kind != 'minecraft':
        return None, jsonify({'success': False, 'message': 'Minecraft servers only.'})
    if need_machine:
        running, _ = vm.vm_status(vm_id)
        if not running:
            return None, jsonify({'success': False, 'message': 'Power on the machine first.'})
    return v, None

def _mc_opt(v):
    try:
        o = json.loads(row_get(v, 'provision_opt') or 'null')
        return o if isinstance(o, dict) else {}
    except Exception:
        return {}

def _mc_version(v):
    out = _server_sh(v, "grep -h -m1 -Eo 'Starting minecraft server version [0-9][0-9.a-z-]*' "
                        + _MC_DIR + "/logs/latest.log 2>/dev/null | awk '{print $NF}'").strip()
    if out and _RE_VER.match(out.splitlines()[0]):
        return out.splitlines()[0]
    ver = (_mc_opt(v).get('version') or '').strip()
    return ver if ver and ver != 'latest' and _RE_VER.match(ver) else ''

def _mc_bg(v, label, script):
    """Run a long task inside the VM in the background; the state endpoint reports it as busy."""
    b64 = base64.b64encode(script.encode()).decode()
    cmd = ("test -f /root/.phvm-busy && echo BUSY || (echo " + b64 + " | base64 -d > /root/phvm-task.sh && echo "
           + shlex.quote(label) + " > /root/.phvm-busy && (nohup bash -c 'bash /root/phvm-task.sh > /root/phvm-task.log 2>&1; "
           "rm -f /root/.phvm-busy' >/dev/null 2>&1 &) ; echo STARTED)")
    out = _server_sh(v, cmd, timeout=40)
    if 'BUSY' in out:
        return False, 'Another task is still running — wait for it to finish.'
    if 'STARTED' not in out:
        return False, 'Could not reach the machine.'
    return True, label + ' started.'

@app.route('/vm/<vm_id>/server/mc/repair-java', methods=['POST'])
@login_required
@vm_owner_or_admin
def mc_repair_java(vm_id):
    """Fix 'requires Java N' start-up failures: install that Java, point start.sh at it, restart."""
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    heap = max(512, int(v['ram_mb'] or 1024) - 512)
    script = ("JM=$(journalctl -u minecraft -n 300 --no-pager -o cat 2>/dev/null | grep -Eo 'Java [0-9]+' | tail -1 | grep -Eo '[0-9]+')\n"
              "JM=${JM:-21}\n"
              "case \"$JM\" in 17|21|25) ;; *) JM=21 ;; esac\n"
              "echo \"Using Java $JM\"\n"
              "if [ ! -x /usr/lib/jvm/java-$JM-openjdk-amd64/bin/java ]; then apt-get update -y >/dev/null; apt-get install -y openjdk-$JM-jre-headless; fi\n"
              "mkdir -p " + _MC_DIR + "\necho $JM > " + _MC_DIR + "/.phvm-java\n"
              + _mc_start_sh_block(heap)
              + _svc_unit_block('minecraft', _MC_DIR, '/bin/bash /root/mcserver/start.sh', 'Minecraft Server')
              + "systemctl reset-failed minecraft 2>/dev/null || true\nsystemctl restart minecraft\necho 'Java repaired — server restarting'\n")
    ok, msg = _mc_bg(v, 'Repairing Java', script)
    if ok:
        audit(session['user_id'], 'mc_repair_java', vm_id)
    return jsonify({'success': ok, 'message': msg})

