@app.route('/vm/<vm_id>/server/mc/plugins')
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_plugins(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    out = _server_sh(v, 'cd ' + _MC_DIR + '/plugins 2>/dev/null && for f in *.jar *.jar.disabled; do '
                        '[ -f "$f" ] && echo "$f|$(stat -c %s "$f")"; done; true')
    items = []
    for line in out.splitlines():
        name, _, size = line.partition('|')
        if _RE_JAR.match(name) and size.strip().isdigit():
            items.append({'file': name, 'size': int(size), 'enabled': not name.endswith('.disabled')})
    return jsonify({'success': True, 'plugins': sorted(items, key=lambda x: x['file'].lower())})

@app.route('/vm/<vm_id>/server/mc/plugins/search')
@login_required
@vm_owner_or_admin
def mc_plugin_search(vm_id):
    v, bad = _mc_ctx(vm_id, need_machine=False)
    if bad:
        return bad
    q = (request.args.get('q') or '').strip()[:60]
    mcv = (request.args.get('mcv') or '').strip()
    facets = [["project_type:plugin"], ["categories:paper", "categories:spigot", "categories:bukkit", "categories:purpur"]]
    if mcv and _RE_VER.match(mcv):
        facets.append(["versions:" + mcv])
    url = 'https://api.modrinth.com/v2/search?' + urllib.parse.urlencode({
        'query': q, 'facets': json.dumps(facets), 'limit': 20, 'index': 'relevance' if q else 'downloads'})
    try:
        data = _http_json(url, ttl=120)
    except Exception as e:
        return jsonify({'success': False, 'message': f'Modrinth is unreachable: {e}'})
    hits = [{'slug': h.get('slug'), 'title': h.get('title'), 'description': h.get('description'),
             'icon': h.get('icon_url'), 'downloads': h.get('downloads'), 'author': h.get('author')}
            for h in data.get('hits', []) if h.get('slug')]
    return jsonify({'success': True, 'results': hits})

def _mc_resolve_plugin(slug, mcv):
    """Newest Modrinth release for this MC version (falls back to any version). -> (version_json, exact)"""
    base = 'https://api.modrinth.com/v2/project/' + urllib.parse.quote(slug, safe='') + '/version'
    loaders = json.dumps(['paper', 'spigot', 'bukkit', 'purpur'])
    for gv in ([mcv] if mcv else []) + [None]:
        q = {'loaders': loaders}
        if gv:
            q['game_versions'] = json.dumps([gv])
        vers = _http_json(base + '?' + urllib.parse.urlencode(q), ttl=60)
        vers = [x for x in vers if x.get('version_type') == 'release'] or vers
        if vers:
            return vers[0], bool(gv)
    return None, False

def _mc_plugin_file(ver):
    files = ver.get('files') or []
    f = next((x for x in files if x.get('primary')), files[0] if files else None)
    if not f:
        return None
    url, name = f.get('url') or '', f.get('filename') or ''
    if urllib.parse.urlparse(url).netloc != 'cdn.modrinth.com' or not _RE_JAR.match(name) or name.endswith('.disabled'):
        return None
    return url, name

@app.route('/vm/<vm_id>/server/mc/plugins/install', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_plugin_install(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    slug = ((request.get_json(silent=True) or {}).get('slug') or '').strip()
    if not _RE_SLUG.match(slug):
        return jsonify({'success': False, 'message': 'Invalid plugin.'})
    mcv = _mc_version(v)
    try:
        ver, exact = _mc_resolve_plugin(slug, mcv)
        if not ver:
            return jsonify({'success': False, 'message': 'No compatible download found for this plugin.'})
        todo = []
        main = _mc_plugin_file(ver)
        if not main:
            return jsonify({'success': False, 'message': 'This plugin has no safe downloadable file.'})
        todo.append(main)
        for d in ver.get('dependencies') or []:
            if d.get('dependency_type') == 'required' and d.get('project_id') and _RE_SLUG.match(d['project_id']):
                dv, _ = _mc_resolve_plugin(d['project_id'], mcv)
                df = _mc_plugin_file(dv) if dv else None
                if df:
                    todo.append(df)
    except Exception as e:
        return jsonify({'success': False, 'message': f'Modrinth error: {e}'})
    cmd = 'mkdir -p ' + _MC_DIR + '/plugins && cd ' + _MC_DIR + '/plugins && '
    for url, name in todo:
        cmd += ('test -f ' + shlex.quote(name) + ' || (curl -fsSL -A ' + shlex.quote(_HTTP_UA) + ' -o ' + shlex.quote(name + '.part')
                + ' ' + shlex.quote(url) + ' && mv ' + shlex.quote(name + '.part') + ' ' + shlex.quote(name) + ') && ')
    out = _server_sh(v, cmd + 'echo DONE', timeout=180)
    if 'DONE' not in out:
        return jsonify({'success': False, 'message': 'Download failed inside the machine: ' + out.strip()[-200:]})
    audit(session['user_id'], 'mc_plugin_install', f'{vm_id}: {slug}')
    names = ', '.join(n for _, n in todo)
    note = '' if exact or not mcv else f' (no build is tagged for {mcv}; installed the newest — it may not work)'
    return jsonify({'success': True, 'message': f'Installed {names}{note}. Restart the server to load it.'})

@app.route('/vm/<vm_id>/server/mc/plugins/manage', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_plugin_manage(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    name, action = d.get('file') or '', d.get('action')
    if not _RE_JAR.match(name) or action not in ('delete', 'toggle'):
        return jsonify({'success': False, 'message': 'Invalid request.'})
    p = _MC_DIR + '/plugins/' + name
    if action == 'delete':
        cmd = 'rm -f ' + shlex.quote(p) + ' && echo OK'
    elif name.endswith('.disabled'):
        cmd = 'mv ' + shlex.quote(p) + ' ' + shlex.quote(p[:-len('.disabled')]) + ' && echo OK'
    else:
        cmd = 'mv ' + shlex.quote(p) + ' ' + shlex.quote(p + '.disabled') + ' && echo OK'
    ok = 'OK' in _server_sh(v, cmd)
    audit(session['user_id'], 'mc_plugin_' + action, f'{vm_id}: {name}')
    return jsonify({'success': ok, 'message': 'Done. Restart the server to apply.' if ok else 'Failed.'})

# ---- versions ----
@app.route('/vm/<vm_id>/server/mc/versions')
@login_required
@vm_owner_or_admin
def mc_versions(vm_id):
    v, bad = _mc_ctx(vm_id, need_machine=False)
    if bad:
        return bad
    sw = request.args.get('software', 'paper')
    try:
        if sw == 'paper':
            d = _http_json('https://fill.papermc.io/v3/projects/paper', ttl=600)
            vers = [x for g in d['versions'].values() for x in g]
        elif sw == 'purpur':
            vers = list(reversed(_http_json('https://api.purpurmc.org/v2/purpur', ttl=600)['versions']))
        elif sw in ('vanilla', 'fabric', 'forge', 'neoforge', 'quilt'):
            d = _http_json('https://launchermeta.mojang.com/mc/game/version_manifest_v2.json', ttl=600)
            vers = [e['id'] for e in d['versions'] if e.get('type') == 'release']
        else:
            return jsonify({'success': False, 'message': 'Unknown software.'})
    except Exception as e:
        return jsonify({'success': False, 'message': f'Could not load versions: {e}'})
    vers = [x for x in vers if _RE_VER.match(x) and not re.search(r'(rc|pre|snapshot)', x, re.I)]
    return jsonify({'success': True, 'versions': vers[:60]})

def _mc_jar_block(software, ver):
    if software == 'paper':
        return ("cat > /tmp/phvm-paper-url.py << 'PYEOF'\n" + _PAPER_URL_PY + "PYEOF\n"
                'URL=$(python3 /tmp/phvm-paper-url.py "' + ver + '") || fail\n')
    if software == 'purpur':
        return 'URL="https://api.purpurmc.org/v2/purpur/' + ver + '/latest/download"\n'
    return ('MANIFEST=$(curl -fsSL https://launchermeta.mojang.com/mc/game/version_manifest_v2.json) || fail\n'
            'VURL=$(echo "$MANIFEST" | python3 -c "import sys,json\nd=json.load(sys.stdin)\n'
            'for e in d[\'versions\']:\n    if e[\'id\']==\'' + ver + '\':\n        print(e[\'url\']); break") || fail\n'
            'URL=$(curl -fsSL "$VURL" | python3 -c "import sys,json; print(json.load(sys.stdin)[\'downloads\'][\'server\'][\'url\'])") || fail\n')

@app.route('/vm/<vm_id>/server/mc/change-version', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_change_version(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    sw, ver, backup = d.get('software'), (d.get('version') or '').strip(), bool(d.get('backup', True))
    if sw not in ('paper', 'purpur', 'vanilla') or not _RE_VER.match(ver):
        return jsonify({'success': False, 'message': 'Pick a software and version.'})
    jm = _mc_java_major(ver)
    heap = max(512, int(v['ram_mb'] or 1024) - 512)
    script = ("cd " + _MC_DIR + "\n"
              "fail(){ echo 'FAILED — restoring the previous jar'; [ -f server.jar.bak ] && cp -f server.jar.bak server.jar; "
              "systemctl start minecraft; exit 1; }\n"
              + ("apt-get update -y >/dev/null; apt-get install -y openjdk-25-jre-headless || fail\n" if jm == 25 else "")
              + "systemctl stop minecraft || true\n"
              + ("mkdir -p /root/mc-backups\ntar czf /root/mc-backups/pre-update-$(date +%Y%m%d-%H%M%S).tgz "
                 "$(ls -d world world_nether world_the_end 2>/dev/null) 2>/dev/null || true\n" if backup else "")
              + "cp -f server.jar server.jar.bak 2>/dev/null || true\n"
              + _mc_jar_block(sw, ver)
              + 'curl -fsSL -A "PHvm-Panel/1.0" "$URL" -o server.jar.new || fail\n'
                'mv -f server.jar.new server.jar\n'
              + _mc_start_sh_block(heap)
              + _svc_unit_block('minecraft', _MC_DIR, '/bin/bash /root/mcserver/start.sh', 'Minecraft Server (' + sw + ')')
              + 'echo ' + str(jm) + ' > /root/mcserver/.phvm-java\nsystemctl start minecraft\necho "Updated to ' + sw + ' ' + ver + '"\n')
    ok, msg = _mc_bg(v, f'Changing version to {sw} {ver}', script)
    if ok:
        opt = _mc_opt(v)
        opt.update({'software': sw, 'version': ver})
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vm_id))
        audit(session['user_id'], 'mc_change_version', f'{vm_id}: {sw} {ver}')
    return jsonify({'success': ok, 'message': msg})

# ---- server icon ----
@app.route('/vm/<vm_id>/server/mc/icon', methods=['GET', 'POST', 'DELETE'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_icon(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    path = _MC_DIR + '/server-icon.png'
    if request.method == 'GET':
        out = _server_sh(v, 'base64 -w0 ' + path + ' 2>/dev/null').strip()
        try:
            raw = base64.b64decode(out, validate=True)
        except Exception:
            return ('', 404)
        return app.response_class(raw, mimetype='image/png', headers={'Cache-Control': 'no-store'})
    if request.method == 'DELETE':
        _server_sh(v, 'rm -f ' + path)
        return jsonify({'success': True, 'message': 'Icon removed. Restart the server to apply.'})
    data = (request.get_json(silent=True) or {}).get('png') or ''
    try:
        raw = base64.b64decode(data.split(',')[-1], validate=True)
    except Exception:
        return jsonify({'success': False, 'message': 'Invalid image.'})
    if not raw.startswith(b'\x89PNG\r\n\x1a\n') or len(raw) > 40000 or struct.unpack('>II', raw[16:24]) != (64, 64):
        return jsonify({'success': False, 'message': 'Icon must be a 64×64 PNG under 40 KB.'})
    out = _server_sh(v, 'echo ' + base64.b64encode(raw).decode() + ' | base64 -d > ' + path + ' && echo OK')
    audit(session['user_id'], 'mc_icon_set', vm_id)
    return jsonify({'success': 'OK' in out, 'message': 'Icon saved. Restart the server to apply.' if 'OK' in out else 'Could not write the icon.'})

# ---- server.properties (settings + MOTD) ----
@app.route('/vm/<vm_id>/server/mc/properties', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_properties(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    p = _MC_DIR + '/server.properties'
    if request.method == 'GET':
        out = _server_sh(v, 'head -c 30000 ' + p + ' 2>/dev/null')
        props = {}
        for line in out.splitlines():
            if line and not line.startswith('#') and '=' in line:
                k, _, val = line.partition('=')
                props[k.strip()] = val
        return jsonify({'success': True, 'props': props, 'exists': bool(props)})
    ch = (request.get_json(silent=True) or {}).get('changes')
    if not isinstance(ch, dict) or not ch or len(ch) > 60:
        return jsonify({'success': False, 'message': 'Nothing to save.'})
    clean = {}
    for k, val in ch.items():
        val = '' if val is None else str(val)
        if (not re.match(r'^[a-z0-9.\-]{1,60}$', k) or k in _MC_DENY_PROPS or len(val) > 500
                or not val.isascii() or any(ord(c) < 32 for c in val)):
            return jsonify({'success': False, 'message': f'Not allowed: {k}'})
        clean[k] = val
    payload = base64.b64encode(json.dumps(clean).encode()).decode()
    script = ("import json,base64,re\np='" + p + "'\nch=json.loads(base64.b64decode('" + payload + "'))\n"
              "try:\n    lines=open(p,encoding='utf-8').read().splitlines()\nexcept FileNotFoundError:\n    lines=[]\n"
              "done=set(); out=[]\nfor l in lines:\n    m=re.match(r'^([A-Za-z0-9.\\-]+)=', l)\n"
              "    if m and m.group(1) in ch:\n        out.append(m.group(1)+'='+ch[m.group(1)]); done.add(m.group(1))\n"
              "    else:\n        out.append(l)\nfor k,x in ch.items():\n    if k not in done:\n        out.append(k+'='+x)\n"
              "open(p,'w',encoding='utf-8').write('\\n'.join(out)+'\\n')\nprint('OK')\n")
    out = _server_sh(v, 'echo ' + base64.b64encode(script.encode()).decode() + ' | base64 -d | python3 -')
    audit(session['user_id'], 'mc_properties', f'{vm_id}: {", ".join(clean)[:120]}')
    return jsonify({'success': 'OK' in out, 'message': 'Saved. Restart the server to apply.' if 'OK' in out else 'Could not save.'})

# ---- world backups ----
@app.route('/vm/<vm_id>/server/mc/backups')
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_backups(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    out = _server_sh(v, 'cd /root/mc-backups 2>/dev/null && for f in $(ls -1t *.tgz 2>/dev/null); do '
                        'echo "$f|$(stat -c %s "$f")|$(stat -c %Y "$f")"; done; '
                        'echo "@@free|$(df -m --output=avail / | tail -1 | tr -d " ")"; true')
    items, free = [], None
    for line in out.splitlines():
        parts = line.split('|')
        if parts[0] == '@@free' and len(parts) > 1 and parts[1].strip().isdigit():
            free = int(parts[1])
        elif len(parts) == 3 and _RE_BACKUP.match(parts[0]) and parts[1].isdigit() and parts[2].isdigit():
            items.append({'file': parts[0], 'size': int(parts[1]), 'time': int(parts[2])})
    return jsonify({'success': True, 'backups': items, 'free_mb': free})

@app.route('/vm/<vm_id>/server/mc/backups/<action>', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_backup_action(vm_id, action):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    name = (request.get_json(silent=True) or {}).get('file') or ''
    if action == 'create':
        script = ("mkdir -p /root/mc-backups\ncd " + _MC_DIR + "\nF=/run/minecraft.stdin\n"
                  "if systemctl is-active --quiet minecraft && [ -p $F ]; then\n"
                  "  timeout 3 sh -c \"echo 'save-off' > $F\" || true\n  timeout 3 sh -c \"echo 'save-all flush' > $F\" || true\n  sleep 6\nfi\n"
                  "tar czf /root/mc-backups/backup-$(date +%Y%m%d-%H%M%S).tgz $(ls -d world world_nether world_the_end plugins server.properties 2>/dev/null) || true\n"
                  "[ -p $F ] && timeout 3 sh -c \"echo 'save-on' > $F\" || true\necho 'Backup finished'\n")
        ok, msg = _mc_bg(v, 'Creating backup', script)
    elif action in ('restore', 'delete') and _RE_BACKUP.match(name):
        if action == 'delete':
            out = _server_sh(v, 'rm -f ' + shlex.quote('/root/mc-backups/' + name) + ' && echo OK')
            ok, msg = 'OK' in out, 'Backup deleted.'
        else:
            script = ("cd " + _MC_DIR + "\nsystemctl stop minecraft || true\nrm -rf world world_nether world_the_end\n"
                      "tar xzf " + shlex.quote('/root/mc-backups/' + name) + " -C " + _MC_DIR + "\nsystemctl start minecraft\necho 'Restore finished'\n")
            ok, msg = _mc_bg(v, 'Restoring ' + name, script)
    else:
        return jsonify({'success': False, 'message': 'Invalid request.'})
    audit(session['user_id'], 'mc_backup_' + action, f'{vm_id}: {name}')
    return jsonify({'success': ok, 'message': msg})

# ───────────── Players, schedules (Minecraft) and bot setup ─────────────
_RE_PLAYER = re.compile(r'^[A-Za-z0-9_]{1,16}$')
_RE_GIT_URL = re.compile(r'^https://(github\.com|gitlab\.com|bitbucket\.org)/[A-Za-z0-9._\-]+/[A-Za-z0-9._\-]+?(\.git)?/?$')
_RE_BRANCH = re.compile(r'^[A-Za-z0-9._/\-]{1,60}$')

def _svc_send(v, svc, line):
    """Write one console line to a service's stdin FIFO. Returns True if delivered."""
    out = _server_sh(v, f'test -p /run/{svc}.stdin && systemctl is-active --quiet {svc} && '
                        f'printf "%s\\n" {shlex.quote(line)} > /run/{svc}.stdin && echo SENT || echo NO')
    return 'SENT' in out

@app.route('/vm/<vm_id>/server/mc/players')
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_players(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    out = _server_sh(v, (
        "cd " + _MC_DIR + "; "
        "if [ -p /run/minecraft.stdin ] && systemctl is-active --quiet minecraft; then "
        "timeout 3 sh -c 'echo list > /run/minecraft.stdin'; sleep 1.3; fi; "
        "echo '@@online'; journalctl -u minecraft -n 80 --no-pager -o cat 2>/dev/null | "
        "grep -E 'There are [0-9]+ of a max of [0-9]+ players online' | tail -1; "
        "for f in whitelist ops banned-players; do echo \"@@$f\"; head -c 30000 $f.json 2>/dev/null; echo; done"))
    secs, cur = {}, None
    for line in out.splitlines():
        if line.startswith('@@'):
            cur = line[2:].strip(); secs[cur] = []
        elif cur:
            secs[cur].append(line)
    online = {'count': 0, 'max': None, 'names': []}
    m = re.search(r'There are (\d+) of a max of (\d+) players online:?\s*(.*)', '\n'.join(secs.get('online', [])))
    if m:
        online = {'count': int(m.group(1)), 'max': int(m.group(2)),
                  'names': [n.strip() for n in m.group(3).split(',') if _RE_PLAYER.match(n.strip())]}
    def _names(key, extra=None):
        try:
            data = json.loads('\n'.join(secs.get(key, [])) or '[]')
        except Exception:
            data = []
        res = []
        for e in data if isinstance(data, list) else []:
            if isinstance(e, dict) and _RE_PLAYER.match(str(e.get('name', ''))):
                res.append({'name': e['name'], **({extra: e.get(extra)} if extra else {})})
        return res
    return jsonify({'success': True, 'online': online, 'whitelist': _names('whitelist'),
                    'ops': _names('ops', 'level'), 'bans': _names('banned-players', 'reason')})

@app.route('/vm/<vm_id>/server/mc/players/action', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_players_action(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    act, name = d.get('action'), (d.get('name') or '').strip()
    reason = re.sub(r'[\r\n]', ' ', (d.get('reason') or '').strip())[:80]
    cmds = {'whitelist-add': 'whitelist add ', 'whitelist-remove': 'whitelist remove ', 'op': 'op ', 'deop': 'deop ',
            'ban': 'ban ', 'pardon': 'pardon ', 'kick': 'kick '}
    if act not in cmds or not _RE_PLAYER.match(name):
        return jsonify({'success': False, 'message': 'Enter a valid Java username (3-16 letters, numbers, _).'})
    line = cmds[act] + name + (' ' + reason if act in ('ban', 'kick') and reason else '')
    if not _svc_send(v, 'minecraft', line):
        return jsonify({'success': False, 'message': 'The server must be running with console enabled for this.'})
    audit(session['user_id'], 'mc_player_' + act, f'{vm_id}: {name}')
    return jsonify({'success': True, 'message': 'Sent.'})

@app.route('/vm/<vm_id>/server/mc/schedule', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def mc_schedule(vm_id):
    v, bad = _mc_ctx(vm_id)
    if bad:
        return bad
    cfgp = '/root/.phvm-schedule.json'
    if request.method == 'GET':
        out = _server_sh(v, 'cat ' + cfgp + ' 2>/dev/null')
        try:
            cfg = json.loads(out)
        except Exception:
            cfg = {}
        return jsonify({'success': True, 'config': {'restart_hours': int(cfg.get('restart_hours', 0)),
                        'backup_hour': int(cfg.get('backup_hour', -1)), 'keep': int(cfg.get('keep', 5))}})
    d = request.get_json(silent=True) or {}
    try:
        rh, bh, keep = int(d.get('restart_hours', 0)), int(d.get('backup_hour', -1)), int(d.get('keep', 5))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Invalid values.'})
    if rh not in (0, 3, 6, 12, 24) or not -1 <= bh <= 23 or not 1 <= keep <= 30:
        return jsonify({'success': False, 'message': 'Invalid values.'})
    cfg_json = json.dumps({'restart_hours': rh, 'backup_hour': bh, 'keep': keep})
    restart_sh = ("#!/bin/bash\nF=/run/minecraft.stdin\nif [ -p $F ] && systemctl is-active --quiet minecraft; then\n"
                  "  timeout 3 sh -c \"echo 'say Server restarting in 60 seconds!' > $F\"; sleep 30\n"
                  "  timeout 3 sh -c \"echo 'say Restarting in 30 seconds...' > $F\"; sleep 20\n"
                  "  timeout 3 sh -c \"echo 'say Restarting in 10 seconds...' > $F\"; sleep 10\n"
                  "  timeout 3 sh -c \"echo 'save-all flush' > $F\"; sleep 4\nfi\nsystemctl restart minecraft\n")
    backup_sh = ("#!/bin/bash\nmkdir -p /root/mc-backups\ncd " + _MC_DIR + "\nF=/run/minecraft.stdin\n"
                 "if [ -p $F ] && systemctl is-active --quiet minecraft; then\n"
                 "  timeout 3 sh -c \"echo 'save-off' > $F\"; timeout 3 sh -c \"echo 'save-all flush' > $F\"; sleep 6\nfi\n"
                 "tar czf /root/mc-backups/auto-$(date +%Y%m%d-%H%M%S).tgz $(ls -d world world_nether world_the_end plugins server.properties 2>/dev/null)\n"
                 "[ -p $F ] && timeout 3 sh -c \"echo 'save-on' > $F\"\n"
                 f"ls -1t /root/mc-backups/auto-*.tgz 2>/dev/null | tail -n +{keep + 1} | xargs -r rm -f\n")
    cron = "SHELL=/bin/bash\nPATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\n"
    if rh:
        cron += ("0 4 * * * root /root/phvm-restart.sh\n" if rh == 24 else f"0 */{rh} * * * root /root/phvm-restart.sh\n")
    if bh >= 0:
        cron += f"30 {bh} * * * root /root/phvm-backup.sh\n"
    def w(path, text, mode='644'):
        return ('echo ' + base64.b64encode(text.encode()).decode() + ' | base64 -d > ' + path + ' && chmod ' + mode + ' ' + path + '\n')
    script = ('set -e\n(command -v cron >/dev/null 2>&1 || (apt-get update -y >/dev/null && apt-get install -y cron >/dev/null))\n'
              + w('/root/phvm-restart.sh', restart_sh, '755') + w('/root/phvm-backup.sh', backup_sh, '755')
              + w('/root/.phvm-schedule.json', cfg_json) + w('/etc/cron.d/phvm-mc', cron)
              + 'systemctl enable --now cron >/dev/null 2>&1 || true\necho OK\n')
    out = _server_sh(v, 'echo ' + base64.b64encode(script.encode()).decode() + ' | base64 -d | bash', timeout=150)
    audit(session['user_id'], 'mc_schedule', f'{vm_id}: restart={rh}h backup={bh}')
    return jsonify({'success': 'OK' in out, 'message': 'Schedule saved.' if 'OK' in out else 'Could not save: ' + out.strip()[-160:]})

# ---- bot setup: env vars, dependencies, git deploy ----
def _bot_ctx(vm_id, need_machine=True):
    v, kind, err = _server_ctx(vm_id)
    if err:
        return None, jsonify({'success': False, 'message': err})
    if kind != 'bot':
        return None, jsonify({'success': False, 'message': 'Bot servers only.'})
    if need_machine and not vm.vm_status(vm_id)[0]:
        return None, jsonify({'success': False, 'message': 'Power on the machine first.'})
    return v, None

@app.route('/vm/<vm_id>/server/bot/setup', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def bot_setup(vm_id):
    v, bad = _bot_ctx(vm_id)
    if bad:
        return bad
    if request.method == 'GET':
        out = _server_sh(v, 'echo "@@git"; cat /root/bot/.phvm-git 2>/dev/null; echo; echo "@@env"; head -c 12000 /root/bot/.env 2>/dev/null')
        git, _, env = out.partition('@@env\n')
        return jsonify({'success': True, 'env': env, 'git': git.replace('@@git\n', '').strip()})
    env = (request.get_json(silent=True) or {}).get('env', '')
    if not isinstance(env, str) or len(env) > 10000 or '\x00' in env:
        return jsonify({'success': False, 'message': 'Invalid environment text.'})
    runtime = 'python' if 'python' in _server_sh(v, 'test -d /root/bot/venv && echo python || echo node') else 'node'
    start = _bot_start_script_cmd(row_get(v, 'startup_cmd') or _bot_default_startup(runtime))
    cmd = (start + 'echo ' + base64.b64encode(env.encode()).decode() + ' | base64 -d > /root/bot/.env && chmod 600 /root/bot/.env && echo OK')
    out = _server_sh(v, cmd)
    audit(session['user_id'], 'bot_env_save', vm_id)
    return jsonify({'success': 'OK' in out, 'message': 'Saved. Restart the bot to use the new values.' if 'OK' in out else 'Could not save.'})

_BOT_DEPS_SH = ("cd /root/bot\n"
                "if [ -f package.json ]; then echo '== npm install =='; npm install --omit=dev --no-audit --no-fund; fi\n"
                "if [ -f requirements.txt ]; then echo '== pip install =='; [ -f venv/bin/activate ] || python3 -m venv venv; . venv/bin/activate; pip install -r requirements.txt; fi\n"
                "echo 'Dependencies done'\n")

@app.route('/vm/<vm_id>/server/bot/install-deps', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def bot_install_deps(vm_id):
    v, bad = _bot_ctx(vm_id)
    if bad:
        return bad
    ok, msg = _mc_bg(v, 'Installing dependencies', _BOT_DEPS_SH)
    if ok:
        audit(session['user_id'], 'bot_install_deps', vm_id)
    return jsonify({'success': ok, 'message': msg})

@app.route('/vm/<vm_id>/server/bot/git-deploy', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def bot_git_deploy(vm_id):
    v, bad = _bot_ctx(vm_id)
    if bad:
        return bad
    d = request.get_json(silent=True) or {}
    url, branch = (d.get('url') or '').strip(), (d.get('branch') or '').strip()
    if not _RE_GIT_URL.match(url) or (branch and not _RE_BRANCH.match(branch)):
        return jsonify({'success': False, 'message': 'Use a public https URL from GitHub, GitLab or Bitbucket.'})
    b = ('-b ' + shlex.quote(branch) + ' ') if branch else ''
    script = ("set -e\ncommand -v git >/dev/null 2>&1 || (apt-get update -y && apt-get install -y git)\n"
              "rm -rf /root/bot-tmp\ngit clone --depth 1 " + b + shlex.quote(url) + " /root/bot-tmp\nrm -rf /root/bot-tmp/.git\n"
              "mkdir -p /root/bot\ncp -a /root/bot-tmp/. /root/bot/\nrm -rf /root/bot-tmp\n"
              "echo " + shlex.quote(url + '|' + branch) + " > /root/bot/.phvm-git\n" + _BOT_DEPS_SH
              + "systemctl is-active --quiet phvm-bot && systemctl restart phvm-bot || true\necho 'Deploy finished'\n")
    ok, msg = _mc_bg(v, 'Deploying from Git', script)
    if ok:
        audit(session['user_id'], 'bot_git_deploy', f'{vm_id}: {url}')
    return jsonify({'success': ok, 'message': msg})

@app.route('/vm/<vm_id>/server/startup', methods=['POST'])
@login_required
@vm_owner_or_admin
@dk_dispatch
def server_startup(vm_id):
    v, kind, err = _server_ctx(vm_id)
    if err or kind != 'bot':
        return jsonify({'success': False, 'message': err or 'Only bot servers have a startup command.'})
    cmd = ((request.get_json(silent=True) or {}).get('command') or '').strip()
    if not cmd or len(cmd) > 300 or '\n' in cmd or '\r' in cmd:
        return jsonify({'success': False, 'message': 'Enter a single-line command (max 300 chars).'})
    out = _server_sh(v, _bot_start_script_cmd(cmd) + 'echo SAVED')
    if 'SAVED' not in out:
        return jsonify({'success': False, 'message': 'Could not save — is the machine running?'})
    db_execute("UPDATE vm_instances SET startup_cmd=? WHERE vm_id=?", (cmd, vm_id))
    audit(session['user_id'], 'server_startup_cmd', f'{vm_id}: {cmd[:80]}')
    return jsonify({'success': True, 'message': 'Saved. Restart the server to use it.'})


@app.route('/vm/<vm_id>/security-scan', methods=['POST'])
@login_required
@vm_owner_or_admin
def vm_security_scan(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'ok': False, 'error': 'VM not found'}), 404
    running, _ = vm.vm_status(vm_id)
