@app.route('/vm/<vm_id>/serial/connect', methods=['POST'])
@login_required
@vm_owner_or_admin
def serial_connect(vm_id):
    _reap_stale_serial_sessions()
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    running, _ = vm.vm_status(vm_id)
    if not running:
        return jsonify({'success': False, 'message': 'VM is not running. Start it first.'})
    port = row_get(v, 'serial_port') or row_get(v, 'vnc_port')
    if not port:
        return jsonify({'success': False, 'message': 'No serial port configured for this VM.'})
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(4)
        sock.connect(('127.0.0.1', int(port)))
        sock.settimeout(0.1)
    except Exception as e:
        return jsonify({'success': False, 'message': f'Could not reach serial console on port {port}: {e}'})
    session_id = str(uuid.uuid4())
    serial_sessions[session_id] = {
        'sock': sock, 'created': time.time(), 'last_active': time.time(),
        'user_id': session.get('user_id'), 'vm_id': vm_id,
        'decoder': codecs.getincrementaldecoder('utf-8')(errors='replace'),
    }
    # Give the guest a moment, then grab whatever's already buffered
    # (e.g. it re-attaches to an already-booted VM with backlog output).
    time.sleep(0.2)
    raw = b''
    try:
        for _ in range(5):
            try:
                chunk = sock.recv(8192)
                if not chunk:
                    break
                raw += chunk
            except (socket.timeout, BlockingIOError):
                break
    except Exception:
        pass
    output = serial_sessions[session_id]['decoder'].decode(strip_telnet_iac(raw))
    return jsonify({'success': True, 'session': session_id, 'output': output})

@app.route('/vm/<vm_id>/serial/read', methods=['POST'])
@login_required
@vm_owner_or_admin
def serial_read(vm_id):
    data = request.json or {}
    session_id = data.get('session')
    if session_id not in serial_sessions:
        return jsonify({'output': '', 'closed': True})
    sess = serial_sessions[session_id]
    if sess.get('user_id') != session.get('user_id') or sess.get('vm_id') != safe_vm_id(vm_id):
        return jsonify({'output': '', 'closed': True, 'error': 'forbidden'}), 403
    sess['last_active'] = time.time()
    sock = sess['sock']
    raw = b''
    closed = False
    try:
        for _ in range(5):
            try:
                chunk = sock.recv(8192)
                if not chunk:
                    closed = True
                    break
                raw += chunk
            except socket.timeout:
                break
            except BlockingIOError:
                break
            time.sleep(0.04)
    except Exception:
        closed = True
    output = sess['decoder'].decode(strip_telnet_iac(raw))
    if closed:
        try:
            sock.close()
        except Exception:
            pass
        serial_sessions.pop(session_id, None)
    return jsonify({'output': output, 'closed': closed})

