@app.route('/vm/<vm_id>/terminal/connect', methods=['POST'])
@login_required
@vm_owner_or_admin
def terminal_connect(vm_id):
    _v0 = db_execute("SELECT runtime FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if _v0 and row_get(_v0, 'runtime') == 'docker':
        _reap_stale_terminal_sessions()
        return _terminal_connect_docker(vm_id, _v0)
    if not HAVE_PARAMIKO:
        return jsonify({'success': False, 'message': 'paramiko not installed'})
    _reap_stale_terminal_sessions()
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    running, _ = vm.vm_status(vm_id)
    if not running:
        return jsonify({'success': False, 'message': 'VM is not running. Start it first.'})
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    is_iso = bool(row_get(v, 'is_iso'))
    vnc_console_port = row_get(v, 'vnc_console_port')
    custom_creds = bool((data.get('username') or '').strip() or (data.get('password') or '').strip())
    username = (data.get('username') or '').strip() or (v['ssh_user'] if v else 'root') or 'root'
    password = data.get('password') if data.get('password') is not None else ((v['ssh_password'] if v else '') or '')
    # public_ip is display-only (no real bridge on this host — see README);
    # the guest is only actually reachable via the hostfwd on 127.0.0.1:ssh_port.
    ssh_host = data.get('host') or '127.0.0.1'
    port = int(data.get('port', v['ssh_port'] if v else 22))

    # ISO-installer templates (Proxmox VE etc.) boot into a manual GUI/TUI
    # installer — there's no cloud-init, so we never actually know the root
    # password until the person types one into that installer over VNC.
    # If nobody has supplied real credentials yet, retrying SSH for two
    # minutes is pointless (the port may not even be listening yet, or
    # worse, will just keep rejecting whatever placeholder password we
    # have) — say so immediately instead of stalling with a cloud-init
    # message that doesn't apply here.
    if is_iso and not custom_creds and not (v['ssh_password'] if v else ''):
        vnc_hint = f' via VNC on {ssh_host}:{vnc_console_port}' if vnc_console_port else ' via VNC'
        return jsonify({
            'success': False,
            'auth_failed': True,
            'message': (f'This is a manual installer template — finish setup{vnc_hint} first '
                        f'(choose your own root password there), then enter that username/password '
                        f'in the credentials box below and connect again.')
        })

    last_err = None
    max_attempts = 30  # ~2 minutes total — cloud-init can take a while without KVM
    for attempt in range(max_attempts):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(
                ssh_host, port=port, username=username, password=password,
                look_for_keys=False, allow_agent=False, timeout=8,
                banner_timeout=15, auth_timeout=15
            )
            # Credentials worked — remember them so the next visit to this
            # page (or an is_iso VM whose password we never had) doesn't
            # need them typed in again.
            if v and (username != (v['ssh_user'] or '') or password != (v['ssh_password'] or '')):
                db_execute("UPDATE vm_instances SET ssh_user=?, ssh_password=? WHERE vm_id=?",
                           (username, password, vm_id))
            init_cols = max(10, min(500, int(data.get('cols', 140) or 140)))
            init_rows = max(5, min(200, int(data.get('rows', 40) or 40)))
            channel = ssh.invoke_shell(term='xterm-256color', width=init_cols, height=init_rows)
            channel.settimeout(0.1)
            session_id = str(uuid.uuid4())
            terminal_sessions[session_id] = {
                'ssh': ssh, 'channel': channel, 'created': time.time(), 'last_active': time.time(),
                'user_id': session.get('user_id'), 'vm_id': vm_id,
                'decoder': codecs.getincrementaldecoder('utf-8')(errors='replace'),
            }
            output = ''
            try:
                raw = b''
                deadline = time.time() + 0.3
                got_any = False
                while time.time() < deadline:
                    if channel.recv_ready():
                        raw += channel.recv(8192)
                        got_any = True
                        time.sleep(0.005)
                        continue
                    if got_any:
                        break
                    time.sleep(0.02)
                output = terminal_sessions[session_id]['decoder'].decode(raw)
            except Exception:
                pass
            return jsonify({'success': True, 'session': session_id, 'output': output})
        except paramiko.AuthenticationException:
            # Wrong username/password — the port is open and SSH is answering,
            # so retrying the same credentials for two minutes will never
            # succeed. Fail immediately with an actionable message instead.
            hint = ''
            if is_iso:
                vnc_hint = f' on {ssh_host}:{vnc_console_port}' if vnc_console_port else ''
                hint = (f' If you haven\'t finished the installer yet, connect via VNC{vnc_hint} and set a root '
                        f'password there first — then enter it in the credentials box below.')
            return jsonify({
                'success': False,
                'auth_failed': True,
                'message': f'Authentication failed for {username}@{ssh_host}:{port} — wrong username or password.{hint}'
            })
        except Exception as e:
            last_err = str(e)
            time.sleep(1.5 if attempt < 5 else 3)  # quick retries early, then back off
    iso_note = ''
    if is_iso:
        vnc_hint = f' via VNC on {ssh_host}:{vnc_console_port}' if vnc_console_port else ' via VNC'
        iso_note = f' This is a manual installer template — make sure you\'ve finished setup{vnc_hint}.'
    return jsonify({
        'success': False,
        'message': f'SSH still not ready after ~2 minutes: {last_err}. '
                   f'On a host without KVM (software emulation), cloud-init + package installs can take '
                   f'several minutes on first boot — check Web Console for boot progress, then retry.{iso_note}'
    })



def _chan_wait(ch, timeout):
    """Sleep until the channel has data (wakes within ~0 ms of it arriving) or `timeout` seconds pass."""
    try:
        if ch.recv_ready():
            return True
        import select
        r, _, _ = select.select([ch], [], [], max(0.0, timeout))
        return bool(r) or ch.recv_ready()
    except Exception:
        time.sleep(min(max(timeout, 0.0), 0.004))
        try:
            return ch.recv_ready()
        except Exception:
            return False


@app.route('/vm/<vm_id>/terminal/read', methods=['POST'])
@login_required
@vm_owner_or_admin
def terminal_read(vm_id):
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    session_id = data.get('session')
    session_id = session_id if isinstance(session_id, str) else ''
    if session_id not in terminal_sessions:
        return jsonify({'output': '', 'closed': True})
    sess = terminal_sessions[session_id]
    if sess.get('user_id') != session.get('user_id') or sess.get('vm_id') != safe_vm_id(vm_id):
        return jsonify({'output': '', 'closed': True, 'error': 'forbidden'}), 403
    sess['last_active'] = time.time()
    channel = sess['channel']
    if 'decoder' not in sess:
        sess['decoder'] = codecs.getincrementaldecoder('utf-8')(errors='replace')
    try:
        wait = min(max(float(data.get('wait', 0.0) or 0.0), 0.0), 1.5)   # long-poll: answer the moment output exists
    except (TypeError, ValueError):
        wait = 0.0
    output = ''
    try:
        raw = b''
        if _chan_wait(channel, wait if wait else 0.02):
            while True:
                if channel.recv_ready():
                    raw += channel.recv(65536)
                if len(raw) > 1048576 or not _chan_wait(channel, 0.0008):   # grab a burst that is right behind it
                    break
        output = sess['decoder'].decode(raw)
        if channel.closed and not raw:
            try:
                sess['ssh'].close()
            except Exception:
                pass
            terminal_sessions.pop(session_id, None)
            return jsonify({'output': output, 'closed': True})
    except Exception:
        try:
            sess['ssh'].close()
        except Exception:
            pass
        terminal_sessions.pop(session_id, None)
        return jsonify({'output': '', 'closed': True})
    return jsonify({'output': output, 'closed': False})

