@app.route('/vm/<vm_id>/files/read', methods=['POST'])
@login_required
@vm_owner_or_admin
def files_read(vm_id):
    v, err = _file_manager_precheck(vm_id)
    if err:
        return err
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    path = safe_remote_path(data.get('path', ''))
    try:
        with sftp_connect(v) as sftp:
            attr = sftp.stat(path)
            if stat.S_ISDIR(attr.st_mode or 0):
                return jsonify({'success': False, 'message': 'That is a folder'}), 400
            if (attr.st_size or 0) > FILE_MANAGER_TEXT_MAX:
                return jsonify({'success': False, 'message': 'File is too large to edit in the browser (2MB max)'}), 400
            with sftp.open(path, 'rb') as f:
                raw = f.read()
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError:
            return jsonify({'success': False, 'message': 'File is not plain text — download it instead'}), 400
        return jsonify({'success': True, 'content': text})
    except FileNotFoundError:
        return jsonify({'success': False, 'message': 'Path not found'}), 404
    except Exception as e:
        return jsonify({'success': False, 'message': f'Read failed: {e}'}), 502


@app.route('/vm/<vm_id>/files/write', methods=['POST'])
@login_required
@vm_owner_or_admin
def files_write(vm_id):
    v, err = _file_manager_precheck(vm_id)
    if err:
        return err
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    path = safe_remote_path(data.get('path', ''))
    content = data.get('content', '')
    if not isinstance(content, str):
        return jsonify({'success': False, 'message': 'Invalid content'}), 400
    if len(content.encode('utf-8')) > FILE_MANAGER_TEXT_MAX:
        return jsonify({'success': False, 'message': 'Content too large (2MB max)'}), 400
    try:
        with sftp_connect(v) as sftp:
            with sftp.open(path, 'w') as f:
                f.write(content)
        return jsonify({'success': True})
    except Exception as e:
        return jsonify({'success': False, 'message': f'Save failed: {e}'}), 502


@app.route('/vm/<vm_id>/files/upload', methods=['POST'])
@login_required
@vm_owner_or_admin
def files_upload(vm_id):
    v, err = _file_manager_precheck(vm_id)
    if err:
        return err
    path = safe_remote_path(request.form.get('path', '/'))
    files = [f for f in request.files.getlist('file') if f and f.filename]
    if not files:
        return jsonify({'success': False, 'message': 'No file selected'}), 400
    done, failed = [], []
    try:
        with sftp_connect(v) as sftp:
            for file in files:
                filename = secure_filename(file.filename)
                if not filename:
                    failed.append(file.filename)
                    continue
                dest = posixpath.join(path, filename)
                try:
                    sftp.putfo(file.stream, dest)
                    done.append(dest)
                except Exception as e:
                    failed.append(f'{filename}: {e}')
    except Exception as e:
        return jsonify({'success': False, 'message': f'Upload failed: {e}'}), 502
    if failed and not done:
        return jsonify({'success': False, 'message': 'Upload failed: ' + '; '.join(failed)[:300]}), 502
    msg = f'Uploaded {len(done)} file(s)' + (f'; failed: {"; ".join(failed)[:200]}' if failed else '')
    return jsonify({'success': True, 'path': done[0] if done else None, 'uploaded': len(done), 'message': msg})


# ---- archive helpers: zip / extract (runs a small python script locally, or inside the VM over SSH) ----
_FM_ARCHIVE_SCRIPT = r'''
import sys, os, json, zipfile, tarfile, shutil
a = json.loads(sys.argv[1])
root = os.path.realpath(a.get('root') or '/')
uid = a.get('uid')
def out(ok, msg):
    print('@@FM@@' + json.dumps({'success': ok, 'message': msg})); sys.exit(0)
def inside(p, base=None):
    base = os.path.realpath(base or root).rstrip('/')
    rp = os.path.realpath(p)
    return rp == base or rp.startswith(base + '/') or base == ''
def own(p):
    if uid is None: return
    try:
        os.chown(p, uid, uid)
        for dp, dns, fns in os.walk(p):
            for n in dns + fns:
                try: os.chown(os.path.join(dp, n), uid, uid)
                except Exception: pass
    except Exception: pass
MAX_BYTES, MAX_FILES = 8 * 1024 ** 3, 300000
try:
    if a['mode'] == 'zip':
        dest = a['out']
        if not inside(os.path.dirname(dest)): out(False, 'Outside the server directory')
        n = 0
        rd = os.path.realpath(dest)
        with zipfile.ZipFile(dest, 'w', zipfile.ZIP_DEFLATED, allowZip64=True) as z:
            for src in a['paths']:
                if not inside(os.path.dirname(src.rstrip('/'))) or not os.path.lexists(src): continue
                base = os.path.dirname(src.rstrip('/'))
                if os.path.isdir(src) and not os.path.islink(src):
                    for dp, dns, fns in os.walk(src):
                        arc = os.path.relpath(dp, base)
                        if not dns and not fns: z.write(dp, arc + '/')
                        for fn in fns:
                            fp = os.path.join(dp, fn)
                            if os.path.realpath(fp) == rd or os.path.islink(fp): continue
                            z.write(fp, os.path.join(arc, fn)); n += 1
                elif os.path.realpath(src) != rd and not os.path.islink(src):
                    z.write(src, os.path.basename(src)); n += 1
        own(dest)
        out(True, 'Created %s (%d files)' % (os.path.basename(dest), n))
    elif a['mode'] == 'extract':
        src, dest = a['path'], a['dest']
        if not (inside(src) and inside(dest)): out(False, 'Outside the server directory')
        os.makedirs(dest, exist_ok=True)
        d = os.path.realpath(dest)
        def target(name):
            t = os.path.realpath(os.path.join(d, name))
            if not (t == d or t.startswith(d.rstrip('/') + '/')): raise ValueError('Unsafe path in archive: ' + name)
            return t
        tops, count = set(), 0
        low = src.lower()
        if low.endswith('.zip'):
            with zipfile.ZipFile(src) as z:
                infos = z.infolist()
                if len(infos) > MAX_FILES or sum(i.file_size for i in infos) > MAX_BYTES: raise ValueError('Archive is too large')
                for i in infos:
                    t = target(i.filename); tops.add(i.filename.split('/')[0])
                    if i.is_dir(): os.makedirs(t, exist_ok=True); continue
                    os.makedirs(os.path.dirname(t), exist_ok=True)
                    with z.open(i) as s_, open(t, 'wb') as o_: shutil.copyfileobj(s_, o_)
                    count += 1
        elif low.endswith(('.tar', '.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.tar.xz', '.txz')):
            with tarfile.open(src) as tf:
                mem = tf.getmembers()
                if len(mem) > MAX_FILES or sum(m.size for m in mem if m.isfile()) > MAX_BYTES: raise ValueError('Archive is too large')
                for m in mem:
                    if not (m.isfile() or m.isdir()): continue
                    t = target(m.name); tops.add(m.name.lstrip('./').split('/')[0])
                    if m.isdir(): os.makedirs(t, exist_ok=True); continue
                    os.makedirs(os.path.dirname(t), exist_ok=True)
                    with tf.extractfile(m) as s_, open(t, 'wb') as o_: shutil.copyfileobj(s_, o_)
                    count += 1
        else:
            out(False, 'Unsupported archive type (use .zip, .tar, .tar.gz, .tgz, .tar.bz2, .tar.xz)')
        for t in tops:
            if t: own(os.path.join(d, t))
        out(True, 'Extracted %d files' % count)
    out(False, 'Unknown mode')
except SystemExit:
    raise
except Exception as e:
    out(False, str(e)[:300])
'''


def _fm_real(v, vpath):
    """(real path, root, uid) for a file-manager path. Docker servers live in their data dir; VMs use the guest filesystem."""
    if row_get(v, 'runtime') == 'docker':
        sf = _LocalSFTP(DOCKER_SERVERS_DIR / v['vm_id'], uid=_dk_uid(v))
        return sf._p(vpath), sf.root, _dk_uid(v)
    return vpath, '/', None


def _fm_run_archive(v, spec):
    js = json.dumps(spec)
    if row_get(v, 'runtime') == 'docker':
        r = subprocess.run([sys.executable, '-I', '-c', _FM_ARCHIVE_SCRIPT, js], capture_output=True, text=True, timeout=1800)
        outp = (r.stdout or '') + (r.stderr or '')
    else:
        outp = vm.ssh_exec(v['ssh_port'], 'python3 -c ' + shlex.quote(_FM_ARCHIVE_SCRIPT) + ' ' + shlex.quote(js),
                           password=v['ssh_password'] or '', user=(row_get(v, 'ssh_user') or 'root'), timeout=1800)
    for line in str(outp).splitlines()[::-1]:
        if line.startswith('@@FM@@'):
            return json.loads(line[6:])
    return {'success': False, 'message': 'Could not run the archive tool (python3 is needed): ' + str(outp).strip()[-200:]}


def _fm_clean_names(names):
    out = []
    for n in names or []:
        n = str(n)
        if n and '/' not in n and n not in ('.', '..') and '\x00' not in n:
            out.append(n)
    return out


@app.route('/vm/<vm_id>/files/zip', methods=['POST'])
@login_required
@vm_owner_or_admin
def files_zip(vm_id):
    v, err = _file_manager_precheck(vm_id)
    if err:
        return err
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    cwd = safe_remote_path(data.get('path', '/'))
    names = _fm_clean_names(data.get('names'))
    if not names:
        return jsonify({'success': False, 'message': 'Select at least one file or folder'}), 400
    base = (secure_filename(str(data.get('out') or '')) or (names[0] if len(names) == 1 else 'archive-' + datetime.now().strftime('%Y%m%d-%H%M%S')))
    base = re.sub(r'\.zip$', '', base, flags=re.I)
    try:
        with sftp_connect(v) as sftp:
            existing = {e.filename for e in sftp.listdir_attr(cwd)}
        out_name, i = base + '.zip', 1
        while out_name in existing:
            i += 1
            out_name = f'{base}-{i}.zip'
        real_cwd, root, uid = _fm_real(v, cwd)
        res = _fm_run_archive(v, {'mode': 'zip', 'root': root, 'uid': uid, 'out': posixpath.join(real_cwd, out_name),
                                  'paths': [posixpath.join(real_cwd, n) for n in names]})
        res['name'] = out_name
        audit(session['user_id'], 'files_zip', f'{vm_id[:8]} {cwd} {out_name}')
        return jsonify(res), (200 if res.get('success') else 400)
    except Exception as e:
        return jsonify({'success': False, 'message': f'Zip failed: {e}'}), 502


@app.route('/vm/<vm_id>/files/extract', methods=['POST'])
@login_required
@vm_owner_or_admin
def files_extract(vm_id):
    v, err = _file_manager_precheck(vm_id)
    if err:
        return err
    data = request.get_json(silent=True)
    data = data if isinstance(data, dict) else {}
    src = safe_remote_path(data.get('path', ''))
    if src == '/':
        return jsonify({'success': False, 'message': 'Pick an archive'}), 400
    folder = bool(data.get('to_folder'))
    parent = posixpath.dirname(src.rstrip('/')) or '/'
    dest = parent
    if folder:
        stem = re.sub(r'(\.tar\.(gz|bz2|xz)|\.tgz|\.tbz2|\.txz|\.tar|\.zip)$', '', posixpath.basename(src), flags=re.I) or 'extracted'
        dest = posixpath.join(parent, stem)
    try:
        real_src, root, uid = _fm_real(v, src)
        real_dest, _, _ = _fm_real(v, dest)
        res = _fm_run_archive(v, {'mode': 'extract', 'root': root, 'uid': uid, 'path': real_src, 'dest': real_dest})
        audit(session['user_id'], 'files_extract', f'{vm_id[:8]} {src}')
        return jsonify(res), (200 if res.get('success') else 400)
    except Exception as e:
        return jsonify({'success': False, 'message': f'Extract failed: {e}'}), 502


@app.route('/vm/<vm_id>/files/download')
@login_required
@vm_owner_or_admin
def files_download(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        flash('VM not found.', 'danger')
        return redirect(url_for('dashboard'))
    running, _ = vm.vm_status(vm_id)
    if not running and not _is_docker_vm(vm_id):
        flash('VM is not running.', 'danger')
        return redirect(url_for('file_manager', vm_id=vm_id))
    path = safe_remote_path(request.args.get('path', ''))
    try:
        with sftp_connect(v) as sftp:
            attr = sftp.stat(path)
            if stat.S_ISDIR(attr.st_mode or 0):
                flash('Cannot download a folder.', 'danger')
                return redirect(url_for('file_manager', vm_id=vm_id, path=path))
            buf = io.BytesIO()
            sftp.getfo(path, buf)
        buf.seek(0)
        filename = posixpath.basename(path) or 'download'
        return send_file(buf, as_attachment=True, download_name=filename)
    except Exception as e:
        flash(f'Download failed: {e}', 'danger')
        return redirect(url_for('file_manager', vm_id=vm_id))


@app.route('/vm/<vm_id>/start')
@login_required
@vm_owner_or_admin
def start_vm_route(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    if (row_get(v, 'status') or '') == 'creating' and int(row_get(v, 'creation_progress') or 0) < 100:
        return jsonify({'success': False, 'message': 'Still installing — wait until ready'})

    node = get_vm_node(v)
    fws = db_execute("SELECT host_port, guest_port, protocol FROM port_forwards WHERE vm_id=?", (vm_id,), fetch=True) or []
    extra = [dict(r) for r in fws]
    nested = bool(row_get(v, 'nested_kvm') or 0)
    sp = int(row_get(v, 'ssh_port') or 0)
    serial = row_get(v, 'serial_port') or row_get(v, 'vnc_port')

    if node_is_remote(node):
        r, _ = node_client.status(node, vm_id)
        if r:
            return jsonify({'success': False, 'message': 'Already running'})
        res = node_client.start_vm(node, vm_id, v['ram_mb'], v['cpu_cores'], sp, serial, nested, extra)
        if res.get('success'):
            db_execute("UPDATE vm_instances SET status='running', pid=NULL WHERE vm_id=?", (vm_id,))
            _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
            audit(session['user_id'], 'start_vm', vm_id)
            return jsonify({'success': True, 'message': 'Started'})
        return jsonify({'success': False, 'message': res.get('message') or 'Failed to start on node'})

    r, _ = vm.vm_status(vm_id)
    if r:
        return jsonify({'success': False, 'message': 'Already running'})
    if sp and sp != 22:
        subprocess.run(['fuser', '-k', f'{sp}/tcp'], capture_output=True)
    time.sleep(0.5)
    pid = vm.start_vm(
        vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
        sp, serial,
        row_get(v, 'network_mode') or 'private',
        row_get(v, 'public_ip'),
        row_get(v, 'private_ip'),
        extra, nested,
        is_iso=bool(row_get(v, 'is_iso')), vnc_port=row_get(v, 'vnc_console_port'),
        bridge_ip=get_vm_bridge_ip(vm_id),
    )
    if pid:
        db_execute("UPDATE vm_instances SET status='running', pid=? WHERE vm_id=?", (pid, vm_id))
        _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
        audit(session['user_id'], 'start_vm', vm_id)
        return jsonify({'success': True, 'message': 'Started'})
    err = getattr(vm, 'last_start_error', None) or 'Failed to start — check host has qemu-system-x86 and VM disk exists'
    return jsonify({'success': False, 'message': err})


@app.route('/vm/<vm_id>/stop')
@login_required
@vm_owner_or_admin
def stop_vm_route(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    node = get_vm_node(v)

    if node_is_remote(node):
        r, _ = node_client.status(node, vm_id)
        if not r:
            return jsonify({'success': False, 'message': 'Not running'})
        res = node_client.stop_vm(node, vm_id)
        if res.get('success'):
            db_execute("UPDATE vm_instances SET status='stopped', pid=NULL WHERE vm_id=?", (vm_id,))
            audit(session['user_id'], 'stop_vm', vm_id)
            return jsonify({'success': True, 'message': 'Stopped'})
        return jsonify({'success': False, 'message': res.get('message') or 'Node could not stop the VM'})

    r, pid = vm.vm_status(vm_id)
    if not r:
        return jsonify({'success': False, 'message': 'Not running'})
    if vm.stop_vm(pid, v['ssh_port'], vid=vm_id):
        db_execute("UPDATE vm_instances SET status='stopped', pid=NULL WHERE vm_id=?", (vm_id,))
        audit(session['user_id'], 'stop_vm', vm_id)
        return jsonify({'success': True, 'message': 'Stopped'})
    return jsonify({'success': False, 'message': 'The VM process would not terminate — try again or contact an admin.'})

@app.route('/vm/<vm_id>/restart')
@login_required
@vm_owner_or_admin
def restart_vm_route(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    node = get_vm_node(v)
    fws = db_execute("SELECT host_port, guest_port, protocol FROM port_forwards WHERE vm_id=?", (vm_id,), fetch=True) or []
    extra = [dict(r) for r in fws]
    nested = bool(row_get(v, 'nested_kvm') or 0)
    sp = int(row_get(v, 'ssh_port') or 0)
    serial = row_get(v, 'serial_port') or row_get(v, 'vnc_port')

    if node_is_remote(node):
        r, _ = node_client.status(node, vm_id)
        if r:
            node_client.stop_vm(node, vm_id)
            time.sleep(2)
        res = node_client.start_vm(node, vm_id, v['ram_mb'], v['cpu_cores'], sp, serial, nested, extra)
        if res.get('success'):
            db_execute("UPDATE vm_instances SET status='running', pid=NULL WHERE vm_id=?", (vm_id,))
            _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
            audit(session['user_id'], 'restart_vm', vm_id)
            return jsonify({'success': True, 'message': 'Restarted!'})
        return jsonify({'success': False, 'message': res.get('message') or 'Failed to restart on node'})

    r, pid = vm.vm_status(vm_id)
    if r:
        vm.stop_vm(pid, row_get(v, 'ssh_port'), vid=vm_id)
        time.sleep(2)
    if sp and sp != 22:
        subprocess.run(['fuser', '-k', f'{sp}/tcp'], capture_output=True)
    time.sleep(0.5)
    np = vm.start_vm(
        vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
        sp, serial,
        row_get(v, 'network_mode') or 'private',
        row_get(v, 'public_ip'),
        row_get(v, 'private_ip'),
        extra, nested,
        is_iso=bool(row_get(v, 'is_iso')), vnc_port=row_get(v, 'vnc_console_port'),
        bridge_ip=get_vm_bridge_ip(vm_id),
    )
    if np:
        db_execute("UPDATE vm_instances SET status='running', pid=? WHERE vm_id=?", (np, vm_id))
        _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
        audit(session['user_id'], 'restart_vm', vm_id)
        return jsonify({'success': True, 'message': 'Restarted!'})
    return jsonify({'success': False, 'message': 'Failed to restart'})



@app.route('/vm/<vm_id>/reinstall', methods=['POST', 'GET'])
@admin_required
def reinstall_vm_route(vm_id):
    """Wipe disk + cloud-init and redeploy same specs (fresh install)."""
    vm_id = safe_vm_id(vm_id)
    if not vm_id:
        return jsonify({'success': False, 'message': 'Invalid VM id'})
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'VM not found'})
    node = get_vm_node(v)

    if node_is_remote(node):
        r, _ = node_client.status(node, vm_id)
        if r:
            node_client.stop_vm(node, vm_id)
            time.sleep(1)
        node_client.delete_vm(node, vm_id)  # wipes the node-side disk dir
        root_pw = generate_vm_password(12)
        db_execute(
            "UPDATE vm_instances SET status='creating', creation_progress=1, creation_step=?, "
            "ssh_password=?, pid=NULL WHERE vm_id=?",
            ('Reinstall queued…', root_pw, vm_id)
        )
        threading.Thread(
            target=complete_vm_setup,
            args=(
                vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
                v['ssh_port'], row_get(v, 'serial_port') or row_get(v, 'vnc_port'),
                row_get(v, 'network_mode') or 'private',
                row_get(v, 'public_ip'), row_get(v, 'private_ip'),
            ),
            daemon=True,
        ).start()
        audit(session['user_id'], 'reinstall_vm', f'Reinstall {v["name"]} ({vm_id[:8]}) on node {node["name"]}')
        if request.is_json or 'application/json' in (request.headers.get('Accept') or ''):
            return jsonify({'success': True, 'message': 'Reinstall started', 'redirect': url_for('vm_installing', vm_id=vm_id)})
        flash('Reinstall started.', 'success')
        return redirect(url_for('vm_installing', vm_id=vm_id))

    if _is_docker_vm(vm_id):
        return jsonify({'success': False, 'message': 'Docker servers cannot be reinstalled — restore a backup, or delete and buy again.'})
    running, pid = vm.vm_status(vm_id)
    if running:
        vm.stop_vm(pid, row_get(v, 'ssh_port'), vid=vm_id)
        time.sleep(1)
    try:
        d = (VM_DIR / vm_id).resolve()
        if str(d).startswith(str(VM_DIR.resolve())) and d.exists():
            shutil.rmtree(d, ignore_errors=True)
        d.mkdir(parents=True, exist_ok=True)
        db_execute("DELETE FROM vm_snapshots WHERE vm_id=?", (vm_id,))  # disk was wiped, old internal snapshots no longer exist
    except Exception as e:
        return jsonify({'success': False, 'message': f'Wipe failed: {e}'})
    root_pw = generate_vm_password(12)
    db_execute(
        "UPDATE vm_instances SET status='creating', creation_progress=1, creation_step=?, "
        "ssh_password=?, pid=NULL WHERE vm_id=?",
        ('Reinstall queued…', root_pw, vm_id)
    )
    threading.Thread(
        target=complete_vm_setup,
        args=(
            vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
            v['ssh_port'], row_get(v, 'serial_port') or row_get(v, 'vnc_port'),
            row_get(v, 'network_mode') or 'private',
            row_get(v, 'public_ip'), row_get(v, 'private_ip'),
        ),
        daemon=True,
    ).start()
    audit(session['user_id'], 'reinstall_vm', f'Reinstall {v["name"]} ({vm_id[:8]})')
    if request.is_json or 'application/json' in (request.headers.get('Accept') or ''):
        return jsonify({'success': True, 'message': 'Reinstall started', 'redirect': url_for('vm_installing', vm_id=vm_id)})
    flash('Reinstall started.', 'success')
    return redirect(url_for('vm_installing', vm_id=vm_id))


@app.route('/vm/<vm_id>/delete')
@admin_required
def delete_vm_route(vm_id):
    vm_id = safe_vm_id(vm_id)
    if not vm_id:
        return jsonify({'success': False, 'message': 'Invalid VM id'})
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return jsonify({'success': False, 'message': 'Not found'})
    node = get_vm_node(v)
    _dk_cleanup(vm_id)

    if node_is_remote(node):
        node_client.stop_vm(node, vm_id)
        node_client.delete_vm(node, vm_id)
    else:
        r, pid = vm.vm_status(vm_id)
        if r:
            vm.stop_vm(pid, v['ssh_port'], vid=vm_id)
        try:
            d = (VM_DIR / vm_id).resolve()
            if str(d).startswith(str(VM_DIR.resolve())) and d.exists():
                shutil.rmtree(d, ignore_errors=True)
        except Exception:
            pass

    if v['public_ip']:
        db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL WHERE ip_address=?",
                   (v['public_ip'],))

    dedicated = db_execute("SELECT * FROM public_ips WHERE assigned_vm_id=?", (vm_id,), fetchone=True)
    if dedicated and dedicated['bridge_ip']:
        unbind_dedicated_ip(dedicated['ip_address'], dedicated['bridge_ip'])
        teardown_vm_tap(vm_id)
        db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL, bridge_ip=NULL, bound=0 WHERE id=?",
                   (dedicated['id'],))

    # Backups live in a separate top-level directory (BACKUP_DIR), not under
    # VM_DIR/<vid> — so deleting the VM's own folder above never touched
    # them. Left alone, every deleted VM's backup files (each potentially
    # several GB) just sit on disk forever, invisible in the UI (nothing
    # lists backups for a VM that no longer exists) until the host quietly
    # runs low on space.
    orphaned_backups = db_execute("SELECT filename FROM vm_backups WHERE vm_id=?", (vm_id,), fetch=True) or []
    for b in orphaned_backups:
        try:
            (BACKUP_DIR / b['filename']).unlink(missing_ok=True)
        except Exception:
            pass
    db_execute("DELETE FROM vm_backups WHERE vm_id=?", (vm_id,))
    db_execute("DELETE FROM vm_snapshots WHERE vm_id=?", (vm_id,))
    db_execute("DELETE FROM usage_history WHERE vm_id=?", (vm_id,))

    db_execute("DELETE FROM port_forwards WHERE vm_id=?", (vm_id,))
    try:
        _mcsub_release(vm_id)
    except Exception:
        pass
    db_execute("DELETE FROM vm_instances WHERE vm_id=?", (vm_id,))
    audit(session['user_id'], 'delete_vm', f'Deleted {v["name"]} ({vm_id[:8]})')
    return jsonify({'success': True, 'message': 'Deleted'})

