@app.route('/admin')
@admin_required
def admin_dashboard():
    tv = (db_execute("SELECT COUNT(*) as c FROM vm_instances", fetchone=True) or {'c': 0})['c']
    # Real running count
    all_vms = db_execute("SELECT vm_id, status FROM vm_instances", fetch=True) or []
    rv = 0
    for v in all_vms:
        running, _ = vm.vm_status(v['vm_id'])
        if running:
            rv += 1
    tu = (db_execute("SELECT COUNT(*) as c FROM users", fetchone=True) or {'c': 0})['c']
    cpu = psutil.cpu_percent(interval=None)
    mem = psutil.virtual_memory()
    disk = psutil.disk_usage('/')
    recent_activity = db_execute(
        "SELECT a.*, u.username FROM audit_log a LEFT JOIN users u ON a.user_id=u.id "
        "ORDER BY a.timestamp DESC LIMIT 8", fetch=True) or []
    local_node = db_execute("SELECT name FROM nodes WHERE is_local=1 LIMIT 1", fetchone=True)
    node_name = local_node['name'] if local_node else 'localhost'
    return render_template('admin/dashboard.html',
                           total_vms=tv, running_vms=rv, total_users=tu,
                           cpu_percent=cpu,
                           memory_percent=mem.percent,
                           memory_used=round(mem.used / (1024 ** 3), 1),
                           memory_total=round(mem.total / (1024 ** 3), 1),
                           disk_percent=disk.percent,
                           recent_activity=recent_activity,
                           kvm_ok=kvm_available(),
                           security_findings=security_checks(),
                           node_name=node_name)

@app.route('/admin/backup-db')
@admin_required
def admin_backup_db():
    """Download a consistent copy of the panel database (users, plans, servers, settings). Keep it private."""
    tmp = Path(tempfile.gettempdir()) / f'phvm-backup-{secrets.token_hex(6)}.db'
    src = sqlite3.connect(DATABASE)
    dst = sqlite3.connect(str(tmp))
    try:
        src.backup(dst)
    finally:
        dst.close()
        src.close()
    audit(session['user_id'], 'panel_backup_download', '')

    @after_this_request
    def _rm(resp):
        try:
            tmp.unlink()
        except Exception:
            pass
        return resp
    return send_file(str(tmp), as_attachment=True, download_name='phvm-backup-' + datetime.now().strftime('%Y%m%d-%H%M') + '.db')


@app.route('/admin/vms')
@admin_required
def admin_vms():
    vms = db_execute(
        "SELECT v.*, u.username FROM vm_instances v LEFT JOIN users u ON v.user_id=u.id "
        "ORDER BY v.created_at DESC", fetch=True) or []
    vl = []
    total_ram = 0
    running = 0
    stopped = 0
    for v in vms:
        d = dict(v)
        r, _ = vm.vm_status(v['vm_id'])
        d['real_status'] = 'running' if r else ('creating' if v['status'] == 'creating' else 'stopped')
        if d['real_status'] == 'running':
            running += 1
        elif d['real_status'] == 'stopped':
            stopped += 1
        total_ram += v['ram_mb'] or 0
        vl.append(d)
    return render_template('admin/vms.html', vms=vl, total=len(vl),
                           running=running, stopped=stopped,
                           total_ram=f"{total_ram/1024:.1f}G")

