@app.route('/admin/settings', methods=['GET', 'POST'])
@admin_required
def admin_settings():
    if request.method == 'POST':
        locked = {'site_version', 'valid_license_key', 'license_activated', 'license_key_entered',
                  'license_activated_at', 'license_digest'}
        saved = 0
        for k, v in request.form.items():
            if not k.startswith('setting_'):
                continue
            key = k.replace('setting_', '', 1).strip()
            if not key or key in locked or key not in SETTINGS_ALLOWLIST:
                continue
            val = str(v).strip()[:2000]
            if key == 'web_mode' and val not in ('direct', 'tunnel'):
                continue
            if key == 'site_name':
                val = val[:80] or 'PHvm Panel'
            if key == 'background_url' and val and not (val.startswith('https://') or val.startswith('/')):
                continue
            if key == 'discord_oauth_client_secret' and not val:
                continue  # blank means "keep existing secret", not "clear it"
            if key in ('smtp_password', 'cf_api_token', 'cf_tunnel_token', 'spaceship_api_key', 'spaceship_api_secret', 'stripe_secret_key', 'stripe_webhook_secret', 'offsite_secret_key', 'turnstile_secret', 'telegram_bot_token') and not val:
                continue  # blank means "keep the saved secret", not "clear it"
            try:
                _set_setting(key, val)
                saved += 1
            except Exception as e:
                flash(f'Failed to save {key}: {e}', 'danger')
        if saved:
            flash(f'Settings saved ({saved} fields).', 'success')
        else:
            flash('No settings were updated.', 'warning')
        # Checkboxes aren't submitted at all when unchecked — handle them explicitly
        # so unchecking actually turns them off instead of leaving the old value.
        if 'settings_form' in request.form:
            _set_setting('security_scan_enabled', 'true' if 'setting_security_scan_enabled' in request.form else 'false')
            _set_setting('security_auto_stop_on_mining', 'true' if 'setting_security_auto_stop_on_mining' in request.form else 'false')
            _set_setting('auto_restart_crashed_vms', 'true' if 'setting_auto_restart_crashed_vms' in request.form else 'false')
            _set_setting('discord_oauth_enabled', 'true' if 'setting_discord_oauth_enabled' in request.form else 'false')
            if _panel_domain():
                threading.Thread(target=_caddy_sync, daemon=True).start()
            _set_setting('email_notify_users', 'true' if 'setting_email_notify_users' in request.form else 'false')
            _set_setting('topup_enabled', 'true' if 'setting_topup_enabled' in request.form else 'false')
            _set_setting('status_enabled', 'true' if 'setting_status_enabled' in request.form else 'false')
            _set_setting('require_admin_2fa', 'true' if 'setting_require_admin_2fa' in request.form else 'false')
            if (gsv('admin_ip_allow', '') or '').strip() and not _ip_allowed(_client_ip(), gsv('admin_ip_allow', '')):
                _set_setting('admin_ip_allow', '')
                flash('Admin IP list was NOT saved: it does not include your current address (' + _client_ip() + '), which would lock you out.', 'danger')
            _set_setting('smtp_enabled', 'true' if 'setting_smtp_enabled' in request.form else 'false')
            _set_setting('smtp_use_tls', 'true' if 'setting_smtp_use_tls' in request.form else 'false')
            _set_setting('smtp_alert_admins', 'true' if 'setting_smtp_alert_admins' in request.form else 'false')
        return redirect(url_for('admin_settings'))
    settings = {r['key']: r['value'] for r in (db_execute("SELECT * FROM settings", fetch=True) or [])}
    return render_template('admin/settings.html', settings=settings, os_templates=get_os_templates())

