@app.route('/admin/public-ips', methods=['GET', 'POST'])
@admin_required
def admin_public_ips():
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add':
            ip = request.form.get('ip_address', '').strip()
            label = request.form.get('label', '').strip()
            notes = request.form.get('notes', '').strip()
            if not ip:
                flash('IP address required.', 'warning')
            else:
                try:
                    db_execute("INSERT INTO public_ips (ip_address, label, notes) VALUES (?,?,?)",
                               (ip, label, notes))
                    audit(session['user_id'], 'add_public_ip', ip)
                    ensure_phvm_bridge()
                    ok, err = sync_dedicated_ips_netplan()
                    if ok:
                        flash(f'IP {ip} added and applied to the network interface via netplan.', 'success')
                    else:
                        flash(f'IP {ip} saved, but netplan apply failed: {err}. '
                              f'You may need to add it manually or check that this host uses netplan.', 'warning')
                except sqlite3.IntegrityError:
                    flash('IP already exists.', 'danger')
        elif action == 'delete':
            ip_id = request.form.get('ip_id')
            row = db_execute("SELECT * FROM public_ips WHERE id=?", (ip_id,), fetchone=True)
            if row and not row['is_available']:
                flash('Cannot delete an assigned IP. Unassign first.', 'warning')
            else:
                if row and row['bridge_ip']:
                    unbind_dedicated_ip(row['ip_address'], row['bridge_ip'])
                db_execute("DELETE FROM public_ips WHERE id=?", (ip_id,))
                sync_dedicated_ips_netplan()
                flash('IP removed.', 'success')
        elif action == 'free':
            ip_id = request.form.get('ip_id')
            row = db_execute("SELECT * FROM public_ips WHERE id=?", (ip_id,), fetchone=True)
            if row and row['bridge_ip']:
                unbind_dedicated_ip(row['ip_address'], row['bridge_ip'])
                if row['assigned_vm_id']:
                    teardown_vm_tap(row['assigned_vm_id'])
            db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL, bridge_ip=NULL, bound=0 WHERE id=?", (ip_id,))
            flash('IP unassigned and freed.', 'success')
        return redirect(url_for('admin_public_ips'))
    ips = db_execute("SELECT * FROM public_ips ORDER BY created_at DESC", fetch=True) or []
    return render_template('admin/public_ips.html', ips=ips, bridge_gw=PHVM_BRIDGE_GW)

@app.route('/admin/nodes/<int:node_id>/ping', methods=['POST'])
@admin_required
def admin_node_ping(node_id):
    node = db_execute("SELECT * FROM nodes WHERE id=?", (node_id,), fetchone=True)
    if not node:
        return jsonify({'success': False, 'message': 'Node not found'})
    if node['is_local']:
        return jsonify({'success': True, 'message': 'Local node — always reachable (same process).', 'latency_ms': 0})
    if not node['api_url']:
        return jsonify({'success': False, 'message': 'No api_url set for this node.'})
    t0 = time.time()
    try:
        req = urllib.request.Request(node['api_url'].rstrip('/') + '/health', method='GET')
        with urllib.request.urlopen(req, timeout=6) as resp:
            data = json.loads(resp.read().decode())
        latency_ms = round((time.time() - t0) * 1000)
        db_execute("UPDATE nodes SET status='online', last_seen=CURRENT_TIMESTAMP WHERE id=?", (node_id,))
        return jsonify({
            'success': True,
            'message': f"Reachable — agent v{data.get('agent_version','?')}, KVM: {'yes' if data.get('has_kvm') else 'no'}",
            'latency_ms': latency_ms,
        })
    except Exception as e:
        db_execute("UPDATE nodes SET status='offline' WHERE id=?", (node_id,))
        return jsonify({'success': False, 'message': f'Unreachable: {e}'})


