@app.route('/admin/os-templates/add', methods=['POST'])
@admin_required
def admin_os_template_add():
    key = sanitize_name(request.form.get('template_key', ''), 40).lower().replace(' ', '-')
    name = (request.form.get('name') or '').strip()
    url = (request.form.get('url') or '').strip()
    default_user = (request.form.get('default_user') or 'root').strip()
    if not key or not name or not url:
        flash('Key, name, and image URL are all required.', 'danger')
        return redirect(url_for('admin_os_templates'))
    if not (url.startswith('http://') or url.startswith('https://')):
        flash('Image URL must be a valid http(s) link.', 'danger')
        return redirect(url_for('admin_os_templates'))
    existing = db_execute("SELECT 1 FROM os_templates WHERE template_key=?", (key,), fetchone=True)
    if existing:
        flash('A template with that key already exists — use Edit instead.', 'danger')
        return redirect(url_for('admin_os_templates'))
    max_order = db_execute("SELECT MAX(sort_order) as m FROM os_templates", fetchone=True)
    next_order = (max_order['m'] + 1) if max_order and max_order['m'] is not None else 0
    # root_pass is intentionally not set here — every VM gets its own randomly
    # generated password at creation time (see complete_vm_setup /
    # generate_vm_password), never a shared per-template default.
    db_execute(
        "INSERT INTO os_templates (template_key, name, url, default_user, sort_order) VALUES (?,?,?,?,?)",
        (key, name, url, default_user, next_order)
    )
    audit(session['user_id'], 'os_template_add', key)
    flash(f'Template "{name}" added.', 'success')
    return redirect(url_for('admin_os_templates'))

