@app.route('/profile', methods=['GET', 'POST'])
@login_required
def profile():
    u = db_execute("SELECT * FROM users WHERE id=?", (session['user_id'],), fetchone=True)
    c = (db_execute("SELECT COUNT(*) as c FROM vm_instances WHERE user_id=?",
                    (session['user_id'],), fetchone=True) or {'c': 0})['c']
    if request.method == 'POST':
        # Profile form only (API keys use different action URL)
        email = request.form.get('email', '').strip()
        new_username = request.form.get('username', '').strip()
        pw = request.form.get('new_password', '').strip()
        if not email or '@' not in email:
            flash('Valid email required.', 'warning')
            return redirect(url_for('profile'))
        if new_username:
            new_username = sanitize_name(new_username, 32)
            if len(new_username) < 3:
                flash('Username must be at least 3 characters.', 'warning')
                return redirect(url_for('profile'))
            existing = db_execute("SELECT id FROM users WHERE username=? AND id!=?",
                                  (new_username, session['user_id']), fetchone=True)
            if existing:
                flash('That username is already taken.', 'warning')
                return redirect(url_for('profile'))
        try:
            if pw:
                if len(pw) < 8:
                    flash('Password must be at least 8 characters.', 'warning')
                    return redirect(url_for('profile'))
                if new_username:
                    db_execute("UPDATE users SET email=?, username=?, password=?, must_change_password=0 WHERE id=?",
                               (email, new_username, generate_password_hash(pw, method='scrypt'), session['user_id']))
                else:
                    db_execute("UPDATE users SET email=?, password=?, must_change_password=0 WHERE id=?",
                               (email, generate_password_hash(pw, method='scrypt'), session['user_id']))
            else:
                if new_username:
                    db_execute("UPDATE users SET email=?, username=? WHERE id=?",
                               (email, new_username, session['user_id']))
                else:
                    db_execute("UPDATE users SET email=? WHERE id=?", (email, session['user_id']))
            if new_username:
                session['username'] = new_username
            flash('Profile updated.', 'success')
        except Exception as e:
            flash(f'Update failed: {e}', 'danger')
        return redirect(url_for('profile'))
    keys = db_execute("SELECT id, name, key_prefix, scope, created_at, last_used, is_active FROM api_keys "
                       "WHERE user_id=? ORDER BY created_at DESC", (session['user_id'],), fetch=True) or []
    return render_template('profile.html', user=u, vm_count=c, api_keys=keys)

AVATAR_ALLOWED_EXT = {'png', 'jpg', 'jpeg', 'webp', 'gif'}
AVATAR_MAX_BYTES = 3 * 1024 * 1024  # 3 MB

@app.route('/profile/avatar/upload', methods=['POST'])
@login_required
def profile_avatar_upload():
    file = request.files.get('avatar')
    if not file or not file.filename:
        flash('No image selected.', 'danger')
        return redirect(url_for('profile'))
    ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else ''
    if ext not in AVATAR_ALLOWED_EXT:
        flash('Unsupported file type. Use PNG, JPG, GIF, or WEBP.', 'danger')
        return redirect(url_for('profile'))
    file.seek(0, os.SEEK_END)
    size = file.tell()
    file.seek(0)
    if size > AVATAR_MAX_BYTES:
        flash('Image too large. Max size is 3 MB.', 'danger')
        return redirect(url_for('profile'))
    upload_dir = BASE_DIR / 'static' / 'uploads' / 'avatars'
    upload_dir.mkdir(parents=True, exist_ok=True)
    uid = session['user_id']
    for old in upload_dir.glob(f'user-{uid}.*'):
        try:
            old.unlink()
        except Exception:
            pass
    dest = upload_dir / f'user-{uid}.{ext}'
    file.save(dest)
    url = f'/static/uploads/avatars/user-{uid}.{ext}?v={int(time.time())}'
    db_execute("UPDATE users SET avatar_url=? WHERE id=?", (url, uid))
    session['avatar_url'] = url
    audit(uid, 'avatar_upload', ext)
    flash('Profile picture updated.', 'success')
    return redirect(url_for('profile'))

