@app.template_filter('datetime')
def dt_fmt(v):
    if not v:
        return 'N/A'
    if isinstance(v, str):
        try:
            return datetime.strptime(v[:19], '%Y-%m-%d %H:%M:%S').strftime('%b %d, %Y')
        except Exception:
            return v
    return v.strftime('%b %d, %Y')

@app.template_filter('status_badge')
def status_badge(s):
    colors = {
        'running': 'success',
        'stopped': 'secondary',
        'creating': 'warning',
        'error': 'danger'
    }
    return colors.get(s, 'secondary')

