    def _power_sync(v, vm_id, action, audit_uid, audit_detail):
        """Blocking VM/Docker work — always run in a worker thread so the bot keeps answering (heartbeats, other commands)."""
        fws = db_execute("SELECT host_port, guest_port, protocol FROM port_forwards WHERE vm_id=?", (vm_id,), fetch=True) or []
        extra = [dict(r) for r in fws]
        nested = bool(v['nested_kvm']) if 'nested_kvm' in v.keys() else False
        pub = v['public_ip'] if 'public_ip' in v.keys() else None
        priv = v['private_ip'] if 'private_ip' in v.keys() else None
        serial = v['serial_port'] if 'serial_port' in v.keys() and v['serial_port'] else v['vnc_port']
        try:
            if action == 'start':
                running, _ = vm.vm_status(vm_id)
                if running:
                    return ("Already running.")
                if v['ssh_port'] and int(v['ssh_port']) != 22:
                    subprocess.run(['fuser', '-k', f'{v["ssh_port"]}/tcp'], capture_output=True)
                pid = vm.start_vm(vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
                                   v['ssh_port'], serial, v['network_mode'] or 'private', pub, priv, extra, nested,
                          is_iso=bool(row_get(v, 'is_iso')), vnc_port=row_get(v, 'vnc_console_port'),
                          bridge_ip=get_vm_bridge_ip(vm_id))
                if pid:
                    db_execute("UPDATE vm_instances SET status='running', pid=? WHERE vm_id=?", (pid, vm_id))
                    _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
                    audit(audit_uid, 'start_vm', audit_detail)
                    return (f"✅ Started **{v['name']}**.")
                return ("❌ Failed to start.")
            if action == 'stop':
                running, pid = vm.vm_status(vm_id)
                if not running:
                    return ("Not running.")
                vm.stop_vm(pid, v['ssh_port'], vid=vm_id)
                db_execute("UPDATE vm_instances SET status='stopped', pid=NULL WHERE vm_id=?", (vm_id,))
                audit(audit_uid, 'stop_vm', audit_detail)
                return (f"🛑 Stopped **{v['name']}**.")
            if action == 'restart':
                running, pid = vm.vm_status(vm_id)
                if running:
                    vm.stop_vm(pid, v['ssh_port'], vid=vm_id)
                    time.sleep(2)
                if v['ssh_port'] and int(v['ssh_port']) != 22:
                    subprocess.run(['fuser', '-k', f'{v["ssh_port"]}/tcp'], capture_output=True)
                np = vm.start_vm(vm_id, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
                                  v['ssh_port'], serial, v['network_mode'] or 'private', pub, priv, extra, nested,
                          is_iso=bool(row_get(v, 'is_iso')), vnc_port=row_get(v, 'vnc_console_port'),
                          bridge_ip=get_vm_bridge_ip(vm_id))
                if np:
                    db_execute("UPDATE vm_instances SET status='running', pid=? WHERE vm_id=?", (np, vm_id))
                    _CRASH_RESTART_ATTEMPTS.pop(vm_id, None)
                    audit(audit_uid, 'restart_vm', audit_detail)
                    return (f"🔄 Restarted **{v['name']}**.")
                return ("❌ Restart failed.")
            if action == 'delete':
                running, pid = vm.vm_status(vm_id)
                if running:
                    vm.stop_vm(pid, v['ssh_port'], vid=vm_id)
                if v['public_ip']:
                    db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL WHERE ip_address=?", (v['public_ip'],))
                dedicated = db_execute("SELECT * FROM public_ips WHERE assigned_vm_id=?", (vm_id,), fetchone=True)
                if dedicated and dedicated['bridge_ip']:
                    unbind_dedicated_ip(dedicated['ip_address'], dedicated['bridge_ip'])
                    teardown_vm_tap(vm_id)
                    db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL, bridge_ip=NULL, bound=0 WHERE id=?",
                               (dedicated['id'],))
                # See the web delete_vm_route for why this matters: backups
                # live outside VM_DIR, so without this they'd orphan on disk
                # forever every time someone deletes a VM from Discord.
                orphaned_backups = db_execute("SELECT filename FROM vm_backups WHERE vm_id=?", (vm_id,), fetch=True) or []
                for b in orphaned_backups:
                    try:
                        (BACKUP_DIR / b['filename']).unlink(missing_ok=True)
                    except Exception:
                        pass
                db_execute("DELETE FROM vm_backups WHERE vm_id=?", (vm_id,))
                db_execute("DELETE FROM vm_snapshots WHERE vm_id=?", (vm_id,))
                db_execute("DELETE FROM usage_history WHERE vm_id=?", (vm_id,))
                db_execute("DELETE FROM port_forwards WHERE vm_id=?", (vm_id,))
                _dk_cleanup(vm_id)
                d = VM_DIR / vm_id
                if d.exists():
                    shutil.rmtree(d, ignore_errors=True)
                try:
                    _mcsub_release(vm_id)
                except Exception:
                    pass
                db_execute("DELETE FROM vm_instances WHERE vm_id=?", (vm_id,))
                audit(audit_uid, 'delete_vm', audit_detail)
                return (f"🗑️ Deleted **{v['name']}**.")
        except Exception as e:
            return (f"❌ Error: {e}")
        return "❌ Unknown action."

    async def _do_power(ctx, vm_id, action):
        v, err = _resolve_owned_vm(ctx, vm_id)
        if err:
            return await ctx.reply(f"❌ {err}")
        caller = _get_panel_user_by_discord(ctx.author.id)
        audit_uid = caller['id'] if caller else None
        audit_detail = f"{vm_id} (via Discord: {ctx.author})"
        note = await ctx.reply(f"⏳ {action.capitalize()}ing **{v['name']}**…") if action != 'delete' else None
        msg = await asyncio.to_thread(_power_sync, v, vm_id, action, audit_uid, audit_detail)
        await ctx.reply(msg)

