def _run_discord_bot_thread(token):
    global _discord_bot_loop, _discord_bot_client
    import asyncio
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    _discord_bot_loop = loop
    try:
        client = _build_discord_client()
        _discord_bot_client = client
        loop.run_until_complete(client.start(token))
    except Exception as e:
        _discord_bot_status['running'] = False
        _discord_bot_status['error'] = str(e)
        logging.getLogger('phvm.bot').error(f"Discord bot crashed: {e}")
    finally:
        _discord_bot_status['running'] = False

def start_discord_bot():
    global _discord_bot_thread
    if not _discord_available():
        _discord_bot_status['error'] = "discord.py not installed — run: pip install discord.py"
        return False
    if _discord_bot_thread and _discord_bot_thread.is_alive():
        return True
    token = (gsv('discord_bot_token', '') or '').strip()
    if not token:
        _discord_bot_status['error'] = "No bot token configured"
        return False
    _discord_bot_status['error'] = None
    _discord_bot_thread = threading.Thread(target=_run_discord_bot_thread, args=(token,), daemon=True)
    _discord_bot_thread.start()
    return True

def stop_discord_bot():
    global _discord_bot_thread, _discord_bot_loop, _discord_bot_client
    if _discord_bot_client and _discord_bot_loop:
        try:
            import asyncio
            asyncio.run_coroutine_threadsafe(_discord_bot_client.close(), _discord_bot_loop)
        except Exception:
            pass
    _discord_bot_status['running'] = False
    _discord_bot_status['connected_as'] = None

@app.route('/admin/settings/discord-bot', methods=['POST'])
@admin_required
def admin_settings_discord_bot():
    token = (request.form.get('discord_bot_token') or '').strip()
    guild_id = (request.form.get('discord_bot_guild_id') or '').strip()
    enabled = 'discord_bot_enabled' in request.form
    if token:
        _set_setting('discord_bot_token', token)
    _set_setting('discord_bot_guild_id', guild_id)
    _set_setting('discord_bot_enabled', 'true' if enabled else 'false')
    _set_setting('discord_bot_public_host', (request.form.get('discord_bot_public_host') or '').strip())

    email_domain = (request.form.get('discord_auto_email_domain') or '').strip().lstrip('@')[:100]
    if email_domain:
        _set_setting('discord_auto_email_domain', email_domain)

    admin_ids_raw = request.form.get('discord_admin_ids')
    if admin_ids_raw is not None:
        cleaned = [x.strip() for x in admin_ids_raw.split(',') if x.strip().isdigit()]
        _set_setting('discord_admin_ids', ','.join(cleaned))

    invite_url = (request.form.get('discord_invite_url') or '').strip()[:300]
    if not invite_url or invite_url.startswith('https://') or invite_url.startswith('http://'):
        _set_setting('discord_invite_url', invite_url)

    ost = (request.form.get('discord_free_vm_os') or '').strip()
    if ost and ost in OS_TEMPLATES:
        _set_setting('discord_free_vm_os', ost)
    for field, default in (
        ('discord_free_vm_ram_mb', 1024),
        ('discord_free_vm_cpu_cores', 2),
        ('discord_free_vm_storage_gb', 40),
        ('discord_free_vm_limit', 1),
    ):
        raw = (request.form.get(field) or '').strip()
        if raw.isdigit():
            _set_setting(field, str(max(0, int(raw))))

    stop_discord_bot()
    time.sleep(0.3)
    if enabled:
        ok = start_discord_bot()
        if ok:
            flash('Discord settings saved — bot (re)connecting, check phvm!help in Discord.', 'success')
        else:
            flash(f"Could not start bot: {_discord_bot_status.get('error')}", 'danger')
    else:
        flash('Discord settings saved.', 'success')
    audit(session['user_id'], 'discord_bot_config', f'enabled={enabled}')
    return redirect(url_for('admin_discord_bot'))

@app.route('/admin/settings/discord-bot/status')
@admin_required
def admin_settings_discord_bot_status():
    return jsonify({
        'running': _discord_bot_status.get('running', False),
        'error': _discord_bot_status.get('error'),
        'connected_as': _discord_bot_status.get('connected_as'),
        'installed': _discord_available(),
    })


# ═══════════════════════════ VM Management: Snapshots ═══════════════════════════

@app.route('/vm/<vm_id>/snapshot/create', methods=['POST'])
@login_required
@vm_owner_or_admin
def snapshot_create(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    name = sanitize_name(request.form.get('name', ''), 40) or f"snap-{int(time.time())}"
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    if not qcow.exists():
        flash('Disk image not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    r = subprocess.run(['qemu-img', 'snapshot', '-c', name, str(qcow)], capture_output=True, text=True)
    if r.returncode != 0:
        flash(f'Snapshot failed: {r.stderr.strip()[:200]}', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    size_mb = round(qcow.stat().st_size / (1024 * 1024), 1)
    db_execute("INSERT INTO vm_snapshots (vm_id, name, size_mb) VALUES (?,?,?)", (vm_id, name, size_mb))
    audit(session['user_id'], 'snapshot_create', f'{name} on {v["name"]} ({vm_id[:8]})')
    flash(f'Snapshot "{name}" created.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))

@app.route('/vm/<vm_id>/snapshot/<int:sid>/restore')
@login_required
@vm_owner_or_admin
def snapshot_restore(vm_id, sid):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    snap = db_execute("SELECT * FROM vm_snapshots WHERE id=? AND vm_id=?", (sid, vm_id), fetchone=True)
    if not snap:
        flash('Snapshot not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    running, pid = vm.vm_status(vm_id)
    if running:
        flash('Stop the VM before restoring a snapshot.', 'warning')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    r = subprocess.run(['qemu-img', 'snapshot', '-a', snap['name'], str(qcow)], capture_output=True, text=True)
    if r.returncode != 0:
        flash(f'Restore failed: {r.stderr.strip()[:200]}', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    audit(session['user_id'], 'snapshot_restore', f'{snap["name"]} on {v["name"]} ({vm_id[:8]})')
    flash(f'Restored snapshot "{snap["name"]}". Start the VM to boot into it.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))

@app.route('/vm/<vm_id>/snapshot/<int:sid>/delete')
@login_required
@vm_owner_or_admin
def snapshot_delete(vm_id, sid):
    snap = db_execute("SELECT * FROM vm_snapshots WHERE id=? AND vm_id=?", (sid, vm_id), fetchone=True)
    if not snap:
        flash('Snapshot not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    if qcow.exists():
        subprocess.run(['qemu-img', 'snapshot', '-d', snap['name'], str(qcow)], capture_output=True, text=True)
    db_execute("DELETE FROM vm_snapshots WHERE id=?", (sid,))
    audit(session['user_id'], 'snapshot_delete', f'{snap["name"]} ({vm_id[:8]})')
    flash('Snapshot deleted.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))

# ═══════════════════════════ VM Management: Clone ═══════════════════════════

@app.route('/vm/<vm_id>/clone', methods=['POST'])
@admin_required
def clone_vm(vm_id):
    vm_id = safe_vm_id(vm_id)
    if not vm_id:
        flash('Invalid VM id.', 'danger')
        return redirect(url_for('admin_vms'))
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        flash('VM not found.', 'danger')
        return redirect(url_for('admin_vms'))
    src_qcow = VM_DIR / vm_id / 'disk.qcow2'
    if not src_qcow.exists():
        flash('Source disk not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    new_name = sanitize_name(request.form.get('name', ''), 64) or f"{v['name']}-clone"
    new_vid = str(uuid.uuid4())
    new_dir = vm.vm_dir(new_vid)
    try:
        shutil.copy2(str(src_qcow), str(new_dir / 'disk.qcow2'))
        seed = VM_DIR / vm_id / 'seed.iso'
        if seed.exists():
            shutil.copy2(str(seed), str(new_dir / 'seed.iso'))
    except Exception as e:
        flash(f'Clone failed: {e}', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    new_sp = allocate_host_port()
    new_serial = allocate_host_port()
    db_execute(
        "INSERT INTO vm_instances (vm_id, user_id, name, os_template, ram_mb, cpu_cores, storage_gb, "
        "ssh_port, ssh_host, ssh_user, ssh_password, network_mode, status, serial_port, accel_mode) "
        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (new_vid, v['user_id'], new_name, v['os_template'], v['ram_mb'], v['cpu_cores'], v['storage_gb'],
         new_sp, row_get(v, 'ssh_host') or '127.0.0.1', row_get(v, 'ssh_user') or 'root',
         v['ssh_password'], row_get(v, 'network_mode') or 'private', 'stopped', new_serial,
         row_get(v, 'accel_mode') or 'auto')
    )
    audit(session['user_id'], 'clone_vm', f'Cloned {v["name"]} -> {new_name} ({new_vid[:8]})')
    flash(f'VM cloned as "{new_name}". Start it from its manage page.', 'success')
    return redirect(url_for('manage_vm', vm_id=new_vid))

