BACKUP_DIR = BASE_DIR / 'backups'
BACKUP_DIR.mkdir(exist_ok=True)

@app.route('/vm/<vm_id>/backup/create')
@login_required
@vm_owner_or_admin
def backup_create(vm_id):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    if not qcow.exists():
        flash('Disk image not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    fname = f"{vm_id}_{int(time.time())}.qcow2"
    dest = BACKUP_DIR / fname
    try:
        shutil.copy2(str(qcow), str(dest))
    except Exception as e:
        flash(f'Backup failed: {e}', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    size_mb = round(dest.stat().st_size / (1024 * 1024), 1)
    db_execute("INSERT INTO vm_backups (vm_id, filename, size_mb) VALUES (?,?,?)", (vm_id, fname, size_mb))
    audit(session['user_id'], 'backup_create', f'{v["name"]} ({vm_id[:8]}) -> {fname}')
    flash('Backup created.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))

@app.route('/vm/<vm_id>/backup/<int:bid>/download')
@login_required
@vm_owner_or_admin
def backup_download(vm_id, bid):
    b = db_execute("SELECT * FROM vm_backups WHERE id=? AND vm_id=?", (bid, vm_id), fetchone=True)
    if not b:
        flash('Backup not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    path = BACKUP_DIR / b['filename']
    if not path.exists():
        flash('Backup file missing on disk.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    return send_file(str(path), as_attachment=True, download_name=b['filename'])

@app.route('/vm/<vm_id>/backup/<int:bid>/delete')
@login_required
@vm_owner_or_admin
def backup_delete(vm_id, bid):
    b = db_execute("SELECT * FROM vm_backups WHERE id=? AND vm_id=?", (bid, vm_id), fetchone=True)
    if b:
        try:
            (BACKUP_DIR / b['filename']).unlink(missing_ok=True)
        except Exception:
            pass
        db_execute("DELETE FROM vm_backups WHERE id=?", (bid,))
        audit(session['user_id'], 'backup_delete', f'{b["filename"]} ({vm_id[:8]})')
        flash('Backup deleted.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))


# ───────── v21.51: scheduled snapshots/backups (QEMU VMs), retention, restore from backup ─────────
@app.route('/vm/<vm_id>/backup/schedule', methods=['POST'])
@login_required
@vm_owner_or_admin
def backup_schedule(vm_id):
    freq = safe_int(request.form.get('freq_hours', 0), 0, 0, 720)
    if freq not in (0, 6, 12, 24, 72, 168):
        freq = 24
    keep = safe_int(request.form.get('keep', 3), 3, 1, 14)
    kind = 'snapshot' if request.form.get('kind') == 'snapshot' else 'backup'
    db_execute("INSERT INTO vm_backup_sched (vm_id, freq_hours, keep, kind, last_run, last_msg) VALUES (?,?,?,?,?,'') "
               "ON CONFLICT(vm_id) DO UPDATE SET freq_hours=excluded.freq_hours, keep=excluded.keep, kind=excluded.kind",
               (vm_id, freq, keep, kind, int(time.time()) if freq else 0))
    audit(session['user_id'], 'backup_schedule', f'{vm_id[:8]} every {freq}h keep {keep} ({kind})')
    flash('Automatic backups turned off.' if not freq else f'Automatic {kind}s every {freq} h, keeping the newest {keep}.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))


@app.route('/vm/<vm_id>/backup/<int:bid>/restore')
@login_required
@vm_owner_or_admin
def backup_restore(vm_id, bid):
    b = db_execute("SELECT * FROM vm_backups WHERE id=? AND vm_id=?", (bid, vm_id), fetchone=True)
    src = (BACKUP_DIR / b['filename']) if b else None
    if not b or not src.exists():
        flash('Backup file not found.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    running, _pid = vm.vm_status(vm_id)
    if running:
        flash('Stop the VM before restoring a backup.', 'warning')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    keep_old = qcow.with_name('disk.qcow2.before-restore')
    need = src.stat().st_size
    if shutil.disk_usage(str(qcow.parent)).free < need * 1.1:
        flash('Not enough free disk space to restore this backup.', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    try:
        if qcow.exists():
            keep_old.unlink(missing_ok=True)
            qcow.rename(keep_old)
        shutil.copy2(str(src), str(qcow))
    except Exception as e:
        if keep_old.exists() and not qcow.exists():
            keep_old.rename(qcow)
        flash(f'Restore failed: {e}', 'danger')
        return redirect(url_for('manage_vm', vm_id=vm_id))
    db_execute("DELETE FROM vm_snapshots WHERE vm_id=?", (vm_id,))  # old snapshots lived inside the replaced disk
    audit(session['user_id'], 'backup_restore', f'{b["filename"]} ({vm_id[:8]})')
    flash('Backup restored. The previous disk was kept as disk.qcow2.before-restore (one copy). Start the VM to boot it.', 'success')
    return redirect(url_for('manage_vm', vm_id=vm_id))


def _vm_sched_prune(vm_id, kind, keep):
    if kind == 'snapshot':
        qcow = VM_DIR / vm_id / 'disk.qcow2'
        rows = db_execute("SELECT * FROM vm_snapshots WHERE vm_id=? AND name LIKE 'auto-%' ORDER BY id DESC", (vm_id,), fetch=True) or []
        for r in rows[keep:]:
            if qcow.exists():
                subprocess.run(['qemu-img', 'snapshot', '-d', r['name'], str(qcow)], capture_output=True, text=True)
            db_execute("DELETE FROM vm_snapshots WHERE id=?", (r['id'],))
    else:
        rows = db_execute("SELECT * FROM vm_backups WHERE vm_id=? AND filename LIKE '%\\_auto\\_%' ESCAPE '\\' ORDER BY id DESC", (vm_id,), fetch=True) or []
        for r in rows[keep:]:
            try:
                (BACKUP_DIR / r['filename']).unlink(missing_ok=True)
            except Exception:
                pass
            db_execute("DELETE FROM vm_backups WHERE id=?", (r['id'],))


def _vm_sched_run(row):
    """Take one automatic snapshot/backup for a QEMU VM. Returns a short status text."""
    vm_id = row['vm_id']
    qcow = VM_DIR / vm_id / 'disk.qcow2'
    if not qcow.exists():
        return 'disk not found'
    ts = int(time.time())
    if row['kind'] == 'snapshot':
        name = f'auto-{ts}'
        r = subprocess.run(['qemu-img', 'snapshot', '-c', name, str(qcow)], capture_output=True, text=True)
        if r.returncode != 0:
            return 'snapshot failed: ' + (r.stderr.strip()[:120] or 'unknown')
        db_execute("INSERT INTO vm_snapshots (vm_id, name, size_mb) VALUES (?,?,?)",
                   (vm_id, name, round(qcow.stat().st_size / 1048576, 1)))
    else:
        if shutil.disk_usage(str(BACKUP_DIR)).free < qcow.stat().st_size * 1.2:
            return 'skipped: not enough free disk space'
        fname = f'{vm_id}_auto_{ts}.qcow2'
        try:
            shutil.copy2(str(qcow), str(BACKUP_DIR / fname))
        except Exception as e:
            (BACKUP_DIR / fname).unlink(missing_ok=True)
            return f'backup failed: {str(e)[:100]}'
        db_execute("INSERT INTO vm_backups (vm_id, filename, size_mb) VALUES (?,?,?)",
                   (vm_id, fname, round((BACKUP_DIR / fname).stat().st_size / 1048576, 1)))
    _vm_sched_prune(vm_id, row['kind'], int(row['keep'] or 3))
    return 'ok'


def _vm_sched_tick():
    now = int(time.time())
    for r in (db_execute("SELECT * FROM vm_backup_sched WHERE freq_hours>0", fetch=True) or []):
        if now - int(r['last_run'] or 0) < int(r['freq_hours']) * 3600:
            continue
        v = db_execute("SELECT user_id, name FROM vm_instances WHERE vm_id=? AND (runtime IS NULL OR runtime!='docker')", (r['vm_id'],), fetchone=True)
        if not v:
            db_execute("DELETE FROM vm_backup_sched WHERE vm_id=?", (r['vm_id'],))
            continue
        msg = _vm_sched_run(r)
        db_execute("UPDATE vm_backup_sched SET last_run=?, last_msg=? WHERE vm_id=?", (now, msg, r['vm_id']))
        if msg != 'ok' and not (r['last_msg'] or '').startswith(msg[:12]):
            try:
                notify_user(v['user_id'], 'Automatic backup problem', f'{v["name"]}: {msg}', 'warning')
            except Exception:
                pass


def _vm_sched_loop():
    time.sleep(150)
    while True:
        try:
            _vm_sched_tick()
        except Exception as e:
            print('[vm-sched] failed:', e, flush=True)
        time.sleep(300)

# ───────── v21.66: real global search (servers, users, tickets) for the top-bar search and Ctrl+K ─────────
@app.route('/api/search')
@login_required
def api_search():
    q = (request.args.get('q') or '').strip()[:60]
    if len(q) < 2:
        return jsonify({'success': True, 'results': []})
    like = '%' + q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_') + '%'
    admin = session.get('role') == 'admin'
    uid = session['user_id']
    out = []
    if admin:
        rows = db_execute("SELECT v.vm_id, v.name, v.provision_kind, v.status, u.username FROM vm_instances v LEFT JOIN users u ON u.id=v.user_id "
                          "WHERE v.name LIKE ? ESCAPE '\\' OR v.vm_id LIKE ? ESCAPE '\\' OR u.username LIKE ? ESCAPE '\\' OR CAST(v.ssh_port AS TEXT) LIKE ? ESCAPE '\\' "
                          "ORDER BY v.name LIMIT 8", (like, like, like, like), fetch=True) or []
    else:
        rows = db_execute("SELECT vm_id, name, provision_kind, status, '' AS username FROM vm_instances WHERE user_id=? AND (name LIKE ? ESCAPE '\\' OR vm_id LIKE ? ESCAPE '\\') "
                          "ORDER BY name LIMIT 8", (uid, like, like), fetch=True) or []
    for r in rows:
        kind = r['provision_kind'] or 'vps'
        out.append({'t': r['name'], 'sub': (kind + (' · ' + r['username'] if r['username'] else '') + ' · ' + (r['status'] or '')).strip(' ·'),
                    'href': '/vm/' + r['vm_id'] + '/manage', 'g': 'Servers', 'i': {'minecraft': 'cube', 'bot': 'robot', 'web': 'globe'}.get(kind, 'server')})
    if admin:
        for r in (db_execute("SELECT id, username, email, role FROM users WHERE username LIKE ? ESCAPE '\\' OR email LIKE ? ESCAPE '\\' ORDER BY username LIMIT 6", (like, like), fetch=True) or []):
            out.append({'t': r['username'], 'sub': (r['email'] or '') + ' · ' + (r['role'] or 'user'), 'href': '/admin/users/%d/edit' % r['id'], 'g': 'Users', 'i': 'user'})
        trows = db_execute("SELECT id, subject, status FROM tickets WHERE subject LIKE ? ESCAPE '\\' ORDER BY id DESC LIMIT 5", (like,), fetch=True) or []
    else:
        trows = db_execute("SELECT id, subject, status FROM tickets WHERE user_id=? AND subject LIKE ? ESCAPE '\\' ORDER BY id DESC LIMIT 5", (uid, like), fetch=True) or []
    for r in trows:
        out.append({'t': r['subject'] or 'Ticket', 'sub': 'ticket #%d · %s' % (r['id'], r['status'] or ''), 'href': '/support/%d' % r['id'], 'g': 'Tickets', 'i': 'life-ring'})
    return jsonify({'success': True, 'results': out})

