@app.route('/admin/plans', methods=['GET', 'POST'])
@admin_required
def admin_plans():
    if request.method == 'POST':
        name = sanitize_name(request.form.get('name', ''), 64)
        category = sanitize_name(request.form.get('category', 'vps') or 'vps', 40).lower().replace(' ', '-') or 'vps'
        flavor = request.form.get('flavor', 'vps') or 'vps'
        if flavor not in ('vps', 'bot', 'minecraft', 'web', 'sandbox'):
            flavor = 'vps'
        try:
            ram = safe_int(request.form.get('ram_mb', 2048), 2048, 256, 262144)
            cpu = safe_int(request.form.get('cpu_cores', 2), 2, 1, 128)
            stor = safe_int(request.form.get('storage_gb', 20), 20, 5, 10000)
            price = float(request.form.get('price', 0) or 0)
            duration = safe_int(request.form.get('duration_days', 30), 30, 1, 3650)
        except Exception:
            flash('Invalid plan values.', 'danger')
            return redirect(url_for('admin_plans'))
        if not name:
            flash('Plan name required.', 'warning')
            return redirect(url_for('admin_plans'))
        try:
            db_execute(
                "INSERT INTO plans (name, category, flavor, ram_mb, cpu_cores, storage_gb, price, duration_days) VALUES (?,?,?,?,?,?,?,?)",
                (name, category, flavor, ram, cpu, stor, price, duration))
            audit(session['user_id'], 'create_plan', f'{name} ({category}/{flavor})')
            flash(f'Plan "{name}" created under "{category}".', 'success')
        except Exception as e:
            flash(f'Could not create plan: {e}', 'danger')
        return redirect(url_for('admin_plans'))
    plans = db_execute("SELECT * FROM plans ORDER BY category ASC, price ASC", fetch=True) or []
    categories = sorted(set((p['category'] or 'vps') for p in plans))
