PHVM_BOT_BASE_OS = 'ubuntu-24.04'
PHVM_MINECRAFT_BASE_OS = 'ubuntu-24.04'
PHVM_MINECRAFT_SOFTWARE = {'paper': 'Paper', 'purpur': 'Purpur', 'vanilla': 'Vanilla'}

@app.route('/plans/<int:pid>/buy', methods=['GET', 'POST'])
@login_required
def buy_plan(pid):
    p = db_execute("SELECT * FROM plans WHERE id=?", (pid,), fetchone=True)
    if not p:
        flash('Plan not found.', 'danger')
        return redirect(url_for('plans_index'))
    flavor = row_get(p, 'flavor') or 'vps'
    # Cloud-init only — ISO installer templates (Proxmox VE etc.) need a
    # manual VNC setup session, which doesn't fit instant self-service
    # checkout. Only offer templates that provision automatically.
    buyable_templates = {k: t for k, t in OS_TEMPLATES.items() if not t.get('iso')}

    if request.method == 'GET':
        user = db_execute("SELECT wallet_balance FROM users WHERE id=?", (session['user_id'],), fetchone=True)
        balance = (user['wallet_balance'] if user else 0) or 0
        available_ips = db_execute("SELECT * FROM public_ips WHERE is_available=1 ORDER BY ip_address", fetch=True) or []
        return render_template('buy_plan.html', plan=p, flavor=flavor, os_templates=buyable_templates,
                               mc_software=PHVM_MINECRAFT_SOFTWARE, balance=balance, available_ips=available_ips,
                               docker_servers=(flavor in ('minecraft', 'bot', 'web') and _docker_enabled()))

    name = sanitize_name(request.form.get('name', '') or f"{p['name']}-{secrets.token_hex(2)}", 64)
    provision_kind, provision_option, ost, extra_port_label = None, None, None, None

    # Shared (NAT, this host's IP + a forwarded port) vs Dedicated (the VM
    # gets a whole IP from the pool to itself, SSH on the standard port 22
    # — like a real dedicated-IP VPS). Already existed for admin-created
    # VMs; self-service plan purchases never offered the choice at all.
    ip_mode = request.form.get('ip_mode', 'shared')
    dedicated_ip_id = request.form.get('public_ip_id') if ip_mode == 'dedicated' else None

    if flavor == 'bot':
        runtime = request.form.get('runtime', 'node')
        if runtime not in ('node', 'python'):
            flash('Choose a valid runtime.', 'danger')
            return redirect(url_for('buy_plan', pid=pid))
        ost = PHVM_BOT_BASE_OS
        provision_kind, provision_option = 'bot', runtime
    elif flavor == 'minecraft':
        software = request.form.get('software', 'paper')
        if software not in PHVM_MINECRAFT_SOFTWARE:
            flash('Choose a valid server software.', 'danger')
            return redirect(url_for('buy_plan', pid=pid))
        mc_version = sanitize_name(request.form.get('mc_version', 'latest') or 'latest', 20)
        connection = request.form.get('connection', 'direct')
        use_playit = connection == 'playit'
        use_minekube = connection == 'minekube' and software in ('paper', 'purpur')
        ost = PHVM_MINECRAFT_BASE_OS
        provision_kind, provision_option = 'minecraft', {
            'software': software, 'version': mc_version, 'playit': use_playit, 'minekube': use_minekube,
        }
        if not use_playit and not use_minekube:
            extra_port_label = 'minecraft'  # direct connection needs the host port-forward; tunnels/plugins don't
    elif flavor == 'web':
        if not _docker_enabled():
            flash('Web hosting needs Docker on the host, and Docker is not available right now.', 'danger')
            return redirect(url_for('buy_plan', pid=pid))
        ost = 'docker'
        provision_kind, provision_option = 'web', {'app': 'wordpress'}
        extra_port_label = 'web'
    else:
        ost = request.form.get('os_template', '')
        if ost not in buyable_templates:
            flash('Choose a valid OS.', 'danger')
            return redirect(url_for('buy_plan', pid=pid))
        if flavor == 'sandbox':
            provision_kind = 'sandbox'

    use_docker = provision_kind in ('minecraft', 'bot', 'web') and _docker_enabled()
    if use_docker:
        dedicated_ip_id = None          # containers use a host port, not a dedicated IP
        if provision_kind == 'minecraft':
            extra_port_label = 'minecraft'
    # Same atomic check-and-debit pattern as the shop, for the same reason:
    # two clicks (or two tabs) buying at once must never both succeed.
    debited = db_execute(
        "UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?",
        (p['price'], session['user_id'], p['price']), rowcount=True
    )
    if not debited:
        flash(f'Insufficient Volts balance. You need ⚡{p["price"]:.2f}.', 'danger')
        return redirect(url_for('buy_plan', pid=pid))

    assigned_ip = None
    network_mode = 'private'
    try:
        vid = str(uuid.uuid4())
        vp = allocate_host_port()
        nid = ensure_local_node()
        expiry_date = (datetime.now() + timedelta(days=p['duration_days'] or 30)).strftime('%Y-%m-%d %H:%M:%S')

        if dedicated_ip_id:
            pip = db_execute("SELECT * FROM public_ips WHERE id=? AND is_available=1", (int(dedicated_ip_id),), fetchone=True)
            if not pip:
                db_execute("UPDATE users SET wallet_balance = wallet_balance + ? WHERE id=?", (p['price'], session['user_id']))
                flash('That dedicated IP is no longer available — pick another, you have not been charged.', 'danger')
                return redirect(url_for('buy_plan', pid=pid))
            assigned_ip = pip['ip_address']
            network_mode = 'public'
            bip = allocate_bridge_ip()
            if bip and ensure_phvm_bridge():
                db_execute("UPDATE public_ips SET is_available=0, assigned_vm_id=?, bridge_ip=? WHERE id=?", (vid, bip, pip['id']))
            else:
                db_execute("UPDATE public_ips SET is_available=0, assigned_vm_id=? WHERE id=?", (vid, pip['id']))
            sp = 22  # dedicated IP: SSH is the standard port 22 on that IP, not a NAT host port
        else:
            sp = allocate_host_port()

        db_execute(
            "INSERT INTO vm_instances (vm_id, user_id, name, os_template, ram_mb, cpu_cores, storage_gb, "
            "ssh_port, vnc_port, network_mode, public_ip, status, expiry_date) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (vid, session['user_id'], name, ('docker' if use_docker else ost), p['ram_mb'], p['cpu_cores'], p['storage_gb'],
             (None if use_docker else sp), (None if use_docker else vp), network_mode, assigned_ip, 'creating', expiry_date)
        )
        db_execute("UPDATE vm_instances SET provision_kind=?, plan_id=?, provision_opt=?, runtime=? WHERE vm_id=?",
                   (provision_kind, p['id'], json.dumps(provision_option), ('docker' if use_docker else None), vid))
        if use_docker:
            _dk_cache[vid] = (time.time(), True)
        print(f"[buy] plan #{p['id']} '{p['name']}' flavor={flavor} -> provision_kind={provision_kind}", flush=True)
        if extra_port_label == 'minecraft' and network_mode == 'private':
            mc_host_port = allocate_host_port(preferred=25565)
            db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                      (vid, mc_host_port, 25565, 'tcp', 'Minecraft'))
        if provision_kind == 'web':
            web_port = allocate_host_port(preferred=8080)
            db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                       (vid, web_port, 80, 'tcp', 'web'))
    except Exception as e:
        # Provisioning setup failed before anything started — refund immediately.
        db_execute("UPDATE users SET wallet_balance = wallet_balance + ? WHERE id=?", (p['price'], session['user_id']))
        if dedicated_ip_id:
            db_execute("UPDATE public_ips SET is_available=1, assigned_vm_id=NULL, bridge_ip=NULL WHERE id=?", (int(dedicated_ip_id),))
        flash(f'Could not start provisioning, you have not been charged: {e}', 'danger')
        return redirect(url_for('buy_plan', pid=pid))

    db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)",
               (session['user_id'], -p['price'], 'plan_purchase', f'Purchased plan: {p["name"]}'))
    add_notification(session['user_id'], 'Wallet updated', f'Debited ⚡{p["price"]:.2f} — Purchased plan: {p["name"]}', 'info')
    add_notification(session['user_id'], 'VM Creating...', f'VM "{name}" from plan "{p["name"]}"' + (f' — dedicated IP {assigned_ip}' if assigned_ip else (' — Docker server' if use_docker else f' — SSH port: {sp}')), 'info')
    audit(session['user_id'], 'plan_purchase', f'{p["name"]} ({vid[:8]}) for ⚡{p["price"]:.2f}')
    _notify_all_admins('New plan purchase', f'{session.get("username")} bought "{p["name"]}" for ⚡{p["price"]:.2f}.', 'info')
    if provision_kind == 'web':
        threading.Thread(target=complete_web_setup, args=(vid,), daemon=True).start()
    elif use_docker:
        threading.Thread(target=complete_docker_setup, args=(vid, provision_kind, provision_option), daemon=True).start()
    else:
        threading.Thread(target=complete_vm_setup,
                         args=(vid, ost, p['ram_mb'], p['cpu_cores'], p['storage_gb'], sp, vp, network_mode, assigned_ip, None),
                         kwargs={'provision_kind': provision_kind, 'provision_option': provision_option},
                         daemon=True).start()
    flash(f'Purchased "{p["name"]}"! Your {"site" if flavor == "web" else "server" if flavor != "vps" else "VM"} is being created now — first boot can take a few extra minutes while it installs.', 'success')
    return redirect(url_for('manage_vm', vm_id=vid))


