@app.route('/admin/shop', methods=['GET', 'POST'])
@admin_required
def admin_shop():
    if request.method == 'POST':
        name = sanitize_name(request.form.get('name', ''), 80)
        description = (request.form.get('description') or '').strip()[:500]
        image_url = (request.form.get('image_url') or '').strip()
        category = sanitize_name(request.form.get('category', 'general') or 'general', 40).lower().replace(' ', '-') or 'general'
        try:
            price = float(request.form.get('price', 0) or 0)
            stock = int(request.form.get('stock', -1) or -1)
        except Exception:
            flash('Invalid price or stock value.', 'danger')
            return redirect(url_for('admin_shop'))
        if not name or price < 0:
            flash('Product name and a valid price are required.', 'warning')
            return redirect(url_for('admin_shop'))
        db_execute(
            "INSERT INTO shop_products (name, description, price, image_url, category, stock) VALUES (?,?,?,?,?,?)",
            (name, description, price, image_url, category, stock)
        )
        audit(session['user_id'], 'shop_product_add', name)
        flash(f'Product "{name}" added to the shop.', 'success')
        return redirect(url_for('admin_shop'))
    products = db_execute("SELECT * FROM shop_products ORDER BY sort_order ASC, created_at DESC", fetch=True) or []
    return render_template('admin/shop.html', products=products)

