@app.route('/shop/<int:pid>/buy', methods=['POST'])
@login_required
def shop_buy(pid):
    p = db_execute("SELECT * FROM shop_products WHERE id=? AND active=1", (pid,), fetchone=True)
    if not p:
        flash('Product not found or no longer available.', 'danger')
        return redirect(url_for('shop_index'))
    if p['stock'] == 0:
        flash('This product is out of stock.', 'warning')
        return redirect(url_for('shop_index'))
    # This used to check the balance/stock, then debit/decrement in separate
    # statements — with the panel now handling real concurrent requests
    # (waitress, many threads), two purchases firing at once could both
    # pass the check before either one's debit lands, taking the wallet
    # negative or overselling limited stock. Making the check part of the
    # UPDATE itself (only matches — and only then applies — if the balance
    # still covers it right now) closes that window: at most one of two
    # simultaneous requests can ever succeed.
    debited = db_execute(
        "UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?",
        (p['price'], session['user_id'], p['price']), rowcount=True
    )
    if not debited:
        flash(f'Insufficient wallet balance. You need {p["price"]:.2f}.', 'danger')
        return redirect(url_for('shop_index'))
    if p['stock'] > 0:
        stock_taken = db_execute(
            "UPDATE shop_products SET stock = stock - 1 WHERE id=? AND stock > 0", (pid,), rowcount=True
        )
        if not stock_taken:
            # Someone else bought the last unit between our SELECT above and
            # now — refund immediately rather than sell something that no
            # longer exists.
            db_execute("UPDATE users SET wallet_balance = wallet_balance + ? WHERE id=?",
                       (p['price'], session['user_id']))
            flash('This product just sold out. You have not been charged.', 'warning')
            return redirect(url_for('shop_index'))
    db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)",
               (session['user_id'], -p['price'], 'shop_purchase', f'Purchased: {p["name"]}'))
    add_notification(session['user_id'], 'Wallet updated', f'Debited {p["price"]:.2f} — Purchased: {p["name"]}', 'info')
    db_execute(
        "INSERT INTO shop_orders (user_id, product_id, product_name, price_paid) VALUES (?,?,?,?)",
        (session['user_id'], pid, p['name'], p['price'])
    )
    audit(session['user_id'], 'shop_purchase', f'{p["name"]} for {p["price"]:.2f}')
    _notify_all_admins('New shop order', f'{session.get("username")} purchased "{p["name"]}" for {p["price"]:.2f}.', 'info')
    flash(f'Purchased "{p["name"]}"! An admin will process your order shortly.', 'success')
    return redirect(url_for('shop_index'))

