@app.route('/login/2fa', methods=['GET', 'POST'])
def login_2fa():
    uid = session.get('_pending_2fa_user_id')
    if not uid:
        return redirect(url_for('login'))
    if request.method == 'POST':
        code = request.form.get('code', '').strip()
        u = db_execute("SELECT * FROM users WHERE id=?", (uid,), fetchone=True)
        if u and verify_totp(u['totp_secret'], code):
            session.pop('_pending_2fa_user_id', None)
            session['user_id'] = u['id']
            session['username'] = u['username']
            session['role'] = u['role']
            session['avatar_url'] = row_get(u, 'avatar_url')
            db_execute("UPDATE users SET last_login=CURRENT_TIMESTAMP WHERE id=?", (u['id'],))
            audit(u['id'], 'login', f'Login (2FA) from {request.remote_addr}')
            _login_alert(u['id'], _client_ip())
            _device_check(u['id'], _client_ip())
            flash(f"Welcome, {u['username']}!", 'success')
            return redirect(url_for('index'))
        flash('Invalid 2FA code.', 'danger')
    return render_template('login_2fa.html')

