# ───────────── Docker server handlers (mirror the VM/SSH ones, same JSON shapes) ─────────────
def _dk_row(vm_id):
    return db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)


def _dk_kind(v):
    return row_get(v, 'provision_kind')


def _dk_rcon(vid, cmd, timeout=15):
    rc, out, err = _docker('exec', _cname(vid), 'rcon-cli', cmd, timeout=timeout)
    return rc == 0, _DK_ANSI.sub('', (out or err)).strip()


def _dk_address(v):
    fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (v['vm_id'],), fetchone=True)
    host = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    if not fw or not host or host == '127.0.0.1':
        return None
    return f"{host}:{int(fw['host_port'])}"


def _dk_logs(vid, n=250):
    rc, out, err = _docker('logs', '--tail', str(n), _cname(vid), timeout=15)
    return _DK_ANSI.sub('', (out + err) if rc == 0 else (err or out))[-20000:]


def _dk_json_err(msg):
    return jsonify({'success': False, 'message': msg})


# ---- page + state + power ----
def dk_server_panel(vm_id):
    v = _dk_row(vm_id)
    kind = _dk_kind(v)
    running, _ = dk_status(vm_id)
    return render_template('server.html', vm=v, kind=kind, is_running=running, svc_error=None, docker=True,
                           files_path='/', mc_address=(_dk_best_address(v)[0] if kind == 'minecraft' else None),
                           startup_cmd=row_get(v, 'startup_cmd') or '')


_MC_ONLINE = {}


def _mc_online_cached(vid):
    """Players online, refreshed in the background at most every 30 s (never blocks the state poll)."""
    hit = _MC_ONLINE.get(vid)
    if not hit or time.time() - hit[0] > 30:
        _MC_ONLINE[vid] = (time.time(), hit[1] if hit else None)

        def work():
            ok, out = _dk_rcon(vid, 'list', timeout=8)
            m_ = re.search(r'There are (\d+) of a max of (\d+) players online', out or '') if ok else None
            _MC_ONLINE[vid] = (time.time(), {'online': int(m_.group(1)), 'max': int(m_.group(2))} if m_ else None)
        threading.Thread(target=work, daemon=True).start()
    return (_MC_ONLINE.get(vid) or (0, None))[1]


def dk_server_state(vm_id):
    v = _dk_row(vm_id)
    kind = _dk_kind(v)
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}', _cname(vm_id), timeout=10)
    if rc != 0:
        return jsonify({'success': True, 'machine': True, 'installed': False, 'state': 'inactive', 'console': False,
                        'logs': 'The container does not exist yet — it is still being created.', 'busy': _dk_busy(vm_id)})
    running, _, health = out.strip().partition('|')
    state = 'inactive'
    if running == 'true':
        state = 'activating' if health == 'starting' else 'active'
    logs = _dk_logs(vm_id)
    t = _DK_TASKS.get(vm_id)
    if t and (not t['done'] or t['log']):
        head = f"== {t['label']}{'' if not t['done'] else ' (finished)'} ==\n" + '\n'.join(t['log'][-40:]) + '\n== server log ==\n'
        logs = head + logs
    addr, note = None, None
    players = None
    if kind == 'minecraft':
        addr, note = _dk_best_address(v)
        if state == 'active':
            players = _mc_online_cached(vm_id)
    return jsonify({'success': True, 'machine': True, 'installed': True, 'state': state, 'console': running == 'true',
                    'logs': logs, 'address': addr, 'address_note': note, 'java_issue': False, 'busy': _dk_busy(vm_id), 'players': players})


def dk_server_power(vm_id):
    action = (request.get_json(silent=True) or {}).get('action', '')
    c = _cname(vm_id)
    if action in ('start', 'restart') and _DK_OVER.get(vm_id):
        return _dk_json_err('Disk limit exceeded — delete some files (File manager), then start the server again.')
    if action in ('start', 'restart') and _expired_block(vm_id):
        return _expired_block(vm_id)
    cmds = {'start': ('start', c), 'stop': ('stop', '-t', '60', c), 'restart': ('restart', '-t', '60', c), 'kill': ('kill', c)}
    if action not in cmds:
        return _dk_json_err('Unknown action.')
    rc, out, err = _docker(*cmds[action], timeout=120)
    if rc == 0 and _dk_kind(_dk_row(vm_id)) == 'minecraft' and _dk_playit_on(_dk_conn_read(vm_id)):
        if action in ('start', 'restart'):
            threading.Thread(target=_dk_playit_sync, args=(vm_id,), daemon=True).start()
        else:
            _docker('stop', _dk_playit_name(vm_id), timeout=30)
    audit(session['user_id'], f'server_{action}', f'{vm_id} (docker)')
    return jsonify({'success': rc == 0, 'message': (err or out).strip()[:300] or 'OK'})


def dk_server_command(vm_id):
    v = _dk_row(vm_id)
    cmd = ((request.get_json(silent=True) or {}).get('command') or '').strip()
    if not cmd or len(cmd) > 300 or '\n' in cmd or '\r' in cmd:
        return _dk_json_err('Enter a single-line command (max 300 chars).')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('The server is not running.')
    if _dk_kind(v) == 'minecraft':
        ok, out = _dk_rcon(vm_id, cmd)
        return jsonify({'success': ok, 'message': out[:300] if not ok else 'Sent.'})
    try:
        with open(_dk_dir(vm_id) / '.console_in', 'a', encoding='utf-8') as f:
            f.write(cmd + '\n')
    except Exception as e:
        return _dk_json_err(f'Could not send: {e}')
    return jsonify({'success': True})


def dk_server_enable_console(vm_id):
    return jsonify({'success': True, 'message': 'Console is always enabled on Docker servers.'})


def dk_server_retry_install(vm_id):
    return _dk_json_err('Docker servers install automatically. If creation failed, delete the server and buy again.')


def dk_server_startup(vm_id):
    v = _dk_row(vm_id)
    if _dk_kind(v) != 'bot':
        return _dk_json_err('Only bot servers have a startup command.')
    cmd = ((request.get_json(silent=True) or {}).get('command') or '').strip()
    if not cmd or len(cmd) > 300 or '\n' in cmd or '\r' in cmd:
        return _dk_json_err('Enter a single-line command (max 300 chars).')
    _dk_write_bot_script(vm_id, cmd)
    db_execute("UPDATE vm_instances SET startup_cmd=? WHERE vm_id=?", (cmd, vm_id))
    audit(session['user_id'], 'server_startup_cmd', f'{vm_id}: {cmd[:80]}')
    return jsonify({'success': True, 'message': 'Saved. Restart the server to use it.'})


# ---- Minecraft: info / plugins / icon / properties ----
def _dk_mc_version(v):
    m = re.search(r'Starting minecraft server version ([0-9][0-9.a-z-]*)', _dk_logs(v['vm_id'], 1500))
    if m and _RE_VER.match(m.group(1)):
        return m.group(1)
    ver = (_mc_opt(v).get('version') or '').strip()
    return ver if ver and ver.lower() != 'latest' and _RE_VER.match(ver) else ''


def dk_mc_info(vm_id):
    v = _dk_row(vm_id)
    return jsonify({'success': True, 'version': _dk_mc_version(v), 'software': _mc_opt(v).get('software') or 'paper',
                    'icon': (_dk_dir(vm_id) / 'server-icon.png').exists(), 'ram_mb': v['ram_mb']})


def _dk_plugins_dir(vm_id):
    p = _dk_dir(vm_id) / 'plugins'
    p.mkdir(parents=True, exist_ok=True)
    _dk_chown(str(p), 1000, 1000)
    return p


def dk_mc_plugins(vm_id):
    items = []
    for f in _dk_plugins_dir(vm_id).iterdir():
        if f.is_file() and _RE_JAR.match(f.name):
            items.append({'file': f.name, 'size': f.stat().st_size, 'enabled': not f.name.endswith('.disabled')})
    return jsonify({'success': True, 'plugins': sorted(items, key=lambda x: x['file'].lower())})


def _dk_download(url, dest, max_bytes=120 * 1024 * 1024):
    req = urllib.request.Request(url, headers={'User-Agent': _HTTP_UA})
    part = str(dest) + '.part'
    size = 0
    with urllib.request.urlopen(req, timeout=60) as r, open(part, 'wb') as out:
        while True:
            chunk = r.read(65536)
            if not chunk:
                break
            size += len(chunk)
            if size > max_bytes:
                raise RuntimeError('file is too large')
            out.write(chunk)
    os.replace(part, dest)
    _dk_chown(str(dest), 1000, 1000)


def dk_mc_plugin_install(vm_id):
    v = _dk_row(vm_id)
    slug = ((request.get_json(silent=True) or {}).get('slug') or '').strip()
    if not _RE_SLUG.match(slug):
        return _dk_json_err('Invalid plugin.')
    mcv = _dk_mc_version(v)
    try:
        ver, exact = _mc_resolve_plugin(slug, mcv)
        if not ver:
            return _dk_json_err('No compatible download found for this plugin.')
        main = _mc_plugin_file(ver)
        if not main:
            return _dk_json_err('This plugin has no safe downloadable file.')
        todo = [main]
        for d in ver.get('dependencies') or []:
            if d.get('dependency_type') == 'required' and d.get('project_id') and _RE_SLUG.match(d['project_id']):
                dv, _ = _mc_resolve_plugin(d['project_id'], mcv)
                df = _mc_plugin_file(dv) if dv else None
                if df:
                    todo.append(df)
        pdir = _dk_plugins_dir(vm_id)
        for url, name in todo:
            if not (pdir / name).exists():
                _dk_download(url, pdir / name)
    except Exception as e:
        return _dk_json_err(f'Install failed: {e}')
    audit(session['user_id'], 'mc_plugin_install', f'{vm_id}: {slug}')
    note = '' if exact or not mcv else f' (no build is tagged for {mcv}; installed the newest — it may not work)'
    return jsonify({'success': True, 'message': f"Installed {', '.join(n for _, n in todo)}{note}. Restart the server to load it."})


def dk_mc_plugin_manage(vm_id):
    d = request.get_json(silent=True) or {}
    name, action = d.get('file') or '', d.get('action')
    if not _RE_JAR.match(name) or action not in ('delete', 'toggle'):
        return _dk_json_err('Invalid request.')
    p = _dk_plugins_dir(vm_id) / name
    if not p.is_file():
        return _dk_json_err('File not found.')
    if action == 'delete':
        p.unlink()
    elif name.endswith('.disabled'):
        p.rename(p.with_name(name[:-len('.disabled')]))
    else:
        p.rename(p.with_name(name + '.disabled'))
    audit(session['user_id'], 'mc_plugin_' + action, f'{vm_id}: {name}')
    return jsonify({'success': True, 'message': 'Done. Restart the server to apply.'})


def dk_mc_icon(vm_id):
    path = _dk_dir(vm_id) / 'server-icon.png'
    if request.method == 'GET':
        if not path.exists():
            return ('', 404)
        return app.response_class(path.read_bytes(), mimetype='image/png', headers={'Cache-Control': 'no-store'})
    if request.method == 'DELETE':
        path.unlink(missing_ok=True)
        return jsonify({'success': True, 'message': 'Icon removed. Restart the server to apply.'})
    data = (request.get_json(silent=True) or {}).get('png') or ''
    try:
        raw = base64.b64decode(data.split(',')[-1], validate=True)
    except Exception:
        return _dk_json_err('Invalid image.')
    if not raw.startswith(b'\x89PNG\r\n\x1a\n') or len(raw) > 40000 or struct.unpack('>II', raw[16:24]) != (64, 64):
        return _dk_json_err('Icon must be a 64×64 PNG under 40 KB.')
    path.write_bytes(raw)
    _dk_chown(str(path), 1000, 1000)
    audit(session['user_id'], 'mc_icon_set', vm_id)
    return jsonify({'success': True, 'message': 'Icon saved. Restart the server to apply.'})


def _dk_props_read(vm_id):
    props = {}
    p = _dk_dir(vm_id) / 'server.properties'
    if p.exists():
        for line in p.read_text(encoding='utf-8', errors='replace')[:30000].splitlines():
            if line and not line.startswith('#') and '=' in line:
                k, _, val = line.partition('=')
                props[k.strip()] = val
    return props


def _dk_props_write(vm_id, changes):
    p = _dk_dir(vm_id) / 'server.properties'
    lines = p.read_text(encoding='utf-8', errors='replace').splitlines() if p.exists() else []
    done, out = set(), []
    for l in lines:
        m = re.match(r'^([A-Za-z0-9.\-]+)=', l)
        if m and m.group(1) in changes:
            out.append(m.group(1) + '=' + changes[m.group(1)])
            done.add(m.group(1))
        else:
            out.append(l)
    for k, x in changes.items():
        if k not in done:
            out.append(k + '=' + x)
    p.write_text('\n'.join(out) + '\n', encoding='utf-8')
    _dk_chown(str(p), 1000, 1000)


def dk_mc_properties(vm_id):
    if request.method == 'GET':
        props = _dk_props_read(vm_id)
        return jsonify({'success': True, 'props': props, 'exists': bool(props)})
    ch = (request.get_json(silent=True) or {}).get('changes')
    if not isinstance(ch, dict) or not ch or len(ch) > 60:
        return _dk_json_err('Nothing to save.')
    clean = {}
    for k, val in ch.items():
        val = '' if val is None else str(val)
        if (not re.match(r'^[a-z0-9.\-]{1,60}$', k) or k in _MC_DENY_PROPS or len(val) > 500
                or not val.isascii() or any(ord(c) < 32 for c in val)):
            return _dk_json_err(f'Not allowed: {k}')
        clean[k] = val
    _dk_props_write(vm_id, clean)
    audit(session['user_id'], 'mc_properties', f'{vm_id}: {", ".join(clean)[:120]}')
    return jsonify({'success': True, 'message': 'Saved. Restart the server to apply.'})


# ---- Minecraft: version change (recreates the container; itzg downloads the jar) ----
def _dk_recreate_mc(v, opt, log):
    vid = v['vm_id']
    fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (vid,), fetchone=True)
    image, args = _dk_mc_create_args(vid, v['ram_mb'], v['cpu_cores'], fw['host_port'] if fw else 25565, opt)
    log(f'Pulling {image}…')
    rc, out, err = _docker('pull', image, timeout=1800)
    if rc != 0:
        raise RuntimeError('image download failed: ' + (err or out).strip()[-200:])
    _docker('stop', '-t', '60', _cname(vid), timeout=120)
    _docker('rm', '-f', _cname(vid), timeout=60)
    rc, out, err = _docker(*args, timeout=120)
    if rc != 0:
        raise RuntimeError('container create failed: ' + (err or out).strip()[-300:])
    rc, out, err = _docker('start', _cname(vid), timeout=60)
    if rc != 0:
        raise RuntimeError('container start failed: ' + (err or out).strip()[-300:])
    _dk_playit_sync(vid)


def _dk_mc_cracked_state(vid):
    rc, out, _ = _docker('inspect', '-f', '{{json .Config.Env}}', _cname(vid), timeout=10)
    try:
        env = json.loads(out) if rc == 0 else []
    except ValueError:
        env = []
    return 'ONLINE_MODE=FALSE' in [e.upper() for e in env]


@app.route('/vm/<vm_id>/server/mc/cracked', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def dk_mc_cracked(vm_id):
    """Allow / forbid cracked (offline-mode) players. Needs a container rebuild because itzg reads these as env vars."""
    if not _is_docker_vm(vm_id):
        return _dk_json_err('This option is for Docker Minecraft servers.')
    v = _dk_row(vm_id)
    if request.method == 'GET':
        return jsonify({'success': True, 'cracked': _dk_mc_cracked_state(vm_id)})
    want = bool((request.get_json(silent=True) or {}).get('enabled'))
    opt = _mc_opt(v)
    opt['cracked'] = want

    def work(log):
        log('Applying the new login mode…')
        _dk_recreate_mc(v, opt, log)
        try:
            _dk_props_write(vm_id, {'online-mode': 'false' if want else 'true'})
        except Exception:
            pass
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vm_id))
        log('Done — cracked players ' + ('can join now.' if want else 'can no longer join.'))
    ok, msg = _dk_task(vm_id, 'Changing login mode', work)
    if ok:
        audit(session['user_id'], 'mc_cracked', f'{vm_id[:8]} {want}')
    return jsonify({'success': ok, 'message': msg if not ok else 'Rebuilding the server — it restarts in about a minute.'})


def dk_mc_change_version(vm_id):
    v = _dk_row(vm_id)
    d = request.get_json(silent=True) or {}
    sw, ver, backup = d.get('software'), (d.get('version') or '').strip(), bool(d.get('backup', True))
    if sw not in _DK_MC_TYPES or sw == 'modrinth' or not _RE_VER.match(ver):
        return _dk_json_err('Pick a software and version.')
    opt = _mc_opt(v)
    opt.update({'software': sw, 'version': ver})

    def work(log):
        if backup:
            log('Backing up the world first…')
            _dk_make_backup(vm_id, 'pre-update', log)
        log(f'Switching to {sw} {ver}…')
        for old in _dk_dir(vm_id).glob('*.jar'):
            if old.name != 'server-icon.png':
                pass  # itzg manages its own jars; leave user files alone
        _dk_recreate_mc(v, opt, log)
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vm_id))
        log(f'Done — now running {sw} {ver}.')
    ok, msg = _dk_task(vm_id, f'Changing version to {sw} {ver}', work)
    if ok:
        audit(session['user_id'], 'mc_change_version', f'{vm_id}: {sw} {ver}')
    return jsonify({'success': ok, 'message': msg})


# ---- Minecraft: backups ----
_DK_WORLD_ITEMS = ('world', 'world_nether', 'world_the_end', 'plugins', 'server.properties', 'whitelist.json', 'ops.json')


def _dk_backup_dir(vm_id):
    p = DK_BACKUP_DIR / str(vm_id)
    p.mkdir(parents=True, exist_ok=True)
    return p


def _dk_make_backup(vm_id, prefix, log=lambda m: None):
    running = dk_status(vm_id)[0]
    if running:
        _dk_rcon(vm_id, 'save-off')
        _dk_rcon(vm_id, 'save-all flush')
        time.sleep(6)
    try:
        dest = _dk_backup_dir(vm_id) / f"{prefix}-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}.tgz"
        base = _dk_dir(vm_id)
        with tarfile.open(dest, 'w:gz') as tar:
            for name in _DK_WORLD_ITEMS:
                if (base / name).exists():
                    tar.add(str(base / name), arcname=name)
        log(f'Saved {dest.name} ({dest.stat().st_size // 1024} KB)')
        return dest
    finally:
        if running:
            _dk_rcon(vm_id, 'save-on')


def dk_mc_backups(vm_id):
    items = []
    for f in _dk_backup_dir(vm_id).glob('*.tgz'):
        if _RE_BACKUP.match(f.name):
            st = f.stat()
            items.append({'file': f.name, 'size': st.st_size, 'time': int(st.st_mtime)})
    items.sort(key=lambda x: -x['time'])
    return jsonify({'success': True, 'backups': items, 'free_mb': shutil.disk_usage(str(DOCKER_SERVERS_DIR)).free // (1024 * 1024)})


def dk_mc_backup_action(vm_id, action):
    name = (request.get_json(silent=True) or {}).get('file') or ''
    if action == 'create':
        ok, msg = _dk_task(vm_id, 'Creating backup', lambda log: _dk_make_backup(vm_id, 'backup', log))
    elif action in ('restore', 'delete') and _RE_BACKUP.match(name):
        path = _dk_backup_dir(vm_id) / name
        if not path.is_file():
            return _dk_json_err('Backup not found.')
        if action == 'delete':
            path.unlink()
            ok, msg = True, 'Backup deleted.'
        else:
            def work(log):
                base = _dk_dir(vm_id)
                log('Stopping the server…')
                _docker('stop', '-t', '60', _cname(vm_id), timeout=120)
                for w in ('world', 'world_nether', 'world_the_end'):
                    shutil.rmtree(base / w, ignore_errors=True)
                with tarfile.open(path, 'r:gz') as tar:
                    for m in tar.getmembers():
                        top = m.name.split('/')[0]
                        if top not in _DK_WORLD_ITEMS or m.name.startswith('/') or '..' in m.name.split('/') or not (m.isfile() or m.isdir()):
                            continue
                        tar.extract(m, str(base))
                _dk_chown_tree(str(base), 1000)
                log('Starting the server…')
                _docker('start', _cname(vm_id), timeout=60)
                log('Restore finished.')
            ok, msg = _dk_task(vm_id, 'Restoring ' + name, work)
    else:
        return _dk_json_err('Invalid request.')
    audit(session['user_id'], 'mc_backup_' + action, f'{vm_id}: {name}')
    return jsonify({'success': ok, 'message': msg})


# ---- Minecraft: players ----
def dk_mc_players(vm_id):
    online = {'count': 0, 'max': None, 'names': []}
    if dk_status(vm_id)[0]:
        ok, out = _dk_rcon(vm_id, 'list')
        m = re.search(r'There are (\d+) of a max of (\d+) players online:?\s*(.*)', out) if ok else None
        if m:
            online = {'count': int(m.group(1)), 'max': int(m.group(2)),
                      'names': [n.strip() for n in m.group(3).split(',') if _RE_PLAYER.match(n.strip())]}

    def names(fname, extra=None):
        try:
            data = json.loads((_dk_dir(vm_id) / fname).read_text(encoding='utf-8') or '[]')
        except Exception:
            data = []
        res = []
        for e in data if isinstance(data, list) else []:
            if isinstance(e, dict) and _RE_PLAYER.match(str(e.get('name', ''))):
                res.append({'name': e['name'], **({extra: e.get(extra)} if extra else {})})
        return res
    return jsonify({'success': True, 'online': online, 'whitelist': names('whitelist.json'),
                    'ops': names('ops.json', 'level'), 'bans': names('banned-players.json', 'reason')})


def dk_mc_players_action(vm_id):
    d = request.get_json(silent=True) or {}
    act, name = d.get('action'), (d.get('name') or '').strip()
    reason = re.sub(r'[\r\n]', ' ', (d.get('reason') or '').strip())[:80]
    cmds = {'whitelist-add': 'whitelist add ', 'whitelist-remove': 'whitelist remove ', 'op': 'op ', 'deop': 'deop ',
            'ban': 'ban ', 'pardon': 'pardon ', 'kick': 'kick '}
    if act not in cmds or not _RE_PLAYER.match(name):
        return _dk_json_err('Enter a valid Java username (3-16 letters, numbers, _).')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('The server must be running for this.')
    ok, out = _dk_rcon(vm_id, cmds[act] + name + (' ' + reason if act in ('ban', 'kick') and reason else ''))
    audit(session['user_id'], 'mc_player_' + act, f'{vm_id}: {name}')
    return jsonify({'success': ok, 'message': 'Sent.' if ok else out[:200]})


# ---- Minecraft: schedule (panel-side; no cron needed) ----
def _dk_sched_path(vm_id):
    return _dk_backup_dir(vm_id) / 'schedule.json'


def _dk_sched_read(vm_id):
    try:
        c = json.loads(_dk_sched_path(vm_id).read_text())
        return c if isinstance(c, dict) else {}
    except Exception:
        return {}


def dk_mc_schedule(vm_id):
    cfg = _dk_sched_read(vm_id)
    if request.method == 'GET':
        return jsonify({'success': True, 'config': {'restart_hours': int(cfg.get('restart_hours', 0)),
                        'backup_hour': int(cfg.get('backup_hour', -1)), 'keep': int(cfg.get('keep', 5))}})
    d = request.get_json(silent=True) or {}
    try:
        rh, bh, keep = int(d.get('restart_hours', 0)), int(d.get('backup_hour', -1)), int(d.get('keep', 5))
    except (TypeError, ValueError):
        return _dk_json_err('Invalid values.')
    if rh not in (0, 3, 6, 12, 24) or not -1 <= bh <= 23 or not 1 <= keep <= 30:
        return _dk_json_err('Invalid values.')
    cfg.update({'restart_hours': rh, 'backup_hour': bh, 'keep': keep})
    _dk_sched_path(vm_id).write_text(json.dumps(cfg))
    audit(session['user_id'], 'mc_schedule', f'{vm_id}: restart={rh}h backup={bh}')
    return jsonify({'success': True, 'message': 'Schedule saved.'})


def _dk_do_restart(vid):
    try:
        if dk_status(vid)[0]:
            for msg, wait in (('Server restarting in 60 seconds!', 30), ('Restarting in 30 seconds...', 20), ('Restarting in 10 seconds...', 10)):
                _dk_rcon(vid, 'say ' + msg)
                time.sleep(wait)
            _dk_rcon(vid, 'save-all flush')
            time.sleep(4)
            _docker('restart', '-t', '60', _cname(vid), timeout=120)
    except Exception as e:
        print(f'[docker] scheduled restart failed for {vid}: {e}', flush=True)


def _dk_do_auto_backup(vid, keep):
    try:
        _dk_make_backup(vid, 'auto')
        autos = sorted(_dk_backup_dir(vid).glob('auto-*.tgz'), key=lambda f: f.stat().st_mtime, reverse=True)
        for old in autos[keep:]:
            old.unlink(missing_ok=True)
    except Exception as e:
        print(f'[docker] scheduled backup failed for {vid}: {e}', flush=True)


def _dk_scheduler_loop():
    while True:
        try:
            time.sleep(60)
            if not docker_available():
                continue
            now = datetime.utcnow()
            for r in (db_execute("SELECT * FROM vm_instances WHERE runtime='docker'", fetch=True) or []):
                try:
                    _dk_check_alerts(r)
                    if int(time.time() // 60) % 5 == 0:
                        _dk_enforce_disk(r)
                except Exception as e:
                    print(f'[docker] monitor error: {e}', flush=True)
            for r in (db_execute("SELECT vm_id FROM vm_instances WHERE runtime='docker' AND provision_kind='minecraft'", fetch=True) or []):
                vid = r['vm_id']
                try:
                    _dk_playit_sync(vid)
                except Exception:
                    pass
                try:
                    _dk_mk_cracked_tick(_dk_row(vid))
                except Exception as e:
                    print('[minekube-cracked]', str(e)[:80], flush=True)
                cfg = _dk_sched_read(vid)
                if not cfg:
                    continue
                changed = False
                rh = int(cfg.get('restart_hours', 0))
                due = rh and now.minute < 5 and ((now.hour == 4) if rh == 24 else (now.hour % rh == 0))
                if due and time.time() - float(cfg.get('last_restart', 0)) > 3000:
                    cfg['last_restart'] = time.time(); changed = True
                    threading.Thread(target=_dk_do_restart, args=(vid,), daemon=True).start()
                bh = int(cfg.get('backup_hour', -1))
                today = now.strftime('%Y-%m-%d')
                if bh >= 0 and now.hour == bh and now.minute >= 30 and cfg.get('last_backup') != today:
                    cfg['last_backup'] = today; changed = True
                    threading.Thread(target=_dk_do_auto_backup, args=(vid, int(cfg.get('keep', 5))), daemon=True).start()
                if changed:
                    _dk_sched_path(vid).write_text(json.dumps(cfg))
        except Exception as e:
            print(f'[docker] scheduler error: {e}', flush=True)


def start_docker_scheduler_thread():
    threading.Thread(target=_dk_scheduler_loop, daemon=True, name='dk-scheduler').start()


# ---- Bot: env, dependencies, git ----
_DK_BOT_DEPS = ("cd /data\n"
                "if [ -f package.json ]; then echo '== npm install =='; npm install --omit=dev --no-audit --no-fund; fi\n"
                "if [ -f requirements.txt ]; then echo '== pip install =='; [ -f venv/bin/activate ] || python3 -m venv venv; . venv/bin/activate; pip install -r requirements.txt; fi\n"
                "echo 'Dependencies done'\n")


def _dk_runtime(vm_id):
    v = _dk_row(vm_id)
    try:
        opt = json.loads(row_get(v, 'provision_opt') or 'null')
    except Exception:
        opt = None
    return opt if opt in ('node', 'python') else 'node'


def _dk_run_in_image(vm_id, script, log):
    image = _DK_IMAGES[_dk_runtime(vm_id)]
    p = subprocess.Popen(['docker', 'run', '--rm', '-v', f'{_dk_dir(vm_id)}:/data', '-w', '/data', '-e', 'HOME=/data', image, 'bash', '-c', script],
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        log(_DK_ANSI.sub('', line.rstrip())[:300])
    p.wait()
    if p.returncode != 0:
        raise RuntimeError(f'exit code {p.returncode}')


def dk_bot_setup(vm_id):
    envp = _dk_dir(vm_id) / '.env'
    if request.method == 'GET':
        gitp = _dk_dir(vm_id) / '.phvm-git'
        return jsonify({'success': True, 'env': envp.read_text(encoding='utf-8', errors='replace')[:12000] if envp.exists() else '',
                        'git': gitp.read_text().strip() if gitp.exists() else ''})
    env = (request.get_json(silent=True) or {}).get('env', '')
    if not isinstance(env, str) or len(env) > 10000 or '\x00' in env:
        return _dk_json_err('Invalid environment text.')
    envp.write_text(env, encoding='utf-8')
    envp.chmod(0o600)
    audit(session['user_id'], 'bot_env_save', vm_id)
    return jsonify({'success': True, 'message': 'Saved. Restart the bot to use the new values.'})


def dk_bot_install_deps(vm_id):
    ok, msg = _dk_task(vm_id, 'Installing dependencies', lambda log: _dk_run_in_image(vm_id, _DK_BOT_DEPS, log))
    if ok:
        audit(session['user_id'], 'bot_install_deps', vm_id)
    return jsonify({'success': ok, 'message': msg})


def dk_bot_git_deploy(vm_id):
    d = request.get_json(silent=True) or {}
    url, branch = (d.get('url') or '').strip(), (d.get('branch') or '').strip()
    if not _RE_GIT_URL.match(url) or (branch and not _RE_BRANCH.match(branch)):
        return _dk_json_err('Use a public https URL from GitHub, GitLab or Bitbucket.')
    b = ('-b ' + shlex.quote(branch) + ' ') if branch else ''
    script = ("set -e\nrm -rf /tmp/repo\ngit clone --depth 1 " + b + shlex.quote(url) + " /tmp/repo\nrm -rf /tmp/repo/.git\n"
              "cp -a /tmp/repo/. /data/\necho " + shlex.quote(url + '|' + branch) + " > /data/.phvm-git\n" + _DK_BOT_DEPS)

    def work(log):
        _dk_run_in_image(vm_id, script, log)
        if dk_status(vm_id)[0]:
            log('Restarting the bot…')
            _docker('restart', '-t', '30', _cname(vm_id), timeout=90)
        log('Deploy finished.')
    ok, msg = _dk_task(vm_id, 'Deploying from Git', work)
    if ok:
        audit(session['user_id'], 'bot_git_deploy', f'{vm_id}: {url}')
    return jsonify({'success': ok, 'message': msg})


# ---- Connection methods for Docker Minecraft servers: Direct / Minekube Connect / playit.gg ----
_DK_PLAYIT_IMAGE = 'ghcr.io/playit-cloud/playit-agent:latest'
_DK_MINEKUBE_URL = 'https://github.com/minekube/connect-java/releases/latest/download/connect-spigot.jar'
_RE_PLAYIT_ADDR = re.compile(r'[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.(?:joinmc\.link|ply\.gg|playit\.plus)(?::\d+)?')
_RE_MK_ADDR = re.compile(r'[A-Za-z0-9-]+\.play\.minekube\.net')
_RE_PLAYIT_KEY = re.compile(r'^[A-Za-z0-9_\-]{16,200}$')
_RE_ADDR_INPUT = re.compile(r'^[A-Za-z0-9.\-]{3,100}(:[0-9]{2,5})?$')


def _dk_playit_name(vid):
    return _cname(vid) + '-playit'


def _dk_conn_path(vid):
    return _dk_backup_dir(vid) / 'connection.json'


def _dk_conn_read(vid):
    try:
        c = json.loads(_dk_conn_path(vid).read_text())
        return c if isinstance(c, dict) else {}
    except Exception:
        return {}


def _dk_conn_write(vid, cfg):
    p = _dk_conn_path(vid)
    p.write_text(json.dumps(cfg))
    try:
        p.chmod(0o600)
    except Exception:
        pass


def _dk_started_at(name):
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}|{{.State.StartedAt}}', name, timeout=10)
    if rc != 0:
        return False, ''
    run, _, at = out.strip().partition('|')
    return run == 'true', at


def _dk_playit_run(vid, key=None):
    """(Re)create the playit sidecar. It shares the Minecraft container's network namespace,
    so the tunnel's local address is simply 127.0.0.1:25565.
    Without a key the agent starts in claim mode: it prints a https://playit.gg/claim/... link and keeps its
    login in a folder next to the server's backups, so nobody has to copy a secret key around."""
    n = _dk_playit_name(vid)
    _docker('rm', '-f', n, timeout=30)
    args = ['run', '-d', '--name', n, '--restart', 'unless-stopped', '--label', 'phvm=1',
            '--network', 'container:' + _cname(vid), '--memory', '128m']
    if key:
        args += ['-e', 'SECRET_KEY=' + key]
    else:
        keep = _dk_backup_dir(vid) / 'playit'
        keep.mkdir(parents=True, exist_ok=True)
        args += ['-v', f'{keep}:/etc/playit']
    rc, out, err = _docker(*args, _DK_PLAYIT_IMAGE, timeout=600)
    return rc == 0, (err or out).strip()[-300:]


_RE_PLAYIT_CLAIM = re.compile(r'https://playit\.gg/(?:claim|login/guest-account)/[A-Za-z0-9_\-?=&./]+')


def _dk_playit_claim(vid):
    """The claim link the agent printed (if it is waiting to be claimed)."""
    rc, out, err = _docker('logs', '--tail', '300', _dk_playit_name(vid), timeout=15)
    found = _RE_PLAYIT_CLAIM.findall(_DK_ANSI.sub('', (out or '') + (err or '')))
    return found[-1] if found else ''


def _dk_playit_on(cfg):
    return bool(cfg.get('playit_key') or cfg.get('playit_claim'))


def _dk_playit_sync(vid):
    """Keep the sidecar attached to the current Minecraft container (needed after the MC container restarts)."""
    cfg = _dk_conn_read(vid)
    key = cfg.get('playit_key')
    if not _dk_playit_on(cfg):
        return
    mc_run, mc_at = _dk_started_at(_cname(vid))
    if not mc_run:
        return
    pl_run, pl_at = _dk_started_at(_dk_playit_name(vid))
    if not pl_run or (mc_at and pl_at and mc_at > pl_at):
        _dk_playit_run(vid, key)


def _dk_install_minekube(vid):
    pdir = _dk_plugins_dir(vid)
    _dk_download(_DK_MINEKUBE_URL, pdir / 'connect-spigot.jar')


def _mc_cracked(opt):
    return bool(opt['cracked']) if 'cracked' in opt else (gsv('mc_cracked_default', 'true') or 'true').lower() in ('1', 'true', 'yes')


def _dk_mk_cfg_path(vid):
    return _dk_dir(vid) / 'plugins' / 'connect' / 'config.yml'


def _dk_mk_cracked_state(vid):
    """True/False = what Minekube Connect's config says about offline-mode players; None = no config file yet."""
    try:
        txt = _dk_mk_cfg_path(vid).read_text(errors='replace')
    except Exception:
        return None
    m_ = re.search(r'^\s*allow-offline-mode-players\s*:\s*(\S+)', txt, re.M)
    return bool(m_ and m_.group(1).strip().lower().strip('"\'') == 'true')


def _dk_mk_cracked_sync(vid, want):
    """Minekube Connect only lets premium players in unless `allow-offline-mode-players` is true in its own config.
    Make that setting match the server's Cracked mode. Returns True if the file changed (server needs a restart)."""
    p = _dk_mk_cfg_path(vid)
    if not p.exists():
        return False
    txt = p.read_text(errors='replace')
    val = 'true' if want else 'false'
    if re.search(r'^\s*allow-offline-mode-players\s*:', txt, re.M):
        new = re.sub(r'^(\s*allow-offline-mode-players\s*:\s*)\S+', lambda m_: m_.group(1) + val, txt, count=1, flags=re.M)
    else:
        new = txt.rstrip('\n') + f'\nallow-offline-mode-players: {val}\n'
    if new == txt:
        return False
    p.write_text(new)
    try:
        _dk_chown(str(p), 1000, 1000)
    except Exception:
        pass
    return True


def _dk_mk_cracked_tick(v):
    """Runs every minute for Minekube servers: keeps the plugin config in step with Cracked mode (restarts once if it had to change)."""
    vid = v['vm_id']
    opt = _mc_opt(v)
    if not opt.get('minekube'):
        return False
    if not _dk_mk_cracked_sync(vid, _mc_cracked(opt)):
        return False
    try:
        if dk_status(vid)[0]:
            threading.Thread(target=lambda: _docker('restart', '-t', '30', _cname(vid), timeout=120), daemon=True).start()
        notify_user(v['user_id'], 'Minekube address updated', f'"{v["name"]}": non-premium (cracked) players ' +
                    ('can now join through the Minekube address. The server restarted once to apply it.' if _mc_cracked(opt) else 'are no longer allowed through the Minekube address.'), 'success')
    except Exception:
        pass
    return True


def _dk_best_address(v):
    """(address, note) players should use, by the connection method this server is set up with."""
    vid = v['vm_id']
    opt, cfg = _mc_opt(v), _dk_conn_read(vid)
    direct = _dk_address(v)
    _sd = _mcsub_get(vid)
    if _sd:
        return _sd, 'Your own address — no port needed'
    if opt.get('minekube'):
        found = _RE_MK_ADDR.findall(_dk_logs(vid, 1500))
        if found:
            return found[-1], 'Minekube address'
    if _dk_playit_on(cfg):
        if cfg.get('playit_address'):
            return cfg['playit_address'], 'playit.gg address'
        rc, out, err = _docker('logs', '--tail', '300', _dk_playit_name(vid), timeout=15)
        found = _RE_PLAYIT_ADDR.findall(_DK_ANSI.sub('', out + err))
        if found:
            return found[-1], 'playit.gg address'
        claim = _dk_playit_claim(vid) if cfg.get('playit_claim') else ''
        if claim:
            return None, 'Open this link once to connect playit: ' + claim
        if not direct:
            return None, 'playit agent is running — create a tunnel to 127.0.0.1:25565 in your playit dashboard'
    if direct:
        return direct, ('Direct address' + (' (Minekube address appears here once it is ready)' if opt.get('minekube') else ''))
    return None, 'Set "Server IP" in admin settings to show the address'


@app.route('/vm/<vm_id>/server/mc/connection', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def mc_connection(vm_id):
    if not _is_docker_vm(vm_id):
        return _dk_json_err('Connection options are only available for Docker servers.')
    v = _dk_row(vm_id)
    if _dk_kind(v) != 'minecraft':
        return _dk_json_err('Minecraft servers only.')
    opt, cfg = _mc_opt(v), _dk_conn_read(vm_id)
    if request.method == 'GET':
        pl_run, _ = _dk_started_at(_dk_playit_name(vm_id)) if _dk_playit_on(cfg) else (False, '')
        addr, note = _dk_best_address(v)
        return jsonify({'success': True, 'direct': _dk_address(v), 'address': addr, 'note': note,
                        'software': opt.get('software') or 'paper',
                        'minekube': bool(opt.get('minekube')),
                        'playit': {'configured': _dk_playit_on(cfg), 'running': pl_run,
                                   'claim': (_dk_playit_claim(vm_id) if (pl_run and cfg.get('playit_claim') and not cfg.get('playit_key')) else ''),
                                   'address': cfg.get('playit_address') or ''},
                        'bedrock': _dk_bedrock_info(v),
                        'subdomain': {'base': _mcsub_base(), 'current': _mcsub_get(vm_id), 'ready': bool((gsv('cf_api_token', '') or '').strip())}})
    d = request.get_json(silent=True) or {}
    act = d.get('action')
    if act in ('minekube-enable', 'minekube-disable'):
        enable = act == 'minekube-enable'
        if enable and (opt.get('software') or 'paper') not in ('paper', 'purpur'):
            return _dk_json_err('Minekube Connect is a plugin — it only works on Paper or Purpur.')
        new_opt = dict(opt, minekube=enable)

        def work(log):
            if enable:
                log('Downloading the Minekube Connect plugin…')
                _dk_install_minekube(vm_id)
            else:
                (_dk_plugins_dir(vm_id) / 'connect-spigot.jar').unlink(missing_ok=True)
            db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(new_opt), vm_id))
            log('Restarting the server…')
            _dk_recreate_mc(v, new_opt, log)
            if enable:
                log('Cracked players are let in through Minekube automatically (applied within a minute of the plugin creating its config).')
            log('Done.' + (' The Minekube address shows up in the console and sidebar in a minute.' if enable else ''))
        ok, msg = _dk_task(vm_id, ('Enabling' if enable else 'Disabling') + ' Minekube Connect', work)
        audit(session['user_id'], 'mc_' + act.replace('-', '_'), vm_id)
        return jsonify({'success': ok, 'message': msg})
    if act == 'playit-set':
        key = (d.get('key') or '').strip()
        if not _RE_PLAYIT_KEY.match(key):
            return _dk_json_err('That does not look like a playit secret key.')
        cfg['playit_key'] = key
        cfg.pop('playit_claim', None)
        _dk_conn_write(vm_id, cfg)
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(dict(opt, playit=True)), vm_id))

        def work(log):
            log('Starting the playit agent…')
            ok, err = _dk_playit_run(vm_id, key)
            if not ok:
                raise RuntimeError(err)
            log('Agent started. Create a Minecraft tunnel to 127.0.0.1:25565 in your playit dashboard.')
        ok, msg = _dk_task(vm_id, 'Starting playit.gg agent', work)
        audit(session['user_id'], 'mc_playit_set', vm_id)
        return jsonify({'success': ok, 'message': msg})
    if act == 'playit-start':
        cfg['playit_claim'] = True
        cfg.pop('playit_key', None)
        _dk_conn_write(vm_id, cfg)
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(dict(opt, playit=True)), vm_id))

        def work(log):
            log('Starting the playit agent (no key needed)…')
            ok, err = _dk_playit_run(vm_id, None)
            if not ok:
                raise RuntimeError(err)
            log('Agent started. A claim link will appear in the Connection tab in a few seconds.')
        ok, msg = _dk_task(vm_id, 'Starting playit.gg agent', work)
        audit(session['user_id'], 'mc_playit_start', vm_id)
        return jsonify({'success': ok, 'message': msg})
    if act == 'playit-remove':
        _docker('rm', '-f', _dk_playit_name(vm_id), timeout=30)
        cfg.pop('playit_key', None)
        cfg.pop('playit_claim', None)
        cfg.pop('playit_address', None)
        _dk_conn_write(vm_id, cfg)
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(dict(opt, playit=False)), vm_id))
        audit(session['user_id'], 'mc_playit_remove', vm_id)
        return jsonify({'success': True, 'message': 'playit removed.'})
    if act == 'playit-address':
        a = (d.get('address') or '').strip()
        if a and not _RE_ADDR_INPUT.match(a):
            return _dk_json_err('Enter the address like name.joinmc.link or name.ply.gg:12345.')
        cfg['playit_address'] = a
        _dk_conn_write(vm_id, cfg)
        return jsonify({'success': True, 'message': 'Address saved.'})
    return _dk_json_err('Unknown action.')




# ───────── v21.67: Minecraft subdomain — play.yourdomain.com → server (A + SRV record via Cloudflare) ─────────
_MCSUB_RESERVED = {'www', 'mail', 'admin', 'panel', 'api', 'ftp', 'smtp', 'ns1', 'ns2', 'play', 'mc', 'status', 'billing'}
_MCSUB_RE = re.compile(r'^[a-z0-9]([a-z0-9-]{1,28}[a-z0-9])$')


def _mcsub_base():
    return ((gsv('mc_subdomain_base', '') or gsv('free_subdomain_base', '') or '').strip().lower().strip('.'))


def _mcsub_init():
    db_execute("CREATE TABLE IF NOT EXISTS mc_subdomains (vm_id TEXT PRIMARY KEY, label TEXT NOT NULL, fqdn TEXT NOT NULL UNIQUE, created_at TEXT DEFAULT CURRENT_TIMESTAMP)")


def _mcsub_get(vid):
    try:
        _mcsub_init()
        r = db_execute("SELECT fqdn FROM mc_subdomains WHERE vm_id=?", (vid,), fetchone=True)
        return r['fqdn'] if r else ''
    except Exception:
        return ''


def _mcsub_dns_drop(fqdn):
    zone = _cf_zone_for(fqdn)
    if not zone:
        return
    for name, typ in ((fqdn, 'A'), ('_minecraft._tcp.' + fqdn, 'SRV')):
        ok, recs = _cf_api('GET', f'/zones/{zone}/dns_records?type={typ}&name=' + urllib.parse.quote(name))
        for r in (recs or []) if ok else []:
            _cf_api('DELETE', f"/zones/{zone}/dns_records/{r['id']}")


def _mcsub_dns_set(fqdn, ip, port):
    """A record (DNS only) + SRV so players can type just the name, whatever the port is. -> (ok, err)"""
    zone = _cf_zone_for(fqdn)
    if not zone:
        return False, 'This domain is not in your Cloudflare account (add it to Cloudflare first).'
    _mcsub_dns_drop(fqdn)
    ok, res = _cf_api('POST', f'/zones/{zone}/dns_records', {'type': 'A', 'name': fqdn, 'content': ip, 'proxied': False, 'ttl': 120})
    if not ok:
        return False, res
    ok, res = _cf_api('POST', f'/zones/{zone}/dns_records', {
        'type': 'SRV', 'name': '_minecraft._tcp.' + fqdn, 'ttl': 120,
        'data': {'service': '_minecraft', 'proto': '_tcp', 'name': fqdn, 'priority': 0, 'weight': 5, 'port': int(port), 'target': fqdn}})
    if not ok:
        _mcsub_dns_drop(fqdn)
        return False, res
    return True, ''


def _mcsub_release(vid):
    fq = _mcsub_get(vid)
    if fq:
        try:
            _mcsub_dns_drop(fq)
        except Exception:
            pass
        db_execute("DELETE FROM mc_subdomains WHERE vm_id=?", (vid,))
    return fq


@app.route('/vm/<vm_id>/server/mc/subdomain', methods=['POST'])
@login_required
@vm_owner_or_admin
def mc_subdomain(vm_id):
    if not _is_docker_vm(vm_id):
        return _dk_json_err('Only for Docker servers.')
    v = _dk_row(vm_id)
    if _dk_kind(v) != 'minecraft':
        return _dk_json_err('Minecraft servers only.')
    base = _mcsub_base()
    if not base:
        return _dk_json_err('The admin has not set a subdomain base yet (Admin → Settings → Free subdomains).')
    if not (gsv('cf_api_token', '') or '').strip():
        return _dk_json_err('The admin must add a Cloudflare API token (Zone → DNS: Edit) so the subdomain can be created.')
    _mcsub_init()
    d = request.get_json(silent=True) or {}
    if d.get('action') == 'remove':
        fq = _mcsub_release(vm_id)
        audit(session['user_id'], 'mc_subdomain_remove', f'{vm_id[:8]} {fq}')
        return jsonify({'success': True, 'message': 'Subdomain removed.'})
    label = (d.get('label') or '').strip().lower()
    if not _MCSUB_RE.match(label) or label in _MCSUB_RESERVED:
        return _dk_json_err('Use 3-30 letters, numbers or dashes, e.g. myserver.')
    fqdn = f'{label}.{base}'
    taken = db_execute("SELECT vm_id FROM mc_subdomains WHERE fqdn=?", (fqdn,), fetchone=True)
    if taken and taken['vm_id'] != vm_id:
        return _dk_json_err('That name is taken. Try another.')
    if db_execute("SELECT 1 FROM web_domains WHERE domain=?", (fqdn,), fetchone=True):
        return _dk_json_err('That name is taken. Try another.')
    fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (vm_id,), fetchone=True)
    ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    if not fw or not ip or ip == '127.0.0.1':
        return _dk_json_err('Server IP / port is not ready. Set "Server IP" in admin settings first.')
    old = _mcsub_get(vm_id)
    ok, err = _mcsub_dns_set(fqdn, ip, int(fw['host_port']))
    if not ok:
        return _dk_json_err('Cloudflare said: ' + str(err))
    if old and old != fqdn:
        try:
            _mcsub_dns_drop(old)
        except Exception:
            pass
    db_execute("INSERT OR REPLACE INTO mc_subdomains (vm_id, label, fqdn) VALUES (?,?,?)", (vm_id, label, fqdn))
    audit(session['user_id'], 'mc_subdomain_set', f'{vm_id[:8]} {fqdn}')
    return jsonify({'success': True, 'domain': fqdn,
                    'message': f'Done — players can join with {fqdn} (no port needed). DNS can take a few minutes to spread.'})



