# ───────── v21.74: subdomain for VPS + Bot servers (A record → server IP) ─────────
def _gensub_target(vid):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
    if not v:
        return None, '', ''
    kind = row_get(v, 'provision_kind') or 'vps'
    if kind in ('minecraft', 'web'):
        return v, kind, ''
    ip = (row_get(v, 'public_ip') or '').strip() if kind == 'vps' else ''
    ip = ip or (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    return v, kind, ip


def _gensub_dns_set(fqdn, ip):
    zone = _cf_zone_for(fqdn)
    if not zone:
        return False, 'This domain is not in your Cloudflare account (add it to Cloudflare first).'
    _mcsub_dns_drop(fqdn)
    ok, res = _cf_api('POST', f'/zones/{zone}/dns_records', {'type': 'A', 'name': fqdn, 'content': ip, 'proxied': False, 'ttl': 120})
    return (True, '') if ok else (False, res)


@app.route('/vm/<vm_id>/subdomain', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def vm_subdomain(vm_id):
    v, kind, ip = _gensub_target(vm_id)
    if not v or kind in ('minecraft', 'web'):
        return _dk_json_err('Use the Connection / Domains tab for this kind of server.')
    base = _mcsub_base()
    ready = bool(base and (gsv('cf_api_token', '') or '').strip())
    cur = _mcsub_get(vm_id)
    if request.method == 'GET':
        ports = [{'host': int(r['host_port']), 'guest': int(r['guest_port']), 'label': row_get(r, 'label') or ''}
                 for r in (db_execute("SELECT host_port, guest_port, label FROM port_forwards WHERE vm_id=? ORDER BY guest_port", (vm_id,), fetch=True) or [])]
        return jsonify({'success': True, 'base': base, 'ready': ready, 'current': cur, 'ip': ip, 'ports': ports, 'ssh_port': row_get(v, 'ssh_port')})
    if not ready:
        return _dk_json_err('The admin has not enabled subdomains yet (subdomain base + Cloudflare token in Settings).')
    d = request.get_json(silent=True) or {}
    if d.get('action') == 'remove':
        _mcsub_release(vm_id)
        audit(session['user_id'], 'vm_subdomain_remove', vm_id[:8])
        return jsonify({'success': True, 'message': 'Subdomain removed.'})
    label = (d.get('label') or '').strip().lower()
    if not _MCSUB_RE.match(label) or label in _MCSUB_RESERVED:
        return _dk_json_err('Use 3-30 letters, numbers or dashes, e.g. myserver.')
    fqdn = f'{label}.{base}'
    taken = db_execute("SELECT vm_id FROM mc_subdomains WHERE fqdn=?", (fqdn,), fetchone=True)
    if (taken and taken['vm_id'] != vm_id) or db_execute("SELECT 1 FROM web_domains WHERE domain=?", (fqdn,), fetchone=True):
        return _dk_json_err('That name is taken. Try another.')
    if not ip or ip == '127.0.0.1':
        return _dk_json_err('Server IP is not set. Ask the admin to set "Server IP" in Settings.')
    old = cur
    ok, err = _gensub_dns_set(fqdn, ip)
    if not ok:
        return _dk_json_err('Cloudflare said: ' + str(err))
    if old and old != fqdn:
        try:
            _mcsub_dns_drop(old)
        except Exception:
            pass
    db_execute("INSERT OR REPLACE INTO mc_subdomains (vm_id, label, fqdn) VALUES (?,?,?)", (vm_id, label, fqdn))
    audit(session['user_id'], 'vm_subdomain_set', f'{vm_id[:8]} {fqdn}')
    return jsonify({'success': True, 'domain': fqdn, 'message': f'Done — {fqdn} now points to your server. DNS can take a few minutes to spread.'})



# ───────── v21.76: Cloud Storage backups (create / download / restore / delete) ─────────
def _stbk_safe(vm_id):
    v = _web_row(vm_id)
    return v if (v and _app_key(v)) else None


def _stbk_list(vm_id):
    items = []
    for f in list(_dk_backup_dir(vm_id).glob('storage-*.tgz')) + list(_dk_backup_dir(vm_id).glob('snap-*.tgz')):
        if _RE_BACKUP.match(f.name):
            st = f.stat()
            items.append({'file': f.name, 'size': st.st_size, 'time': int(st.st_mtime), 'snap': f.name.startswith('snap-')})
    return sorted(items, key=lambda x: -x['time'])


def _stbk_create(vm_id, log=lambda m: None, prefix='storage'):
    dest = _dk_backup_dir(vm_id) / f"{prefix}-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}.tgz"
    base, cfg = _dk_dir(vm_id), _storage_cfg_dir(vm_id)
    with tarfile.open(dest, 'w:gz') as tar:
        tar.add(str(base), arcname='data')
        if cfg.exists():
            tar.add(str(cfg), arcname='config')
    for old in [x for x in _stbk_list(vm_id) if x['snap'] == (prefix == 'snap')][(8 if prefix == 'snap' else 5):]:   # keep the newest 5 backups / 8 snapshots
        (_dk_backup_dir(vm_id) / old['file']).unlink(missing_ok=True)
    log(f'Saved {dest.name} ({dest.stat().st_size // (1024 * 1024)} MB)')
    return dest


def _stbk_restore(vm_id, name, log=lambda m: None):
    path = _dk_backup_dir(vm_id) / name
    base, cfg = _dk_dir(vm_id), _storage_cfg_dir(vm_id)
    with tarfile.open(path, 'r:gz') as tar:                              # check the whole archive BEFORE touching live data
        members = tar.getmembers()
        for m_ in members:
            n = m_.name
            if n.startswith('/') or '..' in n.split('/') or not (n == 'data' or n == 'config' or n.startswith(('data/', 'config/'))) or m_.issym() or m_.islnk() or m_.isdev():
                raise RuntimeError('This backup file is not valid.')
        was = bool(dk_status(vm_id)[0])
        if was:
            log('Stopping storage…')
            _docker('stop', '-t', '20', _cname(vm_id), timeout=90)
            vm._st.pop(vm_id, None)
        try:
            log('Restoring files…')
            for d in (base, cfg):
                if d.exists():
                    for child in d.iterdir():
                        shutil.rmtree(child, ignore_errors=True) if child.is_dir() else child.unlink(missing_ok=True)
            tmp = Path(tempfile.mkdtemp(prefix='stbk-', dir=str(DK_BACKUP_DIR)))
            try:
                try:
                    tar.extractall(str(tmp), filter='data')
                except TypeError:                                  # older Python: members were already checked above
                    tar.extractall(str(tmp))
                for src, dst in ((tmp / 'data', base), (tmp / 'config', cfg)):
                    if src.exists():
                        dst.mkdir(parents=True, exist_ok=True)
                        for child in src.iterdir():
                            shutil.move(str(child), str(dst / child.name))
            finally:
                shutil.rmtree(tmp, ignore_errors=True)
            _u = _dk_uid(_web_row(vm_id)) or 33
            _dk_chown(str(base), _u, _u)
            _dk_chown(str(cfg), _u, _u)
        finally:
            if was:
                _docker('start', _cname(vm_id), timeout=60)
                vm._st.pop(vm_id, None)
    log('Restored.')


@app.route('/vm/<vm_id>/storage/backups', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def storage_backups(vm_id):
    if not _stbk_safe(vm_id):
        return _dk_json_err('Not a Cloud Storage site.')
    if request.method == 'GET':
        t = _WEB_TASKS.get(vm_id)
        return jsonify({'success': True, 'backups': _stbk_list(vm_id),
                        'auto': bool(_web_opt(_stbk_safe(vm_id)).get('auto_backup')), 'snap_hours': int(_web_opt(_stbk_safe(vm_id)).get('snap_hours') or 0),
                        'busy': bool(t and not t['done']), 'task': (t or {}).get('label', ''), 'error': (t or {}).get('error', ''),
                        'free_mb': shutil.disk_usage(str(DOCKER_SERVERS_DIR)).free // (1024 * 1024)})
    d = request.get_json(silent=True) or {}
    act, name = d.get('action'), (d.get('file') or '')
    if act == 'create':
        ok, msg = _web_task(vm_id, 'Creating backup', lambda log: _stbk_create(vm_id, log))
        audit(session['user_id'], 'storage_backup_create', vm_id[:8])
        return jsonify({'success': ok, 'message': 'Backup started — it appears in the list in a moment.' if ok else msg})
    if act == 'auto':
        _web_save_opt(vm_id, auto_backup=bool(d.get('on')))
        return jsonify({'success': True, 'message': 'Daily backup is ' + ('ON.' if d.get('on') else 'OFF.')})
    if act == 'snapshot':
        ok, msg = _web_task(vm_id, 'Taking snapshot', lambda log: _stbk_create(vm_id, log, 'snap'))
        return jsonify({'success': ok, 'message': 'Snapshot started — it appears in the list in a moment.' if ok else msg})
    if act == 'snap_hours':
        h = int(d.get('hours') or 0)
        if h not in (0, 1, 6, 12):
            return _dk_json_err('Choose off, 1, 6 or 12 hours.')
        _web_save_opt(vm_id, snap_hours=h)
        return jsonify({'success': True, 'message': 'Automatic snapshots every %dh.' % h if h else 'Automatic snapshots are off.'})
    if act in ('restore', 'delete'):
        p = _dk_backup_dir(vm_id) / name
        if not (_RE_BACKUP.match(name) and name.startswith(('storage-', 'snap-')) and p.is_file()):
            return _dk_json_err('Backup not found.')
        if act == 'delete':
            p.unlink(missing_ok=True)
            return jsonify({'success': True, 'message': 'Deleted.'})
        def _do_restore(log):
            try:
                _stbk_create(vm_id, log, 'snap')          # safety snapshot first, so a rollback can itself be undone
            except Exception as e:
                log('Safety snapshot skipped: ' + str(e)[:80])
            _stbk_restore(vm_id, name, log)
        ok, msg = _web_task(vm_id, 'Rolling back', _do_restore)
        audit(session['user_id'], 'storage_backup_restore', f'{vm_id[:8]} {name}')
        return jsonify({'success': ok, 'message': 'Restore started — your storage restarts when it is done.' if ok else msg})
    return _dk_json_err('Unknown action.')


@app.route('/vm/<vm_id>/storage/backups/download')
@login_required
@vm_owner_or_admin
def storage_backup_download(vm_id):
    if not _stbk_safe(vm_id):
        return ('Not found', 404)
    name = request.args.get('file') or ''
    p = _dk_backup_dir(vm_id) / name
    if not (_RE_BACKUP.match(name) and name.startswith('storage-') and p.is_file()):
        return ('Not found', 404)
    audit(session['user_id'], 'storage_backup_download', f'{vm_id[:8]} {name}')
    return send_file(str(p), as_attachment=True, download_name=name)



# ───────── v21.80: subdomain self-healing — keeps DNS in step when the server IP or an MC port changes ─────────
def _mcsub_resync_tick():
    if not (gsv('cf_api_token', '') or '').strip() or not _mcsub_base():
        return 0
    _mcsub_init()
    fixed = 0
    for r in (db_execute("SELECT vm_id, fqdn FROM mc_subdomains", fetch=True) or []):
        vid, fq = r['vm_id'], r['fqdn']
        try:
            v, kind, ip = _gensub_target(vid)
            if not v:                                              # server is gone → release its records
                _mcsub_release(vid)
                continue
            if kind == 'minecraft':
                ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
            zone = _cf_zone_for(fq)
            if not zone or not ip:
                continue
            ok, recs = _cf_api('GET', f'/zones/{zone}/dns_records?type=A&name=' + urllib.parse.quote(fq))
            a_ok = bool(ok and any(x.get('content') == ip for x in (recs or [])))
            srv_ok = True
            port = None
            if kind == 'minecraft':
                fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (vid,), fetchone=True)
                ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
                port = int(fw['host_port']) if fw else None
                a_ok = bool(ok and any(x.get('content') == ip for x in (recs or [])))
                ok2, srv = _cf_api('GET', f'/zones/{zone}/dns_records?type=SRV&name=' + urllib.parse.quote('_minecraft._tcp.' + fq))
                srv_ok = bool(ok2 and port and any(((x.get('data') or {}).get('port') == port) for x in (srv or [])))
            if ok and (not a_ok or not srv_ok):
                if kind == 'minecraft' and port and ip:
                    good, _e = _mcsub_dns_set(fq, ip, port)
                elif kind != 'minecraft':
                    good, _e = _gensub_dns_set(fq, ip)
                else:
                    good = False
                fixed += 1 if good else 0
        except Exception as e:
            print(f'[subdomain] resync failed for {fq}: {e}', flush=True)
    return fixed


def _mcsub_resync_loop():
    time.sleep(180)
    while True:
        try:
            n = _mcsub_resync_tick()
            if n:
                print(f'[subdomain] repaired {n} DNS record set(s)', flush=True)
        except Exception as e:
            print(f'[subdomain] resync error: {e}', flush=True)
        time.sleep(3600)



