def _resolve_ips(host, wait=4):
    out = []

    def work():
        try:
            out.extend(sorted({a[4][0] for a in socket.getaddrinfo(host, None, socket.AF_INET)}))
        except Exception:
            pass
    t = threading.Thread(target=work, daemon=True)
    t.start()
    t.join(wait)
    return out


def _mcsub_dns_status(vid):
    fq = _mcsub_get(vid)
    if not fq:
        return {'success': True, 'current': '', 'message': 'No subdomain yet.'}
    v, kind, ip = _gensub_target(vid)
    if kind == 'minecraft':
        ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    ips = _resolve_ips(fq)
    res = {'success': True, 'current': fq, 'ips': ips, 'expected': ip, 'resolves': bool(ips), 'match': bool(ips and ip in ips)}
    if kind == 'minecraft':
        fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=25565", (vid,), fetchone=True)
        port = int(fw['host_port']) if fw else None
        srv_ok = None
        try:
            zone = _cf_zone_for(fq)
            ok, recs = _cf_api('GET', f'/zones/{zone}/dns_records?type=SRV&name=' + urllib.parse.quote('_minecraft._tcp.' + fq)) if zone else (False, None)
            srv_ok = bool(ok and port and any(((x.get('data') or {}).get('port') == port) for x in (recs or [])))
        except Exception:
            srv_ok = None
        res['srv_ok'] = srv_ok
    good = res['match'] and res.get('srv_ok') is not False
    res['message'] = ('Working — ' + fq + ' points to your server.') if good else (
        'Not visible yet. DNS can take a few minutes — try again shortly.' if not ips else 'The name points to ' + ', '.join(ips) + ' but should be ' + str(ip) + '.')
    return res


