# --- Cloud Storage: daily automatic backup ---
def _stbk_auto_tick():
    for r in (db_execute("SELECT vm_id, provision_opt FROM vm_instances WHERE provision_kind='web' AND status IN ('running','stopped')", fetch=True) or []):
        try:
            o = json.loads(r['provision_opt'] or '{}')
            if o.get('app') not in _APPS or not o.get('auto_backup'):
                continue
            vid = r['vm_id']
            newest = max([b['time'] for b in _stbk_list(vid) if not b['snap']] or [0])
            if time.time() - newest >= 23 * 3600:
                t = _WEB_TASKS.get(vid)
                if not (t and not t['done']):
                    _web_task(vid, 'Daily backup', lambda log, vid=vid: _stbk_create(vid, log))
        except Exception as e:
            print(f'[storage] auto backup failed: {e}', flush=True)


def _snap_auto_tick():
    for r in (db_execute("SELECT vm_id, provision_opt FROM vm_instances WHERE provision_kind='web' AND status IN ('running','stopped')", fetch=True) or []):
        try:
            o = json.loads(r['provision_opt'] or '{}')
            h = int(o.get('snap_hours') or 0)
            if o.get('app') not in _APPS or h <= 0:
                continue
            vid = r['vm_id']
            if shutil.disk_usage(str(DOCKER_SERVERS_DIR)).free < 5 * 1024 ** 3:
                continue                                             # never fill the host with snapshots
            newest = max([b['time'] for b in _stbk_list(vid) if b['snap']] or [0])
            t_ = _WEB_TASKS.get(vid)
            if time.time() - newest >= h * 3600 - 120 and not (t_ and not t_['done']):
                _web_task(vid, 'Automatic snapshot', lambda log, vid=vid: _stbk_create(vid, log, 'snap'))
        except Exception as e:
            print(f'[snapshot] failed: {e}', flush=True)


def _snap_loop():
    time.sleep(300)
    while True:
        try:
            _snap_auto_tick()
        except Exception as e:
            print(f'[snapshot] error: {e}', flush=True)
        time.sleep(600)


threading.Thread(target=_snap_loop, daemon=True, name='snapshots').start()


def _stbk_auto_loop():
    time.sleep(240)
    while True:
        try:
            _stbk_auto_tick()
        except Exception as e:
            print(f'[storage] auto backup error: {e}', flush=True)
        time.sleep(3600)



# ───────── v21.83: share a server with a teammate (manager role: console, files, power — not delete/billing/domains) ─────────
_SHARE_OK = re.compile(r'^/vm/[^/]+/(server(/|$)|files/|start$|stop$|restart$|kill$)')
_SHARE_NO = re.compile(r'/server/mc/(subdomain|world/import)|/server/(delete|transfer)')
_shares_ready = [False]


def _shares_init():
    if not _shares_ready[0]:
        db_execute("CREATE TABLE IF NOT EXISTS vm_shares (vm_id TEXT NOT NULL, user_id INTEGER NOT NULL, role TEXT DEFAULT 'manager', created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (vm_id, user_id))")
        _shares_ready[0] = True


def _share_allows(vm_id):
    """True when the logged-in user was given manager access to this server AND this request is one managers may do."""
    try:
        _shares_init()
        uid = session.get('user_id')
        if not uid or not db_execute("SELECT 1 FROM vm_shares WHERE vm_id=? AND user_id=?", (vm_id, uid), fetchone=True):
            return False
        return bool(_SHARE_OK.match(request.path)) and not _SHARE_NO.search(request.path)
    except Exception:
        return False


def _is_true_owner(vm_id):
    v = db_execute("SELECT user_id FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if not v:
        return False
    if session.get('role') == 'admin' or v['user_id'] == session.get('user_id'):
        return True
    if session.get('role') == 'reseller':
        o = db_execute("SELECT reseller_id FROM users WHERE id=?", (v['user_id'],), fetchone=True)
        return bool(o and o['reseller_id'] == session.get('user_id'))
    return False


@app.route('/vm/<vm_id>/team', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def vm_team(vm_id):
    if not _is_true_owner(vm_id) or not _is_docker_vm(vm_id):
        return jsonify({'success': False, 'shared': True, 'message': 'Only the owner manages access.'})
    _shares_init()
    if request.method == 'GET':
        rows = db_execute("SELECT s.user_id, u.username FROM vm_shares s JOIN users u ON u.id=s.user_id WHERE s.vm_id=? ORDER BY s.created_at", (vm_id,), fetch=True) or []
        return jsonify({'success': True, 'members': [{'user_id': r['user_id'], 'username': r['username']} for r in rows]})
    d = request.get_json(silent=True) or {}
    v = db_execute("SELECT name, user_id FROM vm_instances WHERE vm_id=?", (vm_id,), fetchone=True)
    if d.get('action') == 'remove':
        db_execute("DELETE FROM vm_shares WHERE vm_id=? AND user_id=?", (vm_id, safe_int(d.get('user_id'), 0, 0, 10 ** 9)))
        audit(session['user_id'], 'vm_share_remove', vm_id[:8])
        return jsonify({'success': True, 'message': 'Access removed.'})
    name = (d.get('username') or '').strip()
    u = db_execute("SELECT id, username FROM users WHERE lower(username)=lower(?) OR lower(email)=lower(?)", (name, name), fetchone=True) if name else None
    if not u:
        return _dk_json_err('No user with that username or email. They must have an account first.')
    if u['id'] == v['user_id']:
        return _dk_json_err('That is the owner.')
    n = db_execute("SELECT COUNT(*) AS n FROM vm_shares WHERE vm_id=?", (vm_id,), fetchone=True)
    if n and int(n['n']) >= 5:
        return _dk_json_err('You can share a server with up to 5 people.')
    db_execute("INSERT OR IGNORE INTO vm_shares (vm_id, user_id, role) VALUES (?,?,'manager')", (vm_id, u['id']))
    try:
        notify_user(u['id'], 'Server shared with you', f'You can now manage "{v["name"]}". Find it under "Shared with me".', 'info')
    except Exception:
        pass
    audit(session['user_id'], 'vm_share_add', f'{vm_id[:8]} -> {u["username"]}')
    return jsonify({'success': True, 'message': f'{u["username"]} can now manage this server.'})


