_IDLE_OK = ('code', 'sandbox', 'vscode', 'rstudio', 'studio')
_IDLE_ST = {}


def _net_bytes(s):
    tot = 0
    for part in (s or '').split('/'):
        m = re.match(r'\s*([\d.]+)\s*([kMGT]?i?B)', part)
        if m:
            tot += float(m.group(1)) * {'B': 1, 'kB': 1e3, 'KiB': 1024, 'MB': 1e6, 'MiB': 1048576, 'GB': 1e9, 'GiB': 1073741824}.get(m.group(2), 1)
    return tot


def _idle_tick():
    rows = db_execute("SELECT vm_id, user_id, name, provision_opt FROM vm_instances WHERE provision_kind='web' AND runtime='docker'", fetch=True) or []
    now = time.time()
    for v in rows:
        try:
            opt = json.loads(v['provision_opt'] or '{}')
        except Exception:
            continue
        hrs = int(opt.get('idle_hours') or 0)
        if opt.get('app') not in _IDLE_OK or hrs <= 0:
            _IDLE_ST.pop(v['vm_id'], None)
            continue
        vid = v['vm_id']
        if not dk_status(vid)[0]:
            _IDLE_ST.pop(vid, None)
            continue
        rc, out, _ = _docker('stats', '--no-stream', '--format', '{{.CPUPerc}}|{{.NetIO}}', _cname(vid), timeout=20)
        if rc != 0 or '|' not in out:
            continue
        cpu, net = out.strip().splitlines()[0].split('|', 1)
        try:
            cpu = float(cpu.strip('%') or 0)
        except ValueError:
            cpu = 0
        nb = _net_bytes(net)
        st = _IDLE_ST.setdefault(vid, {'net': nb, 'since': now})
        if cpu > 3 or abs(nb - st['net']) > 40000:
            st['since'] = now
        st['net'] = nb
        if now - st['since'] >= hrs * 3600:
            _docker('stop', '-t', '20', _cname(vid), timeout=60)
            vm._st.pop(vid, None)
            _IDLE_ST.pop(vid, None)
            notify_user(v['user_id'], 'Stopped to save resources', f"{v['name']} was idle for {hrs}h and was stopped. Press Start to use it again.", 'info')


def _idle_loop():
    time.sleep(240)
    while True:
        try:
            if docker_available():
                _idle_tick()
        except Exception as e:
            print('[idle] failed:', e, flush=True)
        time.sleep(300)


threading.Thread(target=_idle_loop, daemon=True, name='idle-stop').start()


