def _all_docker_stats():
    rc, out, _ = _docker('stats', '--no-stream', '--format', '{{json .}}', timeout=40)
    res = {}
    for ln in (out or '').splitlines():
        try:
            j = json.loads(ln)
        except Exception:
            continue
        m_ = re.match(r'^phvm-([0-9a-f-]{36})(-db)?$', j.get('Name') or '')
        if not m_ or m_.group(2):
            continue
        try:
            cpu = float((j.get('CPUPerc') or '0').strip('%') or 0)
            mem = float((j.get('MemPerc') or '0').strip('%') or 0)
        except ValueError:
            continue
        res[m_.group(1)] = (cpu, mem, j.get('MemUsage') or '')
    return res


