_OVL = {}


def _overload_tick():
    stats = _all_docker_stats()
    now = time.time()
    for vid, (cpu, mem, _u) in stats.items():
        v = _dk_row(vid)
        if not v:
            continue
        cores = max(1, int(v['cpu_cores'] or 1))
        hot = (cpu / cores >= 95) or mem >= 95
        st = _OVL.setdefault(vid, {'n': 0, 'last': 0})
        st['n'] = st['n'] + 1 if hot else 0
        if st['n'] >= 3 and now - st['last'] > 6 * 3600:
            st['last'] = now
            why = 'RAM' if mem >= 95 else 'CPU'
            _ev_add(vid, 'overload', why)
            _admin_alert(f"⚠️ Overload: {v['name']} has used ~{why} at its plan limit for 10+ minutes.")
            notify_user(v['user_id'], 'Your server is at its limit', f"{v['name']} has been using almost all of its {why} for a while. Consider a bigger plan if it feels slow.", 'warning')


def _overload_loop():
    time.sleep(200)
    while True:
        try:
            if docker_available():
                _overload_tick()
        except Exception as e:
            print('[overload] failed:', e, flush=True)
        time.sleep(200)


threading.Thread(target=_overload_loop, daemon=True, name='overload-guard').start()


