# ───────── v21.93: public status badge/widget, public server list + votes ─────────
def _pub_init():
    db_execute("CREATE TABLE IF NOT EXISTS server_votes (id INTEGER PRIMARY KEY AUTOINCREMENT, vm_id TEXT NOT NULL, user_id INTEGER, ip TEXT, ts INTEGER NOT NULL)")
    db_execute("CREATE INDEX IF NOT EXISTS idx_votes_vm ON server_votes (vm_id, ts)")


def _opt_of(v):
    try:
        return json.loads(row_get(v, 'provision_opt') or '{}') or {}
    except Exception:
        return {}


def _opt_put(vid, **kw):
    v = _dk_row(vid)
    o = _opt_of(v)
    o.update(kw)
    db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(o), vid))
    return o


def _pub_by_token(tok):
    if not re.match(r'^[a-f0-9]{16}$', tok or ''):
        return None
    return db_execute("SELECT * FROM vm_instances WHERE provision_opt LIKE ?", ('%"pub_id": "' + tok + '"%',), fetchone=True)


def _pub_address(v):
    try:
        k = row_get(v, 'provision_kind')
        if k == 'minecraft':
            return (_dk_best_address(v)[0] or '')
        a = _app_key(v)
        if a and _APPS[a].get('game'):
            return _game_addr(v)
        d = db_execute("SELECT domain FROM web_domains WHERE vm_id=? ORDER BY id LIMIT 1", (v['vm_id'],), fetchone=True)
        return d['domain'] if d else ''
    except Exception:
        return ''


_PUB_CACHE = {}


def _pub_status(v):
    vid = v['vm_id']
    hit = _PUB_CACHE.get(vid)
    if hit and time.time() - hit[0] < 20:
        return hit[1]
    running = bool(dk_status(vid)[0]) if row_get(v, 'runtime') == 'docker' else (row_get(v, 'status') == 'running')
    players = maxp = None
    if running and row_get(v, 'provision_kind') == 'minecraft':
        try:
            ok, out = _dk_rcon(vid, 'list', timeout=5)
            mt = re.search(r'There are (\d+) of a max of (\d+)', out or '') if ok else None
            if mt:
                players, maxp = int(mt.group(1)), int(mt.group(2))
        except Exception:
            pass
    res = {'online': running, 'players': players, 'max_players': maxp}
    _PUB_CACHE[vid] = (time.time(), res)
    return res


def _pub_kind_label(v):
    k, lab = _ai_kind(v)
    return lab or {'minecraft': 'Minecraft', 'bot': 'Bot', 'web': 'Website', 'sandbox': 'Sandbox VM'}.get(k, 'Server')


@app.route('/badge/<tok>.svg')
def pub_badge(tok):
    v = _pub_by_token(tok)
    if not v:
        return ('', 404)
    st = _pub_status(v)
    left = (v['name'] or 'server')[:22]
    right = ('online' if st['online'] else 'offline') + (f" · {st['players']}/{st['max_players']}" if st['players'] is not None else '')
    lw, rw = 14 + len(left) * 6.6, 14 + len(right) * 6.6
    col = '#2ea043' if st['online'] else '#6e6e78'
    def esc(s): return s.replace('&', '&amp;').replace('<', '&lt;').replace('"', '&quot;')
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="{lw + rw:.0f}" height="22" role="img" aria-label="{esc(left)}: {esc(right)}">'
           f'<rect width="{lw:.0f}" height="22" rx="5" fill="#1b1b20"/><rect x="{lw:.0f}" width="{rw:.0f}" height="22" rx="5" fill="{col}"/><rect x="{lw - 5:.0f}" width="10" height="22" fill="{col}"/>'
           f'<g fill="#f1f1f5" font-family="Verdana,DejaVu Sans,sans-serif" font-size="11"><text x="7" y="15">{esc(left)}</text><text x="{lw + 7:.0f}" y="15">{esc(right)}</text></g></svg>')
    r = Response(svg, mimetype='image/svg+xml')
    r.headers['Cache-Control'] = 'public, max-age=30'
    return r


@app.route('/api/status/<tok>.json')
def pub_status_json(tok):
    v = _pub_by_token(tok)
    if not v:
        return jsonify({'success': False}), 404
    st = _pub_status(v)
    r = jsonify(dict(st, name=v['name'], address=_pub_address(v), type=_pub_kind_label(v)))
    r.headers['Access-Control-Allow-Origin'] = '*'
    return r


