# ───────── v21.93: Discord — control servers (Minecraft, bots, sites, apps) from chat ─────────
def _dc_find(u, q):
    q = (q or '').strip().lower()
    rows = db_execute("SELECT * FROM vm_instances WHERE user_id=? AND runtime='docker'", (u['id'],), fetch=True) or []
    hits = [r for r in rows if r['vm_id'].lower().startswith(q) or (r['name'] or '').lower() == q] or [r for r in rows if q and q in (r['name'] or '').lower()]
    if len(hits) == 1:
        return hits[0], None
    if not hits:
        return None, "No server matches that. Use `phvm!servers` to see your servers."
    return None, 'Several servers match: ' + ', '.join('`%s`' % h['name'] for h in hits[:6]) + ' — be more specific.'


def _dc_power(u, v, act):
    k = row_get(v, 'provision_kind')
    vid = v['vm_id']
    if k == 'web':
        st, j = _ai_internal('POST', f'/vm/{vid}/web/power', u['id'], u['role'], {'action': act})
    else:
        st, j = _ai_internal('POST', f'/vm/{vid}/server/power', u['id'], u['role'], {'action': act})
    return bool(j and j.get('success')), ((j or {}).get('message') or '')[:200]


# ───────── v21.94: uptime & incidents, upgrade suggestions, AI first reply on tickets, achievements ─────────
def _ev_init():
    db_execute("CREATE TABLE IF NOT EXISTS server_events (id INTEGER PRIMARY KEY AUTOINCREMENT, vm_id TEXT NOT NULL, ts INTEGER NOT NULL, kind TEXT NOT NULL, note TEXT)")
    db_execute("CREATE INDEX IF NOT EXISTS idx_events_vm ON server_events (vm_id, ts)")


def _ev_add(vid, kind, note=''):
    try:
        _ev_init()
        db_execute("INSERT INTO server_events (vm_id, ts, kind, note) VALUES (?,?,?,?)", (vid, int(time.time()), kind, note[:120]))
        db_execute("DELETE FROM server_events WHERE vm_id=? AND ts<?", (vid, int(time.time()) - 90 * 86400))
    except Exception as e:
        print('[events] failed:', str(e)[:80], flush=True)


def _uptime_calc(vid, days=30):
    _ev_init()
    now = int(time.time())
    v = db_execute("SELECT created_at FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
    start = now - days * 86400
    try:
        born = int(datetime.strptime(str(v['created_at'])[:19], '%Y-%m-%d %H:%M:%S').timestamp())
        start = max(start, born)
    except Exception:
        pass
    ev = db_execute("SELECT ts, kind, note FROM server_events WHERE vm_id=? AND kind IN ('down','up') AND ts>=? ORDER BY ts", (vid, start - 7 * 86400), fetch=True) or []
    down, open_ts = 0, None
    for e in ev:
        if e['kind'] == 'down' and (e['note'] or '') in ('crash', 'oom'):
            open_ts = max(e['ts'], start)
        elif e['kind'] == 'up' and open_ts is not None:
            down += max(0, e['ts'] - open_ts); open_ts = None
        elif e['kind'] == 'down':
            open_ts = None
    if open_ts is not None:
        down += max(0, now - open_ts)
    span = max(1, now - start)
    return round(max(0.0, 100.0 - down * 100.0 / span), 2), span


@app.route('/vm/<vm_id>/uptime')
@login_required
@vm_owner_or_admin
def server_uptime(vm_id):
    v = _dk_row(vm_id)
    if not v:
        return _dk_json_err('Not a Docker server.')
    _ev_init()
    pct, span = _uptime_calc(vm_id)
    evs = db_execute("SELECT ts, kind, note FROM server_events WHERE vm_id=? AND kind IN ('down','up','overload') ORDER BY ts DESC LIMIT 15", (vm_id,), fetch=True) or []
    hot = db_execute("SELECT COUNT(*) AS n FROM server_events WHERE vm_id=? AND kind='overload' AND ts>?", (vm_id, int(time.time()) - 7 * 86400), fetchone=True)
    n_hot = int(hot['n']) if hot else 0
    k = row_get(v, 'provision_kind')
    sug = None
    if n_hot >= 2:
        sug = {'count': n_hot, 'url': url_for('web_plans_page') if k == 'web' else url_for('shop_index'),
               'text': f'This server hit its RAM/CPU limit {n_hot} times this week. A bigger plan will make it faster and more stable.'}
    return jsonify({'success': True, 'pct': pct, 'days': round(span / 86400, 1), 'events': [dict(e) for e in evs], 'suggest': sug})


# ---- tickets: instant first answer from the assistant (admin switch in Admin -> AI assistant) ----
def _ai_ticket_reply(tid, uid, subj, body):
    try:
        u = db_execute("SELECT role FROM users WHERE id=?", (uid,), fetchone=True)
        servers = _ai_tool('list_servers', {}, uid, 'user')
        system = (_ai_system(False) + "\nYou are writing the FIRST reply to a support ticket. Be helpful and concrete, 3-8 short lines. "
                  "If it needs a human (billing, refunds, account changes, bugs you cannot confirm), say a human admin will follow up and what info would help. "
                  "Never promise refunds, credits or dates. Do not use tools.")
        msg = f"TICKET SUBJECT: {subj}\nTICKET: {body}\n\nTHE USER'S SERVERS: {json.dumps(servers)[:1500]}"
        r = _ai_call([{'role': 'user', 'content': msg}], system, [])
        text = ''.join(b.get('text', '') for b in (r.get('content') or []) if b.get('type') == 'text').strip()
        if not text:
            return
        db_execute("INSERT INTO ticket_msgs (ticket_id, user_id, is_admin, body) VALUES (?,?,1,?)", (tid, None, '🤖 PHvm Assistant (automatic first reply — an admin will check too):\n' + text[:3500]))
        db_execute("UPDATE tickets SET updated_at=CURRENT_TIMESTAMP WHERE id=?", (tid,))
        notify_user(uid, f'Reply to your ticket #{tid}', text[:300], 'info')
    except Exception as e:
        print('[ai] ticket reply failed:', str(e)[:100], flush=True)


# ---- achievements ----
_BADGES = [
    ('first', 'First server', 'fa-rocket', 10, 'Launch your first server'),
    ('three', 'Collector', 'fa-layer-group', 20, 'Run 3 servers'),
    ('vet', 'Veteran', 'fa-medal', 25, 'Keep a server for 30 days'),
    ('steady', 'Rock solid', 'fa-shield-heart', 25, 'A server 7+ days old with no crashes this week'),
    ('gamer', 'Game host', 'fa-gamepad', 15, 'Host a Minecraft, Palworld or Hytale server'),
    ('dev', 'Builder', 'fa-code', 15, 'Run a code app (Code, Jupyter, VS Code, R)'),
    ('safe', 'Locked down', 'fa-lock', 20, 'Turn on two-factor login'),
    ('link', 'Connected', 'fa-link', 10, 'Link your Discord'),
    ('crowd', 'Recruiter', 'fa-user-plus', 20, 'Invite a friend who signs up'),
    ('fav', 'Fan favourite', 'fa-star', 25, 'Get 10 votes on a listed server'),
]


def _ach_calc(uid):
    vms = db_execute("SELECT vm_id, provision_kind, provision_opt, created_at FROM vm_instances WHERE user_id=?", (uid,), fetch=True) or []
    now = time.time()
    ages, kinds, apps = [], set(), set()
    for v in vms:
        try:
            ages.append((now - datetime.strptime(str(v['created_at'])[:19], '%Y-%m-%d %H:%M:%S').timestamp()) / 86400)
        except Exception:
            pass
        kinds.add(v['provision_kind'])
        try:
            apps.add(json.loads(v['provision_opt'] or '{}').get('app'))
        except Exception:
            pass
    _ev_init()
    crash7 = 0
    if vms:
        ids = [v['vm_id'] for v in vms]
        r = db_execute("SELECT COUNT(*) AS n FROM server_events WHERE vm_id IN (%s) AND kind='down' AND note IN ('crash','oom') AND ts>?" % ','.join('?' * len(ids)), tuple(ids) + (int(now) - 7 * 86400,), fetchone=True)
        crash7 = int(r['n']) if r else 0
    u = db_execute("SELECT totp_enabled, discord_id FROM users WHERE id=?", (uid,), fetchone=True)
    refs = db_execute("SELECT COUNT(*) AS n FROM users WHERE referred_by=?", (uid,), fetchone=True)
    _pub_init()
    votes = 0
    if vms:
        ids = [v['vm_id'] for v in vms]
        r = db_execute("SELECT COUNT(*) AS n FROM server_votes WHERE vm_id IN (%s)" % ','.join('?' * len(ids)), tuple(ids), fetchone=True)
        votes = int(r['n']) if r else 0
    done = {
        'first': bool(vms), 'three': len(vms) >= 3, 'vet': any(a >= 30 for a in ages),
        'steady': any(a >= 7 for a in ages) and crash7 == 0,
        'gamer': bool(kinds & {'minecraft'}) or bool(apps & {'palworld', 'hytale'}),
        'dev': bool(apps & {'code', 'sandbox', 'vscode', 'rstudio'}),
        'safe': bool(u and u['totp_enabled']), 'link': bool(u and u['discord_id']),
        'crowd': bool(refs and refs['n'] >= 1), 'fav': votes >= 10,
    }
    pts = sum(b[3] for b in _BADGES if done.get(b[0]))
    return done, pts


_LB = {'t': 0, 'rows': []}


def _ach_board():
    if time.time() - _LB['t'] < 600:
        return _LB['rows']
    rows = []
    for u in (db_execute("SELECT id, username FROM users WHERE is_active=1 ORDER BY id LIMIT 400", fetch=True) or []):
        try:
            _d, p = _ach_calc(u['id'])
        except Exception:
            continue
        if p > 0:
            n = u['username'] or '?'
            rows.append((n[:2] + '***', p))
    rows.sort(key=lambda x: -x[1])
    _LB.update(t=time.time(), rows=rows[:10])
    return _LB['rows']


@app.route('/achievements')
@login_required
def achievements_page():
    done, pts = _ach_calc(session['user_id'])
    level = 1 + pts // 30
    items = [{'id': b[0], 'name': b[1], 'icon': b[2], 'pts': b[3], 'hint': b[4], 'done': bool(done.get(b[0]))} for b in _BADGES]
    return render_template('achievements.html', items=items, pts=pts, level=level, into=pts % 30, nxt=30, total=sum(b[3] for b in _BADGES), board=_ach_board())


# ───────── v21.95: shell inside Docker servers + web push notifications (self-contained, no extra packages) ─────────
class _PtyChan:
    """Looks like a paramiko channel, but is a local pseudo-terminal running `docker exec -it`."""
    def __init__(self, cmd, cols=140, rows=40):
        import pty
        self.master, slave = pty.openpty()
        self._set(cols, rows)
        env = dict(os.environ, TERM='xterm-256color')
        self.proc = subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, start_new_session=True, close_fds=True, env=env)
        os.close(slave)
        self._closed = False

    def _set(self, cols, rows):
        import fcntl, termios, struct
        fcntl.ioctl(self.master, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))

    def fileno(self):
        return self.master

    def recv_ready(self):
        import select
        try:
            return bool(select.select([self.master], [], [], 0)[0])
        except Exception:
            return False

    def recv(self, n):
        try:
            d = os.read(self.master, n)
        except OSError:
            d = b''
        if not d:
            self._closed = True
        return d

    def send(self, s):
        os.write(self.master, s.encode('utf-8') if isinstance(s, str) else s)

    def resize_pty(self, width=80, height=24):
        self._set(width, height)

    def settimeout(self, t):
        pass

    @property
    def closed(self):
        if not self._closed and self.proc.poll() is not None and not self.recv_ready():
            self._closed = True
        return self._closed

    def close(self):
        self._closed = True
        try:
            self.proc.terminate()
        except Exception:
            pass
        try:
            os.close(self.master)
        except Exception:
            pass
        try:
            self.proc.wait(timeout=2)
        except Exception:
            pass


class _NoSsh:
    def close(self):
        pass


def _docker_shell_cmd(vid):
    return ['docker', 'exec', '-it', _cname(vid), 'sh', '-c', 'command -v bash >/dev/null 2>&1 && exec bash || exec sh']


def _terminal_connect_docker(vm_id, v):
    if not dk_status(vm_id)[0]:
        return jsonify({'success': False, 'message': 'The server is not running. Start it first.'})
    mine = [s for s in terminal_sessions.values() if s.get('user_id') == session.get('user_id') and s.get('docker')]
    if len(mine) >= 3:
        return jsonify({'success': False, 'message': 'You already have 3 shells open. Close one first.'})
    data = request.json or {}
    cols = max(10, min(500, int(data.get('cols', 140) or 140)))
    rows = max(5, min(200, int(data.get('rows', 40) or 40)))
    chan = _PtyChan(_docker_shell_cmd(vm_id), cols, rows)
    sid = str(uuid.uuid4())
    terminal_sessions[sid] = {'ssh': _NoSsh(), 'channel': chan, 'created': time.time(), 'last_active': time.time(),
                              'user_id': session.get('user_id'), 'vm_id': vm_id, 'docker': True,
                              'decoder': codecs.getincrementaldecoder('utf-8')(errors='replace')}
    audit(session['user_id'], 'docker_shell', vm_id[:8])
    out = ''
    deadline = time.time() + 0.6
    raw = b''
    while time.time() < deadline:
        if chan.recv_ready():
            raw += chan.recv(8192)
            time.sleep(0.02)
        elif raw:
            break
        else:
            time.sleep(0.03)
    out = terminal_sessions[sid]['decoder'].decode(raw)
    return jsonify({'success': True, 'session': sid, 'output': out})


# ---- Web Push (RFC 8030 / 8291 / 8292) ----
def _b64u(b):
    return base64.urlsafe_b64encode(b).rstrip(b'=').decode()


def _b64u_dec(s):
    return base64.urlsafe_b64decode(s + '=' * (-len(s) % 4))


def _push_keys():
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import serialization
    pem = gsv('push_priv_pem', '')
    if pem:
        key = serialization.load_pem_private_key(pem.encode(), password=None)
    else:
        key = ec.generate_private_key(ec.SECP256R1())
        _set_setting('push_priv_pem', key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()).decode())
    pub = key.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    return key, _b64u(pub)


def _push_encrypt(payload, ua_pub_b64, auth_b64):
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.kdf.hkdf import HKDF
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    ua_pub, auth = _b64u_dec(ua_pub_b64), _b64u_dec(auth_b64)
    eph = ec.generate_private_key(ec.SECP256R1())
    as_pub = eph.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    shared = eph.exchange(ec.ECDH(), ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ua_pub))
    ikm = HKDF(algorithm=hashes.SHA256(), length=32, salt=auth, info=b'WebPush: info\x00' + ua_pub + as_pub).derive(shared)
    salt = os.urandom(16)
    cek = HKDF(algorithm=hashes.SHA256(), length=16, salt=salt, info=b'Content-Encoding: aes128gcm\x00').derive(ikm)
    nonce = HKDF(algorithm=hashes.SHA256(), length=12, salt=salt, info=b'Content-Encoding: nonce\x00').derive(ikm)
    ct = AESGCM(cek).encrypt(nonce, payload + b'\x02', None)
    return salt + (4096).to_bytes(4, 'big') + bytes([len(as_pub)]) + as_pub + ct


def _push_vapid_header(endpoint):
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
    key, pub = _push_keys()
    u = urllib.parse.urlparse(endpoint)
    head = _b64u(json.dumps({'typ': 'JWT', 'alg': 'ES256'}, separators=(',', ':')).encode())
    claims = _b64u(json.dumps({'aud': f'{u.scheme}://{u.netloc}', 'exp': int(time.time()) + 12 * 3600, 'sub': 'mailto:' + (gsv('smtp_from', '') or 'admin@localhost.invalid').split('<')[-1].strip('> ')}, separators=(',', ':')).encode())
    r, s = decode_dss_signature(key.sign((head + '.' + claims).encode(), ec.ECDSA(hashes.SHA256())))
    sig = _b64u(r.to_bytes(32, 'big') + s.to_bytes(32, 'big'))
    return f'vapid t={head}.{claims}.{sig}, k={pub}'


def _push_init():
    db_execute("CREATE TABLE IF NOT EXISTS push_subs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, endpoint TEXT UNIQUE NOT NULL, p256dh TEXT, auth TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP)")


def _push_send_one(sub, title, body, url='/'):
    data = _push_encrypt(json.dumps({'title': title[:80], 'body': body[:240], 'url': url}).encode(), sub['p256dh'], sub['auth'])
    req = urllib.request.Request(sub['endpoint'], data=data, method='POST', headers={
        'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream', 'TTL': '86400',
        'Authorization': _push_vapid_header(sub['endpoint'])})
    try:
        urllib.request.urlopen(req, timeout=10).read()
        return True
    except urllib.error.HTTPError as e:
        if e.code in (404, 410):
            db_execute("DELETE FROM push_subs WHERE endpoint=?", (sub['endpoint'],))
        print('[push] http', e.code, flush=True)
    except Exception as e:
        print('[push] failed:', str(e)[:80], flush=True)
    return False


def _push_user(uid, title, body, url='/'):
    try:
        _push_init()
        for s in (db_execute("SELECT * FROM push_subs WHERE user_id=?", (uid,), fetch=True) or []):
            _push_send_one(s, title, body, url)
    except Exception as e:
        print('[push] error:', str(e)[:80], flush=True)


@app.route('/push/key')
@login_required
def push_key():
    try:
        _push_init()
        n = db_execute("SELECT COUNT(*) AS n FROM push_subs WHERE user_id=?", (session['user_id'],), fetchone=True)
        return jsonify({'success': True, 'key': _push_keys()[1], 'subscribed': bool(n and n['n'])})
    except Exception as e:
        return jsonify({'success': False, 'message': 'Push is not available: ' + str(e)[:80]})


@app.route('/push/subscribe', methods=['POST'])
@login_required
def push_subscribe():
    _push_init()
    d = request.get_json(silent=True) or {}
    ep, k = (d.get('endpoint') or ''), (d.get('keys') or {})
    if not ep.startswith('https://') or len(ep) > 600 or not k.get('p256dh') or not k.get('auth'):
        return _dk_json_err('Invalid subscription.')
    n = db_execute("SELECT COUNT(*) AS n FROM push_subs WHERE user_id=?", (session['user_id'],), fetchone=True)
    if n and n['n'] >= 8:
        db_execute("DELETE FROM push_subs WHERE id=(SELECT MIN(id) FROM push_subs WHERE user_id=?)", (session['user_id'],))
    db_execute("INSERT INTO push_subs (user_id, endpoint, p256dh, auth) VALUES (?,?,?,?) ON CONFLICT(endpoint) DO UPDATE SET user_id=excluded.user_id, p256dh=excluded.p256dh, auth=excluded.auth",
               (session['user_id'], ep, str(k['p256dh'])[:200], str(k['auth'])[:60]))
