# ───────── v21.95: reseller report + template marketplace ─────────
@app.route('/reseller/report')
@login_required
def reseller_report():
    if session.get('role') not in ('reseller', 'admin'):
        return _dk_json_err('Reseller access only.')
    me = session['user_id']
    now = datetime.now()
    custs = db_execute("SELECT id, username FROM users WHERE reseller_id=? ORDER BY id DESC", (me,), fetch=True) or []
    rows = db_execute("SELECT v.vm_id, v.name, v.status, v.expiry_date, v.user_id FROM vm_instances v JOIN users u ON u.id=v.user_id WHERE u.reseller_id=?", (me,), fetch=True) or []
    per = {c_['id']: {'name': c_['username'], 'sites': 0, 'next': ''} for c_ in custs}
    soon, active = 0, 0
    for r in rows:
        p = per.get(r['user_id'])
        if p is None:
            continue
        p['sites'] += 1
        ex = str(r['expiry_date'] or '')[:10]
        if r['status'] == 'running':
            active += 1
        try:
            dleft = (datetime.strptime(ex, '%Y-%m-%d') - now).days if ex else None
        except Exception:
            dleft = None
        if dleft is not None and 0 <= dleft <= 7:
            soon += 1
        if ex and (not p['next'] or ex < p['next']):
            p['next'] = ex
    months = []
    for i in range(5, -1, -1):
        y, mth = now.year, now.month - i
        while mth <= 0:
            mth += 12; y -= 1
        key = f'{y:04d}-{mth:02d}'
        r = db_execute("SELECT COALESCE(SUM(-amount),0) AS s FROM wallet_transactions WHERE user_id=? AND type='reseller' AND strftime('%Y-%m', created_at)=?", (me, key), fetchone=True)
        months.append({'m': key, 'spent': round(float(r['s']) if r else 0, 2)})
    tot = db_execute("SELECT COALESCE(SUM(-amount),0) AS s FROM wallet_transactions WHERE user_id=? AND type='reseller'", (me,), fetchone=True)
    return jsonify({'success': True, 'customers': len(custs), 'sites': len(rows), 'active': active, 'expiring_7d': soon,
                    'spent_total': round(float(tot['s']) if tot else 0, 2), 'months': months,
                    'top': sorted(per.values(), key=lambda x: -x['sites'])[:10]})


_MKT_KINDS = {'minecraft': 'Minecraft', 'code': 'Code Editor', 'sandbox': 'Code Sandbox', 'vscode': 'VS Code Studio', 'rstudio': 'R Studio'}
_MKT_SKIP_TOP = {'world', 'world_nether', 'world_the_end', 'logs', 'crash-reports', 'cache', 'libraries', 'versions', '.console_in', 'node_modules', '.git'}
_MKT_MAX = 60 * 1024 * 1024


def _mkt_dir():
    d = DK_BACKUP_DIR / '_mkt'
    d.mkdir(parents=True, exist_ok=True)
    return d


def _mkt_init():
    db_execute("CREATE TABLE IF NOT EXISTS mkt_templates (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, name TEXT, descr TEXT, kind TEXT, price REAL DEFAULT 0, status TEXT DEFAULT 'pending', size INTEGER DEFAULT 0, installs INTEGER DEFAULT 0, files TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP)")


def _mkt_kind(v):
    k = row_get(v, 'provision_kind')
    if k == 'minecraft':
        return 'minecraft'
    a = _app_key(v) if k == 'web' else None
    return a if a in _MKT_KINDS else None


def _mkt_build(vid, dest):
    base = _dk_dir(vid)
    names, total = [], 0
    with tarfile.open(dest, 'w:gz') as tar:
        for root, dirs, files in os.walk(str(base)):
            rel = os.path.relpath(root, str(base))
            if rel == '.':
                dirs[:] = [d for d in dirs if d not in _MKT_SKIP_TOP]
            for f in files:
                fp = os.path.join(root, f)
                if os.path.islink(fp) or not os.path.isfile(fp):
                    continue
                r_ = os.path.relpath(fp, str(base))
                if rel == '.' and f.lower().endswith('.jar'):
                    continue                                              # the server jar itself is downloaded by the image
                total += os.path.getsize(fp)
                if total > _MKT_MAX:
                    raise RuntimeError('Too big (max 60 MB). Remove worlds and large files first.')
                tar.add(fp, arcname=r_, recursive=False)
                names.append(r_)
    return names, total


def _mkt_safe_members(tar):
    out = []
    for m_ in tar.getmembers():
        n = m_.name
        if n.startswith('/') or '..' in n.split('/') or m_.issym() or m_.islnk() or m_.isdev() or not (m_.isfile() or m_.isdir()):
            raise RuntimeError('This template contains unsafe files.')
        out.append(m_)
    return out


@app.route('/vm/<vm_id>/template/publish', methods=['POST'])
@login_required
@vm_owner_or_admin
def mkt_publish(vm_id):
    _mkt_init()
    v = _dk_row(vm_id)
    kind = _mkt_kind(v) if v else None
    if not kind:
        return _dk_json_err('Templates can be made from Minecraft, Code, Sandbox, VS Code and R Studio servers.')
    d = request.get_json(silent=True) or {}
    name = re.sub(r'[<>\r\n]', ' ', str(d.get('name') or '')).strip()[:60]
    desc = re.sub(r'[<>\r\n]', ' ', str(d.get('desc') or '')).strip()[:300]
    try:
        price = round(max(0.0, min(50.0, float(d.get('price') or 0))), 2)
    except Exception:
        price = 0.0
    if len(name) < 3:
        return _dk_json_err('Give the template a name (3+ characters).')
    n = db_execute("SELECT COUNT(*) AS n FROM mkt_templates WHERE owner_id=?", (session['user_id'],), fetchone=True)
    if n and n['n'] >= 10:
        return _dk_json_err('You already have 10 templates. Delete one first.')
    tid = db_execute("INSERT INTO mkt_templates (owner_id, name, descr, kind, price, status) VALUES (?,?,?,?,?,'building')", (session['user_id'], name, desc, kind, price), lastrowid=True)
    dest = _mkt_dir() / f'{tid}.tgz'
    try:
        names, total = _mkt_build(vm_id, dest)
        if not names:
            raise RuntimeError('There is nothing to share yet — start the server once and configure it first.')
    except Exception as e:
        dest.unlink(missing_ok=True)
        db_execute("DELETE FROM mkt_templates WHERE id=?", (tid,))
        return _dk_json_err(str(e)[:200])
    db_execute("UPDATE mkt_templates SET status='pending', size=?, files=? WHERE id=?", (total, json.dumps(names[:300]), tid))
    _admin_alert(f'🧩 New template waiting for approval: {name} ({kind})')
    audit(session['user_id'], 'mkt_publish', f'{tid} {name}')
    return jsonify({'success': True, 'message': f'Sent for approval ({len(names)} files, {total // 1024} KB). Everything in it is shared — check there are no passwords or private files.', 'files': names[:60]})


def _mkt_card_row(r, mine_servers):
    return {'id': r['id'], 'name': r['name'], 'desc': r['descr'] or '', 'kind': _MKT_KINDS.get(r['kind'], r['kind']), 'kind_key': r['kind'], 'price': float(r['price'] or 0),
            'size_kb': int((r['size'] or 0) // 1024), 'installs': int(r['installs'] or 0), 'author': (row_get(r, 'username') or '?'),
            'targets': [s for s in mine_servers if s['kind'] == r['kind']]}


