@app.route('/templates/<int:tid>/install', methods=['POST'])
@login_required
def mkt_install(tid):
    _mkt_init()
    uid = session['user_id']
    t_ = db_execute("SELECT * FROM mkt_templates WHERE id=? AND status='approved'", (tid,), fetchone=True)
    vid = safe_vm_id((request.get_json(silent=True) or {}).get('vm_id') or '')
    v = _dk_row(vid) if vid else None
    if not t_ or not v or v['user_id'] != uid or _mkt_kind(v) != t_['kind']:
        return _dk_json_err('Pick one of your own servers of the same type as the template.')
    path = _mkt_dir() / f"{tid}.tgz"
    if not path.is_file():
        return _dk_json_err('Template file is missing.')
    try:
        with tarfile.open(path, 'r:gz') as tar:
            _mkt_safe_members(tar)
    except Exception as e:
        return _dk_json_err(str(e)[:150])
    price = float(t_['price'] or 0)
    owner = t_['owner_id']
    if price > 0 and owner != uid:
        if not db_execute("UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?", (price, uid, price), rowcount=True):
            return _dk_json_err('Not enough Volts (⚡%.2f needed).' % price)
        cut = round(price * (100 - _mkt_fee()) / 100, 2)
        db_execute("UPDATE users SET wallet_balance = COALESCE(wallet_balance,0) + ? WHERE id=?", (cut, owner))
        db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)", (uid, -price, 'template_buy', f"Template: {t_['name']}"))
        db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)", (owner, cut, 'template_sale', f"Template sold: {t_['name']}"))
    uidn = _dk_uid(v) or 0

    def work(log):
        was = bool(dk_status(vid)[0])
        try:
            if was:
                log('Stopping the server…')
                _docker('stop', '-t', '20', _cname(vid), timeout=90)
                vm._st.pop(vid, None)
            base = _dk_dir(vid)
            base.mkdir(parents=True, exist_ok=True)
            with tarfile.open(path, 'r:gz') as tar:
                mem = _mkt_safe_members(tar)
                log('Installing files…')
                try:
                    tar.extractall(str(base), members=mem, filter='data')
                except TypeError:
                    tar.extractall(str(base), members=mem)
            _dk_chown_tree(str(base), uidn) if uidn else None
        except Exception:
            if price > 0 and owner != uid:                       # undo the payment if the install failed
                db_execute("UPDATE users SET wallet_balance = COALESCE(wallet_balance,0) + ? WHERE id=?", (price, uid))
                db_execute("UPDATE users SET wallet_balance = COALESCE(wallet_balance,0) - ? WHERE id=?", (cut, owner))
            raise
        finally:
            if was:
                _docker('start', _cname(vid), timeout=60)
                vm._st.pop(vid, None)
    ok, msg = _web_task(vid, 'Installing template', work)
    if not ok:
        if price > 0 and owner != uid:
            db_execute("UPDATE users SET wallet_balance = COALESCE(wallet_balance,0) + ? WHERE id=?", (price, uid))
            db_execute("UPDATE users SET wallet_balance = COALESCE(wallet_balance,0) - ? WHERE id=?", (cut, owner))
        return _dk_json_err(msg)
    db_execute("UPDATE mkt_templates SET installs=installs+1 WHERE id=?", (tid,))
    audit(uid, 'mkt_install', f'{tid} -> {vid[:8]}')
    return jsonify({'success': True, 'message': 'Installing — your server restarts when it is done.'})


