# ───────── v21.96: maintenance mode, sale banner, health score, new-device alerts, changelog, profit report, API for Docker servers ─────────
def _maint_state():
    now = time.time()
    try:
        on = gsv('maint_on', '0') == '1'
        st, en = float(gsv('maint_start', '0') or 0), float(gsv('maint_end', '0') or 0)
    except Exception:
        return False, '', 0, 0
    active = (on and (en == 0 or now < en)) or (st > 0 and st <= now and (en == 0 or now < en))
    return active, (gsv('maint_msg', '') or 'We are doing maintenance. Back soon!'), st, en


_MAINT_OK = {'static', 'login', 'login_2fa', 'logout', 'healthz', 'status_page', 'pub_badge', 'pub_status_json', 'status_widget', 'mc_public_status', 'changelog_page',
             'pwa_manifest', 'pwa_sw', 'pwa_icon', 'license_page', 'forgot_password', 'stripe_webhook', 'login_discord', 'login_discord_callback', 'status_confirm', 'status_unsub', 'reset_password', 'maintenance_json'}
_MAINT_HTML = """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="60"><title>Maintenance</title>
<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#0b0b0d;color:#e6e6ea;font-family:Inter,system-ui,sans-serif}.c{background:#141418;border:1px solid #26262c;border-radius:18px;padding:36px 40px;text-align:center;max-width:460px;width:calc(100% - 32px)}
.i{width:64px;height:64px;border-radius:18px;margin:0 auto 16px;display:grid;place-items:center;font-size:28px;background:linear-gradient(145deg,#f4f4f7,#b9b9c2);color:#0b0b0d}h1{font-size:22px;margin:0 0 10px}p{color:#a5a5b0;line-height:1.5;margin:0 0 6px}small{color:#6e6e78}a{color:#cfcfd8}</style></head>
<body><div class="c"><div class="i">🛠</div><h1>Under maintenance</h1><p>{{ msg }}</p>{% if until %}<p>Expected back: <b id="u" data-t="{{ until }}"></b></p>{% endif %}<small>This page refreshes by itself. Your servers keep running. · <a href="/login">Admin login</a></small></div>
<script>var u=document.getElementById('u');if(u)u.textContent=new Date(+u.dataset.t*1000).toLocaleString()</script></body></html>"""


@app.before_request
def _maintenance_gate():
    ep = request.endpoint or ''
    if ep in _MAINT_OK or ep.startswith('static'):
        return None
    active, msg, st, en = _maint_state()
    if not active:
        return None
    if session.get('role') == 'admin' or request.path.startswith('/api/node/') or request.path.startswith('/api/v1/admin') or request.path.startswith('/admin/maintenance'):
        return None
    if request.method != 'GET' or request.path.startswith('/api/') or request.headers.get('Accept', '').startswith('application/json'):
        r = jsonify({'success': False, 'message': 'Maintenance: ' + msg})
        r.status_code = 503
        r.headers['Retry-After'] = '120'
        return r
    r = Response(render_template_string(_MAINT_HTML, msg=msg, until=int(en) if en else 0), status=503, mimetype='text/html')
    r.headers['Retry-After'] = '120'
    return r


@app.route('/maintenance.json')
def maintenance_json():
    a, msg, st, en = _maint_state()
    return jsonify({'active': a, 'message': msg if a else '', 'start': int(st), 'end': int(en)})


