# ---- site banners: sale campaign + upcoming maintenance ----
def _site_banners():
    out = []
    try:
        now = time.time()
        end = float(gsv('sale_end', '0') or 0)
        if end > now and gsv('sale_code', ''):
            out.append({'kind': 'sale', 'text': f"🔥 {gsv('sale_title', 'Sale')}: {gsv('sale_percent', '')}% off — use code {gsv('sale_code', '')}", 'end': int(end)})
        a, msg, st, en = _maint_state()
        if not a and st > now and st - now < 48 * 3600:
            out.append({'kind': 'maint', 'text': '🛠 Planned maintenance — ' + (msg or 'short downtime expected'), 'end': int(st), 'start': True})
    except Exception:
        pass
    return out


app.jinja_env.globals['site_banners'] = _site_banners
app.jinja_env.globals['maint_active'] = lambda: _maint_state()[0]


def _expiring_soon():
    uid = session.get('user_id')
    if not uid:
        return []
    out = []
    try:
        for v in (db_execute("SELECT vm_id, name, expiry_date, provision_kind, provision_opt, runtime FROM vm_instances WHERE user_id=? AND expiry_date IS NOT NULL", (uid,), fetch=True) or []):
            d = (datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S') - datetime.now()).total_seconds() / 86400.0
            if 0 < d <= 7:
                pid = ''
                if v['provision_kind'] == 'web':
                    try:
                        pid = (json.loads(v['provision_opt'] or '{}') or {}).get('plan_id') or ''
                    except Exception:
                        pid = ''
                out.append({'name': v['name'], 'days': max(1, int(d + 0.99)), 'vm_id': v['vm_id'], 'web': v['provision_kind'] == 'web', 'plan': pid})
    except Exception:
        pass
    return sorted(out, key=lambda x: x['days'])[:4]


app.jinja_env.globals['expiring_soon'] = _expiring_soon


@app.route('/admin/sales', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_sales():
    if request.method == 'POST':
        if request.form.get('action') == 'stop':
            code = gsv('sale_code', '')
            if code:
                db_execute("UPDATE coupons SET active=0 WHERE code=?", (code,))
            _set_setting('sale_end', '0'); _set_setting('sale_code', '')
            flash('Sale ended.', 'success')
            return redirect(url_for('admin_sales'))
        title = re.sub(r'[<>]', '', (request.form.get('title') or 'Sale').strip())[:40] or 'Sale'
        code = re.sub(r'[^A-Z0-9_-]', '', (request.form.get('code') or '').upper())[:20]
        try:
            pct = int(request.form.get('percent') or 0)
            hrs = float(request.form.get('hours') or 0)
            mx = int(request.form.get('max_uses') or 0)
        except Exception:
            pct, hrs, mx = 0, 0, 0
        if not code or not (1 <= pct <= 90) or not (1 <= hrs <= 24 * 60):
            flash('Enter a code, a percent (1-90) and hours (1-1440).', 'danger')
            return redirect(url_for('admin_sales'))
        exp = (datetime.now() + timedelta(hours=hrs)).strftime('%Y-%m-%d')
        db_execute("INSERT INTO coupons (code, percent, amount_off, max_uses, used, expires, active) VALUES (?,?,0,?,0,?,1) ON CONFLICT(code) DO UPDATE SET percent=excluded.percent, max_uses=excluded.max_uses, used=0, expires=excluded.expires, active=1",
                   (code, pct, max(0, mx), exp))
        _set_setting('sale_title', title); _set_setting('sale_code', code); _set_setting('sale_percent', str(pct)); _set_setting('sale_end', str(int(time.time() + hrs * 3600)))
        audit(session['user_id'], 'sale_start', f'{code} {pct}% {hrs}h')
        flash(f'Sale started — banner is live for {hrs:g} hours.', 'success')
        return redirect(url_for('admin_sales'))
    live = float(gsv('sale_end', '0') or 0) > time.time() and bool(gsv('sale_code', ''))
    c = db_execute("SELECT * FROM coupons WHERE code=?", (gsv('sale_code', ''),), fetchone=True) if live else None
    return render_template('admin/sales.html', live=live, title=gsv('sale_title', ''), code=gsv('sale_code', ''), pct=gsv('sale_percent', ''), end=int(float(gsv('sale_end', '0') or 0)), used=(c['used'] if c else 0))


# ---- health score ----
@app.route('/vm/<vm_id>/health')
@login_required
@vm_owner_or_admin
def server_health(vm_id):
    v = _dk_row(vm_id)
    if not v:
        return _dk_json_err('Not a Docker server.')
    uid = v['user_id']
    items = []
    def add(ok, good, bad, w):
        items.append({'ok': bool(ok), 'text': good if ok else bad, 'w': w})
    pct, span = _uptime_calc(vm_id)
    add(pct >= 99.0 or span < 3600, f'Uptime {pct}% this month', f'Uptime is only {pct}% — check the incident list', 25)
    newest = 0
    try:
        bl = _stbk_list(vm_id) if _app_key(v) else []
        newest = max([b['time'] for b in bl] or [0])
    except Exception:
        pass
    mc_bk = 0
    try:
        mc_bk = max([f.stat().st_mtime for f in _dk_backup_dir(vm_id).glob('*') if f.is_file()] + [0])
    except Exception:
        pass
    newest = max(newest, mc_bk)
    add(time.time() - newest < 7 * 86400 and newest > 0, 'A backup exists from the last 7 days', 'No recent backup — create one in the Backups tab', 20)
    dm = None
    try:
        dm = _dk_disk_cached(vm_id)
    except Exception:
        pass
    lim = int((v['storage_gb'] or 0) * 1024)
    add(dm is None or not lim or dm / lim < 0.8, 'Disk space is fine', 'Disk is over 80% full — delete files or upgrade', 15)
    try:
        dleft = (datetime.strptime(str(v['expiry_date'])[:10], '%Y-%m-%d') - datetime.now()).days if v['expiry_date'] else 999
    except Exception:
        dleft = 999
    add(dleft > 3, 'Plan is paid up', f'Plan ends in {max(0, dleft)} day(s) — renew soon', 15)
    cfg = _dk_alert_cfg(vm_id)
    add(bool(cfg.get('webhook') or cfg.get('tg_token')), 'Crash alerts are on', 'Turn on Discord/Telegram alerts so you hear about crashes first', 10)
    u = db_execute("SELECT totp_enabled FROM users WHERE id=?", (uid,), fetchone=True)
    add(bool(u and u['totp_enabled']), 'Two-factor login is on', 'Turn on two-factor login in My Profile', 15)
    score = sum(i['w'] for i in items if i['ok'])
    return jsonify({'success': True, 'score': score, 'items': items})


# ---- new-device login alerts ----
def _device_label(ua):
    ua = ua or ''
    br = next((n for k, n in (('Edg/', 'Edge'), ('OPR/', 'Opera'), ('Firefox/', 'Firefox'), ('Chrome/', 'Chrome'), ('Safari/', 'Safari')) if k in ua), 'Browser')
    os_ = next((n for k, n in (('Android', 'Android'), ('iPhone', 'iPhone'), ('iPad', 'iPad'), ('Windows', 'Windows'), ('Mac OS', 'Mac'), ('Linux', 'Linux')) if k in ua), 'Unknown OS')
    return f'{br} on {os_}'


def _dev_init():
    db_execute("CREATE TABLE IF NOT EXISTS user_devices (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, fp TEXT NOT NULL, label TEXT, ip TEXT, first_seen INTEGER, last_seen INTEGER, UNIQUE(user_id, fp))")


def _device_check(uid, ip):
    try:
        _dev_init()
        ua = request.headers.get('User-Agent', '')[:300]
        label = _device_label(ua)
        fp = hashlib.sha256((label + '|' + re.sub(r'[\d.]+', '', ua[:120])).encode()).hexdigest()[:20]
        now = int(time.time())
        row = db_execute("SELECT 1 FROM user_devices WHERE user_id=? AND fp=?", (uid, fp), fetchone=True)
        n = db_execute("SELECT COUNT(*) AS n FROM user_devices WHERE user_id=?", (uid,), fetchone=True)
        if row:
            db_execute("UPDATE user_devices SET last_seen=?, ip=? WHERE user_id=? AND fp=?", (now, ip, uid, fp))
            return
        db_execute("INSERT OR IGNORE INTO user_devices (user_id, fp, label, ip, first_seen, last_seen) VALUES (?,?,?,?,?,?)", (uid, fp, label, ip, now, now))
        if n and n['n'] > 0:
            notify_user(uid, 'New device signed in', f'{label} just signed in to your account from {ip}. If this was not you, change your password and turn on two-factor login in My Profile.', 'warning')
    except Exception as e:
        print('[device-check]', str(e)[:80], flush=True)


@app.route('/devices.json')
@login_required
def devices_json():
    _dev_init()
    rows = db_execute("SELECT id, label, ip, first_seen, last_seen FROM user_devices WHERE user_id=? ORDER BY last_seen DESC LIMIT 20", (session['user_id'],), fetch=True) or []
    return jsonify({'success': True, 'devices': [dict(r) for r in rows]})


