@app.route('/admin/profit', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_profit():
    if request.method == 'POST':
        for k in ('cost_server', 'cost_domains', 'cost_other'):
            try:
                _set_setting(k, str(max(0.0, min(1e9, float(request.form.get(k) or 0)))))
            except Exception:
                pass
        flash('Costs saved.', 'success')
        return redirect(url_for('admin_profit'))
    def f(k):
        try:
            return float(gsv(k, '0') or 0)
        except Exception:
            return 0.0
    cost = f('cost_server') + f('cost_domains') + f('cost_other')
    plan_rows = db_execute("SELECT created_at AS t, amount AS amt FROM web_plan_orders WHERE status='done' AND COALESCE(amount,0)>0", fetch=True) or []
    dom_rows = db_execute("SELECT created_at AS t, price AS amt FROM web_domain_orders WHERE status='registered' AND COALESCE(price,0)>0", fetch=True) or []
    by = {}
    for r in list(plan_rows) + list(dom_rows):
        by[str(r['t'])[:7]] = by.get(str(r['t'])[:7], 0.0) + float(r['amt'])
    now = datetime.now()
    months = []
    for i in range(5, -1, -1):
        y, mth = now.year, now.month - i
        while mth <= 0:
            mth += 12; y -= 1
        key = f'{y:04d}-{mth:02d}'
        rev = round(by.get(key, 0.0), 2)
        months.append({'m': key, 'rev': rev, 'cost': round(cost, 2), 'profit': round(rev - cost, 2)})
    running = db_execute("SELECT COUNT(*) AS n FROM vm_instances WHERE status='running'", fetchone=True)
    n = int(running['n']) if running else 0
    cur = (gsv('stripe_currency', 'usd') or 'usd').upper()
    tot_rev, tot_cost = sum(m_['rev'] for m_ in months), cost * len(months)
    return render_template('admin/profit.html', months=months, cost=cost, f=f, n=n, per=(round(cost / n, 2) if n else None), cur=cur,
                           mx=max([abs(m_['rev']) for m_ in months] + [cost, 1]), tot_rev=round(tot_rev, 2), tot_profit=round(tot_rev - tot_cost, 2))


