# ───────── v21.97: expiry reminders, audit filters, panel health ─────────
def _remind_init():
    db_execute("CREATE TABLE IF NOT EXISTS expiry_notices (vm_id TEXT NOT NULL, expiry TEXT NOT NULL, stage INTEGER NOT NULL, PRIMARY KEY (vm_id, expiry, stage))")


def _expiry_remind_tick():
    """Tell users 7, 3 and 1 day before a server expires (once per stage per expiry date)."""
    _remind_init()
    now = datetime.now()
    sent = 0
    for v in (db_execute("SELECT vm_id, name, user_id, expiry_date FROM vm_instances WHERE expiry_date IS NOT NULL", fetch=True) or []):
        try:
            exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        left = (exp - now).total_seconds() / 86400.0
        if left <= 0 or left > 7:
            continue
        stage = 1 if left <= 1 else 3 if left <= 3 else 7
        key = str(v['expiry_date'])[:19]
        if db_execute("SELECT 1 FROM expiry_notices WHERE vm_id=? AND expiry=? AND stage<=?", (v['vm_id'], key, stage), fetchone=True):
            continue
        db_execute("INSERT OR IGNORE INTO expiry_notices (vm_id, expiry, stage) VALUES (?,?,?)", (v['vm_id'], key, stage))
        days = max(1, int(left + 0.99))
        notify_user(v['user_id'], 'Server expires soon', f"\"{v['name']}\" expires in about {days} day(s) ({key[:10]}). Renew it so it keeps running.", 'danger' if stage == 1 else 'warning')
        sent += 1
    try:
        _lowbal_warn_tick()
    except Exception as e:
        print('[lowbal]', str(e)[:80], flush=True)
    return sent


def _expiry_remind_loop():
    time.sleep(90)
    while True:
        try:
            _expiry_remind_tick()
        except Exception as e:
            print('[expiry-remind]', str(e)[:80], flush=True)
        time.sleep(1800)


threading.Thread(target=_expiry_remind_loop, daemon=True, name='expiry-remind').start()


@app.route('/admin/audit')
@login_required
@admin_required
def admin_audit():
    q = (request.args.get('q') or '').strip()[:80]
    who = (request.args.get('user') or '').strip()[:40]
    act = (request.args.get('action') or '').strip()[:60]
    days = request.args.get('days', 0, type=int) or 0
    where, args = [], []
    if q:
        where.append("(a.details LIKE ? OR a.action LIKE ?)"); args += [f'%{q}%', f'%{q}%']
    if who:
        where.append("u.username LIKE ?"); args.append(f'%{who}%')
    if act:
        where.append("a.action = ?"); args.append(act)
    if days > 0:
        where.append("a.timestamp >= datetime('now', ?)"); args.append(f'-{min(days, 3650)} days')
    sql = "SELECT a.*, u.username FROM audit_log a LEFT JOIN users u ON a.user_id=u.id" + (" WHERE " + " AND ".join(where) if where else "") + " ORDER BY a.timestamp DESC LIMIT 300"
    logs = db_execute(sql, tuple(args), fetch=True) or []
    actions = [r['action'] for r in (db_execute("SELECT DISTINCT action FROM audit_log ORDER BY action LIMIT 200", fetch=True) or [])]
    return render_template('admin/audit.html', logs=logs, actions=actions, f={'q': q, 'user': who, 'action': act, 'days': days})


def _panel_health():
    out = {}
    out['cpu'] = psutil.cpu_percent(interval=0.3)
    try:
        out['load'] = [round(x, 2) for x in os.getloadavg()]
    except Exception:
        out['load'] = []
    out['cores'] = psutil.cpu_count() or 1
    vmem = psutil.virtual_memory(); out['ram'] = {'used': vmem.used >> 20, 'total': vmem.total >> 20, 'pct': vmem.percent}
    sw = psutil.swap_memory(); out['swap'] = {'used': sw.used >> 20, 'total': sw.total >> 20}
    try:
        du = shutil.disk_usage(str(Path(__file__).parent)); out['disk'] = {'used': du.used >> 30, 'total': du.total >> 30, 'pct': round(du.used * 100 / max(1, du.total), 1)}
    except Exception:
        out['disk'] = {'used': 0, 'total': 0, 'pct': 0}
    out['uptime_h'] = round((time.time() - psutil.boot_time()) / 3600, 1)
    out['panel_threads'] = threading.active_count()
    try:
        out['db_mb'] = round(Path(DATABASE).stat().st_size / 1048576, 1)
    except Exception:
        out['db_mb'] = None
    dk = docker_available()
    out['docker'] = {'up': bool(dk), 'running': 0, 'total': 0}
    if dk:
        try:
            rc, o, _ = _docker('ps', '-q', timeout=8); out['docker']['running'] = len([x for x in o.split() if x]) if rc == 0 else 0
            rc, o, _ = _docker('ps', '-aq', timeout=8); out['docker']['total'] = len([x for x in o.split() if x]) if rc == 0 else 0
        except Exception:
            pass
    n = db_execute("SELECT COUNT(*) AS n FROM vm_instances", fetchone=True)
    out['servers'] = int(n['n']) if n else 0
    n = db_execute("SELECT COUNT(*) AS n FROM users", fetchone=True)
    out['users'] = int(n['n']) if n else 0
    warn = []
    if out['cpu'] > 90: warn.append('CPU is above 90%.')
    if out['ram']['pct'] > 90: warn.append('RAM is above 90% — stop some servers or add memory.')
    if out['disk']['pct'] > 85: warn.append('Disk is above 85% full — delete old backups or add space.')
    if out['swap']['total'] and out['swap']['used'] * 100 / out['swap']['total'] > 80: warn.append('Swap is almost full.')
    if not dk: warn.append('Docker is not running.')
    out['warnings'] = warn
    return out


