# ───────── v21.102: billing overview (upcoming renewals, auto-renew switches, spend history, low-wallet warning) ─────────
def _billing_data(uid):
    vpu = _vpu()
    u = db_execute("SELECT COALESCE(wallet_balance,0) AS b FROM users WHERE id=?", (uid,), fetchone=True)
    bal = float(u['b']) if u else 0.0
    now = datetime.now()
    items = []
    for v in (db_execute("SELECT vm_id, name, expiry_date, provision_kind, provision_opt, runtime FROM vm_instances WHERE user_id=? AND expiry_date IS NOT NULL ORDER BY expiry_date", (uid,), fetch=True) or []):
        try:
            exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        try:
            opt = json.loads(v['provision_opt'] or '{}') if v['provision_kind'] == 'web' else {}
            opt = opt if isinstance(opt, dict) else {}
        except Exception:
            opt = {}
        pl = db_execute("SELECT name, price, days FROM web_plans WHERE id=?", (opt.get('plan_id'),), fetchone=True) if opt.get('plan_id') else None
        days = (exp - now).total_seconds() / 86400.0
        items.append({'vm_id': v['vm_id'], 'name': v['name'], 'expiry': exp.strftime('%Y-%m-%d'), 'days': int(days) if days > 0 else int(days) - 1,
                      'plan': pl['name'] if pl else '', 'volts': round(float(pl['price'] or 0) * vpu, 2) if pl else None,
                      'web': bool(pl), 'auto': bool(opt.get('auto_renew'))})
    due = round(sum(i['volts'] for i in items if i['volts'] and i['days'] <= 30), 2)
    months = {}
    for r in (db_execute("SELECT amount, created_at FROM wallet_transactions WHERE user_id=? AND created_at >= date('now','-185 days')", (uid,), fetch=True) or []):
        k = str(r['created_at'])[:7]
        a = months.setdefault(k, {'in': 0.0, 'out': 0.0})
        if r['amount'] >= 0:
            a['in'] += r['amount']
        else:
            a['out'] += -r['amount']
    ms = []
    for i in range(5, -1, -1):
        y, mth = now.year, now.month - i
        while mth <= 0:
            mth += 12; y -= 1
        k = f'{y:04d}-{mth:02d}'
        a = months.get(k, {'in': 0.0, 'out': 0.0})
        ms.append({'m': k, 'in': round(a['in'], 2), 'out': round(a['out'], 2)})
    txns = db_execute("SELECT amount, type, description, created_at FROM wallet_transactions WHERE user_id=? ORDER BY id DESC LIMIT 8", (uid,), fetch=True) or []
    return {'balance': round(bal, 2), 'items': items, 'due': due, 'short': round(max(0.0, due - bal), 2), 'months': ms, 'txns': txns,
            'mx': max([m_['in'] for m_ in ms] + [m_['out'] for m_ in ms] + [1])}


