def _lowbal_warn_tick():
    """3 days before an auto-renew, warn once a day if the wallet cannot cover it."""
    now = datetime.now()
    n = 0
    for v in (db_execute("SELECT vm_id, name, user_id, expiry_date, provision_opt FROM vm_instances WHERE provision_kind='web' AND expiry_date IS NOT NULL", fetch=True) or []):
        try:
            opt = json.loads(v['provision_opt'] or '{}')
            exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        if not (isinstance(opt, dict) and opt.get('auto_renew') and opt.get('plan_id')):
            continue
        left = (exp - now).total_seconds() / 86400.0
        if left <= 0 or left > 3:
            continue
        pl = db_execute("SELECT price FROM web_plans WHERE id=?", (opt['plan_id'],), fetchone=True)
        if not pl:
            continue
        cost = round(float(pl['price'] or 0) * _vpu(), 2)
        b = db_execute("SELECT COALESCE(wallet_balance,0) AS b FROM users WHERE id=?", (v['user_id'],), fetchone=True)
        if cost <= 0 or not b or float(b['b']) >= cost:
            continue
        k = 'lowbal:' + v['vm_id']
        if time.time() - float(gsv(k, '0') or 0) < 86400:
            continue
        _set_setting(k, str(time.time()))
        notify_user(v['user_id'], 'Wallet too low for auto-renew', f"\"{v['name']}\" renews on {str(v['expiry_date'])[:10]} for ⚡{cost:g}, but your wallet has ⚡{float(b['b']):g}. Add Volts so it does not stop.", 'warning')
        n += 1
    return n


# ───────── v21.107: Minecraft performance card (TPS, memory, one-click lag presets) ─────────
_MC_PRESETS = {
    'smooth':   {'view-distance': '6',  'simulation-distance': '4', 'network-compression-threshold': '256'},
    'balanced': {'view-distance': '8',  'simulation-distance': '6', 'network-compression-threshold': '256'},
    'max':      {'view-distance': '12', 'simulation-distance': '8', 'network-compression-threshold': '256'},
}
_RE_TPS = re.compile(r'(\d{1,2}(?:\.\d+)?)\s*[,*]?')


def _mc_tps(vid):
    """TPS of the last 1/5/15 minutes from Paper/Purpur's `tps` command, or None."""
    ok, out = _dk_rcon(vid, 'tps', timeout=8)
    if not ok or not out:
        return None
    out = re.sub(r'§.', '', out)
    tail = out.split(':', 1)[-1]
    vals = [float(x) for x in re.findall(r'(\d{1,2}(?:\.\d+)?)', tail)][:3]
    return [min(20.0, v) for v in vals] if vals else None


@app.route('/vm/<vm_id>/server/mc/perf')
@login_required
@vm_owner_or_admin
def mc_perf(vm_id):
    v = _dk_row(vm_id)
    if not v or v['runtime'] != 'docker' or v['provision_kind'] != 'minecraft':
        return _dk_json_err('Only for Docker Minecraft servers.')
    running = bool(dk_status(vm_id)[0])
    props = _dk_props_read(vm_id) or {}
    out = {'success': True, 'running': running, 'view': props.get('view-distance', '10'), 'sim': props.get('simulation-distance', '10'),
           'ram_mb': v['ram_mb'], 'tps': None, 'cpu': None, 'mem': None}
    cur = 'custom'
    for k, p in _MC_PRESETS.items():
        if props.get('view-distance') == p['view-distance'] and props.get('simulation-distance') == p['simulation-distance']:
            cur = k
    out['preset'] = cur
    if running:
        out['tps'] = _mc_tps(vm_id)
        try:
            rc, o, _ = _docker('stats', '--no-stream', '--format', '{{.CPUPerc}}|{{.MemUsage}}', _cname(vm_id), timeout=12)
            if rc == 0 and '|' in o:
                out['cpu'], out['mem'] = [x.strip() for x in o.strip().split('|', 1)]
        except Exception:
            pass
    adv = []
    if out['tps'] and out['tps'][0] < 18:
        adv.append('The server is struggling (TPS under 18). Try the Smooth preset and remove heavy plugins.')
    try:
        if int(out['view']) > 10 and v['ram_mb'] < 4096:
            adv.append('View distance above 10 with less than 4 GB RAM causes lag. Use Balanced or Smooth.')
    except ValueError:
        pass
    out['advice'] = adv
    return jsonify(out)


