def _st_expired(vid):
    try:
        v = _dk_row(vid)
        exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        return exp < datetime.now()
    except Exception:
        return False


def _st_power(vid, act):
    vm._st.pop(vid, None)
    _dk_snap['t'] = 0
    if act in ('start', 'restart') and _st_expired(vid):
        return False, 'This app has expired - renew it first.'
    if act == 'stop':
        return dk_stop(vid), 'Stopped.'
    if act == 'start':
        if not _dk_is_present(vid):
            return False, 'Container is missing — contact support.'
        r = dk_start(vid)
        return bool(r), 'Running.' if r else 'Could not start.'
    if act == 'restart':
        if not _dk_is_present(vid):
            return False, 'Container is missing — contact support.'
        rc, _, e = _docker('restart', '-t', '5', _cname(vid), timeout=60)
        return rc == 0, 'Restarted.' if rc == 0 else (e.strip()[-150:] or 'Restart failed.')
    return False, 'Unknown action.'


def _dk_is_present(vid):
    rc, _, _ = _docker('inspect', '-f', '{{.Id}}', _cname(vid), timeout=10)
    return rc == 0


