# ---- Bedrock cross-play (Geyser + Floodgate) ----
_GEYSER_URL = 'https://download.geysermc.org/v2/projects/geyser/versions/latest/builds/latest/downloads/spigot'
_FLOODGATE_URL = 'https://download.geysermc.org/v2/projects/floodgate/versions/latest/builds/latest/downloads/spigot'


def _dk_bedrock_info(v):
    opt = _mc_opt(v)
    bp = opt.get('bedrock_port')
    host = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    cfgp = _dk_dir(v['vm_id']) / 'plugins' / 'Geyser-Spigot' / 'config.yml'
    return {'enabled': bool(opt.get('bedrock')), 'port': bp, 'address': (f'{host}:{bp}' if bp and host and host != '127.0.0.1' else None),
            'config_ready': cfgp.exists(), 'software_ok': (opt.get('software') or 'paper') in ('paper', 'purpur')}


@app.route('/vm/<vm_id>/server/mc/bedrock', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def mc_bedrock(vm_id):
    if not _is_docker_vm(vm_id):
        return _dk_json_err('Bedrock support is available for Docker Minecraft servers.')
    v = _dk_row(vm_id)
    if _dk_kind(v) != 'minecraft':
        return _dk_json_err('Minecraft servers only.')
    if request.method == 'GET':
        return jsonify(dict(_dk_bedrock_info(v), success=True))
    act = (request.get_json(silent=True) or {}).get('action')
    opt = _mc_opt(v)
    if act == 'enable':
        if (opt.get('software') or 'paper') not in ('paper', 'purpur'):
            return _dk_json_err('Geyser is a plugin — it needs Paper or Purpur.')
        bp = opt.get('bedrock_port')
        if not bp:
            bp = allocate_host_port(preferred=19132)
            db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                       (vm_id, bp, 19132, 'udp', 'Bedrock'))
        new_opt = dict(opt, bedrock=True, bedrock_port=bp)

        def work(log):
            pdir = _dk_plugins_dir(vm_id)
            log('Downloading Geyser…')
            _dk_download(_GEYSER_URL, pdir / 'Geyser-Spigot.jar')
            log('Downloading Floodgate…')
            _dk_download(_FLOODGATE_URL, pdir / 'floodgate-spigot.jar')
            db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(new_opt), vm_id))
            log('Restarting the server…')
            _dk_recreate_mc(v, new_opt, log)
            log('Done. After the first start, press "Let Bedrock players join without a Java account".')
        ok, msg = _dk_task(vm_id, 'Enabling Bedrock support', work)
        audit(session['user_id'], 'mc_bedrock_enable', vm_id)
        return jsonify({'success': ok, 'message': msg})
    if act == 'disable':
        new_opt = dict(opt, bedrock=False)

        def work(log):
            for n in ('Geyser-Spigot.jar', 'floodgate-spigot.jar'):
                (_dk_plugins_dir(vm_id) / n).unlink(missing_ok=True)
            db_execute("DELETE FROM port_forwards WHERE vm_id=? AND guest_port=19132", (vm_id,))
            new_opt.pop('bedrock_port', None)
            db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(new_opt), vm_id))
            log('Restarting the server…')
            _dk_recreate_mc(v, new_opt, log)
        ok, msg = _dk_task(vm_id, 'Disabling Bedrock support', work)
        audit(session['user_id'], 'mc_bedrock_disable', vm_id)
        return jsonify({'success': ok, 'message': msg})
    if act == 'floodgate-auth':
        cfgp = _dk_dir(vm_id) / 'plugins' / 'Geyser-Spigot' / 'config.yml'
        if not cfgp.exists():
            return _dk_json_err('Start the server once so Geyser can create its config, then try again.')
        txt = cfgp.read_text(encoding='utf-8', errors='replace')
        new, n = re.subn(r'(?m)^(\s*auth-type:\s*)\S+', r'\1floodgate', txt, count=1)
        if not n:
            return _dk_json_err('Could not find auth-type in the Geyser config.')
        cfgp.write_text(new, encoding='utf-8')
        _dk_chown(str(cfgp), 1000, 1000)
        _docker('restart', '-t', '60', _cname(vm_id), timeout=120)
        return jsonify({'success': True, 'message': 'Done — Bedrock players can now join without a Java account. Server restarting.'})
    return _dk_json_err('Unknown action.')


# ---- Modrinth modpacks ----
@app.route('/vm/<vm_id>/server/mc/modpack', methods=['POST'])
@login_required
@vm_owner_or_admin
def mc_modpack(vm_id):
    if not _is_docker_vm(vm_id):
        return _dk_json_err('Modpacks are available for Docker Minecraft servers.')
    v = _dk_row(vm_id)
    if _dk_kind(v) != 'minecraft':
        return _dk_json_err('Minecraft servers only.')
    slug = ((request.get_json(silent=True) or {}).get('slug') or '').strip()
    if not _RE_SLUG.match(slug):
        return _dk_json_err('Enter the modpack slug from its Modrinth URL (modrinth.com/modpack/<slug>).')
    opt = dict(_mc_opt(v), software='modrinth', modpack=slug, version='latest', bedrock=False)

    def work(log):
        log('Backing up the world first…')
        _dk_make_backup(vm_id, 'pre-modpack', log)
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vm_id))
        log(f'Installing modpack {slug} (the first start downloads all mods — this can take several minutes)…')
        _dk_recreate_mc(v, opt, log)
        log('Done. Watch the console for progress.')
    ok, msg = _dk_task(vm_id, 'Installing modpack ' + slug, work)
    audit(session['user_id'], 'mc_modpack', f'{vm_id}: {slug}')
    return jsonify({'success': ok, 'message': msg})


