@app.route('/vm/<vm_id>/server/mc/world/import', methods=['POST'])
@login_required
@vm_owner_or_admin
def mc_world_import(vm_id):
    if not _is_docker_vm(vm_id):
        return _dk_json_err('World import is available for Docker servers.')
    v = _dk_row(vm_id)
    f = request.files.get('world')
    if _dk_kind(v) != 'minecraft' or not f or not (f.filename or '').lower().endswith('.zip'):
        return _dk_json_err('Choose a .zip file of your world folder.')
    tmp = _dk_backup_dir(vm_id) / 'import.zip'
    f.save(str(tmp))
    limit_mb = float((v['storage_gb'] or 0) * 1024) or 1e9

    def work(log):
        import zipfile
        try:
            with zipfile.ZipFile(tmp) as z:
                infos = z.infolist()
                if len(infos) > 200000 or sum(i.file_size for i in infos) / 1048576 > limit_mb:
                    raise RuntimeError('the world is bigger than this plan\'s disk')
                levels = sorted((i.filename for i in infos if i.filename.endswith('level.dat')), key=lambda n: n.count('/'))
                if not levels:
                    raise RuntimeError('no level.dat found — is this a Minecraft world zip?')
                prefix = levels[0][:-len('level.dat')]
                base = _dk_dir(vm_id)
                level = (_dk_props_read(vm_id).get('level-name') or 'world')
                level = level if re.match(r'^[A-Za-z0-9_\- ]{1,40}$', level) else 'world'
                log('Backing up the current world…')
                _dk_make_backup(vm_id, 'pre-import', log)
                log('Stopping the server…')
                _docker('stop', '-t', '60', _cname(vm_id), timeout=120)
                for w in (level, level + '_nether', level + '_the_end'):
                    shutil.rmtree(base / w, ignore_errors=True)
                target = base / level
                target.mkdir(parents=True, exist_ok=True)
                log('Extracting…')
                for i in infos:
                    if not i.filename.startswith(prefix) or i.is_dir():
                        continue
                    rel = i.filename[len(prefix):]
                    if not rel or rel.startswith('/') or '..' in rel.split('/'):
                        continue
                    dest = target / rel
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    with z.open(i) as src, open(dest, 'wb') as out:
                        shutil.copyfileobj(src, out)
                _dk_chown_tree(str(target), 1000)
            log('Starting the server…')
            _docker('start', _cname(vm_id), timeout=60)
            log('World imported.')
        finally:
            tmp.unlink(missing_ok=True)
    ok, msg = _dk_task(vm_id, 'Importing world', work)
    audit(session['user_id'], 'mc_world_import', vm_id)
    return jsonify({'success': ok, 'message': msg})


# ---- admin: Docker overview + migrate VM servers to Docker ----
_MC_MIGRATE_SKIP = {'server.jar', 'logs', 'cache', 'libraries', 'versions', 'crash-reports', 'start.sh'}
_BOT_MIGRATE_SKIP = {'venv', 'node_modules', '__pycache__', '.cache'}


def _dk_pull_dir(sftp, remote, local, skip, log, top=True):
    os.makedirs(local, exist_ok=True)
    for e in sftp.listdir_attr(remote):
        n = e.filename
        if (top and n in skip) or n.startswith('.phvm') or n.endswith('.log') or stat.S_ISLNK(e.st_mode):
            continue
        rp, lp = remote.rstrip('/') + '/' + n, os.path.join(local, n)
        if stat.S_ISDIR(e.st_mode):
            _dk_pull_dir(sftp, rp, lp, skip, log, top=False)
        elif stat.S_ISREG(e.st_mode):
            sftp.get(rp, lp)


def _dk_migrate_vm(vid, log):
    v = db_execute("SELECT * FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
    kind = row_get(v, 'provision_kind')
    if kind not in _SERVER_KINDS or row_get(v, 'runtime') == 'docker':
        raise RuntimeError('this VM is not a VM-based Minecraft/Bot server')
    if not vm.vm_status(vid)[0]:
        raise RuntimeError('start the VM first — its files are copied over SSH')
    svc, remote = _SERVER_SVC[kind]
    log('Stopping the server inside the VM…')
    _server_sh(v, f'systemctl stop {svc}', timeout=120)
    opt = _mc_opt(v) if kind == 'minecraft' else None
    if kind == 'minecraft':
        ver = _mc_version(v)
        opt = dict(opt, version=ver or opt.get('version') or 'latest')
    else:
        try:
            opt = json.loads(row_get(v, 'provision_opt') or 'null')
        except Exception:
            opt = None
        opt = opt if opt in ('node', 'python') else ('python' if 'python' in _server_sh(v, 'test -d /root/bot/venv && echo python || echo node') else 'node')
    data = _dk_dir(vid)
    data.mkdir(parents=True, exist_ok=True)
    log(f'Copying {remote} …')
    with sftp_connect(v) as sftp:
        _dk_pull_dir(sftp, remote, str(data), _MC_MIGRATE_SKIP if kind == 'minecraft' else _BOT_MIGRATE_SKIP, log)
    _dk_chown_tree(str(data), 1000 if kind == 'minecraft' else 0)
    log('Files copied. Stopping the VM…')
    pid = vm.vm_status(vid)[1]
    vm.stop_vm(pid, row_get(v, 'ssh_port'), vid=vid)
    db_execute("UPDATE vm_instances SET runtime='docker', os_template='docker', ssh_port=NULL, status='creating', creation_progress=10, "
               "creation_step='Migrating to Docker…', provision_opt=? WHERE vm_id=?", (json.dumps(opt), vid))
    _dk_cache[vid] = (time.time(), True)
    old = VM_DIR / vid
    if old.exists():
        try:
            old.rename(VM_DIR / (vid + '.migrated'))
        except OSError:
            pass
    log('Creating the container…')
    complete_docker_setup(vid, kind, opt)
    if kind == 'bot':
        if row_get(v, 'startup_cmd'):
            _dk_write_bot_script(vid, v['startup_cmd'])
        log('Installing bot dependencies…')
        _dk_run_in_image(vid, _DK_BOT_DEPS, log)
    log('Migration finished. The old VM disk was kept as vm_instances/' + vid + '.migrated — delete it when you are happy.')


# ───────────── Admin: create a Minecraft / Bot server directly (no plan, no payment) ─────────────
@app.route('/admin/create-server', methods=['GET', 'POST'])
@admin_required
def admin_create_server():
    kind = request.values.get('kind', 'minecraft')
    kind = kind if kind in ('minecraft', 'bot', 'web', 'app') else 'minecraft'
    if kind in ('web', 'app') and not _docker_enabled():
        flash('Web hosting needs Docker on the host, and Docker is not available right now.', 'danger')
        return redirect(url_for('admin_dashboard'))
    use_docker = _docker_enabled()
    modded = ('fabric', 'forge', 'neoforge', 'quilt')
    allowed_sw = ['paper', 'purpur', 'vanilla'] + (list(modded) if use_docker else [])
    if request.method == 'POST':
        name = sanitize_name(request.form.get('name', ''), 64)
        ram = safe_int(request.form.get('ram_mb', 2048), 2048, 512, 262144)
        cpu = safe_int(request.form.get('cpu_cores', 2), 2, 1, 128)
        stor = safe_int(request.form.get('storage_gb', 10), 10, 1, 10000)
        uid = safe_int(request.form.get('user_id', session['user_id']), session['user_id'], 1, None)
        days = safe_int(request.form.get('expiry_days', 0), 0, 0, 3650)
        if not db_execute("SELECT id FROM users WHERE id=? AND is_active=1", (uid,), fetchone=True):
            flash('Selected user is invalid.', 'danger')
            return redirect(url_for('admin_create_server', kind=kind))
        if kind == 'app':
            ak = request.form.get('app', '')
            if ak not in _APPS:
                flash('Pick an app or game.', 'danger')
                return redirect(url_for('admin_create_server', kind='app'))
            need = {'palworld': 8192, 'hytale': 4096}.get(ak, 0)
            if ram < need:
                flash(f'Heads up: {_APPS[ak]["name"]} usually needs at least {need // 1024} GB RAM — with {ram // 1024 or ram} {"GB" if ram >= 1024 else "MB"} it may crash. You can raise it later.', 'warning')
            vid = _create_web_site(uid, name or _APPS[ak]['name'], ram, cpu, stor, days, 3, None, ak)
            audit(session['user_id'], 'admin_create_server', f'app {ak} {name} ({str(vid)[:8]}) for user {uid}')
            flash(f'{_APPS[ak]["name"]} "{name}" is being created!', 'success')
            return redirect(url_for('vm_installing', vm_id=vid))
        if kind == 'minecraft':
            sw = request.form.get('software', 'paper')
            ver = (request.form.get('version') or 'latest').strip() or 'latest'
            conn = request.form.get('connection', 'direct')
            if sw not in allowed_sw or (ver.lower() != 'latest' and not _RE_VER.match(ver)) or conn not in ('direct', 'playit', 'minekube'):
                flash('Invalid Minecraft options.', 'danger')
                return redirect(url_for('admin_create_server', kind=kind))
            if conn == 'minekube' and sw not in ('paper', 'purpur'):
                flash('Minekube Connect only works with Paper or Purpur — using Direct IP instead.', 'warning')
                conn = 'direct'
            provision_option = {'software': sw, 'version': ver.lower() if ver.lower() == 'latest' else ver,
                                'playit': conn == 'playit', 'minekube': conn == 'minekube'}
            extra_port = conn == 'direct' or use_docker      # containers always keep a direct port
        elif kind == 'web':
            provision_option = {'app': 'wordpress'}
            extra_port = False
        else:
            rt = request.form.get('runtime', 'node')
            if rt not in ('node', 'python'):
                flash('Invalid runtime.', 'danger')
                return redirect(url_for('admin_create_server', kind=kind))
            provision_option = rt
            extra_port = False
        expiry_date = (datetime.now() + timedelta(days=days)).strftime('%Y-%m-%d %H:%M:%S') if days else None
        vid = str(uuid.uuid4())
        ensure_local_node()
        sp = None if use_docker else allocate_host_port()
        vp = None if use_docker else allocate_host_port()
        ost = 'docker' if use_docker else 'ubuntu-24.04'
        db_execute(
            "INSERT INTO vm_instances (vm_id, user_id, name, os_template, ram_mb, cpu_cores, storage_gb, "
            "ssh_port, vnc_port, network_mode, public_ip, status, expiry_date) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (vid, uid, name, ost, ram, cpu, stor, sp, vp, 'private', None, 'creating', expiry_date))
        db_execute("UPDATE vm_instances SET provision_kind=?, provision_opt=?, runtime=? WHERE vm_id=?",
                   (kind, json.dumps(provision_option), ('docker' if use_docker else None), vid))
        if use_docker:
            _dk_cache[vid] = (time.time(), True)
        if extra_port:
            hp = allocate_host_port(preferred=25565)
            db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                       (vid, hp, 25565, 'tcp', 'minecraft'))
        if kind == 'web':
            hp = allocate_host_port(preferred=8080)
            db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
                       (vid, hp, 80, 'tcp', 'web'))
        add_notification(uid, 'Server creating…', f'{"Minecraft server" if kind == "minecraft" else "Web hosting site" if kind == "web" else "Bot server"} "{name}" is being created.', 'info')
        audit(session['user_id'], 'admin_create_server', f'{kind} {name} ({vid[:8]}) for user {uid} [{"docker" if use_docker else "vm"}]')
        if kind == 'web':
            threading.Thread(target=complete_web_setup, args=(vid,), daemon=True).start()
        elif use_docker:
            threading.Thread(target=complete_docker_setup, args=(vid, kind, provision_option), daemon=True).start()
        else:
            threading.Thread(target=complete_vm_setup,
                             args=(vid, ost, ram, cpu, stor, sp, vp, 'private', None, None),
                             kwargs={'provision_kind': kind, 'provision_option': provision_option}, daemon=True).start()
        flash(f'{"Minecraft server" if kind == "minecraft" else "Web hosting site" if kind == "web" else "Bot server"} "{name}" is being created!', 'success')
        return redirect(url_for('vm_installing', vm_id=vid))
    users = db_execute("SELECT id, username FROM users WHERE is_active=1 ORDER BY username", fetch=True) or []
    return render_template('admin/create_server.html', kind=kind, users=users, use_docker=use_docker, apps=_APPS,
                           software=allowed_sw, labels={'paper': 'Paper (plugins)', 'purpur': 'Purpur (plugins+)', 'vanilla': 'Vanilla',
                                                        'fabric': 'Fabric (mods)', 'forge': 'Forge (mods)', 'neoforge': 'NeoForge (mods)', 'quilt': 'Quilt (mods)'})


@app.route('/admin/docker')
@admin_required
def admin_docker():
    avail = docker_available()
    version, containers, orphans = '', [], []
    known = {r['vm_id'] for r in (db_execute("SELECT vm_id FROM vm_instances", fetch=True) or [])}
    if avail:
        _, version, _ = _docker('version', '--format', '{{.Server.Version}}', timeout=10)
        rc, out, _ = _docker('ps', '-a', '--filter', 'label=phvm=1', '--format', '{{json .}}', timeout=20)
        for line in out.splitlines():
            try:
                j = json.loads(line)
            except ValueError:
                continue
            name = j.get('Names', '')
            vid = name[len('phvm-'):] if name.startswith('phvm-') else name
            vid = vid[:-len('-playit')] if vid.endswith('-playit') else vid
            vid = vid[:-len('-db')] if vid.endswith('-db') else vid
            vid = vid[:-len('-pma')] if vid.endswith('-pma') else vid
            vid = vid[:-len('-cfq')] if vid.endswith('-cfq') else vid
            row = {'name': name, 'vm_id': vid, 'image': j.get('Image'), 'state': j.get('State'), 'status': j.get('Status'), 'orphan': vid not in known}
            containers.append(row)
            if row['orphan']:
                orphans.append(row)
    eligible = [r for r in (db_execute("SELECT vm_id, name, provision_kind FROM vm_instances WHERE provision_kind IN ('minecraft','bot') "
                                      "AND (runtime IS NULL OR runtime != 'docker')", fetch=True) or [])]
    tasks = {k: {'label': t['label'], 'done': t['done'], 'log': t['log'][-8:]} for k, t in _DK_TASKS.items()}
    return render_template('admin/docker.html', avail=avail, version=version.strip(), containers=containers, orphans=orphans,
                           eligible=eligible, tasks=tasks, servers_dir=str(DOCKER_SERVERS_DIR), enabled=_docker_enabled())


@app.route('/admin/docker/remove', methods=['POST'])
@admin_required
def admin_docker_remove():
    name = request.form.get('name', '')
    vid = name[len('phvm-'):] if name.startswith('phvm-') else ''
    vid = vid[:-len('-playit')] if vid.endswith('-playit') else vid
    vid = vid[:-len('-db')] if vid.endswith('-db') else vid
    vid = vid[:-len('-pma')] if vid.endswith('-pma') else vid
    vid = vid[:-len('-cfq')] if vid.endswith('-cfq') else vid
    if not vid or db_execute("SELECT 1 FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True):
        flash('That container belongs to an existing server — delete the server instead.', 'danger')
    else:
        _docker('rm', '-f', name, timeout=60)
        flash(f'Removed orphan container {name}. Its data folder (if any) was kept in {DOCKER_SERVERS_DIR}.', 'success')
    return redirect(url_for('admin_docker'))


