def _dk_console_send(vid, cmd):
    """Send a console line to a Docker server (Minecraft via RCON, bots via their stdin file)."""
    v = _dk_row(vid)
    if not dk_status(vid)[0]:
        return False, 'The server is not running.'
    if _dk_kind(v) == 'minecraft':
        ok, out = _dk_rcon(vid, cmd)
        return ok, (out or 'Sent.')[:500]
    try:
        with open(_dk_dir(vid) / '.console_in', 'a', encoding='utf-8') as f:
            f.write(cmd + '\n')
        return True, 'Sent.'
    except Exception as e:
        return False, str(e)


def _build_docker_embed_fields(v):
    """Plain data for the Discord embed of a Docker server."""
    vid = v['vm_id']
    running, _ = dk_status(vid)
    info = {'running': running, 'cpu': None, 'mem': None, 'addr': None, 'kind': _dk_kind(v)}
    if running:
        rc, out, _ = _docker('stats', '--no-stream', '--format', '{{json .}}', _cname(vid), timeout=20)
        try:
            j = json.loads(out.strip().splitlines()[0])
            info['cpu'] = round(min(100.0, float((j.get('CPUPerc') or '0').strip('%') or 0) / max(1, int(v['cpu_cores'] or 1))), 1)
            info['mem'] = round(_dk_to_mb((j.get('MemUsage') or '').split('/')[0]))
        except Exception:
            pass
    if info['kind'] == 'minecraft':
        info['addr'] = _dk_best_address(v)[0]
    d = _dk_disk_cached(vid)
    info['disk'] = round(d / 1024, 1) if d is not None else None
    return info


