# ═══════════════ Web hosting: WordPress in Docker + Caddy (domains / free SSL) ═══════════════
# Every site = one WordPress container (named like the other servers: phvm-<vm_id>, so power /
# stats / file manager / delete all reuse the Docker server code) + a private MariaDB sidecar
# (phvm-<vm_id>-db). The site files live in the normal server data dir. A single shared Caddy
# container (phvm-caddy) listens on 80/443, gets Let's Encrypt certificates automatically and
# reverse-proxies each connected domain to its WordPress container over the "phvm-web" network.
WEB_NET = 'phvm-web'
CADDY_NAME = 'phvm-caddy'
CADDY_DIR = DOCKER_SERVERS_DIR / '_caddy'
WEB_DB_DIR = DOCKER_SERVERS_DIR / '_webdb'
WEB_CFG_DIR = DOCKER_SERVERS_DIR / '_webcfg'
WEB_WP_IMAGE = 'wordpress:php8.3-apache'
WEB_DB_IMAGE = 'mariadb:11.4'
WEB_MAX_DOMAINS = 5


def _web_domain_limit(v):
    try:
        return max(1, int((_web_opt(v) or {}).get('max_domains') or WEB_MAX_DOMAINS))
    except Exception:
        return WEB_MAX_DOMAINS
_WEB_DOMAIN_RE = re.compile(r'^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$')
_web_dns_cache = {}

_WEB_WP_EXTRA = r"""
if (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && strpos($_SERVER['HTTP_X_FORWARDED_PROTO'], 'https') !== false) { $_SERVER['HTTPS'] = 'on'; }
if (!empty($_SERVER['HTTP_HOST'])) {
    $phvm_scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    define('WP_HOME', $phvm_scheme . '://' . $_SERVER['HTTP_HOST']);
    define('WP_SITEURL', $phvm_scheme . '://' . $_SERVER['HTTP_HOST']);
}
define('FS_METHOD', 'direct');
"""
_WEB_PHP_INI = ("upload_max_filesize = 256M\npost_max_size = 256M\nmemory_limit = 256M\n"
                "max_execution_time = 300\nmax_input_vars = 5000\n"
                "opcache.enable=1\nopcache.memory_consumption=128\nopcache.max_accelerated_files=10000\nopcache.revalidate_freq=60\n")


def _web_names(vid):
    c = _cname(vid)
    return c, c + '-db', c + '-net'


def _web_is(vid):
    try:
        r = db_execute("SELECT provision_kind FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
        return bool(r and row_get(r, 'provision_kind') == 'web')
    except Exception:
        return False


def _web_opt(v):
    try:
        o = json.loads(row_get(v, 'provision_opt') or '{}')
    except Exception:
        o = {}
    return o if isinstance(o, dict) else {}


def _web_tunnel():
    """The admin's default for NEW domains: True = Cloudflare Tunnel, False = public IPv4 (A record).
    Each domain still picks its own way (Domains tab), stored in web_domains.via."""
    return (gsv('web_mode', 'direct') or 'direct').strip() == 'tunnel'


def _web_tunnel_ready():
    """The admin has given the panel a tunnel (token saved, or tunnel chosen as the default at install)."""
    return _web_tunnel() or bool((gsv('cf_tunnel_token', '') or '').strip())


def _web_server_host():
    return (gsv('server_ip', '') or '').strip() or PUBLIC_IP or ''


def _web_direct_url(v):
    fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=80", (v['vm_id'],), fetchone=True)
    host = _web_server_host()
    if not fw or not host or host == '127.0.0.1':
        return None
    return f"http://{host}:{int(fw['host_port'])}"


def _web_server_ips():
    host = _web_server_host()
    if not host:
        return []
    try:
        return sorted(set(socket.gethostbyname_ex(host)[2]))
    except Exception:
        return [host]


def _web_dns_check(domain, via='direct'):
    """(points_here, resolved_ips). Cached for 30 s so the page can poll."""
    if via == 'tunnel':
        return True, ['Cloudflare Tunnel']
    hit = _web_dns_cache.get(domain)
    if hit and time.time() - hit[0] < 30:
        return hit[1], hit[2]
    try:
        ips = sorted(set(socket.gethostbyname_ex(domain)[2]))
    except Exception:
        ips = []
    ok = bool(ips) and any(i in _web_server_ips() for i in ips)
    _web_dns_cache[domain] = (time.time(), ok, ips)
    return ok, ips


def _web_clean_domain(raw):
    d = (raw or '').strip().lower()
    d = re.sub(r'^[a-z]+://', '', d).split('/')[0].split('?')[0].split(':')[0].strip('.')
    return d


# ---------- Cloudflare Tunnel automation (optional) ----------
# With an API token the panel adds/removes each domain's Public hostname in the tunnel and the DNS record itself.
# Token needs: Account -> Cloudflare Tunnel: Edit, and Zone -> DNS: Edit.
_CF_API = 'https://api.cloudflare.com/client/v4'


def _cf_tunnel_ids():
    """(account_id, tunnel_id) decoded from the tunnel token, or (None, None)."""
    tok = (gsv('cf_tunnel_token', '') or '').strip()
    try:
        j = json.loads(base64.b64decode(tok + '=' * (-len(tok) % 4)))
        return str(j['a']), str(j['t'])
    except Exception:
        return None, None


def _cf_ready():
    return bool((gsv('cf_api_token', '') or '').strip()) and all(_cf_tunnel_ids())


def _cf_api(method, path, body=None):
    """-> (ok, result_or_error_text). Never raises, never echoes the token."""
    req = urllib.request.Request(_CF_API + path, method=method,
                                 data=(json.dumps(body).encode() if body is not None else None),
                                 headers={'Authorization': 'Bearer ' + (gsv('cf_api_token', '') or '').strip(),
                                          'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            j = json.loads(r.read().decode() or '{}')
    except urllib.error.HTTPError as e:
        try:
            j = json.loads(e.read().decode() or '{}')
        except Exception:
            return False, f'Cloudflare answered HTTP {e.code}.'
    except Exception as e:
        return False, 'Could not reach Cloudflare: ' + str(e)[:120]
    if j.get('success'):
        return True, j.get('result')
    errs = '; '.join(str(x.get('message', '')) for x in (j.get('errors') or []))[:200]
    return False, errs or 'Cloudflare refused the request.'


def _cf_zone_for(domain):
    parts = domain.split('.')
    for i in range(len(parts) - 1):
        cand = '.'.join(parts[i:])
        ok, res = _cf_api('GET', '/zones?name=' + urllib.parse.quote(cand))
        if ok and res:
            return res[0]['id']
    return None


def _cf_set_ingress(domain, add):
    acc, tid = _cf_tunnel_ids()
    ok, res = _cf_api('GET', f'/accounts/{acc}/cfd_tunnel/{tid}/configurations')
    if not ok:
        return False, res
    cfg = (res or {}).get('config') or {}
    rules = [r for r in (cfg.get('ingress') or []) if r.get('hostname') and r.get('hostname') != domain]
    if add:
        rules.append({'hostname': domain, 'service': 'http://localhost:80'})
    cfg['ingress'] = rules + [{'service': 'http_status:404'}]
    return _cf_api('PUT', f'/accounts/{acc}/cfd_tunnel/{tid}/configurations', {'config': cfg})


def _cf_dns(domain, add):
    _, tid = _cf_tunnel_ids()
    zone = _cf_zone_for(domain)
    if not zone:
        return False, 'This domain is not in your Cloudflare account (add it to Cloudflare first).'
    ok, recs = _cf_api('GET', f'/zones/{zone}/dns_records?name=' + urllib.parse.quote(domain))
    if not ok:
        return False, recs
    target = f'{tid}.cfargotunnel.com'
    mine = [r for r in (recs or []) if r.get('type') == 'CNAME']
    if not add:
        for r in mine:
            if (r.get('content') or '').endswith('.cfargotunnel.com'):
                _cf_api('DELETE', f"/zones/{zone}/dns_records/{r['id']}")
        return True, ''
    other = [r for r in (recs or []) if r.get('type') in ('A', 'AAAA')]
    if other:
        return False, 'An A/AAAA record already exists for this name in Cloudflare. Delete it, then connect the domain again.'
    body = {'type': 'CNAME', 'name': domain, 'content': target, 'proxied': True}
    if mine:
        return _cf_api('PUT', f"/zones/{zone}/dns_records/{mine[0]['id']}", body)
    return _cf_api('POST', f'/zones/{zone}/dns_records', body)


def _cf_connect(domain, add=True):
    """Add/remove a domain in the tunnel + DNS. -> (ok, message)."""
    if add:
        ok, msg = _cf_set_ingress(domain, True)
        if not ok:
            return False, msg
        ok, msg = _cf_dns(domain, True)
        if not ok:
            _cf_set_ingress(domain, False)
        return ok, ('' if ok else msg)
    _cf_set_ingress(domain, False)
    return _cf_dns(domain, False)


def _panel_domain():
    d = _web_clean_domain(gsv('panel_domain', '') or '')
    return d if d and _WEB_DOMAIN_RE.match(d) else ''


def _maxbody(vid):
    try:
        k = _app_key(_dk_row(vid))
        return _APPS[k]['upload'] if k else '512MB'
    except Exception:
        return '512MB'


def _caddy_write():
    rows = db_execute("SELECT d.domain, d.vm_id, d.redirect_to, d.via FROM web_domains d JOIN vm_instances v ON v.vm_id = d.vm_id ORDER BY d.id",
                      fetch=True) or []
    conf = CADDY_DIR / 'conf'
    conf.mkdir(parents=True, exist_ok=True)
    (CADDY_DIR / 'data').mkdir(parents=True, exist_ok=True)
    (CADDY_DIR / 'config').mkdir(parents=True, exist_ok=True)
    parts = ['# Generated by PHvm — do not edit by hand\n']
    _log_on = True   # DDoS shield is hard-wired ON
    if _log_on:
        parts.append("(phvmlog) {\n    log {\n        output file /data/access.log {\n            roll_size 20MiB\n            roll_keep 2\n        }\n    }\n}\n")
    _imp = "    import phvmlog\n" if _log_on else ""
    if any(row_get(r, 'via') == 'tunnel' for r in rows):
        # Tunnel domains: Cloudflare terminates HTTPS and talks plain HTTP to us. Keep its X-Forwarded-Proto
        # (private source ranges only) so WordPress knows it is on https. Direct domains are unaffected.
        parts.append("{\n    servers {\n        trusted_proxies static private_ranges\n    }\n}\n")
    pd = _panel_domain()
    if pd:
        parts.append(f"{pd} {{\n{_imp}    encode gzip\n    request_body {{\n        max_size 2GB\n    }}\n"
                     f"    reverse_proxy host.docker.internal:{PANEL_PORT} {{\n        flush_interval -1\n        transport http {{\n            read_timeout 3600s\n        }}\n    }}\n}}\n")
    for r in rows:
        addr = ('http://' + r['domain']) if row_get(r, 'via') == 'tunnel' else r['domain']
        if row_get(r, 'redirect_to'):
            parts.append(f"{addr} {{\n    redir https://{r['redirect_to']}{{uri}} permanent\n}}\n")
            continue
        speed = ''
        try:
            _row = _dk_row(r['vm_id'])
            if _row and _web_opt(_row).get('speed'):
                speed = ("    @static path_regexp static \\.(css|js|jpg|jpeg|png|gif|webp|avif|svg|ico|woff2?|ttf|mp4)$\n"
                         "    header @static Cache-Control \"public, max-age=2592000\"\n")
        except Exception:
            speed = ''
        hard = ''
        if gsv('web_harden', '1') != '0':
            hsts = '' if row_get(r, 'via') == 'tunnel' else '        Strict-Transport-Security "max-age=31536000"\n'
            hard = ("    header {\n        X-Content-Type-Options nosniff\n        X-Frame-Options SAMEORIGIN\n"
                    "        Referrer-Policy strict-origin-when-cross-origin\n" + hsts + "        -Server\n    }\n"
                    "    @badphp path_regexp badphp ^/wp-content/(uploads|upgrade|cache)/.*\\.(php|phtml|phar)$\n"
                    "    respond @badphp 403\n"
                    "    @xmlrpc path /xmlrpc.php\n    respond @xmlrpc 403\n")
        parts.append(
            f"{addr} {{\n{_imp}    encode zstd gzip\n    request_body {{\n        max_size {_maxbody(r['vm_id'])}\n    }}\n{speed}{hard}"
            f"    reverse_proxy {_cname(r['vm_id'])}:{_app_port(r['vm_id'])}\n}}\n")
    with open(conf / 'Caddyfile', 'w', encoding='utf-8') as f:     # in place: keeps the bind-mounted inode
        f.write('\n'.join(parts))
    return len(rows) + (1 if pd else 0)


def _caddy_sync():
    """Rewrite the Caddyfile from the DB and (start +) reload Caddy. Returns (ok, message)."""
    if not docker_available():
        return False, 'Docker is not available on this host.'
    n = _caddy_write()
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}', CADDY_NAME, timeout=10)
    exists = rc == 0
    running = exists and out.strip() == 'true'
    if exists and _panel_domain():
        # the panel itself is proxied by Caddy: it needs the host-gateway alias (older containers lack it)
        rc2, eh, _ = _docker('inspect', '-f', '{{json .HostConfig.ExtraHosts}}', CADDY_NAME, timeout=10)
        if rc2 == 0 and 'host.docker.internal' not in (eh or ''):
            _docker('rm', '-f', CADDY_NAME, timeout=60)
            exists = running = False
    if not running:
        if n == 0:
            return True, 'No domains yet.'
        _docker('network', 'create', WEB_NET, timeout=20)
        if exists:
            rc, _, err = _docker('start', CADDY_NAME, timeout=60)
        else:
            rc, _, err = _docker('run', '-d', '--name', CADDY_NAME, '--restart', 'unless-stopped', '--network', WEB_NET,
                                 '--label', 'phvm-caddy=1', '--add-host', 'host.docker.internal:host-gateway', '-p', '80:80', '-p', '443:443', '-p', '443:443/udp',
                                 '-v', f'{CADDY_DIR / "conf"}:/etc/caddy', '-v', f'{CADDY_DIR / "data"}:/data',
                                 '-v', f'{CADDY_DIR / "config"}:/config', 'caddy:2', timeout=300)
        if rc != 0:
            msg = (err or '').strip()[-240:]
            if 'address already in use' in msg or 'port is already allocated' in msg:
                msg = 'Port 80/443 is already used by another web server on this host (usually nginx from the old panel-domain setup). Stop it with: systemctl disable --now nginx — then press Save again so Caddy serves the panel and your websites together.'
            return False, msg or 'Could not start the proxy (Caddy).'
        return True, 'Proxy started.'
    rc, out, err = _docker('exec', CADDY_NAME, 'caddy', 'reload', '--config', '/etc/caddy/Caddyfile',
                           '--adapter', 'caddyfile', timeout=30)
    if rc != 0:
        return False, ((err or out).strip()[-240:] or 'Caddy rejected the configuration.')
    return True, 'Proxy reloaded.'


def complete_web_setup(vid):
    """Thread: create the WordPress + MariaDB containers for a new site."""
    try:
        v = _dk_row(vid)
        if _app_key(v):
            return _app_setup(vid)
        c, cdb, cnet = _web_names(vid)
        ram, cores = int(v['ram_mb']), max(1, int(v['cpu_cores'] or 1))
        db_mem = max(256, min(1024, ram // 4))
        wp_mem = max(256, ram - db_mem)
        db_pass, root_pass = secrets.token_urlsafe(18), secrets.token_urlsafe(18)
        d = _dk_dir(vid)
        d.mkdir(parents=True, exist_ok=True)
        dbd = WEB_DB_DIR / vid
        dbd.mkdir(parents=True, exist_ok=True)
        WEB_CFG_DIR.mkdir(parents=True, exist_ok=True)
        opt = _web_opt(v)
        if 'engine' not in opt:
            opt['engine'] = 'ols' if gsv('web_default_engine', 'apache') == 'ols' else 'apache'
        opt.update(db_name='wordpress', db_user='wordpress', db_pass=db_pass, db_root=root_pass)
        ini = WEB_CFG_DIR / f'{vid}.ini'
        ini.write_text(_web_ini_text(_web_settings(opt)))
        _dk_chown(str(d), _web_uid(opt), _web_uid(opt))
        vm.up(vid, 10, 'Preparing site files…')
        _docker('network', 'create', WEB_NET, timeout=20)
        _docker('network', 'create', cnet, timeout=20)
        vm.up(vid, 25, 'Downloading WordPress (the first site can take a few minutes)…')
        rc, out, err = _docker('pull', _web_wp_image(_web_settings(opt), opt), timeout=1800)
        if rc != 0:
            raise RuntimeError('WordPress image download failed: ' + (err or out).strip()[-200:])
        vm.up(vid, 50, 'Downloading the database image…')
        rc, out, err = _docker('pull', WEB_DB_IMAGE, timeout=1800)
        if rc != 0:
            raise RuntimeError('database image download failed: ' + (err or out).strip()[-200:])
        vm.up(vid, 70, 'Creating the site containers…')
        _docker('rm', '-f', c, timeout=60)
        _docker('rm', '-f', cdb, timeout=60)
        fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=80", (vid,), fetchone=True)
        host_port = int(fw['host_port']) if fw else None
        rc, out, err = _docker(
            'create', '--name', cdb, '--restart', 'unless-stopped', '--label', 'phvm=1', '--network', cnet,
            '--pids-limit', '256', '--security-opt', 'no-new-privileges',
            '--memory', f'{db_mem}m', '--memory-swap', f'{db_mem}m', '--cpus', str(cores),
            '-e', 'MARIADB_DATABASE=wordpress', '-e', 'MARIADB_USER=wordpress',
            '-e', f'MARIADB_PASSWORD={db_pass}', '-e', f'MARIADB_ROOT_PASSWORD={root_pass}',
            '-v', f'{dbd}:/var/lib/mysql', WEB_DB_IMAGE,
            '--innodb-buffer-pool-size=64M', '--max-connections=80', '--performance-schema=OFF', timeout=120)
        if rc != 0:
            raise RuntimeError('database container create failed: ' + (err or out).strip()[-300:])
        args = _web_wp_args(v, opt, host_port)
        rc, out, err = _docker(*args, timeout=120)
        if rc != 0:
            raise RuntimeError('WordPress container create failed: ' + (err or out).strip()[-300:])
        _docker('network', 'connect', cnet, c, timeout=20)
        if _web_engine(opt) == 'ols':
            vm.up(vid, 78, 'Turbo engine: downloading WordPress files…')
            _web_ols_prepare(vid, opt)
        vm.up(vid, 85, 'Starting the database and WordPress…')
        rc, out, err = _docker('start', cdb, timeout=60)
        if rc != 0:
            raise RuntimeError('database start failed: ' + (err or out).strip()[-300:])
        for _ in range(40):                                    # up to ~80 s for MariaDB to accept connections
            rc, _, _ = _docker('exec', cdb, 'healthcheck.sh', '--connect', '--innodb_initialized', timeout=10)
            if rc == 0:
                break
            time.sleep(2)
        rc, out, err = _docker('start', c, timeout=60)
        if rc != 0:
            raise RuntimeError('WordPress start failed: ' + (err or out).strip()[-300:])
        db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vid))
        vm.up(vid, 92, 'Installing WordPress and creating the admin login…')
        if _web_engine(opt) == 'ols':
            threading.Thread(target=lambda: _web_wp_cli(vid, 'plugin', 'install', 'litespeed-cache', '--activate', timeout=300), daemon=True).start()
        step = 'Ready — WordPress is installed, log in from the site page'
        try:
            _web_wp_install(vid, lambda m: None)
        except Exception as e:
            print(f'[web] auto-install failed for {vid}: {e}', flush=True)
            step = 'Ready — open your site to finish the WordPress setup (automatic install did not finish)'
        db_execute("UPDATE vm_instances SET status='running', creation_progress=100, creation_step=? WHERE vm_id=?", (step, vid))
    except Exception as e:
        print(f'[web] setup failed for {vid}: {e}', flush=True)
        db_execute("UPDATE vm_instances SET status='error', creation_step=? WHERE vm_id=?",
                   (f'Web hosting setup failed: {e}'[:300], vid))


# ---------- automatic WordPress install (admin login chosen by the panel, not by the visitor) ----------
WEB_CLI_IMAGE = 'wordpress:cli'


def _web_wp_defaults():
    u = re.sub(r'[^A-Za-z0-9_.-]', '', (gsv('web_wp_admin_user', 'phoenixcloud') or '')) or 'phoenixcloud'
    p = (gsv('web_wp_admin_pass', 'phoenixcloud') or '').strip() or 'phoenixcloud'
    return u[:60], p[:100]


def _web_wp_cli(vid, *args, timeout=300):
    """Run one WP-CLI command against a site (as the web user, on the site's private network)."""
    v = _dk_row(vid)
    opt = _web_opt(v)
    c, cdb, cnet = _web_names(vid)
    return _docker('run', '--rm', '--user', f'{_web_uid(opt)}:{_web_uid(opt)}', '--network', cnet, '--security-opt', 'no-new-privileges',
                   '--memory', '384m', '-v', f'{_dk_dir(vid)}:/var/www/html',
                   '-e', f'WORDPRESS_DB_HOST={cdb}:3306', '-e', 'WORDPRESS_DB_NAME=wordpress',
                   '-e', 'WORDPRESS_DB_USER=wordpress', '-e', f"WORDPRESS_DB_PASSWORD={opt.get('db_pass', '')}",
                   WEB_CLI_IMAGE, 'wp', *args, timeout=timeout)


def _web_wp_install(vid, log):
    """Install WordPress if needed and make sure the panel's admin account exists with the chosen password."""
    v = _dk_row(vid)
    user, pw = _web_wp_defaults()
    cfg = _dk_dir(vid) / 'wp-config.php'
    log('Waiting for WordPress to create its config…')
    for _ in range(45):
        if cfg.exists():
            break
        time.sleep(2)
    else:
        raise RuntimeError('WordPress did not finish starting — open the site once, then try again.')
    owner = db_execute("SELECT email FROM users WHERE id=?", (v['user_id'],), fetchone=True)
    email = (owner['email'] if owner and owner['email'] and '@' in owner['email'] else 'admin@example.com')
    last = ''
    for attempt in range(6):
        rc, out, err = _web_wp_cli(vid, 'core', 'is-installed')
        if rc == 0:
            log('WordPress is already installed — updating the admin login…')
            rc2, _, _ = _web_wp_cli(vid, 'user', 'get', user, '--field=ID')
            if rc2 == 0:
                rc, out, err = _web_wp_cli(vid, 'user', 'update', user, f'--user_pass={pw}')
            else:
                rc, out, err = _web_wp_cli(vid, 'user', 'create', user, email, '--role=administrator', f'--user_pass={pw}')
        else:
            log('Installing WordPress…')
            rc, out, err = _web_wp_cli(vid, 'core', 'install', '--url=http://localhost', f"--title={v['name']}",
                                       f'--admin_user={user}', f'--admin_password={pw}', f'--admin_email={email}', '--skip-email')
        if rc == 0:
            _web_save_opt(vid, wp_admin_user=user, wp_admin_pass=pw, wp_install_error='')
            log('Done.')
            return
        last = ((err or out) or '').strip()[-200:]
        time.sleep(5)
    _web_save_opt(vid, wp_install_error=last)
    raise RuntimeError('WordPress install failed: ' + last)



def _web_cleanup(vid):
    """Remove everything a web site owns besides the normal server data dir."""
    c, cdb, cnet = _web_names(vid)
    _docker('rm', '-f', c + '-pma', timeout=30)
    _docker('rm', '-f', c + '-cfq', timeout=30)
    _docker('rm', '-f', cdb, timeout=60)
    _docker('network', 'rm', cnet, timeout=20)
    for p in (WEB_DB_DIR / vid, WEB_CFG_DIR / f'{vid}.ini'):
        try:
            if p.is_dir():
                shutil.rmtree(p, ignore_errors=True)
            elif p.exists():
                p.unlink()
        except Exception:
            pass
    try:
        had = db_execute("SELECT 1 FROM web_domains WHERE vm_id=?", (vid,), fetchone=True)
        db_execute("DELETE FROM web_domains WHERE vm_id=?", (vid,))
        if had:
            threading.Thread(target=_caddy_sync, daemon=True).start()
    except Exception:
        pass


def _web_row(vm_id):
    v = _dk_row(vm_id)
    if not v or row_get(v, 'provision_kind') != 'web':
        return None
    return v


@app.route('/vm/<vm_id>/web')
@login_required
@vm_owner_or_admin
def web_panel(vm_id):
    v = _web_row(vm_id)
    if not v:
        return redirect(url_for('manage_vm', vm_id=vm_id, advanced=1))
    if v['status'] == 'creating' and int(v['creation_progress'] or 0) < 100:
        return redirect(url_for('vm_installing', vm_id=vm_id))
    if _app_key(v) == 'studio':
        return redirect(url_for('studio_page', vm_id=vm_id))
    if _app_key(v):
        return render_template('storage.html', app_key=_app_key(v), app_meta=_APPS[_app_key(v)], vm=v, default_via=('tunnel' if _web_tunnel() else 'direct'), tunnel_ready=_web_tunnel_ready(), server_ip=_web_server_host(), max_domains=_web_domain_limit(v),
                               free_base=(gsv('free_subdomain_base', '') or '').strip())
    return render_template('web.html', vm=v, default_via=('tunnel' if _web_tunnel() else 'direct'), tunnel_ready=_web_tunnel_ready(), cf_auto=_cf_ready(), server_ip=_web_server_host(), max_domains=_web_domain_limit(v))


def _web_dom_expiry(domain):
    g = db_execute("SELECT expires_at FROM web_domain_regs WHERE domain=?", (domain,), fetchone=True)
    if not g or not g['expires_at']:
        return None
    try:
        return {'date': g['expires_at'][:10], 'days': (datetime.strptime(g['expires_at'][:10], '%Y-%m-%d') - datetime.now()).days}
    except Exception:
        return None


@app.route('/vm/<vm_id>/web/state')
@login_required
@vm_owner_or_admin
def web_state(vm_id):
    v = _web_row(vm_id)
    if not v:
        return jsonify({'success': False, 'message': 'Not a web hosting site.'})
    c, cdb, _ = _web_names(vm_id)
    running, _pid = dk_status(vm_id)
    direct = _web_direct_url(v)
    domains = []
    for r in (db_execute("SELECT domain, redirect_to, via FROM web_domains WHERE vm_id=? ORDER BY id", (vm_id,), fetch=True) or []):
        via = 'tunnel' if row_get(r, 'via') == 'tunnel' else 'direct'
        ok, ips = _web_dns_check(r['domain'], via)
        domains.append({'domain': r['domain'], 'dns_ok': ok, 'ips': ips, 'url': 'https://' + r['domain'], 'via': via,
                        'redirect_to': row_get(r, 'redirect_to') or '', 'ssl': _web_ssl_info(r['domain']) if (ok and via == 'direct') else None,
                        'expires': _web_dom_expiry(r['domain'])})
    res = {'success': True, 'running': running, 'direct_url': direct, 'domains': domains,
           'server_ip': _web_server_host(), 'cpu': 0, 'mem_mb': 0,
           'mem_limit_mb': int(v['ram_mb'] or 0), 'disk_mb': _dk_disk_cached(vm_id),
           'disk_limit_mb': int((v['storage_gb'] or 0) * 1024)}
    if running:
        rc, out, _ = _docker('stats', '--no-stream', '--format', '{{json .}}', *((c,) if _app_key(v) else (c, cdb)), timeout=25)
        cpu, mem = 0.0, 0.0
        for line in (out or '').splitlines():
            try:
                j = json.loads(line)
                cpu += float((j.get('CPUPerc') or '0').strip('%') or 0)
                mem += _dk_to_mb((j.get('MemUsage') or '').split('/')[0])
            except Exception:
                pass
        cores = max(1, int(v['cpu_cores'] or 1))
        res['cpu'] = round(min(100.0, cpu / cores), 1)
        res['mem_mb'] = round(mem, 1)
    return jsonify(res)


@app.route('/vm/<vm_id>/web/power', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_power(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    action = (request.get_json(silent=True) or {}).get('action', '')
    c, cdb, _ = _web_names(vm_id)
    if action in ('start', 'restart') and _DK_OVER.get(vm_id):
        return _dk_json_err('Disk limit exceeded — delete some files (Files tab), then start the site again.')
    if action in ('start', 'restart') and _expired_block(vm_id):
        return _expired_block(vm_id)
    _stor = bool(_app_key(v))
    if action == 'start':
        steps = [('start', c)] if _stor else [('start', cdb), ('start', c)]
    elif action == 'stop':
        steps = [('stop', '-t', '30', c)] if _stor else [('stop', '-t', '30', c), ('stop', '-t', '30', cdb)]
    elif action == 'restart':
        steps = [('restart', '-t', '30', c)] if _stor else [('restart', '-t', '30', cdb), ('restart', '-t', '30', c)]
    elif action == 'kill':
        steps = [('kill', c)]
    else:
        return _dk_json_err('Unknown action.')
    msg, ok = '', True
    for st in steps:
        rc, out, err = _docker(*st, timeout=120)
        if rc != 0:
            ok, msg = False, (err or out).strip()[:300]
            break
    audit(session['user_id'], f'web_{action}', f'{vm_id} (web)')
    return jsonify({'success': ok, 'message': msg or 'OK'})


@app.route('/vm/<vm_id>/web/domains', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_domain_add(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    domain = _web_clean_domain((request.get_json(silent=True) or {}).get('domain'))
    if not _WEB_DOMAIN_RE.match(domain) or re.match(r'^\d+\.\d+\.\d+\.\d+$', domain):
        return _dk_json_err('Enter a valid domain such as example.com or www.example.com (no http://, no IP address).')
    if domain in ('localhost',) or domain.endswith(('.local', '.internal', '.localhost')):
        return _dk_json_err('That domain cannot be used.')
    if db_execute("SELECT 1 FROM web_domains WHERE domain=?", (domain,), fetchone=True):
        return _dk_json_err('That domain is already connected to a site.')
    n = db_execute("SELECT COUNT(*) AS n FROM web_domains WHERE vm_id=?", (vm_id,), fetchone=True)
    lim = _web_domain_limit(v)
    if n and int(n['n']) >= lim:
        return _dk_json_err(f'Your plan allows up to {lim} domains on this site.')
    via = (request.get_json(silent=True) or {}).get('via') or ('tunnel' if _web_tunnel() else 'direct')
    if via not in ('direct', 'tunnel'):
        return _dk_json_err('Choose how to connect the domain.')
    if via == 'tunnel' and not _web_tunnel_ready():
        return _dk_json_err('Cloudflare Tunnel is not set up on this server yet. Ask the admin to add the tunnel token in Admin → Settings, or connect with a public IPv4 instead.')
    db_execute("INSERT INTO web_domains (vm_id, domain, via) VALUES (?,?,?)", (vm_id, domain, via))
    ok, msg = _caddy_sync()
    if not ok:
        db_execute("DELETE FROM web_domains WHERE domain=?", (domain,))
        _caddy_write()
        return _dk_json_err(msg)
    _web_dns_cache.pop(domain, None)
    audit(session['user_id'], 'web_domain_add', f'{vm_id[:8]} {domain}')
    pointed, ips = _web_dns_check(domain, via)
    if via == 'tunnel':
        if _cf_ready():
            cok, cmsg = _cf_connect(domain, True)
            if cok:
                return jsonify({'success': True, 'dns_ok': True,
                                'message': 'Connected through your Cloudflare Tunnel. HTTPS works in about a minute — nothing else to do.'})
            return jsonify({'success': True, 'dns_ok': True,
                            'message': 'Connected here, but Cloudflare could not be updated automatically: ' + cmsg +
                                       ' You can add the Public hostname by hand (HTTP → localhost:80).'})
        return jsonify({'success': True, 'dns_ok': True,
                        'message': 'Connected. Now add this domain as a Public hostname in your Cloudflare Tunnel (HTTP → localhost:80).'})
    note = 'Connected. HTTPS is issued automatically once the domain points to this server.' if not pointed \
        else 'Connected. Your free SSL certificate is being issued — it takes about a minute.'
    return jsonify({'success': True, 'message': note, 'dns_ok': pointed})


# ---- Buy a domain inside the panel (Spaceship registrar API) and attach it to the site automatically ----
_SS_API = 'https://spaceship.dev/api/v1'


def _ss_ready():
    return (gsv('domain_shop_enabled', '0') == '1' and (gsv('spaceship_api_key', '') or '').strip()
            and (gsv('spaceship_api_secret', '') or '').strip() and (gsv('spaceship_contact_id', '') or '').strip())


def _ss_api(method, path, body=None):
    """Returns (ok, json_or_message, response_headers)."""
    req = urllib.request.Request(_SS_API + path, method=method,
                                 data=(json.dumps(body).encode() if body is not None else None),
                                 headers={'X-API-Key': (gsv('spaceship_api_key', '') or '').strip(),
                                          'X-API-Secret': (gsv('spaceship_api_secret', '') or '').strip(),
                                          'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read().decode() or '{}'
            try:
                return True, json.loads(raw), dict(r.headers)
            except Exception:
                return True, {}, dict(r.headers)
    except urllib.error.HTTPError as e:
        try:
            j = json.loads(e.read().decode() or '{}')
            msg = j.get('detail') or j.get('message') or j.get('error') or ''
        except Exception:
            msg = ''
        if e.code in (401, 403):
            msg = 'Spaceship rejected the API key or secret.'
        return False, (msg or f'Spaceship answered HTTP {e.code}.')[:240], {}
    except Exception as e:
        return False, 'Could not reach Spaceship: ' + str(e)[:120], {}


def _ss_wait(headers, tries=20):
    h = {k.lower(): v for k, v in (headers or {}).items()}
    op = h.get('spaceship-async-operationid')
    if not op:
        return True, ''
    for _ in range(tries):
        time.sleep(3)
        ok, j, _h = _ss_api('GET', '/async-operations/' + urllib.parse.quote(op))
        if not ok:
            return False, j
        st = (j.get('status') or '').lower()
        if st == 'success':
            return True, ''
        if st == 'failed':
            return False, 'The registrar could not complete the registration.'
    return True, 'pending'


