@app.route('/vm/<vm_id>/web/buy/search', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_buy_search(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not _ss_ready():
        return _dk_json_err('Buying domains is not enabled on this server.')
    q = _web_clean_domain((request.get_json(silent=True) or {}).get('name'))
    if not q:
        return _dk_json_err('Type a name, for example mybrand or mybrand.com.')
    if '.' in q:
        names = [q]
    else:
        tlds = [t.strip().lower().lstrip('.') for t in (gsv('domain_tlds', 'com,net,org,xyz,online,site') or '').split(',') if t.strip()][:8]
        names = [q + '.' + t for t in tlds]
    names = [n for n in names if _WEB_DOMAIN_RE.match(n)]
    if not names:
        return _dk_json_err('That name cannot be used.')

    def chk(n):
        ok, j, _ = _ss_api('GET', '/domains/' + urllib.parse.quote(n) + '/available')
        if not ok:
            return {'domain': n, 'available': False, 'error': j}
        av = (j.get('result') or '').lower() == 'available' and not j.get('premiumPricing')
        return {'domain': n, 'available': av}
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=4) as ex:
        res = list(ex.map(chk, names))
    if res and all(r.get('error') for r in res):
        return _dk_json_err(res[0]['error'])
    return jsonify({'success': True, 'results': res, 'price': gsv('domain_price_text', '') or ''})


# ---- Stripe Checkout for domain orders (no extra library: plain HTTPS + signature check) ----
def _stripe_amount():
    try:
        return max(0.0, float(gsv('domain_price_amount', '') or 0))
    except Exception:
        return 0.0


def _stripe_ready():
    return bool((gsv('stripe_secret_key', '') or '').strip()) and _stripe_amount() > 0 \
        and bool((gsv('stripe_webhook_secret', '') or '').strip())


def _stripe_keys_ok():
    return bool((gsv('stripe_secret_key', '') or '').strip()) and bool((gsv('stripe_webhook_secret', '') or '').strip())


def _stripe_session(oid, title, amount, return_url, mtype):
    cur = (gsv('stripe_currency', 'usd') or 'usd').strip().lower()[:3]
    form = {
        'mode': 'payment',
        'success_url': return_url + '?paid=1',
        'cancel_url': return_url + '?paid=0',
        'client_reference_id': str(oid),
        'metadata[order_id]': str(oid),
        'metadata[type]': mtype,
        'line_items[0][quantity]': '1',
        'line_items[0][price_data][currency]': cur,
        'line_items[0][price_data][unit_amount]': str(int(round(float(amount) * 100))),
        'line_items[0][price_data][product_data][name]': title[:120],
    }
    req = urllib.request.Request('https://api.stripe.com/v1/checkout/sessions', method='POST',
                                 data=urllib.parse.urlencode(form).encode(),
                                 headers={'Authorization': 'Bearer ' + (gsv('stripe_secret_key', '') or '').strip(),
                                          'Content-Type': 'application/x-www-form-urlencoded'})
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            j = json.loads(r.read().decode() or '{}')
    except urllib.error.HTTPError as e:
        try:
            msg = (json.loads(e.read().decode() or '{}').get('error') or {}).get('message') or ''
        except Exception:
            msg = ''
        return False, 'Stripe: ' + (msg or f'HTTP {e.code}')[:200]
    except Exception as e:
        return False, 'Could not reach Stripe: ' + str(e)[:120]
    if not j.get('url'):
        return False, 'Stripe did not return a payment page.'
    return True, j['url']


def _stripe_checkout(oid, domain, vm_id, kind='register'):
    return _stripe_session(oid, (f'Renew {domain} (1 year)' if kind == 'renew' else f'Domain {domain} (1 year)'),
                           _stripe_amount(), f'{request.host_url.rstrip("/")}/vm/{vm_id}/web', 'domain')


def _stripe_verify(payload, header, secret, tolerance=300):
    try:
        parts = dict(p.split('=', 1) for p in header.split(',') if '=' in p)
        ts = int(parts.get('t', '0'))
        sigs = [p.split('=', 1)[1] for p in header.split(',') if p.startswith('v1=')]
    except Exception:
        return False
    if abs(time.time() - ts) > tolerance:
        return False
    exp = hmac.new(secret.encode(), f'{ts}.'.encode() + payload, hashlib.sha256).hexdigest()
    return any(hmac.compare_digest(exp, x) for x in sigs)


def _stripe_fulfil_bg(oid):
    o = db_execute("SELECT * FROM web_domain_orders WHERE id=?", (oid,), fetchone=True)
    if not o:
        return
    try:
        ok, msg = _domain_fulfil(o)
    except Exception as e:
        ok, msg = False, 'Error: ' + str(e)[:150]
    db_execute("UPDATE web_domain_orders SET status=?, note=? WHERE id=?", ('registered' if ok else 'paid_failed', msg[:200], oid))
    if not ok:
        for a in (db_execute("SELECT id FROM users WHERE role='admin'", fetch=True) or []):
            _admin_alert(f"⚠️ Paid domain {o['domain']} failed: {msg[:150]}")
            add_notification(a['id'], 'Paid domain needs attention',
                             f"{o['domain']} was paid by card but could not be registered: {msg[:150]}. Fix it, then Approve it in Domain orders (or refund in Stripe).", 'danger')


@app.route('/api/stripe/webhook', methods=['POST'])
def stripe_webhook():
    secret = (gsv('stripe_webhook_secret', '') or '').strip()
    payload = request.get_data()
    if not secret or not _stripe_verify(payload, request.headers.get('Stripe-Signature', ''), secret):
        return 'bad signature', 400
    try:
        ev = json.loads(payload.decode())
    except Exception:
        return 'bad json', 400
    if ev.get('type') in ('checkout.session.completed', 'checkout.session.async_payment_succeeded'):
        obj = (ev.get('data') or {}).get('object') or {}
        if obj.get('payment_status') == 'paid':
            try:
                oid = int((obj.get('metadata') or {}).get('order_id') or obj.get('client_reference_id') or 0)
            except Exception:
                oid = 0
            # pending -> paid exactly once, so a repeated webhook never registers twice
            if (obj.get('metadata') or {}).get('type') == 'topup':
                if oid and db_execute("UPDATE wallet_topups SET status='paid' WHERE id=? AND status='pending'", (oid,), rowcount=True):
                    _topup_done(oid)
            elif (obj.get('metadata') or {}).get('type') == 'plan':
                if oid and db_execute("UPDATE web_plan_orders SET status='paid', note='paid by card' WHERE id=? AND status='pending'",
                                      (oid,), rowcount=True):
                    threading.Thread(target=_plan_fulfil_bg, args=(oid,), daemon=True).start()
            elif oid and db_execute("UPDATE web_domain_orders SET status='paid', note='paid by card' WHERE id=? AND status='pending'",
                                    (oid,), rowcount=True):
                threading.Thread(target=_stripe_fulfil_bg, args=(oid,), daemon=True).start()
    return 'ok', 200


# ---- Coupons ----
def _coupon_get(code):
    code = (code or '').strip().upper()[:32]
    if not code:
        return None, None
    c = db_execute("SELECT * FROM coupons WHERE code=? AND active=1", (code,), fetchone=True)
    if not c:
        return None, 'That coupon code is not valid.'
    if row_get(c, 'expires') and str(c['expires'])[:10] < datetime.now().strftime('%Y-%m-%d'):
        return None, 'That coupon has expired.'
    if int(c['max_uses'] or 0) and int(c['used'] or 0) >= int(c['max_uses']):
        return None, 'That coupon has been used up.'
    return c, None


def _coupon_price(price, c):
    price = float(price or 0)
    if not c:
        return price
    if int(c['percent'] or 0):
        price = price * (100 - min(100, int(c['percent']))) / 100.0
    price -= float(c['amount_off'] or 0)
    return round(max(0.0, price), 2)


def _coupon_use(c):
    """Atomically reserve one use. False when it just ran out."""
    return bool(db_execute("UPDATE coupons SET used=used+1 WHERE code=? AND (max_uses=0 OR used<max_uses)", (c['code'],), rowcount=True))


# ---- Revenue dashboard ----
@app.route('/admin/revenue')
@login_required
@admin_required
def admin_revenue():
    month = datetime.now().strftime('%Y-%m')
    plan_rows = db_execute("""SELECT o.created_at AS t, o.amount AS amt, p.name AS what FROM web_plan_orders o
                              LEFT JOIN web_plans p ON p.id=o.plan_id WHERE o.status='done' AND COALESCE(o.amount,0)>0""", fetch=True) or []
    dom_rows = db_execute("SELECT created_at AS t, price AS amt, 'Domains' AS what FROM web_domain_orders WHERE status='registered' AND COALESCE(price,0)>0", fetch=True) or []
    rows = [(str(r['t'])[:10], float(r['amt']), r['what'] or 'Plan') for r in list(plan_rows) + list(dom_rows)]
    total = sum(r[1] for r in rows)
    this_month = sum(r[1] for r in rows if r[0][:7] == month)
    by_what = {}
    for d, a, w in rows:
        e = by_what.setdefault(w, [0, 0.0])
        e[0] += 1
        e[1] += a
    today = datetime.now().date()
    days = []
    for i in range(29, -1, -1):
        d = (today - timedelta(days=i)).strftime('%Y-%m-%d')
        days.append({'day': d, 'amt': round(sum(r[1] for r in rows if r[0] == d), 2)})
    pend = (db_execute("SELECT COUNT(*) AS n FROM web_plan_orders WHERE status IN ('pending','paid_failed')", fetchone=True)['n']
            + db_execute("SELECT COUNT(*) AS n FROM web_domain_orders WHERE status IN ('pending','paid_failed')", fetchone=True)['n'])
    stats = {
        'new_users': db_execute("SELECT COUNT(*) AS n FROM users WHERE strftime('%Y-%m', created_at)=?", (month,), fetchone=True)['n'] if _col_exists('users', 'created_at') else None,
        'sites': db_execute("SELECT COUNT(*) AS n FROM vm_instances WHERE provision_kind='web'", fetchone=True)['n'],
        'open_tickets': db_execute("SELECT COUNT(*) AS n FROM tickets WHERE status='open'", fetchone=True)['n'],
        'pending': pend, 'orders': len(rows),
    }
    return render_template('admin/revenue.html', total=total, this_month=this_month, by_what=sorted(by_what.items(), key=lambda x: -x[1][1]),
                           days=days, stats=stats, cur=(gsv('stripe_currency', 'usd') or 'usd').upper(), mx=max([d['amt'] for d in days] + [1]))


def _col_exists(table, col):
    try:
        return any(r['name'] == col for r in (db_execute(f"PRAGMA table_info({table})", fetch=True) or []))
    except Exception:
        return False


# ---- Support tickets ----
def _ticket_access(tid):
    t = db_execute("SELECT * FROM tickets WHERE id=?", (tid,), fetchone=True)
    if not t or (t['user_id'] != session['user_id'] and session.get('role') != 'admin'):
        return None
    return t


@app.route('/support', methods=['GET', 'POST'])
@login_required
def support_page():
    uid = session['user_id']
    if request.method == 'POST':
        subj = (request.form.get('subject') or '').strip()[:120]
        body = (request.form.get('body') or '').strip()[:5000]
        if not subj or not body:
            flash('Write a subject and a message.', 'danger')
        elif not rate_limit(f'ticket:{uid}', limit=5, window=3600):
            flash('Too many tickets in a short time. Please wait a bit.', 'danger')
        else:
            tid = db_execute("INSERT INTO tickets (user_id, subject) VALUES (?,?)", (uid, subj), lastrowid=True)
            db_execute("INSERT INTO ticket_msgs (ticket_id, user_id, is_admin, body) VALUES (?,?,0,?)", (tid, uid, body))
            for a in (db_execute("SELECT id FROM users WHERE role='admin' AND is_active=1", fetch=True) or []):
                notify_user(a['id'], 'New support ticket', f"#{tid} {subj}: {body[:200]}", 'info')
            _admin_alert(f'🎫 New ticket #{tid}: {subj}')
            if gsv('ai_ticket', '0') == '1' and app.jinja_env.globals['ai_enabled']():
                threading.Thread(target=_ai_ticket_reply, args=(tid, uid, subj, body), daemon=True).start()
            flash('Ticket sent. We will reply here.', 'success')
            return redirect(url_for('support_ticket', tid=tid))
    rows = db_execute("SELECT * FROM tickets WHERE user_id=? ORDER BY updated_at DESC", (uid,), fetch=True) or []
    return render_template('support.html', tickets=rows)


@app.route('/support/<int:tid>', methods=['GET', 'POST'])
@login_required
def support_ticket(tid):
    t = _ticket_access(tid)
    if not t:
        flash('Ticket not found.', 'danger')
        return redirect(url_for('support_page'))
    is_admin = session.get('role') == 'admin'
    if request.method == 'POST':
        act = request.form.get('action', 'reply')
        if act == 'close':
            db_execute("UPDATE tickets SET status='closed', updated_at=CURRENT_TIMESTAMP WHERE id=?", (tid,))
            flash('Ticket closed.', 'success')
        else:
            body = (request.form.get('body') or '').strip()[:5000]
            if body:
                db_execute("INSERT INTO ticket_msgs (ticket_id, user_id, is_admin, body) VALUES (?,?,?,?)", (tid, session['user_id'], 1 if is_admin else 0, body))
                db_execute("UPDATE tickets SET status='open', updated_at=CURRENT_TIMESTAMP WHERE id=?", (tid,))
                if is_admin and t['user_id'] != session['user_id']:
                    notify_user(t['user_id'], f"Reply to your ticket #{tid}", f"{t['subject']}: {body[:300]}", 'info')
                elif not is_admin:
                    for a in (db_execute("SELECT id FROM users WHERE role='admin' AND is_active=1", fetch=True) or []):
                        notify_user(a['id'], f'Ticket #{tid} updated', f"{t['subject']}: {body[:200]}", 'info')
        return redirect(url_for('support_ticket', tid=tid))
    msgs = db_execute("SELECT m.*, u.username FROM ticket_msgs m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? ORDER BY m.id", (tid,), fetch=True) or []
    owner = db_execute("SELECT username FROM users WHERE id=?", (t['user_id'],), fetchone=True)
    return render_template('support_ticket.html', t=t, msgs=msgs, owner=owner['username'] if owner else '—', is_admin=is_admin)


