def referral_page():
    code = _referral_code(session['user_id'])
    n = db_execute("SELECT COUNT(*) AS n FROM users WHERE referred_by=?", (session['user_id'],), fetchone=True)['n']
    paid = db_execute("SELECT COUNT(*) AS n FROM users WHERE referred_by=? AND referral_paid=1", (session['user_id'],), fetchone=True)['n']
    try:
        bonus = float(gsv('referral_bonus_volts', '0') or 0)
    except Exception:
        bonus = 0
    return render_template('referral.html', link=request.host_url.rstrip('/') + '/register?ref=' + code, code=code, joined=n, paid=paid, bonus=bonus)


# ======================= Expired servers: stop, then (optionally) delete =======================
def _expired_block(vid):
    v = db_execute("SELECT expiry_date, user_id FROM vm_instances WHERE vm_id=?", (vid,), fetchone=True)
    if not v or not row_get(v, 'expiry_date') or session.get('role') == 'admin':
        return None
    try:
        if datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S') < datetime.now():
            return _dk_json_err('This server has expired. Renew it to start it again.')
    except Exception:
        pass
    return None


def _expiry_enforce_tick():
    try:
        grace = int(float(gsv('expired_delete_days', '0') or 0))
    except Exception:
        grace = 0
    now = datetime.now()
    for v in (db_execute("SELECT vm_id, name, user_id, expiry_date, provision_kind FROM vm_instances WHERE runtime='docker' AND expiry_date IS NOT NULL", fetch=True) or []):
        try:
            exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        if exp >= now:
            continue
        vid = v['vm_id']
        try:
            if dk_status(vid)[0]:
                dk_stop(vid)
                notify_user(v['user_id'], 'Server stopped (expired)', f"\"{v['name']}\" expired and was stopped." +
                            (f" It will be deleted {grace} day(s) after expiry unless you renew it." if grace > 0 else ' Renew it to start it again.'), 'danger')
        except Exception as e:
            print('[expiry] stop failed', vid, e, flush=True)
        if grace > 0 and (now - exp).days >= grace:
            try:
                for r in (db_execute("SELECT domain FROM web_domains WHERE vm_id=?", (vid,), fetch=True) or []):
                    _web_dns_cache.pop(r['domain'], None)
                _dk_cleanup(vid)
                db_execute("DELETE FROM web_domains WHERE vm_id=?", (vid,))
                db_execute("DELETE FROM port_forwards WHERE vm_id=?", (vid,))
                db_execute("DELETE FROM vm_instances WHERE vm_id=?", (vid,))
                audit(None, 'auto_delete_expired', f"{v['name']} ({vid[:8]})")
                notify_user(v['user_id'], 'Server deleted', f"\"{v['name']}\" was deleted because it stayed expired for {grace} days.", 'danger')
                if v['provision_kind'] == 'web':
                    _caddy_sync()
            except Exception as e:
                print('[expiry] delete failed', vid, e, flush=True)


def _expiry_enforce_loop():
    time.sleep(180)
    while True:
        try:
            _expiry_enforce_tick()
        except Exception as e:
            print('[expiry] tick failed:', e, flush=True)
        time.sleep(3600)


# ======================= Public status page =======================
def _probe_url(url):
    t0 = time.time()
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'PHvm-status'})
        with urllib.request.urlopen(req, timeout=8) as r:
            return r.status < 500, int((time.time() - t0) * 1000)
    except urllib.error.HTTPError as e:
        return e.code < 500, int((time.time() - t0) * 1000)
    except Exception:
        return False, 0


def _status_tick():
    ts = int(time.time())
    for c in (db_execute("SELECT * FROM status_components", fetch=True) or []):
        ok, ms = _probe_url(c['url'])
        prev = db_execute("SELECT ok FROM web_uptime WHERE vm_id=? ORDER BY ts DESC LIMIT 1", (f"status:{c['id']}",), fetchone=True)
        db_execute("INSERT INTO web_uptime (vm_id, ts, ok, ms) VALUES (?,?,?,?)", (f"status:{c['id']}", ts, 1 if ok else 0, ms))
        _status_incident(c, ok, prev, ts)
    db_execute("DELETE FROM web_uptime WHERE vm_id LIKE 'status:%' AND ts < ?", (ts - 31 * 86400,))
    db_execute("DELETE FROM status_incidents WHERE started < ?", (ts - 90 * 86400,))


def _status_loop():
    time.sleep(100)
    while True:
        try:
            if (gsv('status_enabled', 'false') or 'false').lower() in ('1', 'true', 'yes'):
                _status_tick()
        except Exception as e:
            print('[status] tick failed:', e, flush=True)
        time.sleep(120)


def _status_summary(key, days):
    since = int(time.time()) - days * 86400
    r = db_execute("SELECT COUNT(*) AS n, COALESCE(SUM(ok),0) AS up FROM web_uptime WHERE vm_id=? AND ts>=?", (key, since), fetchone=True)
    last = db_execute("SELECT ok FROM web_uptime WHERE vm_id=? ORDER BY ts DESC LIMIT 1", (key,), fetchone=True)
    n = int(r['n']) if r else 0
    return {'pct': round(100.0 * int(r['up']) / n, 2) if n else None, 'now': (bool(last['ok']) if last else None)}


def _status_incident(c, ok, prev, ts):
    """Open an incident after two failed checks in a row, close it on the first success; tell subscribers + admin."""
    open_i = db_execute("SELECT * FROM status_incidents WHERE comp_id=? AND ended IS NULL", (c['id'],), fetchone=True)
    if not ok and prev is not None and not prev['ok'] and not open_i:
        db_execute("INSERT INTO status_incidents (comp_id, started) VALUES (?,?)", (c['id'], ts))
        _admin_alert(f"🔴 Status: {c['name']} is DOWN.")
        _status_mail_subs_bg(f"[Status] {c['name']} is down", f"We detected a problem with {c['name']}. We are looking into it.")
    elif ok and open_i:
        db_execute("UPDATE status_incidents SET ended=? WHERE id=?", (ts, open_i['id']))
        mins = max(1, int((ts - open_i['started']) / 60))
        _admin_alert(f"🟢 Status: {c['name']} is back after {mins} min.")
        _status_mail_subs_bg(f"[Status] {c['name']} is back", f"{c['name']} is working again. It was down for about {mins} minute(s).")


def _status_mail_subs_bg(subject, body):
    base = (gsv('panel_domain', '') or '').strip()
    def work():
        for r in (db_execute("SELECT email, token FROM status_subs WHERE confirmed=1", fetch=True) or []):
            try:
                link = (f"https://{base}" if base else '') + f"/status/unsub/{r['token']}"
                send_email([r['email']], subject, body + f"\n\nStop these emails: {link}")
            except Exception:
                pass
    threading.Thread(target=work, daemon=True).start()


