# ======================= Admin security =======================
def _ip_allowed(ip, spec):
    items = [x.strip() for x in (spec or '').replace('\n', ',').split(',') if x.strip()]
    if not items:
        return True
    try:
        a = ipaddress.ip_address(ip)
    except ValueError:
        return False
    for it in items:
        try:
            if '/' in it:
                if a in ipaddress.ip_network(it, strict=False):
                    return True
            elif a == ipaddress.ip_address(it):
                return True
        except ValueError:
            continue
    return False


@app.before_request
def admin_security_guard():
    path = request.path
    if not (path.startswith('/admin') or path.startswith('/api/v1/admin')):
        return None
    spec = gsv('admin_ip_allow', '') or ''
    if spec.strip() and not _ip_allowed(_client_ip(), spec):
        return ('Admin area is limited to approved IP addresses.', 403)
    if (session.get('role') == 'admin' and (gsv('require_admin_2fa', 'false') or 'false').lower() in ('1', 'true', 'yes')
            and not path.startswith('/admin/static')):
        u = db_execute("SELECT totp_enabled FROM users WHERE id=?", (session.get('user_id'),), fetchone=True)
        if u and not row_get(u, 'totp_enabled'):
            flash('Admins must turn on two-factor authentication (2FA) first.', 'warning')
            return redirect(url_for('twofa_setup'))
    return None


