# ======================= Panel update (zip upload / URL) =======================
PANEL_VERSION = 'v21.115'
_UPDATE_KEEP = ('phvm.db', 'phvm.db-wal', 'phvm.db-shm', '.secret_key', 'ADMIN_PASSWORD.txt')
_UPDATE_SKIP_DIRS = ('venv', 'vm_instances', 'backups', '__pycache__', '.git')


def _update_backup_dir():
    d = BASE_DIR / 'backups'
    d.mkdir(exist_ok=True)
    return d


def _update_code_files():
    out = []
    for root, dirs, files in os.walk(BASE_DIR):
        rel = os.path.relpath(root, BASE_DIR)
        top = rel.split(os.sep)[0]
        if top in _UPDATE_SKIP_DIRS or rel.startswith(os.path.join('static', 'uploads')):
            dirs[:] = []
            continue
        for f in files:
            if f in _UPDATE_KEEP or f.endswith(('.db', '.pyc')):
                continue
            out.append(os.path.join(rel, f) if rel != '.' else f)
    return out


def _apply_update(zip_path):
    """Returns (ok, message). Validates, backs up code + database, extracts, then the caller restarts."""
    import zipfile, ast
    try:
        z = zipfile.ZipFile(zip_path)
    except Exception:
        return False, 'That file is not a valid zip.'
    with z:
        names = [n for n in z.namelist() if not n.endswith('/')]
        if not names or len(names) > 4000:
            return False, 'The zip looks empty or too large.'
        roots = {n.split('/')[0] for n in names}
        prefix = ''
        if 'phvm.py' not in names:
            if len(roots) == 1 and (list(roots)[0] + '/phvm.py') in names:
                prefix = list(roots)[0] + '/'
            else:
                return False, 'phvm.py was not found in the zip.'
        plan = []
        for n in names:
            rel = n[len(prefix):] if n.startswith(prefix) else n
            if not rel or rel.startswith('/') or '..' in rel.split('/') or ':' in rel.split('/')[0]:
                return False, 'Unsafe path in zip: ' + n
            if rel.split('/')[0] in _UPDATE_SKIP_DIRS or os.path.basename(rel) in _UPDATE_KEEP or rel.endswith(('.db', '.pyc')):
                continue
            plan.append((n, rel))
        try:
            ast.parse(z.read(prefix + 'phvm.py').decode('utf-8'))
        except Exception as e:
            return False, 'The new phvm.py has a syntax error: ' + str(e)[:120]
        ts = datetime.now().strftime('%Y%m%d-%H%M%S')
        bd = _update_backup_dir()
        with zipfile.ZipFile(bd / f'code-{ts}.zip', 'w', zipfile.ZIP_DEFLATED) as bz:
            for f in _update_code_files():
                bz.write(BASE_DIR / f, f)
        try:
            src = sqlite3.connect(DATABASE)
            dst = sqlite3.connect(str(bd / f'phvm-before-update-{ts}.db'))
            src.backup(dst)
            dst.close()
            src.close()
        except Exception as e:
            return False, 'Could not back up the database first: ' + str(e)[:120]
        base = os.path.realpath(BASE_DIR)
        for n, rel in plan:
            target = os.path.realpath(os.path.join(base, rel))
            if not target.startswith(base + os.sep):
                return False, 'Unsafe path in zip: ' + n
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with z.open(n) as fi, open(target, 'wb') as fo:
                shutil.copyfileobj(fi, fo)
        for sh in ('install.sh', 'restart.sh', 'setup_https.sh'):
            try:
                os.chmod(BASE_DIR / sh, 0o755)
            except Exception:
                pass
    return True, f'Updated {len(plan)} files. A backup is in backups/code-{ts}.zip.'


def _restart_panel_soon():
    def work():
        time.sleep(2)
        try:
            for svc in ('phvm', 'phvm-panel'):
                if subprocess.run(['systemctl', 'is-active', '--quiet', svc], timeout=10).returncode == 0:
                    subprocess.Popen(['systemctl', 'restart', svc])
                    return
        except Exception:
            pass
        os.execv(sys.executable, [sys.executable] + sys.argv)
    threading.Thread(target=work, daemon=True).start()


@app.route('/admin/update', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_update():
    bd = _update_backup_dir()
    if request.method == 'POST':
        act = request.form.get('action')
        tmp = Path(tempfile.gettempdir()) / f'phvm-update-{secrets.token_hex(5)}.zip'
        try:
            if act == 'upload':
                f = request.files.get('zip')
                if not f or not f.filename.lower().endswith('.zip'):
                    flash('Choose a .zip file.', 'danger')
                    return redirect(url_for('admin_update'))
                f.save(str(tmp))
            elif act == 'url':
                url = (request.form.get('url') or gsv('update_url', '') or '').strip()
                if not re.match(r'^https://[^\s]+\.zip(\?[^\s]*)?$', url):
                    flash('Enter an https:// address that ends in .zip', 'danger')
                    return redirect(url_for('admin_update'))
                req = urllib.request.Request(url, headers={'User-Agent': _HTTP_UA})
                with urllib.request.urlopen(req, timeout=60) as r, open(tmp, 'wb') as fo:
                    n = 0
                    while True:
                        chunk = r.read(1 << 20)
                        if not chunk:
                            break
                        n += len(chunk)
                        if n > 200 * 1024 * 1024:
                            raise RuntimeError('The download is larger than 200 MB.')
                        fo.write(chunk)
            elif act == 'rollback':
                olds = sorted(bd.glob('code-*.zip'))
                if not olds:
                    flash('No code backup to go back to.', 'danger')
                    return redirect(url_for('admin_update'))
                shutil.copy(olds[-1], tmp)
            else:
                return redirect(url_for('admin_update'))
            ok, msg = _apply_update(str(tmp))
        except Exception as e:
            ok, msg = False, 'Update failed: ' + str(e)[:160]
        finally:
            tmp.unlink(missing_ok=True)
        audit(session['user_id'], 'panel_update', f'{act}: {ok} {msg[:120]}')
        if ok:
            flash(msg + ' The panel restarts in a few seconds — refresh the page after a moment (Ctrl+F5).', 'success')
            _restart_panel_soon()
        else:
            flash(msg, 'danger')
        return redirect(url_for('admin_update'))
    backups = sorted([f.name for f in bd.glob('code-*.zip')], reverse=True)[:10]
    return render_template('admin/update.html', version=PANEL_VERSION, backups=backups, update_url=gsv('update_url', ''))


# ======================= Admin alerts (Discord / Telegram) =======================
def _admin_alert(text):
    """Best effort, background. Sends to the admin's Discord webhook and/or Telegram chat."""
    def work():
        hook = (gsv('admin_discord_webhook', '') or '').strip()
        if hook and _RE_WEBHOOK.match(hook):
            try:
                _dk_send_webhook(hook, text)
            except Exception as e:
                print('[alert] discord failed:', e, flush=True)
        tok, chat = (gsv('telegram_bot_token', '') or '').strip(), (gsv('telegram_chat_id', '') or '').strip()
        if tok and chat and re.match(r'^\d+:[A-Za-z0-9_-]{20,}$', tok):
            try:
                req = urllib.request.Request(f'https://api.telegram.org/bot{tok}/sendMessage', method='POST',
                                             data=urllib.parse.urlencode({'chat_id': chat, 'text': text[:3500]}).encode())
                urllib.request.urlopen(req, timeout=10).read()
            except Exception as e:
                print('[alert] telegram failed:', str(e)[:80], flush=True)
    if (gsv('admin_discord_webhook', '') or gsv('telegram_bot_token', '')):
        threading.Thread(target=work, daemon=True).start()


