# ======================= WordPress malware scan =======================
_SCAN_PATTERNS = [
    (re.compile(rb'eval\s*\(\s*(?:base64_decode|gzinflate|str_rot13|gzuncompress)\s*\(', re.I), 'obfuscated eval()'),
    (re.compile(rb'(?:shell_exec|passthru|system|proc_open|popen)\s*\(\s*\$_(?:GET|POST|REQUEST|COOKIE)', re.I), 'runs commands from user input'),
    (re.compile(rb'assert\s*\(\s*\$_(?:GET|POST|REQUEST)', re.I), 'assert() backdoor'),
    (re.compile(rb'preg_replace\s*\(\s*[\'"]/.*/e[\'"]', re.I), 'preg_replace /e backdoor'),
    (re.compile(rb'(?:c99|r57|wso|b374k|FilesMan|WebShell)', re.I), 'known web-shell name'),
]


def _web_scan_site(vid, max_files=20000):
    base = _dk_dir(vid)
    findings = []
    n = 0
    for sub in ('wp-content', 'wp-includes', 'wp-admin'):
        for root, dirs, files in os.walk(base / sub):
            in_uploads = os.sep + 'uploads' in root.replace(str(base), '')
            for f in files:
                n += 1
                if n > max_files:
                    return findings, n
                path = os.path.join(root, f)
                rel = os.path.relpath(path, base)
                low = f.lower()
                if in_uploads and low.endswith(('.php', '.phtml', '.php5', '.phar')):
                    findings.append({'file': rel, 'why': 'PHP file inside uploads (should only hold media)'})
                    continue
                if not low.endswith(('.php', '.phtml', '.php5', '.js')):
                    continue
                try:
                    if os.path.getsize(path) > 2_000_000:
                        continue
                    with open(path, 'rb') as fh:
                        data = fh.read()
                except Exception:
                    continue
                for rx, why in _SCAN_PATTERNS:
                    if rx.search(data):
                        findings.append({'file': rel, 'why': why})
                        break
    return findings, n


@app.route('/vm/<vm_id>/web/scan', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_scan(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not rate_limit(f'scan:{vm_id}', limit=3, window=600):
        return _dk_json_err('Scan was just run. Wait a few minutes.')
    findings, n = _web_scan_site(vm_id)
    core = ''
    if dk_status(vm_id)[0]:
        rc, out, err = _web_wp_cli(vm_id, 'core', 'verify-checksums', timeout=120)
        bad = [l.strip() for l in (err or '').splitlines() if 'File doesn' in l or 'File should not exist' in l]
        for l in bad[:30]:
            findings.append({'file': l.split(':', 1)[-1].strip()[:150], 'why': 'WordPress core file changed or unexpected'})
        core = 'WordPress core files match the official checksums.' if rc == 0 and not bad else ''
    return jsonify({'success': True, 'scanned': n, 'findings': findings[:200], 'core_ok': bool(core), 'message': core})


def _web_scan_loop():
    time.sleep(600)
    while True:
        try:
            for v in (db_execute("SELECT vm_id, name, user_id FROM vm_instances WHERE provision_kind='web' AND runtime='docker'", fetch=True) or []):
                key = 'scanned:' + v['vm_id']
                if time.time() - float(gsv(key, '0') or 0) < 6.5 * 86400:
                    continue
                _set_setting(key, str(time.time()))
                findings, _ = _web_scan_site(v['vm_id'])
                if findings:
                    notify_user(v['user_id'], 'Security scan: suspicious files',
                                f"The weekly scan of \"{v['name']}\" found {len(findings)} suspicious file(s), for example {findings[0]['file']}. Open the site → Settings → Security scan.", 'danger')
                    _admin_alert(f"🛡 Scan: {v['name']} has {len(findings)} suspicious file(s).")
        except Exception as e:
            print('[scan] loop failed:', e, flush=True)
        time.sleep(6 * 3600)


