@login_required
@vm_owner_or_admin
def web_purge(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not _cf_ready_token():
        return _dk_json_err('Cloudflare API token is not set on this server (Admin → Settings).')
    done, errs = 0, []
    zones = set()
    for r in (db_execute("SELECT domain FROM web_domains WHERE vm_id=?", (vm_id,), fetch=True) or []):
        z = _cf_zone_for(r['domain'])
        if z:
            zones.add((z, r['domain']))
    if not zones:
        return _dk_json_err('None of this site\'s domains are in your Cloudflare account.')
    seen = set()
    for z, d in zones:
        if z in seen:
            continue
        seen.add(z)
        ok, res = _cf_api('POST', f'/zones/{z}/purge_cache', {'hosts': [x for (zz, x) in zones if zz == z]})
        if ok:
            done += 1
        else:
            errs.append(str(res)[:100])
    return jsonify({'success': done > 0, 'message': 'Cloudflare cache cleared.' if done else ('Cloudflare said: ' + '; '.join(errs))})


