def _setup_checks():
    out = []
    def add(name, state, detail):
        out.append({'name': name, 'state': state, 'detail': detail})
    dock = docker_available()
    add('Docker', 'ok' if dock else 'bad', 'Docker is running.' if dock else 'Docker is not available — Minecraft, bot and website hosting will not work.')
    if dock:
        rc, o, _ = _docker('inspect', '-f', '{{.State.Running}}', CADDY_NAME, timeout=10)
        if rc == 0 and o.strip() == 'true':
            add('Caddy (HTTPS proxy)', 'ok', 'Running.')
        else:
            add('Caddy (HTTPS proxy)', 'warn', 'Not running yet. It starts when you connect the first domain or set a panel domain.')
    import socket
    for port in (80, 443):
        sk = socket.socket(); sk.settimeout(1)
        try:
            up = sk.connect_ex(('127.0.0.1', port)) == 0
        finally:
            sk.close()
        add(f'Port {port}', 'ok' if up else 'warn', 'Something is listening.' if up else 'Nothing is listening yet — fine before the first domain; open it in your firewall/provider panel.')
    try:
        du = shutil.disk_usage(str(DOCKER_SERVERS_DIR if DOCKER_SERVERS_DIR.exists() else Path('/')))
        free = du.free / 1024 ** 3
        add('Disk space', 'ok' if free >= 10 else ('warn' if free >= 3 else 'bad'), f'{free:.1f} GB free of {du.total / 1024 ** 3:.0f} GB.')
    except Exception:
        pass
    try:
        mem = {l.split(':')[0]: int(l.split()[1]) for l in open('/proc/meminfo') if ':' in l}
        av = mem.get('MemAvailable', 0) / 1024
        add('Free memory', 'ok' if av >= 1024 else ('warn' if av >= 400 else 'bad'), f'{av:.0f} MB available.')
    except Exception:
        pass
    _ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    try:
        _v4 = ipaddress.ip_address(_ip).version == 4 and _ip != '127.0.0.1'
    except ValueError:
        _v4 = False
    add('Public IPv4 (shown to players)', 'ok' if _v4 else 'bad', _ip if _v4 else f'Could not detect a public IPv4 ({_ip}). Set "Server IP" in Settings, otherwise players get a wrong address.')
    pd = _panel_domain()
    add('Panel domain / HTTPS', 'ok' if pd else 'warn', pd if pd else 'No panel domain set — the panel is on plain HTTP. Set one in Settings.')
    weak = db_execute("SELECT username FROM users WHERE role='admin'", fetch=True) or []
    bad = []
    for u in weak:
        r = db_execute("SELECT password FROM users WHERE username=?", (u['username'],), fetchone=True)
        try:
            if r and check_password_hash(r['password'], 'phvm123'):
                bad.append(u['username'])
        except Exception:
            pass
    add('Admin password', 'bad' if bad else 'ok', ('Still the default password for: ' + ', '.join(bad) + ' — change it in My Profile.') if bad else 'Not the default.')
    add('Email (SMTP)', 'ok' if (gsv('smtp_host', '') or '').strip() else 'warn', 'Configured.' if (gsv('smtp_host', '') or '').strip() else 'Not set — password reset and email notices will not work.')
    add('Stripe', 'ok' if _stripe_keys_ok() else 'warn', 'Keys saved.' if _stripe_keys_ok() else 'Not set — manual payment is used.')
    add('Domain shop (Spaceship)', 'ok' if _ss_ready() else 'warn', 'Ready.' if _ss_ready() else 'Not set up.')
    add('Cloudflare token', 'ok' if (gsv('cf_api_token', '') or '').strip() else 'warn', 'Saved.' if (gsv('cf_api_token', '') or '').strip() else 'Not set — cache purge and mail forwarding need it.')
    add('Offsite backups', 'ok' if _offsite_ready() else 'warn', 'Configured.' if _offsite_ready() else 'Not set — backups stay on this server only.')
    add('Payment instructions', 'ok' if _pay_info('') else 'warn', 'Shown to customers.' if _pay_info('') else 'No JazzCash/Easypaisa/bank details saved.')
    add('Alerts', 'ok' if (gsv('admin_discord_webhook', '') or gsv('telegram_bot_token', '')) else 'warn', 'Configured.' if (gsv('admin_discord_webhook', '') or gsv('telegram_bot_token', '')) else 'No Discord/Telegram alerts set.')
    return out


