@login_required
@vm_owner_or_admin
def web_free_sub(vm_id):
    v = _web_row(vm_id)
    base = (gsv('free_subdomain_base', '') or '').strip().lower().strip('.')
    if not v or not base:
        return _dk_json_err('Free subdomains are not available here.')
    label = ((request.get_json(silent=True) or {}).get('label') or '').strip().lower()
    if not re.match(r'^[a-z0-9]([a-z0-9-]{1,28}[a-z0-9])$', label) or label in ('www', 'mail', 'admin', 'panel', 'api', 'ftp'):
        return _dk_json_err('Use 3-30 letters, numbers or dashes, e.g. mysite.')
    domain = f'{label}.{base}'
    if db_execute("SELECT 1 FROM web_domains WHERE domain=?", (domain,), fetchone=True):
        return _dk_json_err('That name is taken. Try another.')
    _had = db_execute("SELECT domain FROM web_domains WHERE vm_id=? AND domain LIKE ?", (vm_id, '%.' + base), fetch=True) or []
    _swap = bool(_had) and bool(_app_key(v))      # app sites: the automatic name can be changed
    if _had and not _swap:
        return _dk_json_err('This site already has a free subdomain.')
    n = db_execute("SELECT COUNT(*) AS n FROM web_domains WHERE vm_id=?", (vm_id,), fetchone=True)
    if n and int(n['n']) >= _web_domain_limit(v):
        return _dk_json_err('Your plan has no free domain slot left.')
    if _swap:
        for _r in _had:
            db_execute("DELETE FROM web_domains WHERE domain=?", (_r['domain'],))
    db_execute("INSERT INTO web_domains (vm_id, domain, via) VALUES (?,?,?)", (vm_id, domain, 'direct'))
    ok, msg = _caddy_sync()
    if not ok:
        db_execute("DELETE FROM web_domains WHERE domain=?", (domain,))
        for _r in (_had if _swap else []):
            db_execute("INSERT INTO web_domains (vm_id, domain, via) VALUES (?,?,?)", (vm_id, _r['domain'], 'direct'))
        _caddy_write()
        return _dk_json_err(msg)
    audit(session['user_id'], 'web_free_sub', f'{vm_id[:8]} {domain}')
    return jsonify({'success': True, 'message': f'Done — https://{domain} will work in about a minute.', 'domain': domain})


