@app.route('/vm/<vm_id>/web/mail', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_mail_fwd(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    if not (gsv('cf_api_token', '') or '').strip():
        return _dk_json_err('Email forwarding is not enabled by the admin yet.')
    d = request.get_json(silent=True) or {}
    act = d.get('action', 'add')
    opt = _web_opt(v)
    lst = list(opt.get('mail_fwd') or [])
    if act == 'list':
        return jsonify({'success': True, 'items': lst})
    domain = _web_clean_domain(d.get('domain'))
    if not db_execute("SELECT 1 FROM web_domains WHERE vm_id=? AND domain=?", (vm_id, domain), fetchone=True):
        return _dk_json_err('Pick one of this site\'s connected domains.')
    zid, acc, err = _mail_zone(domain)
    if not zid:
        return _dk_json_err(err)
    if act == 'remove':
        item = next((x for x in lst if x.get('alias') == d.get('alias') and x.get('domain') == domain), None)
        if not item:
            return _dk_json_err('Not found.')
        _cf_api('DELETE', f"/zones/{zid}/email/routing/rules/{item.get('rule_id')}")
        lst.remove(item)
        _web_save_opt(vm_id, mail_fwd=lst)
        return jsonify({'success': True, 'message': 'Removed.', 'items': lst})
    alias = (d.get('alias') or '').strip().lower()
    dest = (d.get('dest') or '').strip().lower()
    if not re.match(r'^[a-z0-9._-]{1,40}$', alias) or not re.match(r'^[^@\s]+@[^@\s]+\.[^@\s]+$', dest):
        return _dk_json_err('Enter a name like info and the real email address to forward to.')
    if len(lst) >= 10:
        return _dk_json_err('Up to 10 forwarding addresses per site.')
    if any(x.get('alias') == alias and x.get('domain') == domain for x in lst):
        return _dk_json_err('That address already exists.')
    _cf_api('POST', f'/zones/{zid}/email/routing/dns', {})
    if acc:
        _cf_api('POST', f'/accounts/{acc}/email/routing/addresses', {'email': dest})
    ok, res = _cf_api('POST', f'/zones/{zid}/email/routing/rules', {
        'name': f'phvm {alias}@{domain}', 'enabled': True,
        'matchers': [{'type': 'literal', 'field': 'to', 'value': f'{alias}@{domain}'}],
        'actions': [{'type': 'forward', 'value': [dest]}]})
    if not ok:
        return _dk_json_err('Cloudflare said: ' + str(res))
    lst.append({'alias': alias, 'domain': domain, 'dest': dest, 'rule_id': (res or {}).get('id')})
    _web_save_opt(vm_id, mail_fwd=lst)
    audit(session['user_id'], 'web_mail_fwd', f'{alias}@{domain}')
    return jsonify({'success': True, 'items': lst,
                    'message': f'{alias}@{domain} now forwards to {dest}. Cloudflare emails {dest} once to verify it — click the link there.'})


# ======================= DDoS / flood protection =======================
# What this does: (1) rate-limits the panel itself, (2) reads Caddy's access log for every hosted website and bans
# IPs that flood requests (firewall DROP, auto-expiring), (3) optional kernel + iptables shield (SYN cookies,
# per-IP connection/SYN limits for web and game ports), (4) one-click Cloudflare "Under Attack" mode.
# What it cannot do: stop a flood bigger than this server's network link — that must be absorbed upstream
# (Cloudflare / the hosting provider's DDoS filter).
DDOS_LOG = None
_ddos_hits = {}          # ip -> deque of timestamps
_ddos_panel_hits = {}    # ip -> list of timestamps (panel's own limiter)
_ddos_pos = {'inode': None, 'pos': 0}
_ddos_lock = threading.Lock()


def _ddos_run(*cmd, timeout=15):
    try:
        r = subprocess.run(list(cmd), capture_output=True, text=True, timeout=timeout)
        return r.returncode, (r.stdout or '') + (r.stderr or '')
    except Exception as e:
        return 1, str(e)


def _ddos_int(key, default, lo, hi):
    try:
        return max(lo, min(hi, int(float(gsv(key, str(default)) or default))))
    except Exception:
        return default


def _ddos_whitelisted(ip):
    try:
        a = ipaddress.ip_address(ip)
    except ValueError:
        return True
    if a.is_loopback or a.is_private or a.is_link_local or a.is_unspecified:
        return True
    for tok in re.split(r'[\s,;]+', gsv('ddos_whitelist', '') or ''):
        if not tok:
            continue
        try:
            if '/' in tok:
                if a in ipaddress.ip_network(tok, strict=False):
                    return True
            elif a == ipaddress.ip_address(tok):
                return True
        except ValueError:
            continue
    return False


def _ddos_fw(action, ip):
    """Add/remove a DROP rule. Docker-published ports skip INPUT, so DOCKER-USER is used as well."""
    if not shutil.which('iptables'):
        return False
    flag = '-I' if action == 'add' else '-D'
    ok = False
    for chain in ('DOCKER-USER', 'INPUT'):
        rc, _ = _ddos_run('iptables', '-C', chain, '-s', ip, '-j', 'DROP')
        exists = rc == 0
        if action == 'add' and not exists:
            rc, _ = _ddos_run('iptables', '-I', chain, '1', '-s', ip, '-j', 'DROP')
            ok = ok or rc == 0
        elif action == 'del' and exists:
            rc, _ = _ddos_run('iptables', '-D', chain, '-s', ip, '-j', 'DROP')
            ok = ok or rc == 0
        elif exists:
            ok = True
    return ok


_ddos_banned = {}       # ip -> until (memory copy of ddos_bans, so the per-request check costs no SQL)
_ddos_repeat = {}       # ip -> (count, last_ban_ts): repeat offenders get longer bans


def _ddos_is_banned(ip):
    u = _ddos_banned.get(ip)
    if not u:
        return False
    if u <= time.time():
        _ddos_banned.pop(ip, None)
        return False
    return True


def _ddos_ban(ip, reason, minutes=None, hits=0):
    try:
        return _ddos_ban_inner(ip, reason, minutes, hits)
    except Exception as e:      # a failed ban must never turn into a 500 for the request
        logging.warning('ddos ban failed: %s', e)
        _ddos_banned[ip] = int(time.time()) + 600
        return False


def _ddos_ban_inner(ip, reason, minutes=None, hits=0):
    if _ddos_whitelisted(ip):
        return False
    minutes = minutes or _ddos_int('ddos_ban_minutes', 60, 1, 10080)
    now = int(time.time())
    rc_, lt_ = _ddos_repeat.get(ip, (0, 0))
    if now - lt_ < 86400 and rc_:
        minutes = min(10080, minutes * (4 ** min(rc_, 3)))      # 2nd ban x4, 3rd x16, ... (max 7 days)
    _ddos_repeat[ip] = (rc_ + 1 if now - lt_ < 86400 else 1, now)
    if db_execute("SELECT 1 FROM ddos_bans WHERE ip=? AND until>?", (ip, now), fetchone=True):
        return False
    _ddos_banned[ip] = now + minutes * 60
    db_execute("INSERT OR REPLACE INTO ddos_bans (ip, until, reason, hits, created) VALUES (?,?,?,?,?)", (ip, now + minutes * 60, reason, hits, now))
    db_execute("INSERT INTO ddos_events (ts, ip, kind, detail) VALUES (?,?,?,?)", (now, ip, 'ban', f'{reason} ({hits} requests)'))
    _ddos_fw('add', ip)
    try:
        _admin_alert(f'🛡 DDoS shield banned {ip} for {minutes} min — {reason}.')
    except Exception:
        pass
    return True


def _ddos_unban(ip):
    _ddos_banned.pop(ip, None)
    db_execute("DELETE FROM ddos_bans WHERE ip=?", (ip,))
    _ddos_fw('del', ip)
    _ddos_hits.pop(ip, None)


def _ddos_expire():
    now = int(time.time())
    for r in db_execute("SELECT ip FROM ddos_bans WHERE until<=?", (now,), fetch=True) or []:
        _ddos_unban(r['ip'])
    db_execute("DELETE FROM ddos_events WHERE ts<?", (now - 7 * 86400,))


def _ddos_feed(ip, ts, thr=None, win=None):
    """Count one request; ban when the per-IP rate crosses the threshold. Returns True if banned now."""
    thr = thr or _ddos_int('ddos_threshold', 150, 20, 100000)
    win = win or _ddos_int('ddos_window', 10, 2, 120)
    dq = _ddos_hits.setdefault(ip, collections.deque())
    dq.append(ts)
    while dq and ts - dq[0] > win:
        dq.popleft()
    if len(dq) > thr:
        dq.clear()
        return _ddos_ban(ip, f'more than {thr} requests in {win}s', hits=thr + 1)
    return False


def _ddos_scan_log(path=None):
    """Read new lines of Caddy's JSON access log and feed the counters. Returns lines processed."""
    path = path or (CADDY_DIR / 'data' / 'access.log')
    try:
        st = os.stat(path)
    except OSError:
        return 0
    if _ddos_pos['inode'] != st.st_ino or st.st_size < _ddos_pos['pos']:
        _ddos_pos.update(inode=st.st_ino, pos=max(0, st.st_size - 2_000_000) if _ddos_pos['inode'] is None else 0)
    n = 0
    with open(path, 'rb') as f:
        f.seek(_ddos_pos['pos'])
        data = f.read(8_000_000)
        _ddos_pos['pos'] += len(data)
    for line in data.splitlines():
        try:
            j = json.loads(line)
            req = j.get('request') or {}
            ip = req.get('client_ip') or req.get('remote_ip') or ''
            ts = float(j.get('ts') or time.time())
        except Exception:
            continue
        if not ip or _ddos_whitelisted(ip):
            continue
        n += 1
        _ddos_feed(ip, ts)
    return n


def _ddos_loop():
    while True:
        try:
            _ddos_scan_log()
            _ddos_expire()
        except Exception as e:
            logging.warning('ddos loop: %s', e)
        time.sleep(3)


def _ddos_restore_bans():
    now = int(time.time())
    for r in db_execute("SELECT ip, until FROM ddos_bans WHERE until>?", (now,), fetch=True) or []:
        _ddos_banned[r['ip']] = r['until']
        _ddos_fw('add', r['ip'])


_SHIELD_CHAIN = 'PHVM-SHIELD'


def _ddos_shield_apply(enable=True):
    """Kernel hardening + per-IP connection/SYN limits. Returns (ok, message)."""
    if not shutil.which('iptables'):
        return False, 'iptables is not installed on this server (apt install iptables).'
    if os.geteuid() != 0:
        return False, 'The panel must run as root to change firewall rules.'
    for ch in ('DOCKER-USER',):
        _ddos_run('iptables', '-N', ch)
    for parent in ('DOCKER-USER', 'INPUT'):
        for _ in range(5):
            if _ddos_run('iptables', '-D', parent, '-j', _SHIELD_CHAIN)[0] != 0:
                break
    _ddos_run('iptables', '-F', _SHIELD_CHAIN)
    _ddos_run('iptables', '-X', _SHIELD_CHAIN)
    if not enable:
        return True, 'Network shield removed.'
    for k, v in (('net.ipv4.tcp_syncookies', '1'), ('net.ipv4.tcp_max_syn_backlog', '4096'), ('net.ipv4.tcp_synack_retries', '2'),
                 ('net.ipv4.conf.all.rp_filter', '1'), ('net.ipv4.icmp_echo_ignore_broadcasts', '1'),
                 ('net.ipv4.conf.all.accept_source_route', '0')):
        _ddos_run('sysctl', '-w', f'{k}={v}')
    _ddos_run('iptables', '-N', _SHIELD_CHAIN)
    pport = str(PANEL_PORT)
    rules = [
        # never rate-limit ourselves: loopback, Docker and private networks (Caddy / tunnels reach us from there)
        ['-s', '127.0.0.0/8', '-j', 'RETURN'], ['-s', '10.0.0.0/8', '-j', 'RETURN'],
        ['-s', '172.16.0.0/12', '-j', 'RETURN'], ['-s', '192.168.0.0/16', '-j', 'RETURN'],
        # malformed / spoofed packets
        ['-m', 'conntrack', '--ctstate', 'INVALID', '-j', 'DROP'],
        ['-p', 'tcp', '--tcp-flags', 'ALL', 'NONE', '-j', 'DROP'],
        ['-p', 'tcp', '--tcp-flags', 'ALL', 'ALL', '-j', 'DROP'],
        ['-p', 'tcp', '--tcp-flags', 'SYN,FIN', 'SYN,FIN', '-j', 'DROP'],
        ['-p', 'tcp', '--tcp-flags', 'SYN,RST', 'SYN,RST', '-j', 'DROP'],
        ['-f', '-j', 'DROP'],
        # the panel port itself: generous but bounded new-connection rate + simultaneous connections per source
        ['-p', 'tcp', '--syn', '--dport', pport, '-m', 'hashlimit', '--hashlimit-above', '40/second',
         '--hashlimit-burst', '80', '--hashlimit-mode', 'srcip', '--hashlimit-name', 'phvm_panel_syn', '-j', 'DROP'],
        ['-p', 'tcp', '--dport', pport, '-m', 'connlimit', '--connlimit-above', '150', '--connlimit-mask', '32',
         '-j', 'REJECT', '--reject-with', 'tcp-reset'],
        # per-source new-connection rate (SSH and the panel port are exempt so you can never lock yourself out)
        ['-p', 'tcp', '--syn', '-m', 'multiport', '!', '--dports', f'22,{pport}', '-m', 'hashlimit', '--hashlimit-above', '60/second',
         '--hashlimit-burst', '120', '--hashlimit-mode', 'srcip', '--hashlimit-name', 'phvm_syn', '-j', 'DROP'],
        # too many simultaneous connections from one address to web ports
        ['-p', 'tcp', '-m', 'multiport', '--dports', '80,443', '-m', 'connlimit', '--connlimit-above', '150', '--connlimit-mask', '32',
         '-j', 'REJECT', '--reject-with', 'tcp-reset'],
        # ICMP flood
        ['-p', 'icmp', '-m', 'hashlimit', '--hashlimit-above', '10/second', '--hashlimit-burst', '20', '--hashlimit-mode', 'srcip',
         '--hashlimit-name', 'phvm_icmp', '-j', 'DROP'],
        # UDP flood to a single source (game servers: Bedrock / Geyser still work at normal rates)
        ['-p', 'udp', '-m', 'hashlimit', '--hashlimit-above', '400/second', '--hashlimit-burst', '800', '--hashlimit-mode', 'srcip',
         '--hashlimit-name', 'phvm_udp', '-j', 'DROP'],
    ]
    bad = []
    for r in rules:
        rc, out = _ddos_run('iptables', '-A', _SHIELD_CHAIN, *r)
        if rc != 0:
            bad.append(out.strip()[:100])
    _ddos_run('iptables', '-A', _SHIELD_CHAIN, '-j', 'RETURN')
    for parent in ('DOCKER-USER', 'INPUT'):
        _ddos_run('iptables', '-I', parent, '1', '-j', _SHIELD_CHAIN)
    if bad:
        return True, 'Shield turned on, but some rules were refused by this kernel: ' + ' | '.join(bad[:2])
    return True, 'Network shield is on (SYN cookies, per-IP SYN/connection/ICMP/UDP limits).'


def _ddos_under_attack(on):
    """Cloudflare Under Attack mode for every zone that hosts one of our domains."""
    if not (gsv('cf_api_token', '') or '').strip():
        return False, 'Add your Cloudflare API token in Settings first.'
    zones, done, fail = set(), 0, 0
    for r in db_execute("SELECT DISTINCT domain FROM web_domains", fetch=True) or []:
        z = _cf_zone_for(r['domain'])
        if z:
            zones.add(z)
    if not zones:
        return False, 'None of the connected domains are on your Cloudflare account.'
    for z in zones:
        ok, _ = _cf_api('PATCH', f'/zones/{z}/settings/security_level', {'value': 'under_attack' if on else 'medium'})
        done += 1 if ok else 0
        fail += 0 if ok else 1
    _set_setting('ddos_under_attack', '1' if on else '0')
    return fail == 0, f"Under Attack mode {'ON' if on else 'OFF'} for {done} Cloudflare zone(s)" + (f', {fail} failed (token needs Zone Settings: Edit).' if fail else '.')


_ddos_404 = {}   # ip -> [timestamps of 404/405 answers] (vulnerability scanners)


@app.before_request
def _ddos_panel_guard():
    """Always-on flood limiter for the panel itself. Static files and logged-in admins are not counted.
    Anonymous visitors get a tighter limit than logged-in users; absurd URLs are refused outright."""
    if request.endpoint == 'static':
        return None
    ip = _client_ip()
    if _ddos_is_banned(ip):
        return ('Too many requests. Try again later.', 429)
    if len(request.url) > 4096 or len(request.query_string or b'') > 3000:
        return ('URL too long', 414)
    if request.endpoint is None:
        return None          # 404s are counted in after_request
    now = time.time()
    if session.get('role') == 'admin' or _ddos_whitelisted(ip):
        return None
    lst = [t for t in _ddos_panel_hits.get(ip, []) if now - t < 10]
    lst.append(now)
    _ddos_panel_hits[ip] = lst
    if len(_ddos_panel_hits) > 20000:
        _ddos_panel_hits.clear()
    cap = 150 if session.get('user_id') else 100      # anonymous: 100 requests / 10 s (shared mobile IPs stay safe)
    if len(lst) > cap:
        _ddos_ban(ip, f'panel flood ({cap}+ requests in 10s)', hits=len(lst))
        return ('Too many requests. Try again later.', 429)
    burst = sum(1 for t in lst if now - t < 2)
    if burst > (60 if session.get('user_id') else 40):   # sudden spike
        _ddos_ban(ip, f'panel burst ({burst} requests in 2s)', hits=burst)
        return ('Too many requests. Try again later.', 429)
    return None


@app.after_request
def _ddos_scan_guard(resp):
    """Vulnerability scanners probe hundreds of URLs that do not exist - ban them after 30 misses in a minute."""
    try:
        if (resp.status_code in (404, 405) and request.endpoint != 'static' and session.get('role') != 'admin'
                and request.path not in ('/favicon.ico', '/robots.txt', '/apple-touch-icon.png', '/apple-touch-icon-precomposed.png')):
            ip = _client_ip()
            if not _ddos_whitelisted(ip):
                now = time.time()
                lst = [t for t in _ddos_404.get(ip, []) if now - t < 60]
                lst.append(now)
                _ddos_404[ip] = lst
                if len(_ddos_404) > 20000:
                    _ddos_404.clear()
                if len(lst) > 30:
                    _ddos_404.pop(ip, None)
                    _ddos_ban(ip, 'URL scanning (30+ missing pages in 60s)', hits=len(lst))
    except Exception:
        pass
    return resp


