@app.route('/admin/ddos', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_ddos():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'save':
            _set_setting('ddos_enabled', '1')   # cannot be switched off
            for k, lo, hi, d in (('ddos_threshold', 20, 100000, 150), ('ddos_window', 2, 120, 10), ('ddos_ban_minutes', 1, 10080, 60)):
                try:
                    _set_setting(k, str(max(lo, min(hi, int(request.form.get(k) or d)))))
                except ValueError:
                    pass
            wl = (request.form.get('ddos_whitelist') or '')[:2000]
            _set_setting('ddos_whitelist', wl)
            ok, msg = _caddy_sync()
            flash('Saved.' + ('' if ok else ' (Proxy: ' + str(msg) + ')'), 'success')
        elif act == 'shield':
            on = True   # the network shield can only be refreshed, never switched off
            ok, msg = _ddos_shield_apply(on)
            if ok:
                _set_setting('ddos_shield', '1' if on else '0')
            flash(msg, 'success' if ok else 'danger')
        elif act == 'attack':
            ok, msg = _ddos_under_attack(request.form.get('mode') == 'on')
            flash(msg, 'success' if ok else 'danger')
        elif act == 'unban':
            _ddos_unban((request.form.get('ip') or '').strip())
            flash('Unbanned.', 'success')
        elif act == 'ban':
            ip = (request.form.get('ip') or '').strip()
            try:
                ipaddress.ip_address(ip)
                flash('Banned.' if _ddos_ban(ip, 'manual ban', hits=0) else 'That address cannot be banned (private, whitelisted or already banned).', 'info')
            except ValueError:
                flash('Enter a valid IP address.', 'danger')
        audit(session['user_id'], 'ddos_' + str(act), '')
        return redirect(url_for('admin_ddos'))
    now = int(time.time())
    bans = db_execute("SELECT * FROM ddos_bans WHERE until>? ORDER BY created DESC", (now,), fetch=True) or []
    events = db_execute("SELECT * FROM ddos_events ORDER BY id DESC LIMIT 40", fetch=True) or []
    top = sorted(((ip, len(dq)) for ip, dq in _ddos_hits.items() if dq), key=lambda x: -x[1])[:10]
    return render_template('admin/ddos.html', bans=bans, events=events, top=top, now=now,
                           enabled=True, thr=_ddos_int('ddos_threshold', 150, 20, 100000),
                           win=_ddos_int('ddos_window', 10, 2, 120), mins=_ddos_int('ddos_ban_minutes', 60, 1, 10080),
                           wl=gsv('ddos_whitelist', ''), shield=(gsv('ddos_shield', '0') == '1'), attack=gsv('ddos_under_attack', '0') == '1',
                           has_ipt=bool(shutil.which('iptables')), has_cf=bool((gsv('cf_api_token', '') or '').strip()))


# ======================= Site tools: updates, cron, maintenance, password reset =======================
def _web_do_updates(vid):
    """Update WordPress core, plugins and themes with WP-CLI. Returns a short text summary."""
    out = []
    for args in (('core', 'update'), ('plugin', 'update', '--all'), ('theme', 'update', '--all'), ('core', 'update-db')):
        rc, o, e = _web_wp_cli(vid, *args, timeout=900)
        out.append(f"{' '.join(args[:2])}: {'ok' if rc == 0 else 'failed'}")
    return ', '.join(out)


@app.route('/vm/<vm_id>/web/tools', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_tools(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    d = request.get_json(silent=True) or {}
    act = d.get('action')
    running, _ = dk_status(vm_id)
    if act in ('update', 'maint_on', 'maint_off', 'resetpw') and not running:
        return _dk_json_err('Start the site first.')
    if act == 'update':
        ok, msg = _web_task(vm_id, 'Updating WordPress', lambda log: (log('Updating…'), log(_web_do_updates(vm_id))))
        return jsonify({'success': ok, 'message': 'Updating WordPress, plugins and themes in the background. Take a backup first if the site is important.' if ok else msg})
    if act in ('maint_on', 'maint_off'):
        rc, o, e = _web_wp_cli(vm_id, 'maintenance-mode', 'activate' if act == 'maint_on' else 'deactivate', timeout=60)
        return jsonify({'success': rc == 0, 'message': ('Maintenance mode ' + ('ON — visitors see a "back soon" page.' if act == 'maint_on' else 'OFF.')) if rc == 0 else ('Failed: ' + (e or o).strip()[-150:])})
    if act == 'resetpw':
        user, _ = _web_wp_defaults()
        pw = secrets.token_urlsafe(12)
        rc, o, e = _web_wp_cli(vm_id, 'user', 'update', user, f'--user_pass={pw}', timeout=60)
        if rc != 0:
            return _dk_json_err('Could not reset: ' + (e or o).strip()[-150:])
        audit(session['user_id'], 'web_resetpw', vm_id[:8])
        return jsonify({'success': True, 'message': f'New WordPress admin password for "{user}":\n\n{pw}\n\nCopy it now — it is not shown again.'})
    if act == 'starter':
        key = d.get('key')
        if key not in _WP_STARTERS:
            return _dk_json_err('Unknown starter.')
        if not running:
            return _dk_json_err('Start the site first.')
        ok, msg = _web_task(vm_id, 'Installing starter', lambda log: _web_install_starter(vm_id, key, log))
        return jsonify({'success': ok, 'message': f'Installing the {_WP_STARTERS[key][0]} starter in the background (1–3 minutes). Open your site afterwards.' if ok else msg})
    if act == 'auto':
        _web_save_opt(vm_id, auto_update=bool(d.get('auto_update')), real_cron=bool(d.get('real_cron')), auto_renew=bool(d.get('auto_renew')))
        return jsonify({'success': True, 'message': 'Saved.'})
    return _dk_json_err('Unknown action.')


def _web_tools_loop():
    """Weekly auto-updates and (opt-in) real cron for WordPress sites."""
    time.sleep(900)
    tick = 0
    while True:
        try:
            for v in (db_execute("SELECT vm_id, name FROM vm_instances WHERE provision_kind='web' AND runtime='docker'", fetch=True) or []):
                opt = _web_opt(_dk_row(v['vm_id']))
                if not (opt.get('auto_update') or opt.get('real_cron')):
                    continue
                if not dk_status(v['vm_id'])[0]:
                    continue
                if opt.get('real_cron'):
                    _web_wp_cli(v['vm_id'], 'cron', 'event', 'run', '--due-now', timeout=120)
                key = 'autoupd:' + v['vm_id']
                if opt.get('auto_update') and time.time() - float(gsv(key, '0') or 0) > 6.9 * 86400:
                    _set_setting(key, str(time.time()))
                    _web_do_updates(v['vm_id'])
        except Exception as e:
            print('[tools] loop failed:', e, flush=True)
        time.sleep(600)


# ======================= Connection doctor: open firewall ports + test them =======================
_fw_done = set()


def _fw_state():
    st = {'ufw': False, 'firewalld': False, 'iptables_drop': False}
    try:
        if shutil.which('ufw'):
            st['ufw'] = 'Status: active' in subprocess.run(['ufw', 'status'], capture_output=True, text=True, timeout=8).stdout
    except Exception:
        pass
    try:
        if shutil.which('firewall-cmd'):
            st['firewalld'] = subprocess.run(['firewall-cmd', '--state'], capture_output=True, text=True, timeout=8).stdout.strip() == 'running'
    except Exception:
        pass
    try:
        if shutil.which('iptables'):
            st['iptables_drop'] = '-P INPUT DROP' in subprocess.run(['iptables', '-S', 'INPUT'], capture_output=True, text=True, timeout=8).stdout
    except Exception:
        pass
    return st


def _fw_open(port, proto='tcp', st=None):
    """Open a host port in whatever host firewall is active (best effort). Provider/cloud firewalls cannot be changed from here."""
    key = (int(port), proto)
    if key in _fw_done:
        return True
    st = st or _fw_state()
    ok = False
    try:
        if st['ufw']:
            ok = subprocess.run(['ufw', 'allow', f'{int(port)}/{proto}'], capture_output=True, timeout=15).returncode == 0 or ok
        if st['firewalld']:
            r = subprocess.run(['firewall-cmd', '--permanent', f'--add-port={int(port)}/{proto}'], capture_output=True, timeout=15)
            subprocess.run(['firewall-cmd', '--reload'], capture_output=True, timeout=15)
            ok = ok or r.returncode == 0
        if st['iptables_drop']:
            chk = subprocess.run(['iptables', '-C', 'INPUT', '-p', proto, '--dport', str(int(port)), '-j', 'ACCEPT'], capture_output=True)
            if chk.returncode != 0:
                ok = subprocess.run(['iptables', '-I', 'INPUT', '1', '-p', proto, '--dport', str(int(port)), '-j', 'ACCEPT'], capture_output=True, timeout=10).returncode == 0 or ok
            else:
                ok = True
        if not (st['ufw'] or st['firewalld'] or st['iptables_drop']):
            ok = True          # no host firewall in the way
    except Exception:
        ok = False
    if ok:
        _fw_done.add(key)
    return ok


def _fw_ports():
    """[(port, proto, vm_id, name, kind, label)] for every forwarded/SSH port the panel hands out."""
    out = []
    for r in db_execute("SELECT f.host_port, f.protocol, f.label, v.vm_id, v.name, v.provision_kind FROM port_forwards f JOIN vm_instances v ON v.vm_id=f.vm_id", fetch=True) or []:
        out.append((int(r['host_port']), (r['protocol'] or 'tcp').lower(), r['vm_id'], r['name'], r['provision_kind'] or 'vm', r['label'] or ''))
    for r in db_execute("SELECT ssh_port, vm_id, name FROM vm_instances WHERE ssh_port IS NOT NULL AND COALESCE(runtime,'')!='docker'", fetch=True) or []:
        out.append((int(r['ssh_port']), 'tcp', r['vm_id'], r['name'], 'vm', 'SSH'))
    return out


def _fw_sync():
    st = _fw_state()
    for port, proto, *_ in _fw_ports():
        _fw_open(port, proto, st)
        if proto == 'tcp' and _fw_label_udp(port):
            _fw_open(port, 'udp', st)


def _fw_label_udp(port):
    return bool(db_execute("SELECT 1 FROM port_forwards WHERE host_port=? AND protocol='udp'", (port,), fetchone=True))


def _fw_loop():
    time.sleep(20)
    while True:
        try:
            _fw_sync()
        except Exception as e:
            print('[fw] sync failed:', e, flush=True)
        time.sleep(120)


def _port_probe(host, port, timeout=2.0):
    sk = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sk.settimeout(timeout)
    try:
        return sk.connect_ex((host, int(port))) == 0
    except Exception:
        return False
    finally:
        sk.close()


@app.route('/admin/vm-branding', methods=['POST'])
@login_required
@admin_required
def admin_vm_branding():
    """Apply the GPU/PCI name ("PHvm Panel Virtual Machine") inside every running VM over SSH."""
    rows = db_execute("SELECT vm_id, ssh_port, ssh_password FROM vm_instances WHERE COALESCE(runtime,'')!='docker' AND ssh_port IS NOT NULL", fetch=True) or []
    b64 = base64.b64encode(_GUEST_BRAND_SH.encode()).decode()
    cmd = f"echo {b64} | base64 -d | bash"

    def work():
        for r in rows:
            try:
                if vm.vm_status(r['vm_id'])[0]:
                    vm.ssh_exec(r['ssh_port'], cmd, password=r['ssh_password'] or '', timeout=40)
            except Exception as e:
                print('[brand]', r['vm_id'][:8], e, flush=True)
    threading.Thread(target=work, daemon=True).start()
    audit(session['user_id'], 'vm_branding', f'{len(rows)} VMs')
    flash(f'Updating the GPU name inside {len(rows)} VM(s) in the background. The Host name (Phoenixcloud) and CPU name change when each VM is restarted.', 'success')
    return redirect(url_for('admin_check'))


@app.route('/admin/ports', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_ports():
    if request.method == 'POST':
        _fw_done.clear()
        _fw_sync()
        flash('Firewall rules refreshed for every server port.', 'success')
        return redirect(url_for('admin_ports'))
    st = _fw_state()
    ip = (gsv('server_ip', '') or '').strip() or PUBLIC_IP
    rows = []
    for port, proto, vid, name, kind, label in _fw_ports():
        listening = _port_probe('127.0.0.1', port) if proto == 'tcp' else None
        public = _port_probe(ip, port) if (proto == 'tcp' and ip and ip != '127.0.0.1') else None
        rows.append({'port': port, 'proto': proto, 'name': name, 'kind': kind, 'label': label, 'listening': listening, 'public': public})
    v4 = False
    try:
        v4 = ipaddress.ip_address(ip).version == 4 and ip != '127.0.0.1'
    except ValueError:
        pass
    return render_template('admin/ports.html', rows=rows, ip=ip, v4=v4, st=st, manual_ip=bool((gsv('server_ip', '') or '').strip()))


# ======================= Billing: payment proof, auto-renew, trial, payouts =======================
PROOF_DIR = BASE_DIR / 'proofs'


def _proof_ext(head, name):
    if head.startswith(b'\x89PNG'):
        return '.png'
    if head.startswith(b'\xff\xd8'):
        return '.jpg'
    if head[:4] == b'RIFF' and head[8:12] == b'WEBP':
        return '.webp'
    if head.startswith(b'%PDF'):
        return '.pdf'
    return None


@app.route('/my-orders', methods=['GET', 'POST'])
@login_required
def my_orders():
    uid = session['user_id']
    if request.method == 'POST':
        kind = request.form.get('kind')
        oid = request.form.get('id', type=int)
        f = request.files.get('proof')
        tbl = {'plan': 'web_plan_orders', 'domain': 'web_domain_orders'}.get(kind)
        o = db_execute(f"SELECT * FROM {tbl} WHERE id=? AND user_id=?", (oid, uid), fetchone=True) if tbl else None
        if not o or o['status'] not in ('pending', 'paid_failed'):
            flash('That order is not waiting for payment.', 'danger')
        elif not f or not f.filename:
            flash('Choose a screenshot or PDF of your payment.', 'danger')
        else:
            data = f.read(4 * 1024 * 1024 + 1)
            ext = _proof_ext(data[:16], f.filename)
            if len(data) > 4 * 1024 * 1024:
                flash('The file is too big (max 4 MB).', 'danger')
            elif not ext:
                flash('Only PNG, JPG, WEBP or PDF files are accepted.', 'danger')
            else:
                PROOF_DIR.mkdir(exist_ok=True)
                name = f'{kind}-{oid}-{secrets.token_hex(6)}{ext}'
                (PROOF_DIR / name).write_bytes(data)
                db_execute(f"UPDATE {tbl} SET proof=? WHERE id=?", (name, oid))
                _admin_alert(f"💳 Payment proof uploaded by {session.get('username')} for {kind} order #{oid}.")
                flash('Proof received. We will confirm your payment shortly.', 'success')
        return redirect(url_for('my_orders'))
    plan_orders = db_execute("""SELECT o.*, p.name AS plan FROM web_plan_orders o LEFT JOIN web_plans p ON p.id=o.plan_id
                                WHERE o.user_id=? ORDER BY o.id DESC LIMIT 30""", (uid,), fetch=True) or []
    dom_orders = db_execute("SELECT * FROM web_domain_orders WHERE user_id=? ORDER BY id DESC LIMIT 30", (uid,), fetch=True) or []
    return render_template('my_orders.html', plan_orders=plan_orders, dom_orders=dom_orders, pay_info=_pay_info(''))


