def _vpu():
    try:
        return float(gsv('topup_volts_per_unit', '1') or 1)
    except Exception:
        return 1.0


def _autorenew_tick():
    now = datetime.now()
    for v in (db_execute("SELECT * FROM vm_instances WHERE provision_kind='web' AND runtime='docker' AND expiry_date IS NOT NULL", fetch=True) or []):
        opt = _web_opt(v)
        if not (opt.get('auto_renew') and opt.get('plan_id')):
            continue
        try:
            exp = datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            continue
        if exp - now > timedelta(hours=36) or now - exp > timedelta(days=3):
            continue
        pl = db_execute("SELECT * FROM web_plans WHERE id=?", (opt['plan_id'],), fetchone=True)
        if not pl:
            continue
        cost = round(float(pl['price'] or 0) * _vpu(), 2)
        uid = v['user_id']
        if cost > 0 and not db_execute("UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?", (cost, uid, cost), rowcount=True):
            k = 'arfail:' + v['vm_id']
            if time.time() - float(gsv(k, '0') or 0) > 86400:
                _set_setting(k, str(time.time()))
                notify_user(uid, 'Auto-renew failed', f"Your wallet has less than ⚡{cost:.2f} for \"{v['name']}\". Add Volts or renew manually before {str(v['expiry_date'])[:10]}.", 'danger')
            continue
        if cost > 0:
            db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)", (uid, -cost, 'auto_renew', f"Auto-renew {v['name']}"))
        new = (max(exp, now) + timedelta(days=int(pl['days'] or 30))).strftime('%Y-%m-%d %H:%M:%S')
        db_execute("UPDATE vm_instances SET expiry_date=? WHERE vm_id=?", (new, v['vm_id']))
        _receipt_make(uid, f"{pl['name']} auto-renewal - {v['name']}", pl['price'], f"autorenew-{v['vm_id'][:8]}-{new[:10]}")
        notify_user(uid, 'Website auto-renewed', f"\"{v['name']}\" was renewed from your wallet (⚡{cost:.2f}) until {new[:10]}.", 'success')
        try:
            if not dk_status(v['vm_id'])[0]:
                _docker('start', _cname(v['vm_id']), timeout=60)
        except Exception:
            pass


def _autorenew_loop():
    time.sleep(120)
    while True:
        try:
            _autorenew_tick()
        except Exception as e:
            print('[autorenew] failed:', e, flush=True)
        time.sleep(1800)


@app.route('/trial', methods=['POST'])
@login_required
def start_trial():
    if gsv('trial_enabled', '0') != '1':
        return _dk_json_err('Free trials are not available.')
    uid, ip = session['user_id'], _client_ip()
    if db_execute("SELECT 1 FROM trials WHERE user_id=? OR ip=?", (uid, ip), fetchone=True):
        return _dk_json_err('The free trial can be used only once per person.')
    pl = db_execute("SELECT * FROM web_plans WHERE id=?", (int(gsv('trial_plan_id', '0') or 0),), fetchone=True)
    if not pl or not _docker_enabled():
        return _dk_json_err('The trial plan is not set up yet.')
    name = sanitize_name((request.get_json(silent=True) or {}).get('name') or 'My trial site', 64)
    try:
        hours = max(1, min(168, int(gsv('trial_hours', '24') or 24)))
    except ValueError:
        hours = 24
    vid = _create_web_site(uid, name, pl['ram_mb'], pl['cpu_cores'], pl['storage_gb'], hours / 24.0, pl['max_domains'], None, row_get(pl, 'engine') or None)
    db_execute("INSERT INTO trials (user_id, ip, vm_id) VALUES (?,?,?)", (uid, ip, vid))
    audit(uid, 'trial_start', vid[:8])
    return jsonify({'success': True, 'message': f'Your free {hours}-hour trial site is being created. Find it in My Virtual Machines.'})


@app.route('/payout', methods=['GET', 'POST'])
@login_required
def payout_page():
    uid = session['user_id']
    on = gsv('payout_enabled', '0') == '1'
    try:
        minv = float(gsv('payout_min_volts', '100') or 100)
    except ValueError:
        minv = 100.0
    try:
        rate = float(gsv('payout_rate', '1') or 1)
    except ValueError:
        rate = 1.0
    me = db_execute("SELECT wallet_balance FROM users WHERE id=?", (uid,), fetchone=True)
    bal = float((me['wallet_balance'] if me else 0) or 0)
    if request.method == 'POST' and on:
        try:
            volts = round(float(request.form.get('volts') or 0), 2)
        except ValueError:
            volts = 0
        method, acct = (request.form.get('method') or '')[:30], (request.form.get('account') or '').strip()[:120]
        if volts < minv or not acct or not method:
            flash(f'Minimum is ⚡{minv:g}, and the payment method and account are required.', 'danger')
        elif not db_execute("UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?", (volts, uid, volts), rowcount=True):
            flash('You do not have that many Volts.', 'danger')
        else:
            db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)", (uid, -volts, 'payout_hold', 'Payout request'))
            db_execute("INSERT INTO payout_requests (user_id, volts, method, account) VALUES (?,?,?,?)", (uid, volts, method, acct))
            _admin_alert(f"💸 Payout request: {session.get('username')} wants ⚡{volts:g} via {method}.")
            flash('Payout requested. We will send it and mark it done.', 'success')
        return redirect(url_for('payout_page'))
    reqs = db_execute("SELECT * FROM payout_requests WHERE user_id=? ORDER BY id DESC LIMIT 20", (uid,), fetch=True) or []
    return render_template('payout.html', on=on, minv=minv, rate=rate, bal=bal, reqs=reqs)


