# ======================= WordPress starters + site health score =======================
_WP_STARTERS = {
    'shop': ('Online shop', ['woocommerce'], 'storefront'),
    'business': ('Business / company', ['elementor', 'contact-form-7'], 'astra'),
    'blog': ('Blog', ['wordpress-seo'], 'astra'),
    'portfolio': ('Portfolio', ['kadence-blocks'], 'kadence'),
}


def _web_install_starter(vid, key, log):
    title, plugins, theme = _WP_STARTERS[key]
    log(f'Installing the {title} starter…')
    rc, o, e = _web_wp_cli(vid, 'theme', 'install', theme, '--activate', timeout=600)
    if rc != 0:
        raise RuntimeError('Theme install failed: ' + (e or o).strip()[-150:])
    for pl in plugins:
        log(f'Installing {pl}…')
        rc, o, e = _web_wp_cli(vid, 'plugin', 'install', pl, '--activate', timeout=600)
        if rc != 0:
            raise RuntimeError(f'Plugin {pl} failed: ' + (e or o).strip()[-150:])
    log('Done.')


def _web_health(vid):
    v = _web_row(vid)
    opt = _web_opt(v)
    items = []

    def add(label, pts, ok, tip):
        items.append({'label': label, 'points': pts, 'ok': bool(ok), 'tip': '' if ok else tip})
    running = False
    try:
        running = dk_status(vid)[0]
    except Exception:
        pass
    add('Site is running', 20, running, 'Start the site.')
    doms = db_execute("SELECT COUNT(*) AS n FROM web_domains WHERE vm_id=?", (vid,), fetchone=True)
    add('Has a domain with free SSL', 10, doms and doms['n'] > 0, 'Connect your domain in the Domains tab.')
    bks = _web_backup_list(vid)
    add('Backup in the last 7 days', 20, bks and time.time() - bks[0]['time'] < 7 * 86400, 'Create a backup, or turn on automatic backups in site settings.')
    add('Weekly auto-update on', 10, opt.get('auto_update'), 'Turn on "Auto-update every week" in Site tools.')
    add('Security scan in the last 14 days', 10, time.time() - float(gsv('scanned:' + vid, '0') or 0) < 14 * 86400, 'Press "Security scan" once.')
    add('Speed boost on', 10, opt.get('speed') or _web_engine(opt) == 'ols', 'Turn on Speed boost.')
    add('Modern PHP (8.2+)', 10, _web_settings(opt)['php'] >= '8.2', 'Choose PHP 8.2 or newer in site settings.')
    left = None
    try:
        left = (datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S') - datetime.now()).days if row_get(v, 'expiry_date') else 999
    except Exception:
        left = 999
    add('More than 7 days of hosting left', 10, left > 7, 'Renew the plan soon (or turn on auto-renew).')
    score = sum(i['points'] for i in items if i['ok'])
    return score, items


