@app.route('/admin/backup', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_backup():
    if request.method == 'POST':
        if not _admin_pw_ok(request.form.get('password')):
            flash('Wrong password.', 'danger')
            return redirect(url_for('admin_backup'))
        act = request.form.get('action')
        if act == 'download':
            tmp = Path(tempfile.gettempdir()) / f'phvm-snap-{secrets.token_hex(5)}.db'
            src = sqlite3.connect(DATABASE)
            dst = sqlite3.connect(str(tmp))
            try:
                src.backup(dst)
            finally:
                dst.close(); src.close()
            buf = io.BytesIO()
            with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z:
                z.write(tmp, 'phvm.db')
                sk = BASE_DIR / '.secret_key'
                if sk.exists():
                    z.write(sk, '.secret_key')
                z.writestr('MANIFEST.txt', f'PHvm panel backup {PANEL_VERSION} {datetime.now().isoformat()}\nContains the database and secret key — keep it private. Server data (worlds, websites) is not included; use each server\'s own backups.\n')
            tmp.unlink(missing_ok=True)
            buf.seek(0)
            audit(session['user_id'], 'panel_backup_download', '')
            return send_file(buf, as_attachment=True, download_name=f"phvm-panel-backup-{datetime.now().strftime('%Y%m%d-%H%M')}.zip")
        if act == 'restore':
            f = request.files.get('file')
            if not f:
                flash('Choose a backup zip.', 'danger')
                return redirect(url_for('admin_backup'))
            tmpz = Path(tempfile.gettempdir()) / f'phvm-restore-{secrets.token_hex(5)}.zip'
            f.save(str(tmpz))
            tmpdb = Path(tempfile.gettempdir()) / f'phvm-restore-{secrets.token_hex(5)}.db'
            try:
                with zipfile.ZipFile(tmpz) as z:
                    if 'phvm.db' not in z.namelist():
                        raise ValueError('This zip has no phvm.db — it is not a panel backup.')
                    if z.getinfo('phvm.db').file_size > 2 * 1024 ** 3:
                        raise ValueError('Backup is too large.')
                    tmpdb.write_bytes(z.read('phvm.db'))
                    key = z.read('.secret_key') if '.secret_key' in z.namelist() else None
                chk = sqlite3.connect(str(tmpdb))
                try:
                    if chk.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
                        raise ValueError('The backup database is damaged.')
                    if not chk.execute("SELECT 1 FROM sqlite_master WHERE name='users'").fetchone():
                        raise ValueError('The backup has no users table.')
                    # keep a copy of the current database first
                    keep = _update_backup_dir() / f"phvm-before-restore-{datetime.now().strftime('%Y%m%d-%H%M%S')}.db"
                    cur = sqlite3.connect(DATABASE)
                    out = sqlite3.connect(str(keep))
                    cur.backup(out); out.close(); cur.close()
                    live = sqlite3.connect(DATABASE)
                    chk.backup(live)
                    live.close()
                finally:
                    chk.close()
                if key:
                    (BASE_DIR / '.secret_key').write_bytes(key)
                audit(session['user_id'], 'panel_restore', '')
                flash('Backup restored. The panel is restarting — log in again.', 'success')
                _restart_panel_soon()
            except Exception as e:
                flash('Restore failed: ' + str(e)[:200], 'danger')
            finally:
                tmpz.unlink(missing_ok=True); tmpdb.unlink(missing_ok=True)
        return redirect(url_for('admin_backup'))
    olds = sorted(_update_backup_dir().glob('phvm-before-restore-*.db'), reverse=True)[:5]
    return render_template('admin/backup.html', olds=[o.name for o in olds])


def _metrics_tick():
    rc, out, _ = _docker('stats', '--no-stream', '--format', '{{.Name}}|{{.CPUPerc}}|{{.MemUsage}}', timeout=60)
    if rc != 0 or not out:
        return
    by_name = {}
    for r in db_execute("SELECT vm_id, name, user_id, cpu_cores FROM vm_instances WHERE runtime='docker'", fetch=True) or []:
        by_name[_cname(r['vm_id'])] = r
    ts = int(time.time() // 60 * 60)
    for line in out.strip().splitlines():
        parts = line.split('|')
        if len(parts) < 3 or parts[0] not in by_name:
            continue
        v = by_name[parts[0]]
        try:
            cpu = float(parts[1].strip().rstrip('%') or 0)
        except ValueError:
            cpu = 0.0
        mem = _parse_bytes(parts[2].split('/')[0].strip()) / 1048576.0
        db_execute("INSERT OR REPLACE INTO server_metrics (vm_id, ts, cpu, mem_mb) VALUES (?,?,?,?)", (v['vm_id'], ts, round(cpu, 1), round(mem, 1)))
        limit = max(1, int(v['cpu_cores'] or 1)) * 100 * 0.9
        last = db_execute("SELECT cpu FROM server_metrics WHERE vm_id=? ORDER BY ts DESC LIMIT 3", (v['vm_id'],), fetch=True) or []
        if len(last) == 3 and all(x['cpu'] >= limit for x in last):
            k = 'cpualert:' + v['vm_id']
            if time.time() - float(gsv(k, '0') or 0) > 6 * 3600:
                _set_setting(k, str(time.time()))
                notify_user(v['user_id'], 'High CPU use', f"\"{v['name']}\" has used almost all of its CPU for the last 15 minutes. Check plugins/scripts, or upgrade the plan.", 'warning')
    db_execute("DELETE FROM server_metrics WHERE ts < ?", (int(time.time()) - 7 * 86400,))


def _metrics_loop():
    time.sleep(60)
    while True:
        try:
            _metrics_tick()
        except Exception as e:
            print('[metrics] failed:', e, flush=True)
        time.sleep(300)


