    resp = app.response_class("self.addEventListener('install',e=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{});self.addEventListener('push',e=>{let d={};try{d=e.data.json()}catch(x){d={title:'PHvm',body:e.data?e.data.text():''}};e.waitUntil(self.registration.showNotification(d.title||'PHvm',{body:d.body||'',icon:'/pwa-icon-192.png',badge:'/pwa-icon-192.png',data:{url:d.url||'/'}}))});self.addEventListener('notificationclick',e=>{e.notification.close();const u=(e.notification.data&&e.notification.data.url)||'/';e.waitUntil(clients.matchAll({type:'window'}).then(l=>{for(const c of l){if('focus' in c){c.navigate(u);return c.focus()}}return clients.openWindow(u)}))});", mimetype='application/javascript')
