@app.route('/pwa-icon-<int:size>.png')
def pwa_icon(size):
    size = 512 if size >= 512 else 192
    from PIL import Image, ImageDraw
    im = Image.new('RGBA', (size, size), (15, 15, 17, 255))
    d = ImageDraw.Draw(im)
    u = size / 10
    d.rounded_rectangle([u, u, size - u, size - u], radius=u * 2, fill=(230, 230, 234, 255))
    bolt = [(5.6 * u, 1.8 * u), (3.2 * u, 5.6 * u), (4.9 * u, 5.6 * u), (4.1 * u, 8.2 * u), (6.9 * u, 4.3 * u), (5.1 * u, 4.3 * u)]
    d.polygon(bolt, fill=(15, 15, 17, 255))
    buf = io.BytesIO()
    im.save(buf, 'PNG')
    buf.seek(0)
    resp = send_file(buf, mimetype='image/png')
    resp.headers['Cache-Control'] = 'public, max-age=86400'
    return resp


# ======================= Resellers =======================
def reseller_required(f):
    @wraps(f)
    def decorated(*a, **k):
        if session.get('role') not in ('reseller', 'admin'):
            flash('Reseller access only.', 'danger')
            return redirect(url_for('dashboard'))
        return f(*a, **k)
    return decorated


def _reseller_rate():
    try:
        d = float(gsv('reseller_discount_percent', '20') or 20)
    except Exception:
        d = 20.0
    try:
        vpu = float(gsv('topup_volts_per_unit', '1') or 1)
    except Exception:
        vpu = 1.0
    return max(0.0, min(100.0, d)), vpu


