    me = session['user_id']
    disc, vpu = _reseller_rate()
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'customer':
            u = (request.form.get('username') or '').strip()[:40]
            e = (request.form.get('email') or '').strip()[:120]
