@app.route('/web-plans/<int:pid>/quote', methods=['POST'])
@login_required
def web_plans_quote(pid):
    pl = db_execute("SELECT * FROM web_plans WHERE id=? AND active=1", (pid,), fetchone=True)
    if not pl:
        return _dk_json_err('That plan is not available.')
    d = request.get_json(silent=True) or {}
    uid = session['user_id']
    base, kind, note = float(pl['price'] or 0), 'new', ''
    if d.get('upgrade_vm') or d.get('renew_vm'):
        v = _web_row(d.get('upgrade_vm') or d.get('renew_vm'))
        if not v or v['user_id'] != uid:
            return _dk_json_err('Choose one of your websites.')
        if d.get('upgrade_vm'):
            kind = 'upgrade'
            cur_id = _web_opt(v).get('plan_id')
            cur = db_execute("SELECT * FROM web_plans WHERE id=?", (cur_id,), fetchone=True) if cur_id else None
            if cur and float(cur['price'] or 0) >= float(pl['price'] or 0):
                return _dk_json_err('Pick a bigger plan than the one this site already has.')
            if int(pl['ram_mb']) < int(v['ram_mb'] or 0) or int(pl['storage_gb']) < int(v['storage_gb'] or 0):
                return _dk_json_err('That plan has less RAM or disk than the site has now.')
            if cur:
                base = max(0.0, float(pl['price'] or 0) - float(cur['price'] or 0))
                note = f"You only pay the difference to your current plan ({cur['name']})."
        else:
            kind = 'renew'
            note = f"Adds {int(pl['days'] or 30)} days to the end date."
    price, cmsg = base, ''
    if d.get('coupon'):
        cp, cerr = _coupon_get(d.get('coupon'))
        if cerr:
            return _dk_json_err(cerr)
        price = _coupon_price(base, cp)
        cmsg = f"Coupon {cp['code']} applied."
    volts = round(price * _vpu(), 2)
    bal = db_execute("SELECT COALESCE(wallet_balance,0) AS b FROM users WHERE id=?", (uid,), fetchone=True)
    b = float(bal['b']) if bal else 0.0
    return jsonify({'success': True, 'kind': kind, 'base': round(base, 2), 'price': round(price, 2), 'volts': volts, 'balance': round(b, 2),
                    'can_wallet': price <= 0 or b >= volts, 'free': price <= 0, 'card': bool(_stripe_keys_ok()), 'note': note, 'coupon': cmsg, 'days': int(pl['days'] or 30),
                    'price_text': pl['price_text'] or ''})


@app.route('/web-plans/<int:pid>/buy', methods=['POST'])
@login_required
def web_plans_buy(pid):
    pl = db_execute("SELECT * FROM web_plans WHERE id=? AND active=1", (pid,), fetchone=True)
    if not pl:
        return _dk_json_err('That plan is not available.')
    if not _docker_enabled():
        return _dk_json_err('Web hosting is not available on this server right now.')
    d = request.get_json(silent=True) or {}
    renew_vm = d.get('renew_vm')
    upgrade_vm = d.get('upgrade_vm')
    uid = session['user_id']
    base_price = float(pl['price'] or 0)
    if upgrade_vm:
        v = _web_row(upgrade_vm)
        if not v or v['user_id'] != uid:
            return _dk_json_err('Choose one of your websites to upgrade.')
        cur_id = _web_opt(v).get('plan_id')
        cur = db_execute("SELECT * FROM web_plans WHERE id=?", (cur_id,), fetchone=True) if cur_id else None
        if cur and float(cur['price'] or 0) >= float(pl['price'] or 0):
            return _dk_json_err('Pick a bigger plan than the one this site already has.')
        if int(pl['ram_mb']) < int(v['ram_mb'] or 0) or int(pl['storage_gb']) < int(v['storage_gb'] or 0):
            return _dk_json_err('That plan has less RAM or disk than the site has now.')
        if cur:
            base_price = max(0.0, float(pl['price'] or 0) - float(cur['price'] or 0))
        renew_vm = None
    if renew_vm:
        v = _web_row(renew_vm)
        if not v or v['user_id'] != uid:
            return _dk_json_err('Choose one of your websites to renew.')
        kind, name = 'renew', v['name']
    elif upgrade_vm:
        kind, name = 'upgrade', v['name']
    else:
        kind, name = 'new', sanitize_name(d.get('name') or '', 64)
        if not name:
            return _dk_json_err('Give your website a name.')
        cnt = db_execute("SELECT COUNT(*) AS n FROM web_plan_orders WHERE user_id=? AND status='pending'", (uid,), fetchone=True)
        if cnt and int(cnt['n']) >= 5:
            return _dk_json_err('You already have several orders waiting. Wait for them to finish first.')
    cp, cerr = _coupon_get(d.get('coupon'))
    if d.get('coupon') and cerr:
        return _dk_json_err(cerr)
    price = _coupon_price(base_price, cp)
    pay_wallet = d.get('pay') == 'wallet' and float(price or 0) > 0
    if pay_wallet:
        _need = round(float(price) * _vpu(), 2)
        _bal = db_execute("SELECT COALESCE(wallet_balance,0) AS b FROM users WHERE id=?", (uid,), fetchone=True)
        if not _bal or float(_bal['b']) < _need:
            return _dk_json_err(f"Not enough Volts: you need {_need:g} and have {float((_bal or {'b': 0})['b']):g}. Add Volts on the Wallet page first.")
    if cp and not _coupon_use(cp):
        return _dk_json_err('That coupon has been used up.')
    oid = db_execute("INSERT INTO web_plan_orders (user_id, plan_id, kind, site_name, vm_id, status, note, amount, coupon) VALUES (?,?,?,?,?,?,?,?,?)",
                     (uid, pid, kind, name, (renew_vm or upgrade_vm) if (renew_vm or upgrade_vm) else None, 'pending', '', price, cp['code'] if cp else None), lastrowid=True)
    if cp and price <= 0 and base_price > 0:
        db_execute("UPDATE web_plan_orders SET status='paid', note='free (coupon)' WHERE id=?", (oid,))
        threading.Thread(target=_plan_fulfil_bg, args=(oid,), daemon=True).start()
        return jsonify({'success': True, 'message': 'Coupon applied — no payment needed. Your website is being created.'})
    if pay_wallet:
        if not db_execute("UPDATE users SET wallet_balance = wallet_balance - ? WHERE id=? AND COALESCE(wallet_balance,0) >= ?", (_need, uid, _need), rowcount=True):
            db_execute("DELETE FROM web_plan_orders WHERE id=?", (oid,))
            if cp:
                db_execute("UPDATE coupons SET used=MAX(0, COALESCE(used,0)-1) WHERE code=?", (cp['code'],))
            return _dk_json_err('Not enough Volts. Add Volts on the Wallet page first.')
        db_execute("INSERT INTO wallet_transactions (user_id, amount, type, description) VALUES (?,?,?,?)", (uid, -_need, 'plan_order', f"{pl['name']} ({kind}) - {name}"))
        db_execute("UPDATE web_plan_orders SET status='paid', note='paid with wallet' WHERE id=?", (oid,))
        threading.Thread(target=_plan_fulfil_bg, args=(oid,), daemon=True).start()
        return jsonify({'success': True, 'paid': True, 'message': {'renew': 'Renewed — your site stays online.', 'upgrade': 'Upgrade paid — it is being applied now.'}.get(kind, 'Paid. Your website is being created — find it in My Virtual Machines in a minute.')})
    if _stripe_keys_ok() and float(price or 0) > 0:
        ok, res = _stripe_session(oid, f"{pl['name']} website hosting ({pl['days']} days)" + (' - renewal' if kind == 'renew' else ' - upgrade' if kind == 'upgrade' else ''),
                                  price, request.host_url.rstrip('/') + '/web-plans', 'plan')
        if not ok:
            db_execute("DELETE FROM web_plan_orders WHERE id=?", (oid,))
            return _dk_json_err(res)
        return jsonify({'success': True, 'checkout_url': res})
    for a in (db_execute("SELECT id FROM users WHERE role='admin'", fetch=True) or []):
        _admin_alert(f"🛒 Website plan order: {pl['name']} ({kind}) for \"{name}\"")
        add_notification(a['id'], 'Website plan order', f"{pl['name']} ({kind}) for \"{name}\" waits for payment approval (Admin → Web plans).", 'info')
    return jsonify({'success': True, 'message': 'Order placed.\n\n' + _pay_info('Pay the admin, and your website is created as soon as the payment is confirmed.') +
                    ('\n\nCoupon ' + cp['code'] + ' applied.' if cp else '') + '\n\nPrice: ' + ((pl['price_text'] if not cp else f"{price:g}") or f"{price:g}")})


@app.route('/admin/web-plans', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_web_plans():
    if request.method == 'POST':
        act = request.form.get('action')
        if act == 'save':
            vals = (sanitize_name(request.form.get('name', ''), 60) or 'Plan',
                    max(0.0, float(request.form.get('price') or 0)), (request.form.get('price_text') or '')[:40],
                    safe_int(request.form.get('ram_mb'), 1024, 256, 65536), safe_int(request.form.get('cpu_cores'), 1, 1, 64),
                    safe_int(request.form.get('storage_gb'), 10, 1, 10000), safe_int(request.form.get('max_domains'), 3, 1, 50),
                    safe_int(request.form.get('days'), 30, 1, 3650), 1 if request.form.get('active') else 0,
                    request.form.get('engine') if request.form.get('engine') in ('ols', 'storage', 'vault', 'kuma', 'code', 'sandbox', 'vscode', 'rstudio', 'palworld', 'hytale') else 'apache')
            pid = request.form.get('id', type=int)
            if pid:
                db_execute("UPDATE web_plans SET name=?, price=?, price_text=?, ram_mb=?, cpu_cores=?, storage_gb=?, max_domains=?, days=?, active=?, engine=? WHERE id=?", vals + (pid,))
            else:
                db_execute("INSERT INTO web_plans (name, price, price_text, ram_mb, cpu_cores, storage_gb, max_domains, days, active, engine) VALUES (?,?,?,?,?,?,?,?,?,?)", vals)
            flash('Plan saved.', 'success')
        elif act == 'coupon_add':
            code = re.sub(r'[^A-Z0-9_-]', '', (request.form.get('code') or '').upper())[:32]
            pct = safe_int(request.form.get('percent'), 0, 0, 100)
            off = max(0.0, float(request.form.get('amount_off') or 0))
            if not code or (not pct and not off):
                flash('Give a code and a percent or amount off.', 'danger')
            else:
                db_execute("INSERT OR REPLACE INTO coupons (code, percent, amount_off, max_uses, used, expires, active) VALUES (?,?,?,?,COALESCE((SELECT used FROM coupons WHERE code=?),0),?,1)",
                           (code, pct, off, safe_int(request.form.get('max_uses'), 0, 0, 10 ** 7), code, (request.form.get('expires') or '')[:10] or None))
                flash('Coupon saved.', 'success')
        elif act == 'coupon_del':
            db_execute("DELETE FROM coupons WHERE code=?", ((request.form.get('code') or '')[:32],))
            flash('Coupon deleted.', 'success')
        elif act == 'delete':
            db_execute("DELETE FROM web_plans WHERE id=?", (request.form.get('id', type=int),))
            flash('Plan deleted.', 'success')
        elif act in ('approve', 'reject'):
            o = db_execute("SELECT * FROM web_plan_orders WHERE id=?", (request.form.get('id', type=int),), fetchone=True)
            if not o or o['status'] not in ('pending', 'paid_failed'):
                flash('That order is not pending.', 'danger')
            elif act == 'reject':
                db_execute("UPDATE web_plan_orders SET status='rejected' WHERE id=?", (o['id'],))
                notify_user(o['user_id'], 'Order rejected', f"Your website order \"{o['site_name']}\" was rejected.", 'warning')
                flash('Order rejected.', 'success')
            else:
                try:
                    ok, msg = _plan_fulfil(o)
                except Exception as e:
                    ok, msg = False, str(e)[:150]
                db_execute("UPDATE web_plan_orders SET status=?, note=? WHERE id=?", ('done' if ok else 'paid_failed', msg[:200], o['id']))
                flash(msg, 'success' if ok else 'danger')
        return redirect(url_for('admin_web_plans'))
    plans = db_execute("SELECT * FROM web_plans ORDER BY id", fetch=True) or []
    orders = db_execute("""SELECT o.*, u.username, p.name AS plan FROM web_plan_orders o LEFT JOIN users u ON u.id=o.user_id
                           LEFT JOIN web_plans p ON p.id=o.plan_id ORDER BY o.id DESC LIMIT 100""", fetch=True) or []
    coupons = db_execute("SELECT * FROM coupons ORDER BY code", fetch=True) or []
    return render_template('admin/web_plans.html', plans=plans, orders=orders, coupons=coupons, stripe=_stripe_keys_ok())


@app.route('/vm/<vm_id>/web/buy/register', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_buy_register(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    if not _ss_ready():
        return _dk_json_err('Buying domains is not enabled on this server.')
    domain = _web_clean_domain((request.get_json(silent=True) or {}).get('domain'))
    if not _WEB_DOMAIN_RE.match(domain) or domain.count('.') != 1:
        return _dk_json_err('Choose a domain like example.com.')
    if not [i for i in _web_server_ips() if re.match(r'^\d+\.\d+\.\d+\.\d+$', i)]:
        return _dk_json_err('This server has no public IPv4 set, so a new domain cannot be pointed at it. Ask the admin to set the Server IP.')
    if db_execute("SELECT 1 FROM web_domains WHERE domain=?", (domain,), fetchone=True):
        return _dk_json_err('That domain is already connected to a site.')
    if _stripe_ready():  # an abandoned card checkout must not lock the name forever
        db_execute("UPDATE web_domain_orders SET status='expired' WHERE status='pending' AND created_at < datetime('now','-1 hour') AND price > 0")
    if db_execute("SELECT 1 FROM web_domain_orders WHERE domain=? AND status='pending' AND COALESCE(kind,'register')='register'", (domain,), fetchone=True):
        return _dk_json_err('Someone has already ordered that domain and is waiting for approval.')
    n = db_execute("SELECT COUNT(*) AS n FROM web_domains WHERE vm_id=?", (vm_id,), fetchone=True)
    lim = _web_domain_limit(v)
    if n and int(n['n']) + 2 > lim:
        return _dk_json_err(f'This site has no room for another domain and its www (plan limit {lim}).')
    ok, j, _ = _ss_api('GET', '/domains/' + urllib.parse.quote(domain) + '/available')
    if not ok:
        return _dk_json_err(j)
    if (j.get('result') or '').lower() != 'available' or j.get('premiumPricing'):
        return _dk_json_err(domain + ' is not available.')
    return _domain_order_create(session['user_id'], vm_id, domain, 'register', (request.get_json(silent=True) or {}).get('coupon'))


def _ss_expiry(domain):
    ok, j, _ = _ss_api('GET', '/domains/' + urllib.parse.quote(domain))
    exp = (j.get('expirationDate') or '')[:10] if ok and isinstance(j, dict) else ''
    if not re.match(r'^\d{4}-\d{2}-\d{2}$', exp):
        exp = (datetime.now() + timedelta(days=365)).strftime('%Y-%m-%d')
    return exp


def _domain_fulfil(order):
    """Admin approved / card paid: register (or renew), set DNS, attach. Returns (ok, message)."""
    domain, vm_id, uid = order['domain'], order['vm_id'], order['user_id']
    if row_get(order, 'kind') == 'renew':
        reg = db_execute("SELECT expires_at FROM web_domain_regs WHERE domain=?", (domain,), fetchone=True)
        cur = (reg['expires_at'] if reg else '') or _ss_expiry(domain)
        ok, j, h = _ss_api('POST', '/domains/' + urllib.parse.quote(domain) + '/renew',
                           {'years': 1, 'currentExpirationDate': cur if 'T' in cur else cur + 'T00:00:00.000Z'})
        if not ok:
            return False, 'Registrar: ' + str(j)
        wok, wmsg = _ss_wait(h)
        if not wok:
            return False, 'Registrar: ' + str(wmsg)
        exp = _ss_expiry(domain)
        db_execute("INSERT INTO web_domain_regs (domain, user_id, vm_id, expires_at, reminded) VALUES (?,?,?,?,0) "
                   "ON CONFLICT(domain) DO UPDATE SET expires_at=excluded.expires_at, reminded=0", (domain, uid, vm_id, exp))
        notify_user(uid, 'Domain renewed', f'{domain} was renewed. It now runs until {exp}.', 'success')
        _receipt_make(uid, f'Domain renewal {domain}', row_get(order, 'price'), f"domain-order-{order['id']}")
        return True, f'{domain} renewed until {exp}.'
    ipv4 = [i for i in _web_server_ips() if re.match(r'^\d+\.\d+\.\d+\.\d+$', i)]
    if not ipv4:
        return False, 'Set a public IPv4 in Server IP first.'
    if not _web_row(vm_id):
        return False, 'The site no longer exists.'
    if db_execute("SELECT 1 FROM web_domains WHERE domain=?", (domain,), fetchone=True):
        return False, 'That domain is already connected to a site.'
    cid = (gsv('spaceship_contact_id', '') or '').strip()
    ok, j, h = _ss_api('POST', '/domains/' + urllib.parse.quote(domain), {
        'autoRenew': False, 'years': 1, 'privacyProtection': {'level': 'high', 'userConsent': True},
        'contacts': {'registrant': cid, 'admin': cid, 'tech': cid, 'billing': cid}})
    if not ok:
        return False, 'Registrar: ' + str(j)
    wok, wmsg = _ss_wait(h)
    if not wok:
        return False, 'Registrar: ' + str(wmsg)
    db_execute("INSERT INTO web_domain_regs (domain, user_id, vm_id, expires_at, reminded) VALUES (?,?,?,?,0) "
               "ON CONFLICT(domain) DO UPDATE SET expires_at=excluded.expires_at, reminded=0, user_id=excluded.user_id, vm_id=excluded.vm_id",
               (domain, uid, vm_id, _ss_expiry(domain)))
    items = []
    for ip in ipv4[:2]:
        items.append({'type': 'A', 'name': '@', 'address': ip, 'ttl': 300})
        items.append({'type': 'A', 'name': 'www', 'address': ip, 'ttl': 300})
    dok, dmsg, _h = _ss_api('PUT', '/dns/records/' + urllib.parse.quote(domain), {'force': True, 'items': items})
    for d in (domain, 'www.' + domain):
        db_execute("INSERT OR IGNORE INTO web_domains (vm_id, domain, via) VALUES (?,?,?)", (vm_id, d, 'direct'))
    db_execute("UPDATE web_domains SET redirect_to=? WHERE domain=?", (domain, 'www.' + domain))
    cok, cmsg = _caddy_sync()
    _web_dns_cache.pop(domain, None)
    notify_user(uid, 'Domain ready', f'{domain} is registered and connected to your website.', 'success')
    _referral_reward(uid)
    _receipt_make(uid, f'Domain {domain}', row_get(order, 'price'), f"domain-order-{order['id']}")
    msg = f'{domain} registered and connected.'
    msg += ' DNS set.' if dok else ' DNS NOT set automatically (' + str(dmsg) + ') — add A records for @ and www to ' + ', '.join(ipv4) + '.'
    if wmsg == 'pending':
        msg += ' Registrar still finishing.'
    if not cok:
        msg += ' Web server reload problem: ' + str(cmsg)
    return True, msg


def _domain_order_create(uid, vm_id, domain, kind='register', coupon=None):
    cp, cerr = _coupon_get(coupon)
    if coupon and cerr:
        return _dk_json_err(cerr)
    price = _coupon_price(_stripe_amount(), cp)
    if cp and not _coupon_use(cp):
        return _dk_json_err('That coupon has been used up.')
    oid = db_execute("INSERT INTO web_domain_orders (user_id, vm_id, domain, price, status, note, kind, coupon) VALUES (?,?,?,?,?,?,?,?)",
                     (uid, vm_id, domain, price, 'pending', '', kind, cp['code'] if cp else None), lastrowid=True)
    if cp and price <= 0 and _stripe_ready():      # fully discounted: no payment needed
        db_execute("UPDATE web_domain_orders SET status='paid', note='free (coupon)' WHERE id=?", (oid,))
        threading.Thread(target=_stripe_fulfil_bg, args=(oid,), daemon=True).start()
        return jsonify({'success': True, 'message': 'Coupon applied — no payment needed. Your domain is being set up.'})
    audit(uid, 'web_domain_' + ('renew' if kind == 'renew' else 'order'), f'{vm_id[:8]} {domain}')
    if _stripe_ready():
        ok, res = _stripe_session(oid, (f'Renew {domain} (1 year)' if kind == 'renew' else f'Domain {domain} (1 year)'), price,
                                  f'{request.host_url.rstrip("/")}/vm/{vm_id}/web', 'domain')
        if not ok:
            db_execute("DELETE FROM web_domain_orders WHERE id=?", (oid,))
            return _dk_json_err(res)
        return jsonify({'success': True, 'checkout_url': res, 'message': 'Opening secure payment…'})
    for a in (db_execute("SELECT id FROM users WHERE role='admin'", fetch=True) or []):
        add_notification(a['id'], 'Domain order', f'{domain} ({kind}) was ordered and waits for payment approval (Admin → Domain orders).', 'info')
    return jsonify({'success': True, 'message': f'Order placed for {domain}.\n\n' + _pay_info('Pay the admin, then it is done as soon as the payment is confirmed.') +
                    f'\n\nPrice: {gsv("domain_price_text", "") or "ask the admin"}'})


