def _domain_expiry_loop():
    while True:
        try:
            for r in (db_execute("SELECT * FROM web_domain_regs", fetch=True) or []):
                try:
                    days = (datetime.strptime(r['expires_at'][:10], '%Y-%m-%d') - datetime.now()).days
                except Exception:
                    continue
                lvl = 3 if days <= 1 else 2 if days <= 7 else 1 if days <= 30 else 0
                if lvl > int(r['reminded'] or 0):
                    db_execute("UPDATE web_domain_regs SET reminded=? WHERE domain=?", (lvl, r['domain']))
                    when = 'has expired' if days < 0 else f'expires in {max(days, 0)} day(s)'
                    notify_user(r['user_id'], 'Domain expiring', f"{r['domain']} {when}. Open your website → Domains and press Renew so the site keeps working.",
                                'danger' if lvl >= 2 else 'warning')
        except Exception as e:
            print('[domains] expiry check failed:', e, flush=True)
        time.sleep(6 * 3600)



