# ---- Free Cloudflare link (quick tunnel): a public https://xxxx.trycloudflare.com address, no domain or account needed ----
_QUICK_RE = re.compile(r'https://[a-z0-9-]+\.trycloudflare\.com')


def _web_quick_state(vid):
    c = _cname(vid) + '-cfq'
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}|{{.State.Restarting}}', c, timeout=10)
    if rc != 0:
        return {'running': False, 'url': None, 'log': ''}
    run, _, restarting = out.strip().partition('|')
    rc, out, err = _docker('logs', '--tail', '60', c, timeout=10)
    text = _DK_ANSI.sub('', (out or '') + (err or ''))
    urls = _QUICK_RE.findall(text)
    tail = '\n'.join([l for l in text.splitlines() if l.strip()][-6:])[-600:]
    return {'running': run == 'true' and restarting != 'true', 'url': urls[-1] if urls else None, 'log': tail}


def _web_quick_start(vid, log):
    c = _cname(vid) + '-cfq'
    log('Downloading cloudflared (first time only)…')
    rc, out, err = _docker('pull', 'cloudflare/cloudflared:latest', timeout=900)
    if rc != 0:
        raise RuntimeError('Could not download cloudflared: ' + (err or out).strip()[-200:])
    _docker('network', 'create', WEB_NET, timeout=20)
    # the site must be on the shared web network for cloudflared to reach it by name
    _docker('network', 'connect', WEB_NET, _cname(vid), timeout=20)
    last = {}
    for proto in ('http2', 'quic'):           # http2 = TCP 7844, quic = UDP 7844: many hosts block one of them
        _docker('rm', '-f', c, timeout=30)
        log(f'Starting the tunnel ({proto})…')
        rc, out, err = _docker('run', '-d', '--name', c, '--label', 'phvm=1', '--network', WEB_NET, '--restart', 'on-failure:5',
                               '--memory', '128m', '--memory-swap', '128m', '--pids-limit', '128', '--security-opt', 'no-new-privileges',
                               'cloudflare/cloudflared:latest', 'tunnel', '--no-autoupdate', '--protocol', proto, '--edge-ip-version', '4',
                               '--url', f'http://{_cname(vid)}:80', timeout=120)
        if rc != 0:
            raise RuntimeError('Could not start the tunnel: ' + (err or out).strip()[-200:])
        log('Waiting for Cloudflare to give your link…')
        for _ in range(30):
            time.sleep(2)
            last = _web_quick_state(vid)
            if last['url']:
                log('Your link is ready. If it shows an error for the first 30 seconds, wait a little and reload.')
                return
            if not last['running']:
                break
    _docker('rm', '-f', c, timeout=30)
    raise RuntimeError('Cloudflare did not hand out a link. ' + (last.get('log') or '')[-300:] +
                       ' — this server probably blocks outgoing connections to Cloudflare (port 7844, TCP and UDP). Open outgoing 7844 in your firewall.')


@app.route('/vm/<vm_id>/web/quick', methods=['GET', 'POST'])
@login_required
@vm_owner_or_admin
def web_quick(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if request.method == 'GET':
        return jsonify({'success': True, **_web_quick_state(vm_id)})
    action = (request.get_json(silent=True) or {}).get('action')
    c = _cname(vm_id) + '-cfq'
    if action == 'stop':
        _docker('rm', '-f', c, timeout=30)
        return jsonify({'success': True, 'message': 'Free link stopped.'})
    if action != 'start':
        return _dk_json_err('Unknown action.')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('Start the site first.')
    ok, msg = _web_task(vm_id, 'Creating your free Cloudflare link', lambda log: _web_quick_start(vm_id, log))
    audit(session['user_id'], 'web_quick_start', vm_id[:8])
    return jsonify({'success': ok, 'message': 'Creating your free link — this can take up to a minute the first time.' if ok else msg})


