# ───────────── Web hosting upgrades: settings, 1-click login, phpMyAdmin, backups, clone, SSL status ─────────────
import ssl as _ssl

_WEB_PHP_VERSIONS = ('8.1', '8.2', '8.3', '8.4')
_WEB_TASKS = {}
_WEB_BK_RE = re.compile(r'^[a-z-]{3,20}-\d{8}-\d{6}\.tar\.gz$')
_WEB_SIZE_RE = re.compile(r'^\d{1,4}[MG]$')
WEB_MAX_BACKUPS = 10
_web_ssl_cache = {}
_web_ssl_busy = set()

_WEB_SSO_PHP = r"""<?php
/* PHvm one-click login (single-use token, valid for 60 seconds) */
add_action('init', function () {
    if (empty($_GET['phvm_sso'])) { return; }
    $f = WP_CONTENT_DIR . '/.phvm_sso';
    if (!is_file($f)) { return; }
    $d = json_decode(file_get_contents($f), true);
    @unlink($f);
    if (!$d || empty($d['h']) || empty($d['e']) || time() > (int) $d['e']) { return; }
    if (!hash_equals($d['h'], hash('sha256', (string) $_GET['phvm_sso']))) { return; }
    $admins = get_users(array('role' => 'administrator', 'number' => 1, 'orderby' => 'ID'));
    if (!$admins) { return; }
    wp_set_current_user($admins[0]->ID);
    wp_set_auth_cookie($admins[0]->ID, false);
    wp_safe_redirect(admin_url());
    exit;
});
"""


def _web_settings(opt):
    opt = opt or {}
    try:
        mx = int(opt.get('max_exec') or 300)
    except (TypeError, ValueError):
        mx = 300
    return {
        'php': opt.get('php') if opt.get('php') in _WEB_PHP_VERSIONS else '8.3',
        'memory_limit': opt.get('memory_limit') if _WEB_SIZE_RE.match(str(opt.get('memory_limit') or '')) else '256M',
        'upload_max': opt.get('upload_max') if _WEB_SIZE_RE.match(str(opt.get('upload_max') or '')) else '256M',
        'max_exec': max(30, min(900, mx)),
        'direct_access': opt.get('direct_access', True) is not False,
        'auto_backup': bool(opt.get('auto_backup')),
    }


def _web_ini_text(st):
    return (f"upload_max_filesize = {st['upload_max']}\npost_max_size = {st['upload_max']}\n"
            f"memory_limit = {st['memory_limit']}\nmax_execution_time = {st['max_exec']}\nmax_input_vars = 5000\n")


OLS_ROOT = '/var/www/vhosts/localhost/html'


def _web_engine(opt):
    return 'ols' if (opt or {}).get('engine') == 'ols' else 'apache'


def _web_uid(opt):
    return 65534 if _web_engine(opt) == 'ols' else 33


def _web_wp_image(st, opt=None):
    if _web_engine(opt) == 'ols':
        ver = re.sub(r'[^0-9.]', '', gsv('ols_version', '1.8.3') or '') or '1.8.3'
        return f"litespeedtech/openlitespeed:{ver}-lsphp{st['php'].replace('.', '')}"
    return f"wordpress:php{st['php']}-apache"


def _web_ols_prepare(vid, opt):
    """Turbo engine: download WordPress with WP-CLI and write wp-config.php (the OLS image ships no WordPress)."""
    d = _dk_dir(vid)
    c, cdb, cnet = _web_names(vid)
    if not (d / 'wp-includes').is_dir():
        rc, out, err = _docker('run', '--rm', '--user', '65534:65534', '--network', cnet, '--memory', '512m', '-v', f'{d}:/var/www/html',
                               WEB_CLI_IMAGE, 'wp', 'core', 'download', '--path=/var/www/html', timeout=900)
        if rc != 0 and not (d / 'wp-includes').is_dir():
            raise RuntimeError('WordPress download failed: ' + (err or out).strip()[-200:])
    cfg = d / 'wp-config.php'
    if not cfg.exists():
        keys = ''.join(f"define('{k}', '{secrets.token_urlsafe(48)}');\n" for k in
                       ('AUTH_KEY', 'SECURE_AUTH_KEY', 'LOGGED_IN_KEY', 'NONCE_KEY', 'AUTH_SALT', 'SECURE_AUTH_SALT', 'LOGGED_IN_SALT', 'NONCE_SALT'))
        cfg.write_text("<?php\ndefine('DB_NAME', 'wordpress');\ndefine('DB_USER', 'wordpress');\n"
                       f"define('DB_PASSWORD', '{opt.get('db_pass', '')}');\ndefine('DB_HOST', '{cdb}:3306');\n"
                       "define('DB_CHARSET', 'utf8mb4');\ndefine('DB_COLLATE', '');\n" + keys +
                       "$table_prefix = 'wp_';\ndefine('WP_DEBUG', false);\n" + _WEB_WP_EXTRA +
                       "\nif (!defined('ABSPATH')) { define('ABSPATH', __DIR__ . '/'); }\nrequire_once ABSPATH . 'wp-settings.php';\n")
    _dk_chown_tree(str(d), 65534)


def _web_wp_args(v, opt, host_port):
    """`docker create` arguments for the WordPress container of a site."""
    vid = v['vm_id']
    c, cdb, _cnet = _web_names(vid)
    st = _web_settings(opt)
    ram, cores = int(v['ram_mb']), max(1, int(v['cpu_cores'] or 1))
    wp_mem = max(256, ram - max(256, min(1024, ram // 4)))
    args = ['create', '--name', c, '--restart', 'unless-stopped', '--label', 'phvm=1', '--network', WEB_NET,
            '--pids-limit', '512', '--security-opt', 'no-new-privileges',
            '--memory', f'{wp_mem}m', '--memory-swap', f'{wp_mem}m', '--cpus', str(cores),
            '--log-opt', 'max-size=10m', '--log-opt', 'max-file=3',
            '-e', f'WORDPRESS_DB_HOST={cdb}:3306', '-e', 'WORDPRESS_DB_NAME=wordpress',
            '-e', 'WORDPRESS_DB_USER=wordpress', '-e', f"WORDPRESS_DB_PASSWORD={opt.get('db_pass', '')}",
            '-e', 'WORDPRESS_CONFIG_EXTRA=' + _WEB_WP_EXTRA,
            '-v', f'{_dk_dir(vid)}:/var/www/html',
            '-v', f'{WEB_CFG_DIR / (vid + ".ini")}:/usr/local/etc/php/conf.d/phvm.ini:ro']
    if host_port:
        args += ['-p', (f'{host_port}:80' if st['direct_access'] else f'127.0.0.1:{host_port}:80')]
    if _web_engine(opt) == 'ols':
        i = args.index('-v')
        # OpenLiteSpeed: docroot differs, PHP limits come from .user.ini, no php.ini mount
        del args[i:i + 4]
        (_dk_dir(vid) / '.user.ini').write_text(_web_ini_text(st))
        try:
            _dk_chown(str(_dk_dir(vid) / '.user.ini'), 65534, 65534)
        except Exception:
            pass
        args += ['-v', f'{_dk_dir(vid)}:{OLS_ROOT}']
    args.append(_web_wp_image(st, opt))
    return args


def _web_host_port(vid):
    fw = db_execute("SELECT host_port FROM port_forwards WHERE vm_id=? AND guest_port=80", (vid,), fetchone=True)
    return int(fw['host_port']) if fw else None


def _web_save_opt(vid, **changes):
    v = _dk_row(vid)
    opt = _web_opt(v)
    opt.update(changes)
    db_execute("UPDATE vm_instances SET provision_opt=? WHERE vm_id=?", (json.dumps(opt), vid))
    return opt


def _web_task(vid, label, fn):
    """Run fn(log) in a background thread; one task per site at a time. Returns (ok, message)."""
    t = _WEB_TASKS.get(vid)
    if t and not t['done']:
        return False, f"Please wait — “{t['label']}” is still running."
    t = {'label': label, 'done': False, 'error': '', 'log': []}
    _WEB_TASKS[vid] = t

    def run():
        try:
            fn(lambda m: t['log'].append(str(m)[:200]))
        except Exception as e:
            t['error'] = str(e)[:300]
            print(f'[web] task {label} failed for {vid}: {e}', flush=True)
        finally:
            t['done'] = True
    threading.Thread(target=run, daemon=True).start()
    return True, 'Started.'


def _web_recreate_wp(vid, log, pull=True):
    """Re-create the WordPress container with the current settings (PHP version, limits, direct access)."""
    v = _dk_row(vid)
    opt = _web_opt(v)
    st = _web_settings(opt)
    c, cdb, cnet = _web_names(vid)
    running, _ = dk_status(vid)
    WEB_CFG_DIR.mkdir(parents=True, exist_ok=True)
    (WEB_CFG_DIR / f'{vid}.ini').write_text(_web_ini_text(st))
    if pull:
        log(f'Downloading PHP {st["php"]} image…')
        rc, out, err = _docker('pull', _web_wp_image(st, opt), timeout=1800)
        if rc != 0:
            raise RuntimeError('image download failed: ' + (err or out).strip()[-200:])
    log('Re-creating the site container…')
    _docker('stop', '-t', '20', c, timeout=60)
    _docker('rm', '-f', c, timeout=60)
    rc, out, err = _docker(*_web_wp_args(v, opt, _web_host_port(vid)), timeout=120)
    if rc != 0:
        raise RuntimeError('container create failed: ' + (err or out).strip()[-300:])
    _docker('network', 'connect', cnet, c, timeout=20)
    if running:
        _docker('start', cdb, timeout=60)
        rc, out, err = _docker('start', c, timeout=60)
        if rc != 0:
            raise RuntimeError('start failed: ' + (err or out).strip()[-300:])
    log('Done.')


# ---- backups ----
def _web_bk_dir(vid):
    return DK_BACKUP_DIR / str(vid)


def _web_backup_list(vid):
    d = _web_bk_dir(vid)
    out = []
    if d.is_dir():
        for f in sorted(d.glob('*.tar.gz'), key=lambda x: x.stat().st_mtime, reverse=True):
            if _WEB_BK_RE.match(f.name):
                st = f.stat()
                out.append({'name': f.name, 'size': st.st_size, 'time': int(st.st_mtime),
                            'kind': f.name.rsplit('-', 2)[0]})
    return out


def _web_db_exec(vid, sh, stdin_path=None, stdout_path=None, timeout=3600):
    """Run a shell snippet inside the DB container (root password comes from the container's own env)."""
    c, cdb, _ = _web_names(vid)
    cmd = ['docker', 'exec'] + (['-i'] if stdin_path else []) + [cdb, 'sh', '-c', sh]
    fin = open(stdin_path, 'rb') if stdin_path else None
    fout = open(stdout_path, 'wb') if stdout_path else subprocess.PIPE
    try:
        r = subprocess.run(cmd, stdin=fin, stdout=fout, stderr=subprocess.PIPE, timeout=timeout)
    finally:
        if fin:
            fin.close()
        if stdout_path:
            fout.close()
    return r.returncode, (r.stderr or b'').decode('utf-8', 'replace')[-300:]


def _web_make_backup(vid, kind, log):
    existing = _web_backup_list(vid)
    if len(existing) >= WEB_MAX_BACKUPS:
        olds = [b for b in existing if b['kind'] in ('auto', 'pre')]
        if not olds:
            raise RuntimeError(f'You already have {WEB_MAX_BACKUPS} backups — delete an old one first.')
        (_web_bk_dir(vid) / olds[-1]['name']).unlink(missing_ok=True)
    d = _web_bk_dir(vid)
    d.mkdir(parents=True, exist_ok=True)
    name = f"{kind}-{datetime.now().strftime('%Y%m%d-%H%M%S')}.tar.gz"
    tmp_sql = d / '.dump.sql'
    c, cdb, _ = _web_names(vid)
    _docker('start', cdb, timeout=60)
    log('Exporting the database…')
    rc, err = _web_db_exec(vid, 'mariadb-dump -u root -p"$MARIADB_ROOT_PASSWORD" --single-transaction --routines wordpress',
                           stdout_path=str(tmp_sql))
    if rc != 0:
        tmp_sql.unlink(missing_ok=True)
        raise RuntimeError('database export failed: ' + err.strip())
    log('Packing the site files…')
    out = d / name
    try:
        with tarfile.open(out, 'w:gz') as tf:
            tf.add(str(tmp_sql), arcname='db.sql')
            tf.add(str(_dk_dir(vid)), arcname='files')
    except Exception:
        out.unlink(missing_ok=True)
        raise
    finally:
        tmp_sql.unlink(missing_ok=True)
    log(f'Backup {name} created.')
    return name


def _web_safe_extract(tf, dest):
    dest = os.path.realpath(dest)
    for m in tf.getmembers():
        if not m.name.startswith('files'):
            continue
        rel = posixpath.normpath(m.name)
        t = os.path.realpath(os.path.join(os.path.dirname(dest), rel))
        if not (t == dest or t.startswith(dest + os.sep)):
            raise RuntimeError('Unsafe path in backup: ' + m.name)
        if not (m.isfile() or m.isdir()):
            continue
        try:
            tf.extract(m, os.path.dirname(dest), filter='data')
        except TypeError:                                       # Python < 3.12
            tf.extract(m, os.path.dirname(dest))


def _web_restore_file(vid, path, log):
    c, cdb, _ = _web_names(vid)
    d = _dk_dir(vid)
    log('Stopping the site…')
    _docker('stop', '-t', '20', c, timeout=60)
    _docker('start', cdb, timeout=60)
    with tarfile.open(path, 'r:gz') as tf:
        names = tf.getnames()
        if 'db.sql' not in names or not any(n == 'files' or n.startswith('files/') for n in names):
            raise RuntimeError('This is not a valid site backup.')
        log('Restoring the files…')
        for child in list(d.iterdir()):
            shutil.rmtree(child, ignore_errors=True) if child.is_dir() and not child.is_symlink() else child.unlink(missing_ok=True)
        # backups store the site dir as "files/…", so extract next to it under a temp name then move
        tmp = d.parent / f'.restore-{vid}'
        shutil.rmtree(tmp, ignore_errors=True)
        tmp.mkdir(parents=True)
        _web_safe_extract(tf, str(tmp / 'files'))
        tf.extract('db.sql', str(tmp))
    src = tmp / 'files'
    if src.is_dir():
        for child in src.iterdir():
            shutil.move(str(child), str(d / child.name))
    _dk_chown_tree(str(d), 33)
    log('Restoring the database…')
    rc, err = _web_db_exec(vid, 'mariadb -u root -p"$MARIADB_ROOT_PASSWORD" -e "DROP DATABASE IF EXISTS wordpress; CREATE DATABASE wordpress;"')
    if rc != 0:
        raise RuntimeError('could not reset the database: ' + err.strip())
    rc, err = _web_db_exec(vid, 'mariadb -u root -p"$MARIADB_ROOT_PASSWORD" wordpress', stdin_path=str(tmp / 'db.sql'))
    shutil.rmtree(tmp, ignore_errors=True)
    if rc != 0:
        raise RuntimeError('database import failed: ' + err.strip())
    _docker('exec', cdb, 'sh', '-c', 'mariadb -u root -p"$MARIADB_ROOT_PASSWORD" -e "GRANT ALL ON wordpress.* TO \'wordpress\'@\'%\'; FLUSH PRIVILEGES;"', timeout=30)
    rc, out, err = _docker('start', c, timeout=60)
    if rc != 0:
        raise RuntimeError('could not start the site: ' + (err or out).strip()[-200:])
    log('Restore complete.')


# ---- Offsite backups: any S3-compatible storage (AWS S3, Cloudflare R2, Backblaze B2, Wasabi, MinIO) ----
def _offsite_ready():
    return (gsv('offsite_enabled', '0') == '1' and all((gsv(k, '') or '').strip() for k in
            ('offsite_endpoint', 'offsite_bucket', 'offsite_access_key', 'offsite_secret_key')))


_S3_NOW = None


def _s3_request(method, key, path=None, body_bytes=None):
    """SigV4-signed request (path-style). Streams a file when `path` is given. Returns (status, text)."""
    import http.client
    from urllib.parse import urlparse, quote
    ep = (gsv('offsite_endpoint', '') or '').strip()
    if not ep.startswith('http'):
        ep = 'https://' + ep
    u = urlparse(ep)
    region = (gsv('offsite_region', '') or 'auto').strip() or 'auto'
    bucket = (gsv('offsite_bucket', '') or '').strip()
    ak = (gsv('offsite_access_key', '') or '').strip()
    sk = (gsv('offsite_secret_key', '') or '').strip()
    uri = '/' + quote(bucket + '/' + key.lstrip('/'), safe='/')
    host = u.netloc
    now = _S3_NOW() if _S3_NOW else datetime.utcnow()
    amz = now.strftime('%Y%m%dT%H%M%SZ')
    day = now.strftime('%Y%m%d')
    size = os.path.getsize(path) if path else len(body_bytes or b'')
    if u.scheme == 'https':
        payload_hash = 'UNSIGNED-PAYLOAD'
    else:                                   # plain http (e.g. a local MinIO): the payload must be hashed
        hh = hashlib.sha256()
        if path:
            with open(path, 'rb') as f:
                for chunk in iter(lambda: f.read(1 << 20), b''):
                    hh.update(chunk)
        else:
            hh.update(body_bytes or b'')
        payload_hash = hh.hexdigest()
    hdrs = {'host': host, 'x-amz-content-sha256': payload_hash, 'x-amz-date': amz}
    signed = ';'.join(sorted(hdrs))
    canon = '\n'.join([method, uri, '', ''.join(f'{k}:{hdrs[k]}\n' for k in sorted(hdrs)), signed, payload_hash])
    scope = f'{day}/{region}/s3/aws4_request'
    sts = '\n'.join(['AWS4-HMAC-SHA256', amz, scope, hashlib.sha256(canon.encode()).hexdigest()])

    def hm(k, m):
        return hmac.new(k, m.encode(), hashlib.sha256).digest()
    kk = hm(hm(hm(hm(('AWS4' + sk).encode(), day), region), 's3'), 'aws4_request')
    sig = hmac.new(kk, sts.encode(), hashlib.sha256).hexdigest()
    headers = {'x-amz-content-sha256': payload_hash, 'x-amz-date': amz, 'Content-Length': str(size),
               'Authorization': f'AWS4-HMAC-SHA256 Credential={ak}/{scope}, SignedHeaders={signed}, Signature={sig}'}
    conn = (http.client.HTTPSConnection if u.scheme == 'https' else http.client.HTTPConnection)(u.hostname, u.port, timeout=1800)
    try:
        conn.putrequest(method, uri, skip_host=False)
        for k, v in headers.items():
            conn.putheader(k, v)
        conn.endheaders()
        if path:
            with open(path, 'rb') as f:
                while True:
                    chunk = f.read(1 << 20)
                    if not chunk:
                        break
                    conn.send(chunk)
        elif body_bytes:
            conn.send(body_bytes)
        r = conn.getresponse()
        return r.status, r.read().decode('utf-8', 'replace')[:300]
    finally:
        conn.close()


def _offsite_upload(path, key):
    """Returns (ok, message). Keeps only the newest N objects per folder is the provider's job (use lifecycle rules)."""
    if not _offsite_ready():
        return False, 'Offsite backup is not set up.'
    try:
        st, txt = _s3_request('PUT', key, path=str(path))
    except Exception as e:
        return False, 'Upload failed: ' + str(e)[:150]
    if st in (200, 201):
        return True, 'Uploaded to offsite storage.'
    m_ = re.search(r'<Message>(.*?)</Message>', txt)
    return False, f'Storage answered {st}: ' + (m_.group(1) if m_ else txt[:120])


def _offsite_panel_db_backup():
    tmp = Path(tempfile.gettempdir()) / f'phvm-offsite-{secrets.token_hex(4)}.db'
    src = sqlite3.connect(DATABASE)
    dst = sqlite3.connect(str(tmp))
    try:
        src.backup(dst)
    finally:
        dst.close()
        src.close()
    try:
        return _offsite_upload(tmp, 'panel/phvm-' + datetime.now().strftime('%Y%m%d-%H%M') + '.db')
    finally:
        tmp.unlink(missing_ok=True)


def _offsite_loop():
    """Once a day: copy the panel database offsite. Site backups are copied right after they are made."""
    while True:
        time.sleep(3600)
        try:
            if _offsite_ready():
                last = float(gsv('offsite_last_panel', '0') or 0)
                if time.time() - last > 23 * 3600:
                    ok, msg = _offsite_panel_db_backup()
                    _set_setting('offsite_last_panel', str(time.time() if ok else last))
                    if not ok:
                        _notify_all_admins('Offsite backup failed', 'Panel database upload: ' + msg, 'warning')
        except Exception as e:
            print('[offsite] loop failed:', e, flush=True)


@app.route('/admin/offsite/test', methods=['POST'])
@login_required
@admin_required
def admin_offsite_test():
    if not _offsite_ready():
        return jsonify({'success': False, 'message': 'Turn offsite backup on and fill in all fields, save, then test.'})
    ok, msg = _offsite_panel_db_backup()
    if ok:
        _set_setting('offsite_last_panel', str(time.time()))
    return jsonify({'success': ok, 'message': ('Panel database copied to your storage.' if ok else msg)})


@app.route('/vm/<vm_id>/web/backups/offsite', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_backup_offsite(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not _offsite_ready():
        return _dk_json_err('Offsite storage is not set up on this server.')
    name = (request.get_json(silent=True) or {}).get('name') or ''
    if not _WEB_BK_RE.match(name) or not (_web_bk_dir(vm_id) / name).is_file():
        return _dk_json_err('Backup not found.')
    ok, msg = _offsite_upload(_web_bk_dir(vm_id) / name, f'sites/{vm_id}/{name}')
    return jsonify({'success': ok, 'message': msg})


def _web_autobackup_loop():
    while True:
        time.sleep(1800)
        try:
            for v in (db_execute("SELECT vm_id FROM vm_instances WHERE provision_kind='web' AND runtime='docker' AND status='running'", fetch=True) or []):
                vid = v['vm_id']
                if not _web_settings(_web_opt(_dk_row(vid)))['auto_backup']:
                    continue
                autos = [b for b in _web_backup_list(vid) if b['kind'] == 'auto']
                if autos and time.time() - autos[0]['time'] < 23 * 3600:
                    continue
                def _auto(log, vid=vid):
                    nm = _web_make_backup(vid, 'auto', log)
                    if _offsite_ready():
                        log('Copying to offsite storage…')
                        ok, msg = _offsite_upload(_web_bk_dir(vid) / nm, f'sites/{vid}/{nm}')
                        log(msg)
                _web_task(vid, 'Automatic backup', _auto)
        except Exception as e:
            print(f'[web] autobackup loop: {e}', flush=True)


# ---- SSL health (looked up in the background so the page never waits) ----
def _web_ssl_refresh(domain):
    def work():
        try:
            ctx = _ssl.create_default_context()
            with socket.create_connection((domain, 443), timeout=5) as sk:
                with ctx.wrap_socket(sk, server_hostname=domain) as ss:
                    cert = ss.getpeercert()
            days = int((_ssl.cert_time_to_seconds(cert['notAfter']) - time.time()) / 86400)
            issuer = dict(x[0] for x in cert.get('issuer', ())).get('organizationName', '')
            res = {'ok': True, 'days': days, 'issuer': issuer}
        except _ssl.SSLCertVerificationError:
            res = {'ok': False, 'error': 'Certificate is not valid yet'}
        except Exception:
            res = {'ok': False, 'error': 'HTTPS is not reachable yet'}
        _web_ssl_cache[domain] = (time.time(), res)
        _web_ssl_busy.discard(domain)
    if domain in _web_ssl_busy:
        return
    _web_ssl_busy.add(domain)
    threading.Thread(target=work, daemon=True).start()


def _web_ssl_info(domain):
    hit = _web_ssl_cache.get(domain)
    if not hit or time.time() - hit[0] > 300:
        _web_ssl_refresh(domain)
    return hit[1] if hit else None


# ---- routes ----
def _web_pma_state(vid, opt):
    c = _cname(vid) + '-pma'
    rc, out, _ = _docker('inspect', '-f', '{{.State.Running}}', c, timeout=10)
    running = rc == 0 and out.strip() == 'true'
    until = int(opt.get('pma_until') or 0)
    host = _web_server_host()
    port = opt.get('pma_port')
    return {'running': running, 'minutes_left': max(0, int((until - time.time()) / 60)) if running else 0,
            'url': f'http://{host}:{port}' if running and host and port else None}


def _web_pma_stop(vid):
    _docker('rm', '-f', _cname(vid) + '-pma', timeout=30)
    db_execute("DELETE FROM port_forwards WHERE vm_id=? AND guest_port=81", (vid,))
    _web_save_opt(vid, pma_port=None, pma_until=0)


