# ---------- site uptime monitor (checks every 2 minutes, alerts when a site goes down / comes back) ----------
_WEB_UP = {}   # vid -> {'fails': n, 'down': bool}


def _web_probe(vid):
    """-> (ok, ms). Looks at the container first, then asks the site itself on its local port."""
    if not dk_status(vid)[0]:
        return False, 0
    try:
        if _APPS.get(_app_key(_dk_row(vid)) or '', {}).get('game'):
            return True, 0                      # UDP game servers have no web page to probe
    except Exception:
        pass
    port = _web_host_port(vid)
    if not port:
        return True, 0
    t0 = time.time()
    try:
        class _NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *a, **k):
                return None
        op = urllib.request.build_opener(_NoRedirect)
        req = urllib.request.Request(f'http://127.0.0.1:{port}/', headers={'User-Agent': 'PHvm-uptime'})
        try:
            r = op.open(req, timeout=10)
            code = r.status
        except urllib.error.HTTPError as e:
            code = e.code
        return code < 500, int((time.time() - t0) * 1000)
    except Exception:
        return False, int((time.time() - t0) * 1000)


def _web_uptime_tick():
    rows = db_execute("SELECT vm_id, user_id, name, status FROM vm_instances WHERE provision_kind='web' AND runtime='docker'", fetch=True) or []
    now = int(time.time())
    for v in rows:
        vid = v['vm_id']
        if v['status'] in ('stopped', 'creating', 'error'):
            _WEB_UP.pop(vid, None)
            continue
        ok, ms = _web_probe(vid)
        db_execute("INSERT INTO web_uptime (vm_id, ts, ok, ms) VALUES (?,?,?,?)", (vid, now, 1 if ok else 0, ms))
        st = _WEB_UP.setdefault(vid, {'fails': 0, 'down': False})
        if ok:
            if st['down']:
                st['down'] = False
                notify_user(v['user_id'], 'Site is back online', f"{v['name']} is reachable again.", 'success')
                _dk_notify(vid, f"✅ **{v['name']}** is back online.", force=True)
            st['fails'] = 0
        else:
            st['fails'] += 1
            if st['fails'] >= 2 and not st['down']:
                st['down'] = True
                _admin_alert(f"🚨 Site down: {v['name']}")
                notify_user(v['user_id'], 'Site is down', f"{v['name']} is not responding.", 'danger')
                _dk_notify(vid, f"🚨 **{v['name']}** is not responding.", force=True)
    db_execute("DELETE FROM web_uptime WHERE ts < ?", (now - 7 * 86400,))


# ---- Per-site traffic and disk usage (sampled every few minutes, kept 90 days) ----
_NETIO_LAST = {}
_UNIT = {'b': 1, 'kb': 1000, 'mb': 1000 ** 2, 'gb': 1000 ** 3, 'tb': 1000 ** 4, 'kib': 1024, 'mib': 1024 ** 2, 'gib': 1024 ** 3, 'tib': 1024 ** 4}


def _parse_bytes(txt):
    m_ = re.match(r'^\s*([\d.]+)\s*([A-Za-z]+)\s*$', txt or '')
    if not m_:
        return 0
    return int(float(m_.group(1)) * _UNIT.get(m_.group(2).lower(), 1))


def _web_usage_tick():
    day = datetime.now().strftime('%Y-%m-%d')
    for v in (db_execute("SELECT vm_id, name, user_id, storage_gb FROM vm_instances WHERE provision_kind='web' AND runtime='docker'", fetch=True) or []):
        vid = v['vm_id']
        rc, out, _ = _docker('stats', '--no-stream', '--format', '{{.NetIO}}', _cname(vid), timeout=20)
        if rc == 0 and '/' in (out or ''):
            rx_s, _, tx_s = out.strip().partition('/')
            rx, tx = _parse_bytes(rx_s), _parse_bytes(tx_s)
            lrx, ltx = _NETIO_LAST.get(vid, (None, None))
            drx = (rx - lrx) if lrx is not None and rx >= lrx else (rx if lrx is not None else 0)
            dtx = (tx - ltx) if ltx is not None and tx >= ltx else (tx if ltx is not None else 0)
            _NETIO_LAST[vid] = (rx, tx)
            db_execute("INSERT INTO web_usage (vm_id, day, rx, tx) VALUES (?,?,?,?) ON CONFLICT(vm_id, day) DO UPDATE SET rx=rx+excluded.rx, tx=tx+excluded.tx",
                       (vid, day, max(0, drx), max(0, dtx)))
        try:
            mb = int(_dk_disk_mb(vid, 300) or 0)
        except Exception:
            mb = 0
        if mb:
            db_execute("INSERT INTO web_usage (vm_id, day, disk_mb) VALUES (?,?,?) ON CONFLICT(vm_id, day) DO UPDATE SET disk_mb=excluded.disk_mb", (vid, day, mb))
            limit = int(v['storage_gb'] or 0) * 1024
            if limit:
                lvl = 2 if mb >= limit else 1 if mb >= limit * 0.9 else 0
                key = 'diskwarn:' + vid
                if lvl and gsv(key, '') != f'{day}:{lvl}':
                    _set_setting(key, f'{day}:{lvl}')
                    notify_user(v['user_id'], 'Website disk is full' if lvl == 2 else 'Website disk almost full',
                                f"{v['name']} uses {mb} MB of {limit} MB. " + ('Uploads may fail now — delete files or upgrade your plan.' if lvl == 2 else 'Free some space or upgrade your plan.'),
                                'danger' if lvl == 2 else 'warning')
    db_execute("DELETE FROM web_usage WHERE day < date('now','-90 day')")


def _plan_expiry_loop():
    """Email + notify users 7 / 3 / 1 days before a website plan ends (and once when it has ended)."""
    time.sleep(120)
    while True:
        try:
            for v in (db_execute("SELECT vm_id, name, user_id, expiry_date FROM vm_instances WHERE provision_kind='web' AND expiry_date IS NOT NULL", fetch=True) or []):
                try:
                    days = (datetime.strptime(str(v['expiry_date'])[:19], '%Y-%m-%d %H:%M:%S') - datetime.now()).days
                except Exception:
                    continue
                lvl = 4 if days < 0 else 3 if days <= 1 else 2 if days <= 3 else 1 if days <= 7 else 0
                key = 'planrem:' + v['vm_id']
                mark = f"{str(v['expiry_date'])[:10]}:{lvl}"
                if lvl and gsv(key, '') != mark:
                    _set_setting(key, mark)
                    when = 'has ended' if lvl == 4 else f'ends in {max(days, 0)} day(s)'
                    notify_user(v['user_id'], 'Website plan ending', f"Your website \"{v['name']}\" {when}. Open Web Hosting → pick a plan → Renew an existing site.", 'danger' if lvl >= 3 else 'warning')
        except Exception as e:
            print('[plans] expiry check failed:', e, flush=True)
        time.sleep(6 * 3600)


def _web_usage_loop():
    time.sleep(90)
    while True:
        try:
            _web_usage_tick()
        except Exception as e:
            print('[web] usage sample failed:', e, flush=True)
        time.sleep(600)


def _web_usage_summary(vid):
    rows = db_execute("SELECT day, rx, tx, disk_mb FROM web_usage WHERE vm_id=? AND day >= date('now','-29 day') ORDER BY day", (vid,), fetch=True) or []
    days = [{'day': r['day'], 'rx': int(r['rx'] or 0), 'tx': int(r['tx'] or 0), 'disk_mb': int(r['disk_mb'] or 0)} for r in rows]
    return {'days': days, 'rx': sum(d['rx'] for d in days), 'tx': sum(d['tx'] for d in days)}


def _web_uptime_loop():
    time.sleep(60)
    while True:
        try:
            _web_uptime_tick()
        except Exception as e:
            print(f'[web] uptime check failed: {e}', flush=True)
        time.sleep(120)


def _web_uptime_summary(vid):
    since = int(time.time()) - 86400
    r = db_execute("SELECT COUNT(*) AS n, COALESCE(SUM(ok),0) AS up, COALESCE(AVG(CASE WHEN ok=1 THEN ms END),0) AS ms FROM web_uptime WHERE vm_id=? AND ts>=?",
                   (vid, since), fetchone=True)
    n = int(r['n']) if r else 0
    last = db_execute("SELECT ok, ms FROM web_uptime WHERE vm_id=? ORDER BY ts DESC LIMIT 1", (vid,), fetchone=True)
    return {'checks': n, 'pct': round(100.0 * int(r['up']) / n, 2) if n else None, 'avg_ms': int(r['ms']) if n else None,
            'now_ok': bool(last['ok']) if last else None}


# ---------- WordPress toolkit (plugins, updates, maintenance) via WP-CLI ----------
_WP_SLUG_RE = re.compile(r'^[a-z0-9][a-z0-9_-]{0,80}$')


@app.route('/vm/<vm_id>/web/wp/plugins')
@login_required
@vm_owner_or_admin
def web_wp_plugins(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('Start the site first.')
    rc, out, err = _web_wp_cli(vm_id, 'plugin', 'list', '--fields=name,title,status,update,version', '--format=json', timeout=90)
    if rc != 0:
        return _dk_json_err('WordPress is not installed yet, or not reachable: ' + ((err or out).strip()[-160:] or 'unknown error'))
    try:
        plugins = json.loads(out[out.index('['):out.rindex(']') + 1])
    except Exception:
        return _dk_json_err('Could not read the plugin list.')
    rc2, out2, _ = _web_wp_cli(vm_id, 'maintenance-mode', 'status', timeout=60)
    return jsonify({'success': True, 'plugins': plugins, 'maintenance': 'is active' in (out2 or '') and 'not' not in (out2 or '')})


@app.route('/vm/<vm_id>/web/wp/action', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_wp_action(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('Start the site first.')
    d = request.get_json(silent=True) or {}
    action, slug = d.get('action'), str(d.get('slug') or '').strip().lower()
    needs_slug = {'plugin_activate', 'plugin_deactivate', 'plugin_update', 'plugin_delete', 'plugin_install'}
    if action in needs_slug and not _WP_SLUG_RE.match(slug):
        return _dk_json_err('Enter the plugin name as on wordpress.org, for example "classic-editor".')
    plans = {
        'plugin_activate': ('Activating ' + slug, [('plugin', 'activate', slug)]),
        'plugin_deactivate': ('Deactivating ' + slug, [('plugin', 'deactivate', slug)]),
        'plugin_update': ('Updating ' + slug, [('plugin', 'update', slug)]),
        'plugin_delete': ('Deleting ' + slug, [('plugin', 'deactivate', slug), ('plugin', 'delete', slug)]),
        'plugin_install': ('Installing ' + slug, [('plugin', 'install', slug, '--activate')]),
        'update_all': ('Updating WordPress, plugins and themes', [('core', 'update'), ('plugin', 'update', '--all'), ('theme', 'update', '--all'), ('core', 'update-db')]),
        'core_update': ('Updating WordPress', [('core', 'update'), ('core', 'update-db')]),
        'maintenance_on': ('Turning maintenance mode on', [('maintenance-mode', 'activate')]),
        'maintenance_off': ('Turning maintenance mode off', [('maintenance-mode', 'deactivate')]),
        'flush': ('Clearing caches and permalinks', [('cache', 'flush'), ('rewrite', 'flush'), ('transient', 'delete', '--all')]),
    }
    if action not in plans:
        return _dk_json_err('Unknown action.')
    label, cmds = plans[action]

    def work(log):
        for c in cmds:
            log('wp ' + ' '.join(c))
            rc, out, err = _web_wp_cli(vm_id, *c, timeout=900)
            if rc != 0:
                raise RuntimeError(((err or out).strip().splitlines() or ['WP-CLI failed'])[-1][:200])
        log('Done.')
    ok, msg = _web_task(vm_id, label, work)
    audit(session['user_id'], 'web_wp_' + action, f'{vm_id[:8]} {slug}')
    return jsonify({'success': ok, 'message': 'Started.' if ok else msg})


@app.route('/vm/<vm_id>/web/login', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_login(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('Start the site first.')
    wpc = _dk_dir(vm_id) / 'wp-content'
    if not wpc.is_dir():
        return _dk_json_err('WordPress is still setting up — open the site once, finish the setup screen, then try again.')
    mu = wpc / 'mu-plugins'
    mu.mkdir(exist_ok=True)
    token = secrets.token_urlsafe(24)
    (mu / 'phvm-sso.php').write_text(_WEB_SSO_PHP)
    (wpc / '.phvm_sso').write_text(json.dumps({'h': hashlib.sha256(token.encode()).hexdigest(), 'e': int(time.time()) + 60}))
    _u = _web_uid(_web_opt(v))
    _dk_chown_tree(str(mu), _u)
    _dk_chown(str(wpc / '.phvm_sso'), _u, _u)
    doms = db_execute("SELECT domain FROM web_domains WHERE vm_id=? AND (redirect_to IS NULL OR redirect_to='') ORDER BY id LIMIT 1", (vm_id,), fetchone=True)
    base = ('https://' + doms['domain']) if doms else _web_direct_url(v)
    if not base:
        return _dk_json_err('No site address yet — set "Server IP" in admin settings.')
    audit(session['user_id'], 'web_sso', vm_id[:8])
    return jsonify({'success': True, 'url': f'{base}/?phvm_sso={token}'})


@app.route('/vm/<vm_id>/web/pma', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_pma(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    action = (request.get_json(silent=True) or {}).get('action')
    c, cdb, cnet = _web_names(vm_id)
    if action == 'stop':
        _web_pma_stop(vm_id)
        return jsonify({'success': True, 'message': 'phpMyAdmin stopped.'})
    if action != 'start':
        return _dk_json_err('Unknown action.')
    if not dk_status(vm_id)[0]:
        return _dk_json_err('Start the site first.')
    _docker('rm', '-f', c + '-pma', timeout=30)
    db_execute("DELETE FROM port_forwards WHERE vm_id=? AND guest_port=81", (vm_id,))
    port = allocate_host_port(preferred=8081)
    db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
               (vm_id, port, 81, 'tcp', 'phpmyadmin'))
    rc, out, err = _docker('run', '-d', '--name', c + '-pma', '--label', 'phvm=1', '--network', cnet,
                           '--memory', '192m', '--memory-swap', '192m', '--pids-limit', '128', '--security-opt', 'no-new-privileges',
                           '-e', f'PMA_HOST={cdb}', '-e', 'UPLOAD_LIMIT=256M', '-p', f'{port}:80', 'phpmyadmin:5-apache', timeout=600)
    if rc != 0:
        db_execute("DELETE FROM port_forwards WHERE vm_id=? AND guest_port=81", (vm_id,))
        return _dk_json_err('Could not start phpMyAdmin: ' + (err or out).strip()[-200:])
    until = int(time.time()) + 30 * 60
    _web_save_opt(vm_id, pma_port=port, pma_until=until)

    def stopper():
        time.sleep(30 * 60 + 5)
        o = _web_opt(_dk_row(vm_id) or {}) if _dk_row(vm_id) else {}
        if o.get('pma_until') == until:
            _web_pma_stop(vm_id)
    threading.Thread(target=stopper, daemon=True).start()
    audit(session['user_id'], 'web_pma_start', vm_id[:8])
    return jsonify({'success': True, 'message': 'phpMyAdmin is running for 30 minutes.'})


@app.route('/vm/<vm_id>/web/backups', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_backup_action(vm_id):
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    d = request.get_json(silent=True) or {}
    action, name = d.get('action'), str(d.get('name') or '')
    if action == 'create':
        ok, msg = _web_task(vm_id, 'Creating backup', lambda log: _web_make_backup(vm_id, 'manual', log))
        audit(session['user_id'], 'web_backup', vm_id[:8])
        return jsonify({'success': ok, 'message': 'Backup started.' if ok else msg})
    if not _WEB_BK_RE.match(name) or not (_web_bk_dir(vm_id) / name).is_file():
        return _dk_json_err('Backup not found.')
    path = _web_bk_dir(vm_id) / name
    if action == 'delete':
        path.unlink(missing_ok=True)
        return jsonify({'success': True, 'message': 'Backup deleted.'})
    if action == 'restore':
        def work(log):
            log('Saving the current site first…')
            _web_make_backup(vm_id, 'pre', log)
            _web_restore_file(vm_id, str(path), log)
        ok, msg = _web_task(vm_id, 'Restoring backup', work)
        audit(session['user_id'], 'web_restore', f'{vm_id[:8]} {name}')
        return jsonify({'success': ok, 'message': 'Restore started — the current site is saved as a "pre" backup first.' if ok else msg})
    return _dk_json_err('Unknown action.')


