@app.route('/vm/<vm_id>/web/clone', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_clone(vm_id):
    """Copy a site (files + database) into a new staging site. Owners get one staging copy per site."""
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    if not _docker_enabled():
        return _dk_json_err('Docker is not available.')
    if _web_opt(v).get('staging_of'):
        return _dk_json_err('This is already a staging copy.')
    if session.get('role') != 'admin':
        for o in (db_execute("SELECT provision_opt FROM vm_instances WHERE user_id=? AND provision_kind='web'", (v['user_id'],), fetch=True) or []):
            try:
                if json.loads(o['provision_opt'] or '{}').get('staging_of') == vm_id:
                    return _dk_json_err('This site already has a staging copy. Push it to live or delete it first.')
            except Exception:
                pass
    new_vid = str(uuid.uuid4())
    name = sanitize_name((request.get_json(silent=True) or {}).get('name') or f"{v['name']}-copy", 64)
    ensure_local_node()
    db_execute(
        "INSERT INTO vm_instances (vm_id, user_id, name, os_template, ram_mb, cpu_cores, storage_gb, ssh_port, vnc_port, network_mode, public_ip, status, expiry_date) "
        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (new_vid, v['user_id'], name, 'docker', v['ram_mb'], v['cpu_cores'], v['storage_gb'], None, None, 'private', None, 'creating', row_get(v, 'expiry_date')))
    src_opt = _web_settings(_web_opt(v))
    db_execute("UPDATE vm_instances SET provision_kind='web', provision_opt=?, runtime='docker' WHERE vm_id=?",
               (json.dumps({'app': 'wordpress', 'staging_of': vm_id, **{k: src_opt[k] for k in ('php', 'memory_limit', 'upload_max', 'max_exec')}}), new_vid))
    _dk_cache[new_vid] = (time.time(), True)
    db_execute("INSERT INTO port_forwards (vm_id, host_port, guest_port, protocol, label) VALUES (?,?,?,?,?)",
               (new_vid, allocate_host_port(preferred=8080), 80, 'tcp', 'web'))

    def work():
        tmp_name = None
        try:
            tmp_name = _web_make_backup(vm_id, 'clone', lambda m: None)
            complete_web_setup(new_vid)
            if _dk_row(new_vid)['status'] == 'error':
                raise RuntimeError('new site setup failed')
            db_execute("UPDATE vm_instances SET status='creating', creation_progress=95, creation_step='Copying the site content…' WHERE vm_id=?", (new_vid,))
            _web_restore_file(new_vid, str(_web_bk_dir(vm_id) / tmp_name), lambda m: None)
            db_execute("UPDATE vm_instances SET status='running', creation_progress=100, creation_step='Ready — copy of the site' WHERE vm_id=?", (new_vid,))
        except Exception as e:
            db_execute("UPDATE vm_instances SET status='error', creation_step=? WHERE vm_id=?", (f'Clone failed: {e}'[:300], new_vid))
        finally:
            if tmp_name:
                (_web_bk_dir(vm_id) / tmp_name).unlink(missing_ok=True)
    threading.Thread(target=work, daemon=True).start()
    audit(session['user_id'], 'web_clone', f'{vm_id[:8]} -> {new_vid[:8]}')
    return jsonify({'success': True, 'message': 'Copy started.', 'redirect': url_for('vm_installing', vm_id=new_vid)})


@app.route('/vm/<vm_id>/web/push', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_push_live(vm_id):
    """Replace the live site with this staging copy (the live site is saved as a 'pre' backup first)."""
    v = _web_row(vm_id)
    if not v:
        return _dk_json_err('Not a web hosting site.')
    live_id = _web_opt(v).get('staging_of')
    live = _web_row(live_id) if live_id else None
    if not live or live['user_id'] != v['user_id']:
        return _dk_json_err('This site is not a staging copy of a live site.')

    def work(log):
        log('Saving the current live site first…')
        _web_make_backup(live_id, 'pre', log)
        log('Packing the staging copy…')
        nm = _web_make_backup(vm_id, 'clone', log)
        try:
            _web_restore_file(live_id, str(_web_bk_dir(vm_id) / nm), log)
        finally:
            (_web_bk_dir(vm_id) / nm).unlink(missing_ok=True)
    ok, msg = _web_task(live_id, 'Pushing staging to live', work)
    audit(session['user_id'], 'web_push_live', f'{vm_id[:8]} -> {live_id[:8]}')
    return jsonify({'success': ok, 'message': 'Pushing to the live site. The previous live site is kept as a "pre" backup you can restore.' if ok else msg,
                    'redirect': url_for('web_panel', vm_id=live_id) if ok else None})


@app.route('/vm/<vm_id>/web/domains/redirect', methods=['POST'])
@login_required
@vm_owner_or_admin
def web_domain_redirect(vm_id):
    if not _web_row(vm_id):
        return _dk_json_err('Not a web hosting site.')
    d = request.get_json(silent=True) or {}
    dom, target = _web_clean_domain(d.get('domain')), _web_clean_domain(d.get('target'))
    mine = {r['domain']: row_get(r, 'redirect_to') for r in (db_execute("SELECT domain, redirect_to FROM web_domains WHERE vm_id=?", (vm_id,), fetch=True) or [])}
    if dom not in mine:
        return _dk_json_err('Domain not found on this site.')
    if target:
        if target == dom or target not in mine:
            return _dk_json_err('Pick another domain connected to this site.')
        if mine[target]:
            return _dk_json_err('That domain itself redirects somewhere — choose the main one.')
        if any(v == dom for v in mine.values()):
            return _dk_json_err('Other domains redirect to this one, so it cannot redirect away.')
    db_execute("UPDATE web_domains SET redirect_to=? WHERE domain=?", (target or None, dom))
    ok, msg = _caddy_sync()
    return jsonify({'success': ok, 'message': ('Saved.' if ok else msg)})





# ─────────────── Security checks, live overview and alerts ───────────────
_HIST = {'t': [], 'cpu': [], 'mem': [], 'disk': [], 'net': []}
_HIST_MAX = 120   # 120 samples x 30 s = 1 hour
_hist_lock = threading.Lock()
_net_prev = [None]


def _hist_sample():
    try:
        cpu = psutil.cpu_percent(interval=None)
        mem = psutil.virtual_memory().percent
        disk = psutil.disk_usage('/').percent
        nio = psutil.net_io_counters()
        now = time.time()
        rate = 0.0
        if _net_prev[0]:
            dt = max(1.0, now - _net_prev[0][0])
            rate = ((nio.bytes_sent + nio.bytes_recv) - _net_prev[0][1]) / dt / 1024.0
        _net_prev[0] = (now, nio.bytes_sent + nio.bytes_recv)
        with _hist_lock:
            for k, val in (('t', int(now)), ('cpu', round(cpu, 1)), ('mem', round(mem, 1)), ('disk', round(disk, 1)), ('net', round(max(0.0, rate), 1))):
                _HIST[k].append(val)
                del _HIST[k][:-_HIST_MAX]
    except Exception:
        pass


def _hist_loop():
    psutil.cpu_percent(interval=None)
    while True:
        _hist_sample()
        time.sleep(30)


def start_history_thread():
    threading.Thread(target=_hist_loop, daemon=True).start()


_sec_cache = [0, []]


def security_checks():
    """Plain-language findings for admins (cached 60 s): each is {level, title, detail, fix}."""
    if time.time() - _sec_cache[0] < 60:
        return _sec_cache[1]
    out = _security_checks_raw()
    _sec_cache[0], _sec_cache[1] = time.time(), out
    return out


def _security_checks_raw():
    out = []
    try:
        for u in (db_execute("SELECT username, password FROM users WHERE role='admin' AND is_active=1", fetch=True) or []):
            if u['password'] and check_password_hash(u['password'], 'phvm123'):
                out.append({'level': 'danger', 'title': 'Admin password is the public default',
                        'detail': f'The "{u["username"]}" account still uses the default password, which anyone can look up.',
                        'fix': 'Profile → change password'})
    except Exception:
        pass
    try:
        n = (db_execute("SELECT COUNT(*) AS c FROM users WHERE role='admin' AND is_active=1 AND COALESCE(totp_enabled,0)=0", fetchone=True) or {'c': 0})['c']
        if n:
            out.append({'level': 'warning', 'title': f'{n} admin account{"s" if n != 1 else ""} without 2-step login',
                        'detail': 'Turn on 2FA so a stolen password is not enough to take over the panel.',
                        'fix': 'Profile → Two-factor authentication'})
    except Exception:
        pass
    try:
        if not _docker_enabled():
            out.append({'level': 'info', 'title': 'Docker is not available',
                        'detail': 'Minecraft, bot and web hosting need Docker on this server.', 'fix': 'Install Docker'})
        else:
            n = (db_execute("SELECT COUNT(*) AS c FROM web_domains", fetchone=True) or {'c': 0})['c']
            if n:
                _dir = (db_execute("SELECT COUNT(*) AS c FROM web_domains WHERE COALESCE(via,'direct')='direct'", fetchone=True) or {'c': 0})['c']
                for port in ((80, 443) if _dir else (80,)):
                    s = socket.socket(); s.settimeout(1)
                    try:
                        s.connect(('127.0.0.1', port))
                    except Exception:
                        out.append({'level': 'warning', 'title': f'Port {port} is not answering',
                                    'detail': 'Domains are connected, but nothing is listening here. Check that the web proxy is running and the firewall allows 80 and 443.',
                                    'fix': 'Open ports 80 and 443'})
                    finally:
                        s.close()
    except Exception:
        pass
    try:
        if shutil.which('ufw'):
            rc = subprocess.run(['ufw', 'status'], capture_output=True, text=True, timeout=5).stdout
            if 'inactive' in rc.lower():
                out.append({'level': 'info', 'title': 'Firewall (ufw) is off',
                            'detail': 'Only open the ports you use: SSH, the panel, 80, 443 and your server ports.', 'fix': 'ufw enable'})
    except Exception:
        pass
    return out


def _alerts_for(user_id, is_admin):
    al = []
    rows = db_execute("SELECT vm_id, name, status, expiry_date, user_id, provision_kind, creation_step FROM vm_instances" +
                      ("" if is_admin else " WHERE user_id=?"), (() if is_admin else (user_id,)), fetch=True) or []
    now = datetime.now() if 'datetime' in globals() else None
    for v in rows:
        link = url_for('manage_vm', vm_id=v['vm_id'])
        if v['status'] == 'error':
            al.append({'level': 'danger', 'text': f"{v['name']} failed to install", 'link': link})
        exp = row_get(v, 'expiry_date')
        if exp and now:
            try:
                d = datetime.fromisoformat(str(exp)[:19].replace('T', ' ')) if len(str(exp)) > 10 else datetime.strptime(str(exp)[:10], '%Y-%m-%d')
                left = (d - now).total_seconds() / 86400
                if left < 0:
                    al.append({'level': 'danger', 'text': f"{v['name']} has expired", 'link': link})
                elif left < 7:
                    al.append({'level': 'warning', 'text': f"{v['name']} expires in {max(0, int(left))} day{'s' if int(left) != 1 else ''}", 'link': link})
            except Exception:
                pass
    if is_admin:
        with _hist_lock:
            for k, name in (('disk', 'Server disk'), ('mem', 'Server memory')):
                if _HIST[k] and _HIST[k][-1] >= 90:
                    al.append({'level': 'danger' if _HIST[k][-1] >= 95 else 'warning', 'text': f'{name} is {_HIST[k][-1]:.0f}% full', 'link': None})
        sec = [f for f in security_checks() if f['level'] in ('danger', 'warning')]
        if sec:
            al.append({'level': 'danger' if any(f['level'] == 'danger' for f in sec) else 'warning',
                       'text': f"Security check: {len(sec)} thing{'s' if len(sec) != 1 else ''} need attention", 'link': url_for('admin_dashboard') + '#security'})
    else:
        u = db_execute("SELECT COALESCE(totp_enabled,0) AS t FROM users WHERE id=?", (user_id,), fetchone=True)
        if u and not u['t']:
            al.append({'level': 'info', 'text': 'Turn on two-factor login to protect your account', 'link': '/profile'})
    order = {'danger': 0, 'warning': 1, 'info': 2}
    al.sort(key=lambda a: order.get(a['level'], 3))
    return al[:12]


@app.route('/api/overview')
@login_required
def api_overview():
    is_admin = session.get('role') == 'admin'
    with _hist_lock:
        hist = {k: list(v) for k, v in _HIST.items()} if is_admin else None
    return jsonify({'success': True, 'history': hist, 'alerts': _alerts_for(session['user_id'], is_admin),
                    'host': {'cpu': hist['cpu'][-1] if hist and hist['cpu'] else None,
                             'mem': hist['mem'][-1] if hist and hist['mem'] else None,
                             'disk': hist['disk'][-1] if hist and hist['disk'] else None} if is_admin else None})


